                playtestState.opponentGrave.push(chosenSkillId);
                checkAndTriggerRemembranza(chosenSkillId, 'opponent');
                checkAndTriggerEscape(chosenSkillId, 'opponent');
                checkAndTriggerDesvelo(chosenSkillId, 'opponent');
                shuffleArray(playtestState.opponentDeck);

                addLog(`[Efecto Roy SP253 Rival] El rival envió a <strong>${cardsDatabase[chosenSkillId].nombre}</strong> de su deck a su cementerio y barajó su mazo.`, 'var(--accent-purple)');
                updatePlaytestView();
                checkMarinaSP186OrProceed(endOfTurnFinalCallback);
