        const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
        showContextMenu(dummyEvent, items, () => {
          checkMarinaSP186OrProceed(endOfTurnFinalCallback);
        });
