              checkAndTriggerApunteIgneo(discardedId);
              checkAndTriggerCrimenNocturno(discardedId);
              checkAndTriggerAlmacenamientoFallido(discardedId, 'hand');
              checkAndTriggerKatshi159(discardedId);
              checkAndTriggerFulgorOfensivo(discardedId);
              checkAndTriggerEspiralDigital(discardedId, 'hand');
