              const drawnO = playtestState.opponentDeck.shift();
              playtestState.opponentHand.push(drawnO);
              addLog(`[Efecto Fredlard] Tu adversario robó 1 carta de su deck.`, 'var(--accent-purple)');

              checkAndTriggerInestabilidad('player');
              checkAndTriggerInestabilidad('opponent');

              updatePlaytestView();
              checkNobukoOrProceed();
