function activateOpponentEishetBenchSP278(index) {
  const bItem = playtestState.opponentBench[index];
  if (!bItem) return;
  if (playtestState.turnOwner !== 'opponent') {
    alert("Solo puedes activar este efecto de banca durante el turno del adversario.");
    return;
  }
  if (bItem.effectUsed) {
    alert("Este efecto de banca ya se usó este turno.");
    return;
  }
  if (isBenchEffectBlocked('opponent')) {
    const reason = isHarukaSP345Active() ? "Haruka (BBX-SP345)" : "Aislamiento (SP128)";
    alert(`Los efectos de banca están bloqueados por ${reason}.`);
    return;
  }

  const isEishetSkill = id => cardsDatabase[id] && cardsDatabase[id].tipo === 'Skill' && cardsDatabase[id].portador && cardsDatabase[id].portador.includes("Eishet");
  const oppGraveItems = [];
  playtestState.opponentGrave.forEach((id, gIdx) => {
    if (isEishetSkill(id)) {
      oppGraveItems.push({ id, graveIndex: gIdx, owner: 'opponent', text: cardsDatabase[id].nombre });
    }
  });

  if (oppGraveItems.length === 0) {
    alert("No hay Skills propias de Eishet en el cementerio rival.");
    return;
  }

  const maxQty = Math.min(2, oppGraveItems.length);
  openUpToMultiCardChooserModal(oppGraveItems, `[Rival] Eishet (Banca): Selecciona hasta ${maxQty} Skill(s) propias de Eishet para barajar a su deck`, maxQty, (chosenIndices) => {
    const selectedItems = chosenIndices.map(i => oppGraveItems[i]);
    selectedItems.sort((a, b) => b.graveIndex - a.graveIndex);

    const selectedNames = [];
    selectedItems.forEach(item => {
      let idx = item.graveIndex;
      if (playtestState.opponentGrave[idx] !== item.id) {
        idx = playtestState.opponentGrave.lastIndexOf(item.id);
      }
      if (idx !== -1) {
        const removedId = playtestState.opponentGrave.splice(idx, 1)[0];
        playtestState.opponentDeck.push(removedId);
        selectedNames.push(cardsDatabase[removedId].nombre);
      }
    });

    shuffleArray(playtestState.opponentDeck);
    bItem.effectUsed = true;
    addLog(`[Efecto Eishet Banca BBX-SP278 Rival] El rival barajó ${selectedNames.length} Skill(s) propia(s) de Eishet de su cementerio a su deck: <strong>${selectedNames.join(', ')}</strong>.`, 'var(--accent-purple)');
    updatePlaytestView();
  });
}

