function activateOpponentKatherineBenchSP248(index, chosen = null) {
  const bItem = playtestState.opponentBench[index];
  if (!bItem) return;
  if (playtestState.turnOwner !== 'opponent') {
    alert("Solo puedes activar este efecto de banca durante el turno del adversario.");
    return;
  }
  if (bItem.effectUsed) {
    alert("Este efecto de banca ya se usó este turno.");
    return;
  }
  if (isBenchEffectBlocked('opponent')) {
    const reason = isHarukaSP345Active() ? "Haruka (BBX-SP345)" : "Aislamiento (SP128)";
    alert(`Los efectos de banca están bloqueados por ${reason}.`);
    return;
  }

  const oppEquippedSkills = [];
  playtestState.slots.forEach((s, sIdx) => {
    if (s.character) {
      const cName = cardsDatabase[s.character].nombre;
      s.skills.forEach((skId, skIdx) => {
        if (canRemoveSkillByEffect(skId, false, 'opponent', s, 'deck')) {
          oppEquippedSkills.push({
            id: skId,
            owner: 'player',
            slotIndex: sIdx,
            skillIndex: skIdx,
            charName: cName
          });
        }
      });
    }
  });
  playtestState.opponentSlots.forEach((s, sIdx) => {
    if (s.character) {
      const cName = cardsDatabase[s.character].nombre;
      s.skills.forEach((skId, skIdx) => {
        if (canRemoveSkillByEffect(skId, true, 'opponent', s, 'deck')) {
          oppEquippedSkills.push({
            id: skId,
            owner: 'opponent',
            slotIndex: sIdx,
            skillIndex: skIdx,
            charName: cName
          });
        }
      });
    }
  });

  if (oppEquippedSkills.length === 0) {
    alert("No hay Skills portadas en el campo que el rival pueda barajar al deck.");
    return;
  }

  const doResolve = (selectedItem) => {
    if (selectedItem.owner === 'player') {
      const targetSlot = playtestState.slots[selectedItem.slotIndex];
      const sIdx = targetSlot.skills.indexOf(selectedItem.id);
      if (sIdx !== -1) targetSlot.skills.splice(sIdx, 1);
      playtestState.deck.push(selectedItem.id);
      shuffleArray(playtestState.deck);
      addLog(`[Efecto Katherine SP248 - Rival] Barajó al deck del jugador la Skill portada <strong>${cardsDatabase[selectedItem.id].nombre}</strong> (equipada a ${selectedItem.charName}).`, 'var(--accent-purple)');
    } else {
      const targetSlot = playtestState.opponentSlots[selectedItem.slotIndex];
      const sIdx = targetSlot.skills.indexOf(selectedItem.id);
      if (sIdx !== -1) targetSlot.skills.splice(sIdx, 1);
      playtestState.opponentDeck.push(selectedItem.id);
      shuffleArray(playtestState.opponentDeck);
      addLog(`[Efecto Katherine SP248 - Rival] Barajó a su deck su Skill portada <strong>${cardsDatabase[selectedItem.id].nombre}</strong> (equipada a ${selectedItem.charName}).`, 'var(--accent-purple)');
    }
    bItem.effectUsed = true;
    if (typeof notifySkillsRemovedByEffect === 'function') {
      notifySkillsRemovedByEffect(1, () => { updatePlaytestView(); }, 'opponent');
    } else {
      updatePlaytestView();
    }
  };

  if (chosen) {
    doResolve(chosen);
  } else if (typeof openCardChooserModal === 'function' && !playtestState.isDuelVsAI) {
    const chooserTargets = oppEquippedSkills.map(item => ({
      id: item.id,
      owner: item.owner,
      text: `"${cardsDatabase[item.id].nombre}" (de ${item.charName} - ${item.owner === 'player' ? 'Tú' : 'Rival'})`
    }));
    openCardChooserModal(chooserTargets, "[Rival] Katherine: Selecciona 1 Skill portada para barajar a su deck", (chosenIdx) => {
      doResolve(oppEquippedSkills[chosenIdx]);
    });
  } else {
    doResolve(oppEquippedSkills[0]);
  }
}

