    const yaUsadoHOPT = !!playtestState.opponentUsedDominioDelJuego418ThisTurn || (playtestState.opponentUsedGlobalEffects || []).includes('Dominio del juego') || (playtestState.opponentUsedGlobalEffects || []).includes('BBX-SP418');
    const playerHasCharacter = (playtestState.slots || []).some(s => s && s.character);
