function resolveOpponentEnsamblarDeclaration(oppSlot, declaredType) {
  if (playtestState.deck.length === 0) return;
  const bottomCardId = playtestState.deck[playtestState.deck.length - 1];
  const bottomCard = cardsDatabase[bottomCardId];

  addLog(`[Efecto Ensamblar BBX-SP336 Rival] El rival declaró tipo <strong>${declaredType}</strong>. Revelando la carta en el fondo de tu deck...`, 'var(--accent-purple)');

  revealCardsSequentially([bottomCardId], "Carta en el fondo de tu deck (Ensamblar Rival)", () => {
    addLog(`[Efecto Ensamblar BBX-SP336 Rival] La carta en el fondo de tu deck es <strong>${bottomCard.nombre}</strong> (${bottomCard.tipo}).`, 'var(--accent-purple)');

    if (bottomCard.tipo === declaredType) {
      if (typeof isPlayCharacterFromDeckBlocked === 'function' && isPlayCharacterFromDeckBlocked()) {
        addLog(`[Efecto Ensamblar BBX-SP336 Rival] ¡El tipo coincidió!, pero ningún jugador puede jugar Personajes directamente desde el deck por el efecto continuo de Katherine (BBX-SP350).`, 'var(--text-muted)');
        updatePlaytestView();
        return;
      }

      const isChiakoChar = id => cardsDatabase[id] && cardsDatabase[id].tipo === 'Personaje' && cardsDatabase[id].nombre.includes("Chiako");
      const chiakosInOppDeck = playtestState.opponentDeck.filter(isChiakoChar);

      if (chiakosInOppDeck.length === 0) {
        addLog(`[Efecto Ensamblar BBX-SP336 Rival] ¡El tipo coincidió!, pero el rival no tiene ningún Personaje Chiako en su deck.`, 'var(--text-muted)');
        updatePlaytestView();
        return;
      }

      const freeOppSlots = playtestState.opponentSlots.map((s, idx) => (!s.character ? idx : -1)).filter(idx => idx !== -1);
      if (freeOppSlots.length === 0) {
        addLog(`[Efecto Ensamblar BBX-SP336 Rival] ¡El tipo coincidió!, pero el rival no tiene slots libres en su campo.`, 'var(--text-muted)');
        updatePlaytestView();
        return;
      }

      const chooserTargets = chiakosInOppDeck.map(id => ({ id, owner: 'opponent', from: 'deck' }));
      openCardChooserModal(chooserTargets, "[Rival] Ensamblar: Selecciona 1 Personaje Chiako del deck rival para jugar al campo", (chosenIdx) => {
        const chosenCharId = chiakosInOppDeck[chosenIdx];
        const charCard = cardsDatabase[chosenCharId];

        const deployToOppSlot = (targetSlotIdx) => {
          const dIdx = playtestState.opponentDeck.indexOf(chosenCharId);
          if (dIdx !== -1) {
            playtestState.opponentDeck.splice(dIdx, 1);
          }

          const targetSlot = playtestState.opponentSlots[targetSlotIdx];
          targetSlot.character = chosenCharId;
          targetSlot.skills = [];
          targetSlot.usedSkills = [];
          targetSlot.usedSkillIndexes = [];
          targetSlot.isRotated = false;
          targetSlot.effectUsed = false;

          shuffleArray(playtestState.opponentDeck);
          addLog(`[Efecto Ensamblar BBX-SP336 Rival] ¡El tipo coincidió! El rival jugó a <strong>${charCard.nombre}</strong> directamente desde su deck al Slot ${targetSlotIdx + 1} y barajó su deck.`, 'var(--accent-purple)');
          checkAndTriggerInestabilidad('opponent');
          if (typeof notifyCharacterPlayedDirectlyFromDeck === 'function') {
            notifyCharacterPlayedDirectlyFromDeck('opponent', chosenCharId, targetSlotIdx);
          }
          updatePlaytestView();
        };

        if (freeOppSlots.length === 1) {
          deployToOppSlot(freeOppSlots[0]);
        } else {
          const slotItems = freeOppSlots.map(sIdx => ({
            text: `📍 [Rival] Jugar en Slot ${sIdx + 1}`,
            action: () => deployToOppSlot(sIdx)
          }));
          const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
          showContextMenu(dummyEvent, slotItems);
        }
      });
    } else {
      addLog(`[Efecto Ensamblar BBX-SP336 Rival] El tipo revelado (${bottomCard.tipo}) no coincidió con el declarado (${declaredType}). El rival no juega ningún Personaje.`, 'var(--text-muted)');
      updatePlaytestView();
    }
  });
}

function activateOpponentAnalizarDatos(slotIndex, skIndex) {
  const oppSlot = playtestState.opponentSlots[slotIndex];
  if (!oppSlot || !oppSlot.skills) return;
  const skIdxInSlot = (typeof skIndex === 'number' && skIndex >= 0) ? skIndex : oppSlot.skills.indexOf('BBX-SP337');
  if (skIdxInSlot === -1) return;

  playtestState.opponentUsedGlobalEffects = playtestState.opponentUsedGlobalEffects || [];
  if (playtestState.opponentUsedGlobalEffects.includes("Analizar datos")) {
    alert("El rival ya usó el efecto de Analizar datos este turno.");
    return;
  }

  const maxBench = (typeof isConmocionActive === 'function' && isConmocionActive()) ? 2 : 3;
  if (playtestState.opponentBench.length >= maxBench) {
    alert("El rival no tiene espacio en su banca.");
    return;
  }

  if (playtestState.opponentDeck.length < 3) {
    alert("El deck rival debe tener como mínimo 3 cartas para activar Analizar datos.");
    return;
  }

  if (isVoidOhActive()) {
    alert("Efecto bloqueado por la regla continua de Void-oh (BBX-SP308): Ningún jugador puede robar 2 o más cartas por efectos de cartas en el campo.");
    return;
  }

  if (isDrawBySkillBlocked('opponent', 3)) {
    alert("El robo de cartas por efectos de Skill está bloqueado para el rival este turno.");
    return;
  }

  const oppChiakoSlots = playtestState.opponentSlots
    .map((s, idx) => ({ slot: s, idx }))
    .filter(item => item.slot.character && cardsDatabase[item.slot.character] && cardsDatabase[item.slot.character].nombre.includes("Chiako"));

  if (oppChiakoSlots.length === 0) {
    alert("El rival no controla ningún Personaje Chiako en el campo.");
    return;
  }

  oppSlot.usedSkills = oppSlot.usedSkills || [];
  oppSlot.usedSkills.push('BBX-SP337');
  if (typeof skIndex === 'number' && skIndex >= 0) {
    oppSlot.usedSkillIndexes = oppSlot.usedSkillIndexes || [];
    oppSlot.usedSkillIndexes.push(skIndex);
  }
  playtestState.opponentUsedGlobalEffects.push("Analizar datos");

  if (oppChiakoSlots.length === 1) {
    resolveOpponentAnalizarDatos(oppChiakoSlots[0].idx);
  } else {
    const chooserTargets = oppChiakoSlots.map(item => ({
      id: item.slot.character,
      owner: 'opponent',
      from: 'field',
      charName: `Slot ${item.idx + 1}: ${cardsDatabase[item.slot.character].nombre}`
    }));
    openCardChooserModal(chooserTargets, "[Rival] Analizar datos: Selecciona 1 Personaje Chiako rival para enviar a su banca", (chosenIdx) => {
      resolveOpponentAnalizarDatos(oppChiakoSlots[chosenIdx].idx);
    });
  }
}

function resolveOpponentAnalizarDatos(chosenSlotIdx) {
  const targetSlot = playtestState.opponentSlots[chosenSlotIdx];
  if (!targetSlot || !targetSlot.character) return;

  const charId = targetSlot.character;
  const charCard = cardsDatabase[charId];
  const removedSkills = [...(targetSlot.skills || [])];

  // 1. Manda Chiako rival a la banca rival
  playtestState.opponentBench.push({ id: charId, effectUsed: false });

  // 2. Limpia el slot rival
  targetSlot.character = null;
  targetSlot.skills = [];
  targetSlot.usedSkills = [];
  targetSlot.usedSkillIndexes = [];
  targetSlot.isRotated = false;
  targetSlot.effectUsed = false;

  // 3. Sus Skills portadas se mandan al cementerio rival
  removedSkills.forEach(sk => {
    playtestState.opponentGrave.push(sk);
    onEquippedSkillSentToGraveByEffect(sk, 'opponent', 'opponent');
    checkAndTriggerRemembranza(sk, 'opponent');
  });
  if (removedSkills.length > 0 && typeof notifySkillsRemovedByEffect === 'function') {
    notifySkillsRemovedByEffect(removedSkills.length, null, 'opponent');
  }

  addLog(`[Efecto Analizar datos BBX-SP337 Rival] El rival envió a <strong>${charCard.nombre}</strong> (Slot ${chosenSlotIdx + 1}) a su banca.${removedSkills.length > 0 ? ` Sus ${removedSkills.length} Skill(s) portadas fueron enviadas al cementerio.` : ''}`, 'var(--accent-purple)');

  // 4. Entonces roba 3 cartas del deck rival
  const drawn = [];
  for (let i = 0; i < 3; i++) {
    if (playtestState.opponentDeck.length > 0) {
      const dId = playtestState.opponentDeck.shift();
      playtestState.opponentHand.push(dId);
      drawn.push(dId);
    }
  }
  const drawnNames = drawn.map(dId => cardsDatabase[dId]?.nombre || dId);
  addLog(`[Efecto Analizar datos BBX-SP337 Rival] El rival robó 3 cartas de su deck: <strong>${drawnNames.join(', ')}</strong>.`, 'var(--accent-purple)');

  checkAndTriggerServicioImpecable('opponent', 'skill');
  updatePlaytestView();
}

function activateOpponentBorealInsidiosa(slotIndex, skIndex) {
  const oppSlot = playtestState.opponentSlots[slotIndex];
  if (!oppSlot || !oppSlot.skills) return;
  const skIdxInSlot = (typeof skIndex === 'number' && skIndex >= 0) ? skIndex : oppSlot.skills.indexOf('BBX-SP284');
  if (skIdxInSlot === -1) return;

  if (playtestState.opponentBorealInsidiosaUsedThisTurn) {
    alert("El rival ya usó el efecto de Boreal insidiosa este turno.");
    return;
  }

  const isCarrierEishet = oppSlot.character && cardsDatabase[oppSlot.character] && cardsDatabase[oppSlot.character].nombre.includes("Eishet");
  const willCarrierHaveNoSkills = isCarrierEishet && oppSlot.skills.length === 1;
  const otherEishetsNoSkills = playtestState.opponentSlots.filter(s => s !== oppSlot && s.character && cardsDatabase[s.character] && cardsDatabase[s.character].nombre.includes("Eishet") && (!s.skills || s.skills.length === 0)).length;
  const totalOppEishetsSinSkills = otherEishetsNoSkills + (willCarrierHaveNoSkills ? 1 : 0);

  if (totalOppEishetsSinSkills === 0) {
    alert("El rival no controla ningún Personaje Eishet que vaya a quedar sin Skills portadas.");
    return;
  }

  if (playtestState.opponentDeck.length < totalOppEishetsSinSkills) {
    alert(`El rival no tiene suficientes cartas en su deck para robar obligatoriamente ${totalOppEishetsSinSkills} carta(s).`);
    return;
  }

  if (totalOppEishetsSinSkills >= 2 && isVoidOhActive()) {
    alert("Efecto bloqueado por la regla continua de Void-oh (BBX-SP308): Ningún jugador puede robar 2 o más cartas por efectos de cartas en el campo.");
    return;
  }

  if (isDrawBySkillBlocked('opponent', totalOppEishetsSinSkills)) {
    alert("El robo de cartas por efecto de Skill está bloqueado para el rival este turno.");
    return;
  }

  playtestState.opponentBorealInsidiosaUsedThisTurn = true;

  // Paso 1: Enviar Boreal insidiosa al cementerio rival
  const removedId = oppSlot.skills.splice(skIdxInSlot, 1)[0];
  playtestState.opponentGrave.push(removedId);
  addLog(`[Efecto Boreal insidiosa BBX-SP284 Rival] El rival envió <strong>${cardsDatabase[removedId].nombre}</strong> a su cementerio.`, 'var(--accent-purple)');
  onEquippedSkillSentToGraveByEffect(removedId, 'opponent', 'opponent');
  checkAndTriggerRemembranza(removedId, 'opponent');

  // Paso 2: Robar exactamente 1 carta por cada Personaje Eishet rival sin Skills
  const oppEishetsSinSkillsActual = playtestState.opponentSlots.filter(s => s.character && cardsDatabase[s.character] && cardsDatabase[s.character].nombre.includes("Eishet") && (!s.skills || s.skills.length === 0)).length;

  const drawnNames = [];
  for (let i = 0; i < oppEishetsSinSkillsActual; i++) {
    const drawnId = playtestState.opponentDeck.shift();
    playtestState.opponentHand.push(drawnId);
    drawnNames.push(cardsDatabase[drawnId].nombre);
  }
  addLog(`[Efecto Boreal insidiosa BBX-SP284 Rival] El rival controla ${oppEishetsSinSkillsActual} Personaje(s) Eishet sin Skills. Robó ${drawnNames.length} carta(s) de su deck: <strong>${drawnNames.join(', ')}</strong>.`, 'var(--accent-purple)');
  checkAndTriggerServicioImpecable('opponent', 'skill');
  updatePlaytestView();
}

