  // Marina BBX-SP186: Al final del turno de cualquier jugador, puedes enviar esta carta en tu mano al cementerio, entonces, puedes enviar al cementerio 1 Skill portada.
  if (card.id === 'BBX-SP186') {
    const targetableSkills = getAvailableTargetableSkillsForMarina();
    const canActivate = targetableSkills.length > 0;

    items.push({
      text: '⚡ Activar Marina (Enviar 1 Skill portada al cementerio)',
      disabled: !canActivate,
      action: () => {
        const cardEl = document.getElementById(`hand-card-${index}`);
        runActivationAnimation(cardEl, () => {
          const discardedId = playtestState.hand.splice(index, 1)[0];
          playtestState.grave.push(discardedId);
          addLog(`[Efecto Marina SP186] Enviaste a Marina desde tu mano al cementerio.`, 'var(--accent-purple)');

          checkAndTriggerAlBorde(discardedId);
          checkAndTriggerReflejo(discardedId);
          checkAndTriggerEstrategia(discardedId);
          checkAndTriggerHackeo(discardedId);
          checkAndTriggerLlamarada(discardedId);
          checkAndTriggerEspiral(discardedId);
          checkAndTriggerFirewall(discardedId);
          checkAndTriggerFervor(discardedId);
          checkAndTriggerApunteIgneo(discardedId);
          checkAndTriggerCrimenNocturno(discardedId);
          checkAndTriggerAlmacenamientoFallido(discardedId, 'hand');
          checkAndTriggerKatshi159(discardedId);
          checkAndTriggerFulgorOfensivo(discardedId);
          checkAndTriggerEspiralDigital(discardedId, 'hand');
          checkAndTriggerBolaDeFuego(discardedId, 'hand');

          const currentSkills = getAvailableTargetableSkillsForMarina();
          if (currentSkills.length === 0) {
            updatePlaytestView();
            return;
          }

          const removeSingleSkill = (targetItem) => {
            const doRemove = () => {
              const slot = (targetItem.owner === 'player') ? playtestState.slots[targetItem.slotIndex] : playtestState.opponentSlots[targetItem.slotIndex];
              const removedId = slot.skills.splice(targetItem.skillIndex, 1)[0];
              if (targetItem.owner === 'player') {
                playtestState.grave.push(removedId);
              } else {
                playtestState.opponentGrave.push(removedId);
              }
              addLog(`[Efecto Marina SP186] Enviaste al cementerio "${cardsDatabase[removedId].nombre}" de ${targetItem.charName} (${targetItem.owner === 'player' ? 'Tú' : 'Rival'}).`, 'var(--accent-purple)');

              checkAndTriggerSupportPlan(removedId);
              checkAndTriggerDesechos(removedId);
              checkAndTriggerSplash(removedId);
              checkAndTriggerArremetida(removedId);
              checkAndTriggerCargaSorpresa(removedId);
              checkAndTriggerRomperElPiso(removedId);
              checkAndTriggerReflejo(removedId);
              checkAndTriggerFulgorOfensivo(removedId);
              checkAndTriggerRemembranza(removedId, targetItem.owner);

              updatePlaytestView();
              checkAndTriggerTempanoCertero(1);
            };

            if (targetItem.owner === 'opponent') {
              checkAndProtectSendSkillsToGrave('opponent', () => {
                updatePlaytestView();
              }, () => {
                doRemove();
              });
            } else {
              doRemove();
            }
          };

          if (currentSkills.length === 1) {
            removeSingleSkill(currentSkills[0]);
          } else {
            const chooserTargets = currentSkills.map(item => ({
              id: item.id,
              owner: item.owner,
              text: `"${cardsDatabase[item.id].nombre}" (de ${item.charName} - ${item.owner === 'player' ? 'Tú' : 'Rival'})`
            }));

            openCardChooserModal(chooserTargets, "Marina: Selecciona 1 Skill portada para enviar al cementerio", (chosenIdx) => {
              removeSingleSkill(currentSkills[chosenIdx]);
            });
          }
        });
      }
    });
  }

  // ¡Tropiezo! BBX-SP213: Al final del turno de tu adversario, si este controla 1 Personaje con 4 o más Skills: puedes enviar esta carta en tu mano al cementerio, entonces tu adversario debe barajar al deck 2 Skills portadas en su campo.
  if (card.id === 'BBX-SP213') {
    const isHandBlocked = typeof isSkillHandEffectBlocked === 'function' && isSkillHandEffectBlocked('player');
    if (!isHandBlocked) {
      const isOppTurn = playtestState.turnOwner === 'opponent';
      const oppHasCharWith4Skills = playtestState.opponentSlots.some(s => s.character && s.skills && s.skills.length >= 4);
      const getOpponentTargetableSkills = () => {
        const list = [];
        playtestState.opponentSlots.forEach((s, sIdx) => {
          if (s.character) {
            const cName = cardsDatabase[s.character].nombre;
            s.skills.forEach((skId, skIdx) => {
              if (canRemoveSkillByEffect(skId, true, 'player', s)) {
                list.push({ id: skId, slotIndex: sIdx, skillIndex: skIdx, charName: cName, text: `"${cardsDatabase[skId].nombre}" (de ${cName})` });
              }
            });
          }
        });
        return list;
      };
      const targetableSkills = getOpponentTargetableSkills();
      const canActivate = isOppTurn && oppHasCharWith4Skills && targetableSkills.length >= 2;

      items.push({
        text: '⚡ Activar ¡Tropiezo! (Rival baraja 2 Skills portadas)',
        disabled: !canActivate,
        action: () => {
          const cardEl = document.getElementById(`hand-card-${index}`);
          runActivationAnimation(cardEl, () => {
          const discardedId = playtestState.hand.splice(index, 1)[0];
          playtestState.grave.push(discardedId);
          addLog(`[Efecto ¡Tropiezo!] Enviaste a ¡Tropiezo! desde tu mano al cementerio.`, 'var(--accent-purple)');

          checkAndTriggerAlBorde(discardedId);
          checkAndTriggerReflejo(discardedId);
          checkAndTriggerEstrategia(discardedId);
          checkAndTriggerHackeo(discardedId);
          checkAndTriggerLlamarada(discardedId);
          checkAndTriggerEspiral(discardedId);
          checkAndTriggerFirewall(discardedId);
          checkAndTriggerFervor(discardedId);
          checkAndTriggerApunteIgneo(discardedId);
          checkAndTriggerCrimenNocturno(discardedId);
          checkAndTriggerAlmacenamientoFallido(discardedId, 'hand');
          checkAndTriggerKatshi159(discardedId);
          checkAndTriggerFulgorOfensivo(discardedId);
          checkAndTriggerEspiralDigital(discardedId, 'hand');
          checkAndTriggerBolaDeFuego(discardedId, 'hand');
          checkAndTriggerKatshi205(discardedId);

          const currentTargetable = getOpponentTargetableSkills();
          if (currentTargetable.length < 2) {
            addLog(`[Efecto ¡Tropiezo!] Ya no hay al menos 2 Skills portadas del rival para barajar.`, 'var(--text-muted)');
            updatePlaytestView();
            return;
          }

          const executeShuffle = (selectedItems) => {
            const proceedShuffle = () => {
              const removalsBySlot = {};
              const logs = [];

              selectedItems.forEach(item => {
                if (!removalsBySlot[item.slotIndex]) removalsBySlot[item.slotIndex] = [];
                removalsBySlot[item.slotIndex].push(item.skillIndex);
              });

              Object.keys(removalsBySlot).forEach(sIdxStr => {
                const sIdx = parseInt(sIdxStr);
                const indices = removalsBySlot[sIdx].sort((a, b) => b - a);
                const oSlot = playtestState.opponentSlots[sIdx];
                indices.forEach(skIdx => {
                  const removedId = oSlot.skills.splice(skIdx, 1)[0];
                  playtestState.opponentDeck.push(removedId);
                  logs.push(`"${cardsDatabase[removedId].nombre}"`);
                });
              });

              shuffleArray(playtestState.opponentDeck);
              addLog(`[Efecto ¡Tropiezo!] Tu adversario barajó 2 Skills portadas a su deck: ${logs.join(', ')}.`, 'var(--accent-purple)');
              updatePlaytestView();
              notifySkillsRemovedByEffect(2);
            };

            if (playtestState.opponentHand.includes('BBX-SP180')) {
              const itemsRyu = [
                {
                  text: "🛡️ Activar Ryu-chan (SP180) del rival (Enviar al cementerio en su lugar)",
                  action: () => {
                    const rIdx = playtestState.opponentHand.indexOf('BBX-SP180');
                    if (rIdx !== -1) {
                      const discardedRyu = playtestState.opponentHand.splice(rIdx, 1)[0];
                      playtestState.opponentGrave.push(discardedRyu);
                      addLog(`[Efecto Ryu-chan SP180] El adversario descartó a Ryu-chan de su mano al cementerio. Sus Skills portadas fueron protegidas de ser barajadas al deck.`, 'var(--accent-purple)');
                    }
                    updatePlaytestView();
                  }
                },
                {
                  text: "❌ No activar Ryu-chan (Permitir barajar las Skills)",
                  action: () => {
                    proceedShuffle();
                  }
                }
              ];
              const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
              showContextMenu(dummyEvent, itemsRyu);
            } else {
              proceedShuffle();
            }
          };

          if (currentTargetable.length === 2) {
            executeShuffle(currentTargetable);
          } else {
            const chooserTargets = currentTargetable.map(item => ({
              id: item.id,
              owner: 'opponent',
              text: item.text
            }));

            openMultiCardChooserModal(chooserTargets, "¡Tropiezo!: Tu adversario debe seleccionar 2 Skills portadas para barajar", 2, (chosenIndices) => {
              const selectedItems = chosenIndices.map(idx => currentTargetable[idx]);
              executeShuffle(selectedItems);
            });
          }
        });
      }
    });
    }
  }

  // Sophia BBX-SP190: Puedes enviar esta carta en tu mano al cementerio; porta 1 Skill "Dirigir el caos" a un Personaje que controles directamente desde tu deck o cementerio.
  if (card.id === 'BBX-SP190') {
    const isBannedByNobuko = isSkillBannedFromEquip('BBX-SP064');
    const availableCopies = [];

    playtestState.deck.forEach(cId => {
      if (cardsDatabase[cId] && cardsDatabase[cId].nombre === 'Dirigir el caos') {
        availableCopies.push({ id: cId, from: 'deck' });
      }
    });

    playtestState.grave.forEach(cId => {
      if (cardsDatabase[cId] && cardsDatabase[cId].nombre === 'Dirigir el caos') {
        availableCopies.push({ id: cId, from: 'grave' });
      }
    });

    const hasControlledCharacter = playtestState.slots.some(s => s.character);
    const canActivate = isPlayerTurn && hasControlledCharacter && availableCopies.length > 0 && !isBannedByNobuko;

    let btnText = '⚡ Activar Sophia (Portar "Dirigir el caos" desde Deck o Cementerio)';
    if (!isPlayerTurn) {
      btnText = '⚠️ Solo en tu turno (Sophia SP190)';
    }

    items.push({
      text: btnText,
      disabled: !canActivate,
      action: () => {
        if (!isPlayerTurn) return;
        const cardEl = document.getElementById(`hand-card-${index}`);
        runActivationAnimation(cardEl, () => {
          const discardedId = playtestState.hand.splice(index, 1)[0];
          playtestState.grave.push(discardedId);
          addLog(`[Efecto Sophia SP190] Enviaste a Sophia desde tu mano al cementerio.`, 'var(--accent-purple)');

          checkAndTriggerAlBorde(discardedId);
          checkAndTriggerReflejo(discardedId);
          checkAndTriggerEstrategia(discardedId);
          checkAndTriggerHackeo(discardedId);
          checkAndTriggerLlamarada(discardedId);
          checkAndTriggerEspiral(discardedId);
          checkAndTriggerFirewall(discardedId);
          checkAndTriggerFervor(discardedId);
          checkAndTriggerApunteIgneo(discardedId);
          checkAndTriggerCrimenNocturno(discardedId);
          checkAndTriggerAlmacenamientoFallido(discardedId, 'hand');
          checkAndTriggerKatshi159(discardedId);
          checkAndTriggerFulgorOfensivo(discardedId);
          checkAndTriggerEspiralDigital(discardedId, 'hand');
          checkAndTriggerBolaDeFuego(discardedId, 'hand');

          // Recalcular copias disponibles de "Dirigir el caos"
          const currentCopies = [];
          playtestState.deck.forEach(cId => {
            if (cardsDatabase[cId] && cardsDatabase[cId].nombre === 'Dirigir el caos') {
              currentCopies.push({ id: cId, from: 'deck' });
            }
          });
          playtestState.grave.forEach(cId => {
            if (cardsDatabase[cId] && cardsDatabase[cId].nombre === 'Dirigir el caos') {
              currentCopies.push({ id: cId, from: 'grave' });
            }
          });

          if (currentCopies.length === 0) {
            alert("No hay copias de 'Dirigir el caos' en tu deck ni en tu cementerio.");
            updatePlaytestView();
            return;
          }

          const eligibleSlots = playtestState.slots
            .map((slot, sIdx) => ({ slot, sIdx }))
            .filter(item => item.slot.character);

          if (eligibleSlots.length === 0) {
            alert("No controlas ningún personaje para portar la Skill.");
            updatePlaytestView();
            return;
          }

          openCardChooserModal(currentCopies, "Sophia: Selecciona la copia de 'Dirigir el caos' que deseas portar", (chosenCopyIdx) => {
            const chosen = currentCopies[chosenCopyIdx];

            const performEquip = (targetSlotIdx) => {
              let removedSkillId = null;
              if (chosen.from === 'deck') {
                const dIdx = playtestState.deck.indexOf(chosen.id);
                if (dIdx !== -1) {
                  removedSkillId = playtestState.deck.splice(dIdx, 1)[0];
                }
                shuffleArray(playtestState.deck);
              } else {
                const gIdx = playtestState.grave.indexOf(chosen.id);
                if (gIdx !== -1) {
                  removedSkillId = playtestState.grave.splice(gIdx, 1)[0];
                }
              }

              if (!removedSkillId) {
                updatePlaytestView();
                return;
              }

              const targetSlot = playtestState.slots[targetSlotIdx];
              targetSlot.skills.push(removedSkillId);

              const charName = cardsDatabase[targetSlot.character].nombre;
              addLog(`[Efecto Sophia SP190] Equipaste <strong>${cardsDatabase[removedSkillId].nombre}</strong> directamente desde tu ${chosen.from === 'deck' ? 'deck' : 'cementerio'} a ${charName} (Slot ${targetSlotIdx + 1}).${chosen.from === 'deck' ? ' Barajaste tu deck.' : ''}`, 'var(--accent-purple)');

              checkAndTriggerInestabilidad('player');
              updatePlaytestView();
            };

            if (eligibleSlots.length === 1) {
              performEquip(eligibleSlots[0].sIdx);
            } else {
              const subItems = eligibleSlots.map(item => {
                const charName = cardsDatabase[item.slot.character].nombre;
                return {
                  text: `🛡️ Portar a ${charName} (Slot ${item.sIdx + 1})`,
                  action: () => performEquip(item.sIdx)
                };
              });
              const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
              showContextMenu(dummyEvent, subItems);
            }
          });
        });
      }
    });
  }

  // ¡No me rendiré! BBX-SP194: Si no controlas Personajes y tienes 2 o menos cartas en tu mano: puedes jugar 1 Personaje directamente desde tu deck a tu campo, entonces, portale esta Skill desde tu mano.
  if (card.id === 'BBX-SP194') {
    const isHandBlocked = typeof isSkillHandEffectBlocked === 'function' && isSkillHandEffectBlocked('player');
    if (!isHandBlocked) {
      const controlsNoCharacters = playtestState.slots.every(s => !s.character);
      const hasFewCardsInHand = playtestState.hand.length <= 2;
      const isBannedByNobuko = isSkillBannedFromEquip('BBX-SP194');
      const isDeckPlayBlocked = typeof isPlayCharacterFromDeckBlocked === 'function' && isPlayCharacterFromDeckBlocked();
      const availableCharactersInDeck = playtestState.deck.filter(id => cardsDatabase[id] && cardsDatabase[id].tipo === 'Personaje');

      const canActivate = isPlayerTurn && controlsNoCharacters && hasFewCardsInHand && availableCharactersInDeck.length > 0 && !isBannedByNobuko && !isDeckPlayBlocked;

      let btnText = '⚡ Activar ¡No me rendiré! (Jugar Personaje de Deck y portar)';
      if (!isPlayerTurn) {
        btnText = '⚠️ Solo en tu turno (¡No me rendiré!)';
      } else if (isDeckPlayBlocked) {
        btnText = '⚠️ ¡No me rendiré!: Bloqueado por Katherine (BBX-SP350)';
      }

      items.push({
        text: btnText,
        disabled: !canActivate,
        action: () => {
          if (!isPlayerTurn) return;
          if (typeof isPlayCharacterFromDeckBlocked === 'function' && isPlayCharacterFromDeckBlocked()) {
            alert("No se pueden jugar Personajes directamente desde el deck debido al efecto continuo de Katherine (BBX-SP350).");
            return;
          }
          const cardEl = document.getElementById(`hand-card-${index}`);
          runActivationAnimation(cardEl, () => {
            const currentCharsInDeck = playtestState.deck.filter(id => cardsDatabase[id] && cardsDatabase[id].tipo === 'Personaje');
            if (currentCharsInDeck.length === 0) {
              alert("No hay Personajes en tu deck para jugar.");
              return;
            }

            openCardChooserModal(currentCharsInDeck, "¡No me rendiré!: Selecciona 1 Personaje de tu deck para jugar a tu campo", (chosenCharIdx) => {
              const chosenCharId = currentCharsInDeck[chosenCharIdx];
              const charCard = cardsDatabase[chosenCharId];

              const deployToSlot = (slotToUse) => {
                // Retirar el personaje del deck
                const dIdx = playtestState.deck.indexOf(chosenCharId);
                if (dIdx !== -1) {
                  playtestState.deck.splice(dIdx, 1);
                }

                const slot = playtestState.slots[slotToUse];
                slot.character = chosenCharId;
                slot.skills = [];
                slot.usedSkills = [];
                slot.usedSkillIndexes = [];
                slot.isRotated = false;
                slot.effectUsed = false;

                addLog(`[Efecto ¡No me rendiré!] Jugaste a <strong>${charCard.nombre}</strong> directamente desde tu deck al Slot ${slotToUse + 1}.`, 'var(--accent-cyan)');

                // Retirar ¡No me rendiré! de la mano y portarla al personaje
                const hIdx = playtestState.hand.indexOf('BBX-SP194');
                if (hIdx !== -1) {
                  const skillCardId = playtestState.hand.splice(hIdx, 1)[0];
                  slot.skills.push(skillCardId);
                  addLog(`[Efecto ¡No me rendiré!] Portaste <strong>¡No me rendiré!</strong> a <strong>${charCard.nombre}</strong> desde tu mano.`, 'var(--accent-purple)');
                }

                // Barajar el deck
                shuffleArray(playtestState.deck);
                addLog(`[Efecto ¡No me rendiré!] Barajaste tu deck.`, 'var(--text-muted)');

                checkAndTriggerInestabilidad('player');
                if (typeof notifyCharacterPlayedDirectlyFromDeck === 'function') {
                  notifyCharacterPlayedDirectlyFromDeck('player', chosenCharId, slotToUse);
                }
                updatePlaytestView();
              };

              const slotItems = [0, 1, 2].map(sIdx => ({
                text: `📍 Jugar en Slot ${sIdx + 1}`,
                action: () => deployToSlot(sIdx)
              }));
              const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
              showContextMenu(dummyEvent, slotItems);
            });
          });
        }
      });
    }
  }

  // Estocada de cristal BBX-SP197: Puedes enviar esta carta en tu mano al cementerio, entonces 1 Personaje Avanzado Helica que controles puede realizar hasta 3 ataques por el resto de este turno.
  if (card.id === 'BBX-SP197') {
    const isHandBlocked = typeof isSkillHandEffectBlocked === 'function' && isSkillHandEffectBlocked('player');
    if (!isHandBlocked) {
      const isHelicaAvanzada = s => s.character && cardsDatabase[s.character].nombre.includes("Helica") && cardsDatabase[s.character].clase === 'Avanzada';
      const eligibleSlots = playtestState.slots
        .map((slot, sIdx) => ({ slot, sIdx }))
        .filter(item => isHelicaAvanzada(item.slot));

      const canActivate = isPlayerTurn && eligibleSlots.length > 0;

      let btnText = '⚡ Activar Estocada de cristal (Helica Avanzada realiza hasta 3 ataques)';
      if (!isPlayerTurn) {
        btnText = '⚠️ Solo en tu turno (Estocada de cristal)';
      }

      items.push({
        text: btnText,
        disabled: !canActivate,
        action: () => {
          if (!isPlayerTurn) return;
          const cardEl = document.getElementById(`hand-card-${index}`);
          runActivationAnimation(cardEl, () => {
            const applyBuffToSlot = (targetSlotIdx) => {
              const discardedId = playtestState.hand.splice(index, 1)[0];
              playtestState.grave.push(discardedId);
              addLog(`[Efecto Estocada de cristal] Enviaste a Estocada de cristal desde tu mano al cementerio.`, 'var(--accent-purple)');

              const targetSlot = playtestState.slots[targetSlotIdx];
              targetSlot.maxAttacks = 3;
              const charCard = cardsDatabase[targetSlot.character];

              addLog(`[Efecto Estocada de cristal] <strong>${charCard.nombre} (${charCard.evolucion || 'Avanzada'})</strong> ahora puede realizar hasta 3 ataques por el resto de este turno.`, 'var(--accent-purple)');

              updatePlaytestView();
            };

            if (eligibleSlots.length === 1) {
              applyBuffToSlot(eligibleSlots[0].sIdx);
            } else {
              const subItems = eligibleSlots.map(item => {
                const charCard = cardsDatabase[item.slot.character];
                return {
                  text: `🗡️ Aplicar a ${charCard.nombre} (${charCard.evolucion || 'Avanzada'}) - Slot ${item.sIdx + 1}`,
                  action: () => applyBuffToSlot(item.sIdx)
                };
              });
              const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
              showContextMenu(dummyEvent, subItems);
            }
          });
        }
      });
    }
  }

