// Encuentro imprevisto (BBX-SP338): Durante el turno de tu adversario, si 1 Personaje que controles es destruido por una batalla mientras esta carta esté en tu cementerio, puedes recuperar a tu mano 1 carta en tu cementerio. Solo puedes usar este efecto de "Encuentro imprevisto" una vez por turno.
function checkAndTriggerEncuentroImprevistoPlayer() {
  if (playtestState.turnOwner !== 'opponent') return;
  if (!playtestState.grave.includes('BBX-SP338')) return;
  if (isCardGraveEffectBlocked('player', 'BBX-SP338')) return;
  if ((playtestState.usedGlobalEffects || []).includes("Encuentro imprevisto")) return;
  if (isGraveToHandBlocked()) return;
  if (typeof isAislamientoActive === 'function' && isAislamientoActive()) return;
  if (playtestState.grave.length === 0) return;

  const menu = document.getElementById('card-context-menu');
  if (menu && !menu.classList.contains('hidden')) {
    setTimeout(checkAndTriggerEncuentroImprevistoPlayer, 300);
    return;
  }

  const items = [
    {
      text: "💥 No activar Encuentro imprevisto",
      action: () => {
        // No hace nada
      }
    },
    {
      text: "✨ Activar \"Encuentro imprevisto\" (Recuperar 1 carta de tu cementerio a tu mano)",
      action: () => {
        if ((playtestState.usedGlobalEffects || []).includes("Encuentro imprevisto")) return;
        if (isGraveToHandBlocked()) return;
        if (playtestState.grave.length === 0) return;

        playtestState.usedGlobalEffects = playtestState.usedGlobalEffects || [];
        playtestState.usedGlobalEffects.push("Encuentro imprevisto");

        const graveTargets = playtestState.grave.map((id, idx) => ({
          id,
          owner: 'player',
          from: 'grave',
          indexInGrave: idx
        }));

        openCardChooserModal(graveTargets, "Encuentro imprevisto: Selecciona 1 carta de tu cementerio para recuperar a tu mano", (chosenIdx) => {
          const chosenTarget = graveTargets[chosenIdx];
          const targetId = chosenTarget ? chosenTarget.id : playtestState.grave[chosenIdx];
          const actualIdx = playtestState.grave.indexOf(targetId);
          if (actualIdx !== -1) {
            const cardId = playtestState.grave.splice(actualIdx, 1)[0];
            playtestState.hand.push(cardId);
            const cardObj = cardsDatabase[cardId];
            addLog(`[Efecto Encuentro imprevisto BBX-SP338] Recuperaste a <strong>${cardObj ? cardObj.nombre : cardId}</strong> de tu cementerio a tu mano.`, 'var(--accent-purple)');
            updatePlaytestView();
            notifySkillInGraveEffectUsed('player');
          }
        });
      }
    }
  ];

  const dummyEvent = { clientX: window.innerWidth / 2 - 140, clientY: window.innerHeight / 2 - 80 };
  showContextMenu(dummyEvent, items);
}

