function checkCuentaAtrasOrProceed(nextCallback) {
  if (!playtestState.cuentaAtrasList || playtestState.cuentaAtrasList.length === 0) {
    nextCallback();
    return;
  }

  const remaining = [];
  const triggered = [];
  const currentTurn = playtestState.turnCount || 1;

  playtestState.cuentaAtrasList.forEach(cd => {
    if (!playtestState.isOnlineMatch || cd.lastIncrementedTurn !== currentTurn) {
      cd.turnsElapsed = (cd.turnsElapsed || 0) + 1;
      cd.lastIncrementedTurn = currentTurn;
    }
    if (cd.turnsElapsed >= (cd.targetTurns || 10)) {
      if (playtestState.isOnlineMatch && cd.activator === 'player') {
        // El rival es quien debe elegir 1 Personaje propio para mandar a su banca cuando reciba el estado / fin de turno
        remaining.push(cd);
      } else {
        triggered.push(cd);
      }
    } else {
      remaining.push(cd);
      if (!playtestState.isOnlineMatch || playtestState.turnOwner === 'player') {
        addLog(`⏳ [Cuenta atrás BBX-SP301] Fin del turno: el contador de Cuenta atrás (${cd.activator === 'player' ? 'Jugador' : 'Rival'}) pasa a <strong>${cd.turnsElapsed}/${cd.targetTurns || 10}</strong>.`, 'var(--accent-cyan)');
      }
    }
  });

  playtestState.cuentaAtrasList = remaining;

  if (triggered.length === 0) {
    nextCallback();
    return;
  }

  const runTriggered = (idx) => {
    if (idx >= triggered.length) {
      nextCallback();
      return;
    }
    const item = triggered[idx];
    addLog(`⏰ [Cuenta atrás BBX-SP301] ¡Fin del turno ${item.turnsElapsed}! Se ejecuta la resolución de Cuenta atrás (${item.activator === 'player' ? 'Jugador' : 'Rival'}).`, 'var(--accent-warning)');
    resolveCuentaAtras(item.activator, () => {
      runTriggered(idx + 1);
    });
  };

  runTriggered(0);
}

// Roy BBX-SP339: [Requisito: 1 o más Skills] Una vez por turno, puedes enviar al cementerio desde tu mano o deck 1 Skill que no sea propia de Roy, entonces al final de este turno agrega 1 Skill propia de Roy o 1 Personaje Roy de tu deck a tu mano.
function checkRoy339OrProceed(nextCallback) {
  // 1. Resolver búsqueda pendiente del Jugador
  if (playtestState.pendingRoy339SearchPlayer && playtestState.pendingRoy339SearchPlayer > 0) {
    playtestState.pendingRoy339SearchPlayer--;
    const isRoyTarget = id => {
      const c = cardsDatabase[id];
      return c && ((c.tipo === 'Personaje' && c.nombre.includes("Roy")) || (c.tipo === 'Skill' && c.portador === 'Roy'));
    };
    const eligibleCards = playtestState.deck.filter(isRoyTarget);

    if (eligibleCards.length === 0) {
      addLog(`[Efecto Roy BBX-SP339] Al final de este turno se resolvió el efecto de Roy, pero no quedan Personajes Roy ni Skills propias de Roy en tu deck.`, 'var(--text-muted)');
      updatePlaytestView();
      checkRoy339OrProceed(nextCallback);
      return;
    }

    const chooserTargets = eligibleCards.map(id => ({ id, owner: 'player', from: 'deck' }));
    openCardChooserModal(chooserTargets, "Roy BBX-SP339 (Fin de Turno): Selecciona 1 Skill de Roy o Personaje Roy de tu deck", (chosenIdx) => {
      const chosenId = eligibleCards[chosenIdx];
      const dIdx = playtestState.deck.indexOf(chosenId);
      if (dIdx !== -1) {
        playtestState.deck.splice(dIdx, 1);
      }
      playtestState.hand.push(chosenId);
      shuffleArray(playtestState.deck);
      addLog(`[Efecto Roy BBX-SP339] Al final del turno agregaste a <strong>${cardsDatabase[chosenId].nombre}</strong> de tu deck a tu mano y barajaste el mazo.`, 'var(--accent-purple)');
      checkAndTriggerInestabilidad('player');
      updatePlaytestView();
      checkRoy339OrProceed(nextCallback);
    });
    return;
  }

  // 2. Resolver búsqueda pendiente del Rival
  if (!playtestState.isOnlineMatch && playtestState.pendingRoy339SearchOpponent && playtestState.pendingRoy339SearchOpponent > 0) {
    playtestState.pendingRoy339SearchOpponent--;
    const isRoyTarget = id => {
      const c = cardsDatabase[id];
      return c && ((c.tipo === 'Personaje' && c.nombre.includes("Roy")) || (c.tipo === 'Skill' && c.portador === 'Roy'));
    };
    const oppEligibleCards = playtestState.opponentDeck.filter(isRoyTarget);

    if (oppEligibleCards.length === 0) {
      addLog(`[Efecto Roy BBX-SP339 Rival] Al final de este turno se resolvió el efecto de Roy, pero no quedan Personajes Roy ni Skills propias de Roy en el deck rival.`, 'var(--text-muted)');
      updatePlaytestView();
      checkRoy339OrProceed(nextCallback);
      return;
    }

    const chooserTargets = oppEligibleCards.map(id => ({ id, owner: 'opponent', from: 'deck' }));
    openCardChooserModal(chooserTargets, "[Rival] Roy BBX-SP339 (Fin de Turno): Selecciona 1 Skill de Roy o Personaje Roy del deck rival", (chosenIdx) => {
      const chosenId = oppEligibleCards[chosenIdx];
      const dIdx = playtestState.opponentDeck.indexOf(chosenId);
      if (dIdx !== -1) {
        playtestState.opponentDeck.splice(dIdx, 1);
      }
      playtestState.opponentHand.push(chosenId);
      shuffleArray(playtestState.opponentDeck);
      addLog(`[Efecto Roy BBX-SP339 Rival] Al final del turno el rival agregó a <strong>${cardsDatabase[chosenId].nombre}</strong> de su deck a su mano y barajó su deck.`, 'var(--accent-purple)');
      checkAndTriggerInestabilidad('opponent');
      updatePlaytestView();
      checkRoy339OrProceed(nextCallback);
    });
    return;
  }

  nextCallback();
}

// Planificar BBX-SP342: Puedes enviar 1 Skill portada en tu campo al cementerio excepto "Planificar" y entonces al final of este turno puedes agregar 1 Personaje de tu deck a tu mano (Esta carta debe permanecer portada al final del turno para resolver este efecto). Solo puedes usar este efecto de "Planificar" una vez por turno.
function checkPlanificar342OrProceed(nextCallback) {
  if (!playtestState.pendingPlanificar342List || playtestState.pendingPlanificar342List.length === 0) {
    nextCallback();
    return;
  }

  let itemIdx = 0;
  if (playtestState.isOnlineMatch) {
    itemIdx = playtestState.pendingPlanificar342List.findIndex(it => it && it.owner === 'player');
    if (itemIdx === -1) {
      nextCallback();
      return;
    }
  }

  const item = playtestState.pendingPlanificar342List.splice(itemIdx, 1)[0];
  const isPlayer = item.owner === 'player';
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;
  const targetSlot = slots[item.slotIndex];

  // Comprobar la condición de permanencia:
  // "(Esta carta debe permanecer portada al final del turno para resolver este efecto)"
  const isStillEquipped = targetSlot && targetSlot.character && targetSlot.skills && targetSlot.skills.includes('BBX-SP342');

  if (!isStillEquipped) {
    addLog(`[Efecto Planificar BBX-SP342 ${isPlayer ? '' : 'Rival'}] Al final del turno, el efecto de Planificar <strong>no se resolvió</strong> porque la carta ya no se encuentra portada en el campo.`, 'var(--text-muted)');
    updatePlaytestView();
    checkPlanificar342OrProceed(nextCallback);
    return;
  }

  const currentDeck = isPlayer ? playtestState.deck : playtestState.opponentDeck;
  const eligibleCharacters = currentDeck.filter(id => cardsDatabase[id]?.tipo === 'Personaje');

  if (eligibleCharacters.length === 0) {
    addLog(`[Efecto Planificar BBX-SP342 ${isPlayer ? '' : 'Rival'}] Al final de este turno se resolvió el efecto de Planificar, pero no quedan Personajes en el deck ${isPlayer ? '' : 'rival'}.`, 'var(--text-muted)');
    updatePlaytestView();
    checkPlanificar342OrProceed(nextCallback);
    return;
  }

  const chooserTargets = eligibleCharacters.map(id => ({
    id,
    owner: isPlayer ? 'player' : 'opponent',
    from: 'deck'
  }));

  const modalTitle = isPlayer
    ? "Planificar BBX-SP342 (Fin de Turno): Selecciona 1 Personaje de tu deck para agregar a tu mano"
    : "[Rival] Planificar BBX-SP342 (Fin de Turno): Selecciona 1 Personaje del deck rival para agregar a su mano";

  openCardChooserModal(chooserTargets, modalTitle, (chosenIdx) => {
    const chosenId = eligibleCharacters[chosenIdx];
    const deckArr = isPlayer ? playtestState.deck : playtestState.opponentDeck;
    const dIdx = deckArr.indexOf(chosenId);
    if (dIdx !== -1) {
      deckArr.splice(dIdx, 1);
    }
    const handArr = isPlayer ? playtestState.hand : playtestState.opponentHand;
    handArr.push(chosenId);
    shuffleArray(deckArr);
    addLog(`[Efecto Planificar BBX-SP342 ${isPlayer ? '' : 'Rival'}] Al final del turno ${isPlayer ? 'agregaste' : 'el rival agregó'} a <strong>${cardsDatabase[chosenId].nombre}</strong> de su deck a su mano y barajó su mazo.`, 'var(--accent-purple)');
    checkAndTriggerInestabilidad(isPlayer ? 'player' : 'opponent');
    updatePlaytestView();
    checkPlanificar342OrProceed(nextCallback);
  });
}

// ==========================================
// BBX-SP302 Vacío:
// "Una vez por turno, puedes declarar el nombre de 1 Skill, tu adversario revela su mano and si la Skill declarada se encuentra en su mano, enviala al cementerio, entonces puedes agregar a tu mano desde tu deck 1 Skill con el mismo nombre."
// ==========================================
function activatePlayerVacio(slotIndex, skIndex) {
  const slot = playtestState.slots[slotIndex];
  if (!slot) return;

  slot.usedSkills = slot.usedSkills || [];
  slot.usedSkills.push('BBX-SP302');
  if (typeof skIndex === 'number' && skIndex >= 0) {
    slot.usedSkillIndexes = slot.usedSkillIndexes || [];
    slot.usedSkillIndexes.push(skIndex);
  }

  openSkillDeclarationModal("Vacío (BBX-SP302): Declara el nombre de 1 Skill", (declaredSkill) => {
    const declaredName = declaredSkill.nombre;
    addLog(`[Efecto Vacío BBX-SP302] Declaraste la Skill: <strong>${declaredName}</strong>.`, 'var(--accent-purple)');

    const oppHand = playtestState.opponentHand.slice();
    const chooserTargets = oppHand.map(id => ({ id, owner: 'opponent' }));
    const matchingCardId = oppHand.find(id => cardsDatabase[id] && cardsDatabase[id].nombre === declaredName);

    if (!matchingCardId) {
      // No contiene la Skill declarada
      openCardChooserModal(chooserTargets, `Vacío: Mano del rival revelada (No contiene "${declaredName}")`, () => {
        addLog(`[Efecto Vacío BBX-SP302] Tu adversario reveló su mano (${oppHand.length} carta${oppHand.length > 1 ? 's' : ''}). No contiene la Skill <strong>${declaredName}</strong>.`, 'var(--text-muted)');
        updatePlaytestView();
      });
    } else {
      // Contiene la Skill declarada
      openCardChooserModal(chooserTargets, `Vacío: ¡Acierto! Mano revelada (Contiene "${declaredName}")`, () => {
        const realIdx = playtestState.opponentHand.indexOf(matchingCardId);
        if (realIdx !== -1) {
          playtestState.opponentHand.splice(realIdx, 1);
        }
        playtestState.opponentGrave.push(matchingCardId);
        addLog(`[Efecto Vacío BBX-SP302] Se reveló la mano de tu adversario y la Skill declarada <strong>${declaredName}</strong> fue enviada a su cementerio.`, 'var(--accent-cyan)');

        // Triggers de cementerio por efecto de carta de adversario
        checkAndTriggerRemembranza(matchingCardId, 'opponent');
        checkAndTriggerDesvelo(matchingCardId, 'opponent');
        checkAndTriggerHoraDelTe(matchingCardId, 'opponent');
        if (typeof checkAndTriggerMarinaSP410 === 'function') {
          checkAndTriggerMarinaSP410(matchingCardId, 'player', 'opponent');
        }
        checkAndTriggerDragoFulgor(matchingCardId, 'opponent');

        // "entonces puedes agregar a tu mano desde tu deck 1 Skill con el mismo nombre."
        const matchingInDeck = [];
        playtestState.deck.forEach((id, dIdx) => {
          if (cardsDatabase[id] && cardsDatabase[id].tipo === 'Skill' && cardsDatabase[id].nombre === declaredName) {
            matchingInDeck.push({ id, originalIdx: dIdx });
          }
        });

        if (matchingInDeck.length === 0) {
          addLog(`[Efecto Vacío BBX-SP302] No tienes ninguna copia de <strong>${declaredName}</strong> en tu deck para agregar a tu mano.`, 'var(--text-muted)');
          updatePlaytestView();
        } else {
          const promptOptions = [
            {
              text: `✨ Agregar 1 "${declaredName}" de tu deck a tu mano`,
              action: () => {
                const deckTargets = matchingInDeck.map(item => ({ id: item.id, owner: 'player', from: 'deck' }));
                openCardChooserModal(deckTargets, `Vacío: Selecciona 1 "${declaredName}" para agregar a tu mano`, (chosenIdx) => {
                  const chosenTarget = matchingInDeck[chosenIdx];
                  const realDeckIdx = playtestState.deck.indexOf(chosenTarget.id);
                  if (realDeckIdx !== -1) {
                    playtestState.deck.splice(realDeckIdx, 1);
                    playtestState.hand.push(chosenTarget.id);
                  }
                  shuffleArray(playtestState.deck);
                  addLog(`[Efecto Vacío BBX-SP302] Agregaste 1 <strong>${declaredName}</strong> de tu deck a tu mano y barajaste tu deck.`, 'var(--accent-purple)');
                  checkAndTriggerInestabilidad('player');
                  updatePlaytestView();
                });
              }
            },
            {
              text: `❌ No agregar carta a la mano`,
              action: () => {
                addLog(`[Efecto Vacío BBX-SP302] Decidiste no agregar ninguna copia a tu mano.`, 'var(--text-muted)');
                updatePlaytestView();
              }
            }
          ];
          const dummyEv = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 60 };
          showContextMenu(dummyEv, promptOptions);
        }
      });
    }
  }, () => {
    // Revertir uso si el jugador cierra la ventana de declaración sin elegir
    const idx = slot.usedSkills.indexOf('BBX-SP302');
    if (idx !== -1) slot.usedSkills.splice(idx, 1);
    if (typeof skIndex === 'number' && slot.usedSkillIndexes) {
      const sIdx = slot.usedSkillIndexes.indexOf(skIndex);
      if (sIdx !== -1) slot.usedSkillIndexes.splice(sIdx, 1);
    }
    updatePlaytestView();
  });
}

function activateOpponentVacio(slotIndex, skIndex) {
  const oppSlot = playtestState.opponentSlots[slotIndex];
  if (!oppSlot) return;

  oppSlot.usedSkills = oppSlot.usedSkills || [];
  oppSlot.usedSkills.push('BBX-SP302');
  if (typeof skIndex === 'number' && skIndex >= 0) {
    oppSlot.usedSkillIndexes = oppSlot.usedSkillIndexes || [];
    oppSlot.usedSkillIndexes.push(skIndex);
  }

  openSkillDeclarationModal("[RIVAL] Vacío (BBX-SP302): Declara el nombre de 1 Skill", (declaredSkill) => {
    const declaredName = declaredSkill.nombre;
    addLog(`[Efecto Vacío BBX-SP302 Rival] El rival declaró la Skill: <strong>${declaredName}</strong>.`, 'var(--accent-purple)');

    const playerHand = playtestState.hand.slice();
    const chooserTargets = playerHand.map(id => ({ id, owner: 'player' }));
    const matchingCardId = playerHand.find(id => cardsDatabase[id] && cardsDatabase[id].nombre === declaredName);

    if (!matchingCardId) {
      openCardChooserModal(chooserTargets, `Vacío [Rival]: Tu mano revelada (No contiene "${declaredName}")`, () => {
        addLog(`[Efecto Vacío BBX-SP302 Rival] Revelaste tu mano (${playerHand.length} carta${playerHand.length > 1 ? 's' : ''}). No contiene la Skill <strong>${declaredName}</strong>.`, 'var(--text-muted)');
        updatePlaytestView();
      });
    } else {
      openCardChooserModal(chooserTargets, `Vacío [Rival]: ¡Acierto! Tu mano revelada (Contiene "${declaredName}")`, () => {
        const realIdx = playtestState.hand.indexOf(matchingCardId);
        if (realIdx !== -1) {
          playtestState.hand.splice(realIdx, 1);
        }
        playtestState.grave.push(matchingCardId);
        addLog(`[Efecto Vacío BBX-SP302 Rival] Revelaste tu mano y tu Skill <strong>${declaredName}</strong> fue enviada a tu cementerio.`, 'var(--accent-warning)');

        // Triggers de cementerio para el jugador
        checkAndTriggerRemembranza(matchingCardId, 'player');
        checkAndTriggerDesvelo(matchingCardId, 'player');
        checkAndTriggerHoraDelTe(matchingCardId, 'player');
        if (typeof checkAndTriggerMarinaSP410 === 'function') {
          checkAndTriggerMarinaSP410(matchingCardId, 'opponent', 'player');
        }
        checkAndTriggerDragoFulgor(matchingCardId, 'player');

        // Oponente busca en su deck 1 Skill con el mismo nombre
        const oppMatchingInDeck = playtestState.opponentDeck.filter(id => cardsDatabase[id] && cardsDatabase[id].tipo === 'Skill' && cardsDatabase[id].nombre === declaredName);
        if (oppMatchingInDeck.length === 0) {
          addLog(`[Efecto Vacío BBX-SP302 Rival] El rival no tiene ninguna copia de <strong>${declaredName}</strong> en su deck para agregar.`, 'var(--text-muted)');
          updatePlaytestView();
        } else {
          const oppCardId = oppMatchingInDeck[0];
          const realOppDeckIdx = playtestState.opponentDeck.indexOf(oppCardId);
          if (realOppDeckIdx !== -1) {
            playtestState.opponentDeck.splice(realOppDeckIdx, 1);
          }
          playtestState.opponentHand.push(oppCardId);
          shuffleArray(playtestState.opponentDeck);
          addLog(`[Efecto Vacío BBX-SP302 Rival] El rival agregó 1 <strong>${declaredName}</strong> de su deck a su mano y barajó su deck.`, 'var(--accent-purple)');
          checkAndTriggerInestabilidad('opponent');
          updatePlaytestView();
        }
      });
    }
  }, () => {
    const idx = oppSlot.usedSkills.indexOf('BBX-SP302');
    if (idx !== -1) oppSlot.usedSkills.splice(idx, 1);
    if (typeof skIndex === 'number' && oppSlot.usedSkillIndexes) {
      const sIdx = oppSlot.usedSkillIndexes.indexOf(skIndex);
      if (sIdx !== -1) oppSlot.usedSkillIndexes.splice(sIdx, 1);
    }
    updatePlaytestView();
  });
}

// ==========================================
// BBX-SP304 Reunión:
// "Si tu adversario controla 3 Personajes, puedes robar 3 cartas de tu deck. Solo puedes usar este efecto de "Reunión" una vez por turno."
// ==========================================
function activatePlayerReunion(slotIndex, skIndex) {
  const slot = playtestState.slots[slotIndex];
  if (!slot) return;

  const oppCharsCount = playtestState.opponentSlots.filter(s => s.character).length;
  if (oppCharsCount !== 3) {
    alert("No se cumple el requisito: Tu adversario debe controlar exactamente 3 Personajes.");
    return;
  }

  playtestState.usedGlobalEffects = playtestState.usedGlobalEffects || [];
  if (playtestState.usedGlobalEffects.includes("Reunión")) {
    alert("Solo puedes usar el efecto de 'Reunión' una vez por turno (Límite Global).");
    return;
  }

  if (isDrawBySkillBlocked('player', 3) || playtestState.cannotDrawByEffectsThisTurn || isVoidOhActive()) {
    alert("No puedes robar cartas por efectos de Skill en este momento (bloqueado por efecto o por Void-oh).");
    return;
  }

  if (playtestState.deck.length < 3) {
    alert("No puedes activar 'Reunión': Debes tener al menos 3 cartas en tu deck para poder robar (tienes " + playtestState.deck.length + ").");
    return;
  }

  playtestState.usedGlobalEffects.push("Reunión");
  slot.usedSkills = slot.usedSkills || [];
  slot.usedSkills.push('BBX-SP304');
  if (typeof skIndex === 'number' && skIndex >= 0) {
    slot.usedSkillIndexes = slot.usedSkillIndexes || [];
    slot.usedSkillIndexes.push(skIndex);
  }

  const drawnCards = [];
  for (let i = 0; i < 3; i++) {
    const drawnId = playtestState.deck.shift();
    playtestState.hand.push(drawnId);
    drawnCards.push(cardsDatabase[drawnId].nombre);
  }

  addLog(`[Efecto Reunión BBX-SP304] Tu adversario controla 3 Personajes. Robaste 3 cartas de tu deck: <strong>${drawnCards.join(', ')}</strong>.`, 'var(--accent-purple)');
  updatePlaytestView();
}

function activateOpponentReunion(slotIndex, skIndex) {
  const oppSlot = playtestState.opponentSlots[slotIndex];
  if (!oppSlot) return;

  const playerCharsCount = playtestState.slots.filter(s => s.character).length;
  if (playerCharsCount !== 3) {
    alert("No se cumple el requisito: El jugador debe controlar 3 Personajes.");
    return;
  }

  playtestState.opponentUsedGlobalEffects = playtestState.opponentUsedGlobalEffects || [];
  if (playtestState.opponentUsedGlobalEffects.includes("Reunión")) {
    alert("El rival ya usó el efecto de 'Reunión' este turno (Límite Global).");
    return;
  }

  if (isDrawBySkillBlocked('opponent', 3) || isVoidOhActive()) {
    alert("El rival no puede robar cartas por efecto de Skill (bloqueado por efecto o por Void-oh).");
    return;
  }

  if (playtestState.opponentDeck.length < 3) {
    alert("El rival no tiene suficientes cartas en su deck para robar 3 cartas.");
    return;
  }

  playtestState.opponentUsedGlobalEffects.push("Reunión");
  oppSlot.usedSkills = oppSlot.usedSkills || [];
  oppSlot.usedSkills.push('BBX-SP304');
  if (typeof skIndex === 'number' && skIndex >= 0) {
    oppSlot.usedSkillIndexes = oppSlot.usedSkillIndexes || [];
    oppSlot.usedSkillIndexes.push(skIndex);
  }

  for (let i = 0; i < 3; i++) {
    const drawnId = playtestState.opponentDeck.shift();
    playtestState.opponentHand.push(drawnId);
  }

  addLog(`[Efecto Reunión BBX-SP304 Rival] Controlas 3 Personajes. El rival robó 3 cartas de su deck.`, 'var(--accent-purple)');
  updatePlaytestView();
}

// BBX-SP305 ¡Destello sorpresa!:
// "Una vez por turno, puedes barajar al deck Skills portadas en el campo de tu adversario igual a la cantidad of Personajes Nara y/o Ryu-chan en tu banca."
function activatePlayerDestelloSorpresa(slotIndex, skIndex) {
  const slot = playtestState.slots[slotIndex];
  if (!slot || !slot.character) return;
  const charCard = cardsDatabase[slot.character];
  if (!charCard || !charCard.nombre.includes("Nobuko")) {
    alert("Esta Skill solo puede ser activada si su portador es Nobuko.");
    return;
  }
  slot.usedSkills = slot.usedSkills || [];
  slot.usedSkillIndexes = slot.usedSkillIndexes || [];
  if (slot.usedSkills.includes('BBX-SP305') || slot.usedSkillIndexes.includes(skIndex)) {
    alert("Ya has usado el efecto de ¡Destello sorpresa! en esta copia este turno.");
    return;
  }
  if (isSkillEffectBlocked('BBX-SP305', 'player', slot)) {
    alert("El efecto de esta Skill está bloqueado.");
    return;
  }
  const benchEligible = playtestState.bench.filter(b => cardsDatabase[b.id] && cardsDatabase[b.id].tipo === 'Personaje' && (cardsDatabase[b.id].nombre.includes("Nara") || cardsDatabase[b.id].nombre.includes("Ryu-chan")));
  if (benchEligible.length === 0) {
    alert("No tienes Personajes Nara y/o Ryu-chan en tu banca.");
    return;
  }

  const oppTargetable = [];
  playtestState.opponentSlots.forEach((s, sIdx) => {
    if (s.character && s.skills && s.skills.length > 0) {
      s.skills.forEach((sk, skIdx) => {
        if (canRemoveSkillByEffect(sk, true, 'player', s, 'deck')) {
          oppTargetable.push({
            id: sk,
            slotIndex: sIdx,
            skillIndex: skIdx,
            owner: 'opponent'
          });
        }
      });
    }
  });

  if (oppTargetable.length === 0) {
    alert("El adversario no tiene Skills portadas que puedan ser barajadas al deck.");
    return;
  }

  const maxQty = Math.min(benchEligible.length, oppTargetable.length);

  openUpToMultiCardChooserModal(oppTargetable, `¡Destello sorpresa!: Selecciona hasta ${maxQty} Skill(s) portadas del adversario para barajar a su deck`, maxQty, (chosenIndices) => {
    slot.usedSkills.push('BBX-SP305');
    slot.usedSkillIndexes.push(skIndex);

    const chosenItems = chosenIndices.map(i => oppTargetable[i]);
    chosenItems.sort((a, b) => {
      if (a.slotIndex !== b.slotIndex) return a.slotIndex - b.slotIndex;
      return b.skillIndex - a.skillIndex;
    });

    const removedNames = [];
    chosenItems.forEach(item => {
      const oppSlot = playtestState.opponentSlots[item.slotIndex];
      let idx = item.skillIndex;
      if (oppSlot.skills[idx] !== item.id) {
        idx = oppSlot.skills.indexOf(item.id);
      }
      if (idx !== -1) {
        const removedSkId = oppSlot.skills.splice(idx, 1)[0];
        playtestState.opponentDeck.push(removedSkId);
        removedNames.push(cardsDatabase[removedSkId].nombre);
      }
    });

    if (removedNames.length > 0) {
      shuffleArray(playtestState.opponentDeck);
      addLog(`[Efecto ¡Destello sorpresa! BBX-SP305] Barajaste al deck del adversario ${removedNames.length} Skill(s) portada(s): <strong>${removedNames.join(', ')}</strong> (tienes ${benchEligible.length} Nara/Ryu-chan en tu banca).`, 'var(--accent-purple)');
      if (typeof notifySkillsRemovedByEffect === 'function') {
        notifySkillsRemovedByEffect(removedNames.length, null, 'player');
      }
    }
    updatePlaytestView();
  });
}

function activateOpponentDestelloSorpresa(slotIndex, skIndex) {
  const oppSlot = playtestState.opponentSlots[slotIndex];
  if (!oppSlot || !oppSlot.character) return;
  const charCard = cardsDatabase[oppSlot.character];
  if (!charCard || !charCard.nombre.includes("Nobuko")) {
    alert("Esta Skill solo puede ser activada si su portador es Nobuko.");
    return;
  }
  oppSlot.usedSkills = oppSlot.usedSkills || [];
  oppSlot.usedSkillIndexes = oppSlot.usedSkillIndexes || [];
  if (oppSlot.usedSkills.includes('BBX-SP305') || oppSlot.usedSkillIndexes.includes(skIndex)) {
    alert("El rival ya ha usado el efecto de ¡Destello sorpresa! en esta copia este turno.");
    return;
  }
  if (isSkillEffectBlocked('BBX-SP305', 'opponent', oppSlot)) {
    alert("El efecto de esta Skill está bloqueado.");
    return;
  }
  const oppBenchEligible = playtestState.opponentBench.filter(b => cardsDatabase[b.id] && cardsDatabase[b.id].tipo === 'Personaje' && (cardsDatabase[b.id].nombre.includes("Nara") || cardsDatabase[b.id].nombre.includes("Ryu-chan")));
  if (oppBenchEligible.length === 0) {
    alert("El rival no tiene Personajes Nara y/o Ryu-chan en su banca.");
    return;
  }

  const playerTargetable = [];
  playtestState.slots.forEach((s, sIdx) => {
    if (s.character && s.skills && s.skills.length > 0) {
      s.skills.forEach((sk, skIdx) => {
        if (canRemoveSkillByEffect(sk, false, 'opponent', s, 'deck')) {
          playerTargetable.push({
            id: sk,
            slotIndex: sIdx,
            skillIndex: skIdx,
            owner: 'player'
          });
        }
      });
    }
  });

  if (playerTargetable.length === 0) {
    alert("No tienes Skills portadas en el campo que puedan ser barajadas al deck.");
    return;
  }

  const maxQty = Math.min(oppBenchEligible.length, playerTargetable.length);

  openUpToMultiCardChooserModal(playerTargetable, `[Rival] ¡Destello sorpresa!: Selecciona hasta ${maxQty} Skill(s) portadas de tu campo para barajar a tu deck`, maxQty, (chosenIndices) => {
    oppSlot.usedSkills.push('BBX-SP305');
    oppSlot.usedSkillIndexes.push(skIndex);

    const chosenItems = chosenIndices.map(i => playerTargetable[i]);
    chosenItems.sort((a, b) => {
      if (a.slotIndex !== b.slotIndex) return a.slotIndex - b.slotIndex;
      return b.skillIndex - a.skillIndex;
    });

    const removedNames = [];
    chosenItems.forEach(item => {
      const pSlot = playtestState.slots[item.slotIndex];
      let idx = item.skillIndex;
      if (pSlot.skills[idx] !== item.id) {
        idx = pSlot.skills.indexOf(item.id);
      }
      if (idx !== -1) {
        const removedSkId = pSlot.skills.splice(idx, 1)[0];
        playtestState.deck.push(removedSkId);
        removedNames.push(cardsDatabase[removedSkId].nombre);
      }
    });

    if (removedNames.length > 0) {
      shuffleArray(playtestState.deck);
      addLog(`[Efecto ¡Destello sorpresa! BBX-SP305 Rival] El rival barajó a tu deck ${removedNames.length} Skill(s) portada(s): <strong>${removedNames.join(', ')}</strong> (el rival tiene ${oppBenchEligible.length} Nara/Ryu-chan en su banca).`, 'var(--accent-purple)');
      if (typeof notifySkillsRemovedByEffect === 'function') {
        notifySkillsRemovedByEffect(removedNames.length, null, 'opponent');
      }
    }
    updatePlaytestView();
  });
}

// BBX-SP306 Depósito secreto:
// "Si tu adversario tiene 15 o más cartas en su cementerio, puedes hacer que tu adversario mande a su banca 1 Personaje desde su mano, deck, cementerio o campo. Solo puedes usar este efecto de "Depósito secreto" una vez por partida."
function activatePlayerDepositoSecreto(slotIndex, skIndex) {
  const slot = playtestState.slots[slotIndex];
  if (!slot || !slot.character) return;
  const charCard = cardsDatabase[slot.character];
  if (!charCard || !charCard.nombre.includes("Chiako")) {
    alert("Esta Skill solo puede ser activada si su portador es Chiako.");
    return;
  }
  if (playtestState.opponentGrave.length < 15) {
    alert("Tu adversario debe tener 15 o más cartas en su cementerio para activar este efecto.");
    return;
  }
  playtestState.usedPerGameEffects = playtestState.usedPerGameEffects || [];
  if (playtestState.usedPerGameEffects.includes('BBX-SP306')) {
    alert("Solo puedes usar el efecto de 'Depósito secreto' una vez por partida.");
    return;
  }
  if (isSkillEffectBlocked('BBX-SP306', 'player', slot)) {
    alert("El efecto de esta Skill está bloqueado.");
    return;
  }

  const options = [];

  // 1. Campo del rival
  playtestState.opponentSlots.forEach((s, sIdx) => {
    if (s.character) {
      options.push({
        id: s.character,
        owner: 'opponent',
        from: 'field',
        slotIndex: sIdx
      });
    }
  });

  // 2. Mano del rival
  playtestState.opponentHand.forEach((hId) => {
    if (cardsDatabase[hId] && cardsDatabase[hId].tipo === 'Personaje') {
      options.push({
        id: hId,
        owner: 'opponent',
        from: 'hand'
      });
    }
  });

  // 3. Cementerio del rival
  playtestState.opponentGrave.forEach((gId) => {
    if (cardsDatabase[gId] && cardsDatabase[gId].tipo === 'Personaje') {
      options.push({
        id: gId,
        owner: 'opponent',
        from: 'grave'
      });
    }
  });

  // 4. Deck del rival (deduplicar IDs únicos para mostrar opciones claras)
  const seenDeckIds = new Set();
  playtestState.opponentDeck.forEach((dId) => {
    if (cardsDatabase[dId] && cardsDatabase[dId].tipo === 'Personaje' && !seenDeckIds.has(dId)) {
      seenDeckIds.add(dId);
      options.push({
        id: dId,
        owner: 'opponent',
        from: 'deck'
      });
    }
  });

  if (options.length === 0) {
    alert("Tu adversario no tiene Personajes en su mano, deck, cementerio o campo.");
    return;
  }

  slot.usedSkills = slot.usedSkills || [];
  slot.usedSkills.push('BBX-SP306');
  if (typeof skIndex === 'number' && skIndex >= 0) {
    slot.usedSkillIndexes = slot.usedSkillIndexes || [];
    slot.usedSkillIndexes.push(skIndex);
  }

  playtestState.usedPerGameEffects.push('BBX-SP306');
  addLog(`[Efecto Depósito secreto BBX-SP306] Activaste el efecto de <strong>Depósito secreto</strong> (1 vez por partida).`, 'var(--accent-purple)');

  openCardChooserModal(options, "Depósito secreto (SP306): Tu adversario selecciona 1 Personaje para mandar a su banca", (chosenIdx) => {
    const chosen = options[chosenIdx];
    const targetCharCard = cardsDatabase[chosen.id];

    if (chosen.from === 'field') {
      const targetSlot = playtestState.opponentSlots[chosen.slotIndex];
      if (targetSlot.skills && targetSlot.skills.length > 0) {
        targetSlot.skills.forEach(sk => playtestState.opponentGrave.push(sk));
        targetSlot.skills = [];
      }
      targetSlot.character = null;
      targetSlot.isRotated = false;
      targetSlot.effectUsed = false;
      playtestState.opponentBench.push({ id: chosen.id, effectUsed: false });
      addLog(`[Efecto Depósito secreto BBX-SP306] Tu adversario mandó a <strong>${targetCharCard.nombre}</strong> de su campo a su banca.`, 'var(--accent-purple)');
    } else if (chosen.from === 'hand') {
      const idxInHand = playtestState.opponentHand.indexOf(chosen.id);
      if (idxInHand !== -1) {
        playtestState.opponentHand.splice(idxInHand, 1);
      }
      playtestState.opponentBench.push({ id: chosen.id, effectUsed: false });
      addLog(`[Efecto Depósito secreto BBX-SP306] Tu adversario mandó a <strong>${targetCharCard.nombre}</strong> de su mano a su banca.`, 'var(--accent-purple)');
    } else if (chosen.from === 'grave') {
      const idxInGrave = playtestState.opponentGrave.indexOf(chosen.id);
      if (idxInGrave !== -1) {
        playtestState.opponentGrave.splice(idxInGrave, 1);
      }
      playtestState.opponentBench.push({ id: chosen.id, effectUsed: false });
      addLog(`[Efecto Depósito secreto BBX-SP306] Tu adversario mandó a <strong>${targetCharCard.nombre}</strong> de su cementerio a su banca.`, 'var(--accent-purple)');
    } else if (chosen.from === 'deck') {
      const idxInDeck = playtestState.opponentDeck.indexOf(chosen.id);
      if (idxInDeck !== -1) {
        playtestState.opponentDeck.splice(idxInDeck, 1);
      }
      playtestState.opponentBench.push({ id: chosen.id, effectUsed: false });
      shuffleArray(playtestState.opponentDeck);
      addLog(`[Efecto Depósito secreto BBX-SP306] Tu adversario mandó a <strong>${targetCharCard.nombre}</strong> de su deck a su banca y barajó su deck.`, 'var(--accent-purple)');
    }

    updatePlaytestView();
  });
}

