// BBX-SP307 ¡Big Win Skill!:
// "Puedes lanzar una moneda, si el resultado es sello, envía esta carta al cementerio. Solo puedes usar este efecto de \"¡Big Win Skill!\" una vez por turno. Si a lo largo de la partida, obtienes 3 caras en los lanzamientos por efecto de \"¡Big Win Skill!\" tú ganas la partida."
function activatePlayerBigWinSkill(slotIndex, skIndex) {
  const slot = playtestState.slots[slotIndex];
  if (!slot || !slot.character) return;
  slot.usedSkills = slot.usedSkills || [];
  slot.usedSkillIndexes = slot.usedSkillIndexes || [];
  if (slot.usedSkills.includes('BBX-SP307') || slot.usedSkillIndexes.includes(skIndex)) {
    alert("Ya has usado el efecto de ¡Big Win Skill! en esta copia este turno.");
    return;
  }
  if (isSkillEffectBlocked('BBX-SP307', 'player', slot)) {
    alert("El efecto de esta Skill está bloqueado.");
    return;
  }

  slot.usedSkills.push('BBX-SP307');
  if (typeof skIndex === 'number' && skIndex >= 0) {
    slot.usedSkillIndexes.push(skIndex);
  }

  addLog(`[Efecto ¡Big Win Skill! BBX-SP307] Activaste el efecto: Lanzando una moneda...`, 'var(--accent-purple)');

  flipCoin((result) => {
    if (result === 'sello') {
      let targetIdx = (typeof skIndex === 'number' && skIndex >= 0) ? skIndex : slot.skills.indexOf('BBX-SP307');
      if (slot.skills[targetIdx] !== 'BBX-SP307') {
        targetIdx = slot.skills.indexOf('BBX-SP307');
      }
      if (targetIdx !== -1) {
        const removedId = slot.skills.splice(targetIdx, 1)[0];
        playtestState.grave.push(removedId);
        addLog(`[Efecto ¡Big Win Skill! BBX-SP307] El resultado fue <strong>SELLO</strong> 🛡️. <strong>¡Big Win Skill!</strong> ha sido enviada al cementerio.`, 'var(--accent-danger)');
        onEquippedSkillSentToGraveByEffect(removedId, 'player', 'player');
      }
      updatePlaytestView();
    } else {
      playtestState.bigWinSkillHeads = (playtestState.bigWinSkillHeads || 0) + 1;
      addLog(`[Efecto ¡Big Win Skill! BBX-SP307] ¡El resultado fue <strong>CARA</strong> 👑! Progreso acumulado: <strong>${playtestState.bigWinSkillHeads}/3</strong> caras.`, 'var(--accent-cyan)');
      if (playtestState.bigWinSkillHeads >= 3) {
        addLog(`🏆🎉 <strong>¡VICTORIA AUTOMÁTICA!</strong> ¡Has obtenido 3 caras a lo largo de la partida por el efecto de "¡Big Win Skill!"! ¡Ganas la partida!`, 'var(--accent-cyan)');
        if (typeof adjustBo3Score === 'function') {
          adjustBo3Score('victories', 1);
        }
        alert("🏆 ¡VICTORIA!\n\n¡Has obtenido 3 caras con el efecto de ¡Big Win Skill! y has ganado la partida automáticamente!");
      }
      updatePlaytestView();
    }
  });
}

