      checkAndTriggerCargaSorpresa(target.id);
      checkAndTriggerRomperElPiso(target.id);
      checkAndTriggerReflejo(target.id);
      checkAndTriggerFulgorOfensivo(target.id);
      checkAndTriggerAlBorde(target.id);
      checkAndTriggerEstrategia(target.id);
      checkAndTriggerHackeo(target.id);
      checkAndTriggerLlamarada(target.id);
      checkAndTriggerEspiral(target.id);
      checkAndTriggerFirewall(target.id);
      checkAndTriggerFervor(target.id);
      checkAndTriggerApunteIgneo(target.id);
      checkAndTriggerCrimenNocturno(target.id);
      checkAndTriggerAlmacenamientoFallido(target.id, 'deck');
      checkAndTriggerKatshi159(target.id);
