          const oppYaUsadoTurno = !!playtestState.opponentUsedSonrisaQueAcecha426ThisTurn || (playtestState.opponentUsedGlobalEffects || []).includes('BBX-SP426') || (playtestState.opponentUsedGlobalEffects || []).includes('Sonrisa que acecha');
          const oppControlsCharacters = playtestState.opponentSlots.some(s => s && s.character);
          const oppEligibleTargetsInDeck = playtestState.opponentDeck.filter(cId => typeof isVoidOhOrEishetCharacter === 'function' && isVoidOhOrEishetCharacter(cId));
          const hasOppEligibleInDeck = oppEligibleTargetsInDeck.length > 0;

