function checkAndTriggerEspiralDigital(cardId, fromZone) {
  if (cardId !== 'BBX-SP170') return;
  if (fromZone !== 'hand' && fromZone !== 'deck') return;

  const hasKatherine = playtestState.slots.some(s => s.character && cardsDatabase[s.character].nombre.includes("Katherine"));
  if (!hasKatherine) return;

  const targetableSkills = [];
  playtestState.opponentSlots.forEach((s, sIdx) => {
    if (s.character) {
      const cName = cardsDatabase[s.character].nombre;
      s.skills.forEach((sk, skIdx) => {
        if (canRemoveSkillByEffect(sk, true, 'player')) {
          targetableSkills.push({
            id: sk,
            slotIndex: sIdx,
            skillIndex: skIdx,
            charName: cName,
            text: `"${cardsDatabase[sk].nombre}" (de ${cName})`
          });
        }
      });
    }
  });

  if (targetableSkills.length === 0) return;

  const items = [
    {
      text: "⚡ Activar Espiral digital (Barajar 1 Skill del rival a su deck)",
      action: () => {
        const executeShuffle = (selected) => {
          const oSlot = playtestState.opponentSlots[selected.slotIndex];
          if (!oSlot || !oSlot.skills) {
            updatePlaytestView();
            return;
          }
          const skRealIdx = oSlot.skills.indexOf(selected.id);
          if (skRealIdx !== -1) {
            const removedSkillId = oSlot.skills.splice(skRealIdx, 1)[0];
            playtestState.opponentDeck.push(removedSkillId);
            shuffleArray(playtestState.opponentDeck);
            addLog(`[Efecto Espiral digital] Barajaste al deck del adversario su Skill portada: <strong>${cardsDatabase[removedSkillId].nombre}</strong> (de ${selected.charName}).`, 'var(--accent-purple)');
          }
          updatePlaytestView();
        };

        if (targetableSkills.length === 1) {
          executeShuffle(targetableSkills[0]);
        } else {
          const chooserTargets = targetableSkills.map(item => ({
            id: item.id,
            owner: 'opponent',
            text: item.text
          }));
          openCardChooserModal(chooserTargets, "Espiral digital: Selecciona 1 Skill portada del adversario para barajar a su deck", (chosenIdx) => {
            executeShuffle(targetableSkills[chosenIdx]);
          });
        }
      }
    },
    {
      text: "💥 No activar Espiral digital",
      action: () => {
        addLog(`[Efecto Espiral digital] Decidiste no activar el efecto.`, 'var(--text-muted)');
        updatePlaytestView();
      }
    }
  ];

  addLog(`[Trigger] Se envió <strong>Espiral digital</strong> al cementerio desde tu ${fromZone === 'hand' ? 'mano' : 'deck'} controlando a Katherine.`, 'var(--accent-cyan)');
  const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
  showContextMenu(dummyEvent, items);
}

function checkAndTriggerBolaDeFuego(cardId, fromZone) {
  if (typeof checkAndTriggerEncargoSP402 === 'function' && cardId === 'BBX-SP402') {
    checkAndTriggerEncargoSP402(cardId, fromZone, 'player');
  }
  if (typeof checkAndTriggerTormentaDigitalSP407 === 'function' && cardId === 'BBX-SP407') {
    checkAndTriggerTormentaDigitalSP407(cardId, fromZone, 'player');
  }
  if (typeof checkAndTriggerFlamaCerteraSP413 === 'function' && cardId === 'BBX-SP413') {
    checkAndTriggerFlamaCerteraSP413(cardId, fromZone, 'player');
  }
  if (cardId !== 'BBX-SP203') return;
  if (fromZone !== 'hand' && fromZone !== 'deck') return;

  const katherineSlots = [];
  playtestState.slots.forEach((s, sIdx) => {
    if (s.character && cardsDatabase[s.character].nombre.includes("Katherine")) {
      katherineSlots.push({
        slot: s,
        slotIndex: sIdx,
        name: cardsDatabase[s.character].nombre
      });
    }
  });

  if (katherineSlots.length === 0) {
    addLog(`[Efecto Bola de fuego] Enviada al cementerio desde tu ${fromZone === 'hand' ? 'mano' : 'deck'}, pero no controlas a ningún Personaje Katherine.`, 'var(--text-muted)');
    return;
  }

  const applyBuff = (targetKatherine) => {
    targetKatherine.slot.maxAttacks = 2;
    if ((targetKatherine.slot.attacksDeclared || 0) < targetKatherine.slot.maxAttacks) {
      targetKatherine.slot.isRotated = false;
    }
    addLog(`[Efecto Bola de fuego] <strong>${targetKatherine.name}</strong> (Slot ${targetKatherine.slotIndex + 1}) puede realizar hasta 2 ataques por el resto de este turno.`, 'var(--accent-purple)');
    updatePlaytestView();
  };

  const items = [
    {
      text: "🔥 Activar Bola de fuego (Conceder hasta 2 ataques a 1 Katherine)",
      action: () => {
        if (katherineSlots.length === 1) {
          applyBuff(katherineSlots[0]);
        } else {
          const chooserTargets = katherineSlots.map(kItem => ({
            id: kItem.slot.character,
            owner: 'player',
            text: `Katherine en Slot ${kItem.slotIndex + 1} (${kItem.name})`
          }));
          openCardChooserModal(chooserTargets, "Bola de fuego: Selecciona a qué Katherine conceder hasta 2 ataques", (chosenIdx) => {
            applyBuff(katherineSlots[chosenIdx]);
          });
        }
      }
    },
    {
      text: "❌ No activar Bola de fuego",
      action: () => {
        addLog(`[Efecto Bola de fuego] Decidiste no activar su efecto.`, 'var(--text-muted)');
        updatePlaytestView();
      }
    }
  ];

  const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
  showContextMenu(dummyEvent, items);
}

// Tarea nocturna (BBX-SP363): "Si esta carta es enviada al cementerio desde tu mano o deck, puedes robar 1 carta por cada Personaje Katherine que controles. Solo puedes usar este efecto de \"Tarea nocturna\" una vez por turno."
function checkAndTriggerTareaNocturnaSP363(cardId, fromZone = 'deck', owner = 'player') {
  if (cardId !== 'BBX-SP363') return;
  if (fromZone !== 'hand' && fromZone !== 'deck') return;

  const isPlayer = owner === 'player';
  const tag = isPlayer ? '[Efecto Tarea nocturna BBX-SP363]' : '[Rival - Efecto Tarea nocturna BBX-SP363]';

  // Bloqueo de efectos de cementerio (ej. Anhelo BBX-SP352)
  if (typeof isCardGraveEffectBlocked === 'function' && isCardGraveEffectBlocked(owner, 'BBX-SP363')) {
    addLog(`${tag} No se puede activar: Los efectos de cartas en el cementerio están bloqueados este turno.`, 'var(--text-muted)');
    return;
  }

  // Hard Once Per Turn
  const usedGlobal = isPlayer ? (playtestState.usedGlobalEffects || []) : (playtestState.opponentUsedGlobalEffects || []);
  if (usedGlobal.includes('Tarea nocturna')) {
    return;
  }

  // Bloqueo de robo por efectos de Skill
  if (isPlayer) {
    if (playtestState.cannotDrawByEffectsThisTurn) {
      addLog(`${tag} No puedes robar cartas por efectos este turno.`, 'var(--text-muted)');
      return;
    }
  }

  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;
  const katherineCount = slots.filter(s => s.character && cardsDatabase[s.character] && cardsDatabase[s.character].nombre.includes("Katherine")).length;

  if (katherineCount === 0) {
    addLog(`${tag} Enviada al cementerio desde ${fromZone === 'hand' ? 'la mano' : 'el deck'}, pero ${isPlayer ? 'no controlas' : 'el rival no controla'} ningún Personaje Katherine.`, 'var(--text-muted)');
    return;
  }

  if (isPlayer && typeof isDrawBySkillBlocked === 'function' && isDrawBySkillBlocked('player', katherineCount)) {
    addLog(`${tag} No puedes robar cartas por efectos de Skills este turno.`, 'var(--text-muted)');
    return;
  }

  const deck = isPlayer ? playtestState.deck : playtestState.opponentDeck;

  // Regla tipo Boreal: El mazo debe tener como mínimo tantas cartas como Personajes Katherine controles
  if (deck.length < katherineCount) {
    addLog(`${tag} No se puede activar: Se requieren al menos ${katherineCount} cartas en tu deck para robar (tienes ${deck.length}).`, 'var(--text-muted)');
    return;
  }

  if (!isPlayer) {
    // Modo Rival
    if (!playtestState.opponentUsedGlobalEffects) playtestState.opponentUsedGlobalEffects = [];
    playtestState.opponentUsedGlobalEffects.push('Tarea nocturna');

    const drawnNames = [];
    for (let i = 0; i < katherineCount; i++) {
      if (deck.length > 0) {
        const drawnId = deck.shift();
        playtestState.opponentHand.push(drawnId);
        drawnNames.push(cardsDatabase[drawnId]?.nombre || drawnId);
      }
    }
    addLog(`${tag} El rival controla ${katherineCount} Personaje(s) Katherine y robó ${drawnNames.length} carta(s) de su deck.`, 'var(--accent-purple)');
    updatePlaytestView();
    return;
  }

  // Modo Jugador: Confirmación interactiva
  const items = [
    {
      text: `🃏 Activar Tarea nocturna (Robar ${katherineCount} carta(s) por ${katherineCount} Katherine)`,
      action: () => {
        if (!playtestState.usedGlobalEffects) playtestState.usedGlobalEffects = [];
        playtestState.usedGlobalEffects.push('Tarea nocturna');

        const drawnNames = [];
        for (let i = 0; i < katherineCount; i++) {
          if (playtestState.deck.length > 0) {
            const drawnId = playtestState.deck.shift();
            playtestState.hand.push(drawnId);
            drawnNames.push(cardsDatabase[drawnId]?.nombre || drawnId);
          }
        }
        addLog(`${tag} Controlas ${katherineCount} Personaje(s) Katherine y robaste ${drawnNames.length} carta(s) de tu deck: <strong>${drawnNames.join(', ')}</strong>.`, 'var(--accent-purple)');
        updatePlaytestView();
      }
    },
    {
      text: "❌ No activar Tarea nocturna",
      action: () => {
        addLog(`${tag} Decidiste no activar el efecto de Tarea nocturna.`, 'var(--text-muted)');
        updatePlaytestView();
      }
    }
  ];

  const dummyEvent = { clientX: window.innerWidth / 2 - 140, clientY: window.innerHeight / 2 - 80 };
  showContextMenu(dummyEvent, items);
}

// Encargo (BBX-SP402): "Si esta carta es enviada al cementerio desde tu mano o deck, puedes robar 2 cartas de tu deck y si lo haces baraja 1 carta en tu mano al deck. Solo puedes usar este efecto de \"Encargo\" una vez por turno."
function checkAndTriggerEncargoSP402(cardId, fromZone = 'deck', owner = 'player', testOptions = {}, onDone = null) {
  if (cardId !== 'BBX-SP402') {
    if (typeof onDone === 'function') onDone(false, { reason: 'not_target_card' });
    return;
  }
  if (fromZone !== 'hand' && fromZone !== 'deck') {
    if (typeof onDone === 'function') onDone(false, { reason: 'invalid_from_zone' });
    return;
  }

  const isPlayer = (owner === 'player');
  const tag = isPlayer ? '[Efecto Encargo BBX-SP402]' : '[Rival - Efecto Encargo BBX-SP402]';
  const usedGlobal = isPlayer 
    ? (playtestState.usedGlobalEffects = playtestState.usedGlobalEffects || []) 
    : (playtestState.opponentUsedGlobalEffects = playtestState.opponentUsedGlobalEffects || []);
  const deck = isPlayer ? playtestState.deck : playtestState.opponentDeck;
  const hand = isPlayer ? playtestState.hand : playtestState.opponentHand;

  // 1. Verificación HOPT
  if (usedGlobal.includes('Encargo') || usedGlobal.includes('BBX-SP402')) {
    if (typeof onDone === 'function') onDone(false, { reason: 'already_used' });
    return;
  }

  // 2. Bloqueos de cementerio y Skill
  if (typeof isCardGraveEffectBlocked === 'function' && isCardGraveEffectBlocked(owner, 'BBX-SP402')) {
    addLog(`${tag} No se puede activar: Los efectos de cartas en el cementerio están bloqueados este turno.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false, { reason: 'grave_effect_blocked' });
    return;
  }
  if (typeof isSkillEffectBlocked === 'function' && isSkillEffectBlocked('BBX-SP402', owner)) {
    addLog(`${tag} No se puede activar: El efecto de la Skill está bloqueado este turno.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false, { reason: 'skill_effect_blocked' });
    return;
  }

  // 3. Bloqueo de robo por efectos
  if (isPlayer) {
    if (playtestState.cannotDrawByEffectsThisTurn) {
      addLog(`${tag} No puedes robar cartas por efectos este turno.`, 'var(--text-muted)');
      if (typeof onDone === 'function') onDone(false, { reason: 'draw_blocked' });
      return;
    }
    if (typeof isDrawBySkillBlocked === 'function' && isDrawBySkillBlocked('player', 2)) {
      addLog(`${tag} No puedes robar cartas por efectos de Skills este turno.`, 'var(--text-muted)');
      if (typeof onDone === 'function') onDone(false, { reason: 'draw_blocked' });
      return;
    }
  }

  // 4. Cartas mínimas en deck para robar 2
  if (!deck || deck.length < 2) {
    addLog(`${tag} No se puede activar: Se requieren al menos 2 cartas en el deck para robar (tienes ${deck ? deck.length : 0}).`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false, { reason: 'not_enough_cards_in_deck' });
    return;
  }

  const executeEffect = () => {
    usedGlobal.push('Encargo');
    if (!usedGlobal.includes('BBX-SP402')) usedGlobal.push('BBX-SP402');

    // Robar 2 cartas
    if (isPlayer) {
      if (typeof drawCard === 'function') {
        drawCard('skill');
        drawCard('skill');
      } else {
        if (deck.length > 0) hand.push(deck.shift());
        if (deck.length > 0) hand.push(deck.shift());
      }
    } else {
      if (typeof opponentDrawCard === 'function') {
        opponentDrawCard('skill');
        opponentDrawCard('skill');
      } else {
        if (deck.length > 0) hand.push(deck.shift());
        if (deck.length > 0) hand.push(deck.shift());
      }
    }

    const handleShuffleHandCard = (chosenHandCardIndex) => {
      let cardToShuffle = null;
      if (chosenHandCardIndex !== undefined && chosenHandCardIndex >= 0 && chosenHandCardIndex < hand.length) {
        cardToShuffle = hand.splice(chosenHandCardIndex, 1)[0];
      } else {
        cardToShuffle = hand.shift();
      }

      if (cardToShuffle) {
        deck.push(cardToShuffle);
        if (typeof shuffleArray === 'function') {
          shuffleArray(deck);
        }
      }

      const cardName = cardsDatabase[cardToShuffle]?.nombre || cardToShuffle;
      if (isPlayer) {
        addLog(`[Efecto Encargo BBX-SP402] Robaste 2 cartas de tu deck y barajaste <strong>${cardName}</strong> de tu mano a tu deck.`, 'var(--accent-purple)');
      } else {
        addLog(`[Efecto Encargo BBX-SP402 Rival] El rival robó 2 cartas de su deck y barajó <strong>${cardName}</strong> de su mano a su deck.`, 'var(--accent-purple)');
      }

      if (typeof checkAndTriggerInestabilidad === 'function') checkAndTriggerInestabilidad(owner);
      if (typeof updatePlaytestView === 'function') updatePlaytestView();
      if (typeof onDone === 'function') onDone(true, { shuffledCard: cardToShuffle });
    };

    if (testOptions) {
      if (testOptions.cardToShuffleIndex !== undefined) {
        handleShuffleHandCard(testOptions.cardToShuffleIndex);
        return;
      }
      if (testOptions.cardToShuffleId) {
        const idx = hand.indexOf(testOptions.cardToShuffleId);
        handleShuffleHandCard(idx !== -1 ? idx : 0);
        return;
      }
    }

    if (!isPlayer || typeof openCardChooserModal !== 'function' || typeof document === 'undefined') {
      handleShuffleHandCard(0);
      return;
    }

    const chooserTargets = hand.map((id, idx) => ({
      id,
      owner: 'player',
      from: 'hand',
      text: cardsDatabase[id]?.nombre || id
    }));

    openCardChooserModal(chooserTargets, "Encargo (SP402): Selecciona 1 carta de tu mano para barajar al deck", (chosenIdx) => {
      handleShuffleHandCard(chosenIdx);
    });
  };

  if (testOptions && (testOptions.autoActivate !== undefined || testOptions.cardToShuffleIndex !== undefined || testOptions.cardToShuffleId !== undefined)) {
    if (testOptions.autoActivate === false) {
      if (typeof onDone === 'function') onDone(false, { reason: 'user_declined' });
      return;
    }
    executeEffect();
    return;
  }

  if (!isPlayer || typeof showContextMenu !== 'function' || typeof window === 'undefined') {
    executeEffect();
    return;
  }

  const items = [
    {
      text: `📦 Activar Encargo (Robar 2 cartas y barajar 1 de tu mano al deck)`,
      action: () => {
        executeEffect();
      }
    },
    {
      text: "❌ No activar Encargo",
      action: () => {
        addLog(`${tag} Decidiste no activar el efecto de Encargo.`, 'var(--text-muted)');
        if (typeof updatePlaytestView === 'function') updatePlaytestView();
        if (typeof onDone === 'function') onDone(false, { reason: 'user_declined' });
      }
    }
  ];

  const dummyEvent = { clientX: window.innerWidth / 2 - 140, clientY: window.innerHeight / 2 - 80 };
  showContextMenu(dummyEvent, items);
}

// Tormenta digital (BBX-SP407): "Si esta carta es enviada al cementerio desde tu mano o deck, puedes portarle a 1 Personaje Katherine que controles hasta 3 Skills propias de Katherine desde tu cementerio. Solo puedes usar este efecto de \"Tormenta digital\" una vez por turno."
function checkAndTriggerTormentaDigitalSP407(cardId, fromZone = 'deck', owner = 'player', testOptions = {}, onDone = null) {
  if (cardId !== 'BBX-SP407') {
    if (typeof onDone === 'function') onDone(false, { reason: 'not_target_card' });
    return;
  }

  // 1. Condición de zona: mano o deck
  if (fromZone !== 'hand' && fromZone !== 'deck') {
    if (typeof onDone === 'function') onDone(false, { reason: 'invalid_from_zone' });
    return;
  }

  const isPlayer = (owner === 'player');
  const tag = isPlayer ? '[Efecto Tormenta digital BBX-SP407]' : '[Rival - Efecto Tormenta digital BBX-SP407]';
  const usedGlobal = isPlayer 
    ? (playtestState.usedGlobalEffects = playtestState.usedGlobalEffects || []) 
    : (playtestState.opponentUsedGlobalEffects = playtestState.opponentUsedGlobalEffects || []);
  const grave = isPlayer ? playtestState.grave : playtestState.opponentGrave;
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;

  // 2. Verificación HOPT (Hard Once Per Turn)
  if (usedGlobal.includes('Tormenta digital') || usedGlobal.includes('BBX-SP407')) {
    if (typeof onDone === 'function') onDone(false, { reason: 'already_used' });
    return;
  }

  // 3. Bloqueos de cementerio y Skill
  if (typeof isCardGraveEffectBlocked === 'function' && isCardGraveEffectBlocked(owner, 'BBX-SP407')) {
    addLog(`${tag} No se puede activar: Los efectos de cartas en el cementerio están bloqueados este turno.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false, { reason: 'grave_effect_blocked' });
    return;
  }
  if (typeof isSkillEffectBlocked === 'function' && isSkillEffectBlocked('BBX-SP407', owner)) {
    addLog(`${tag} No se puede activar: El efecto de la Skill está bloqueado este turno.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false, { reason: 'skill_effect_blocked' });
    return;
  }

  // 4. Bloqueo de equipar desde cementerio (ej. Katherine SP085)
  const canGrave = typeof canEquipFromZone === 'function' ? canEquipFromZone('grave') : true;
  if (!canGrave) {
    addLog(`${tag} No se puede activar: No se permite portar Skills desde el cementerio debido a una restricción activa.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false, { reason: 'equip_from_grave_blocked' });
    return;
  }

  // 5. Debe controlar al menos 1 Personaje Katherine
  const katherineSlots = [];
  slots.forEach((s, sIdx) => {
    if (s && s.character && cardsDatabase[s.character] && cardsDatabase[s.character].nombre.includes("Katherine")) {
      katherineSlots.push({
        slot: s,
        slotIndex: sIdx,
        name: cardsDatabase[s.character].nombre
      });
    }
  });

  if (katherineSlots.length === 0) {
    addLog(`${tag} Enviada al cementerio desde tu ${fromZone === 'hand' ? 'mano' : 'deck'}, pero no controlas a ningún Personaje Katherine.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false, { reason: 'no_katherine_on_field' });
    return;
  }

  // 6. Debe haber al menos 1 Skill propia de Katherine en el cementerio
  const isKatherineSkill = id => {
    const card = cardsDatabase[id];
    if (!card) return false;
    if (card.tipo !== 'Skill') return false;
    if (!card.portador || !card.portador.includes("Katherine")) return false;
    if (typeof isSkillBannedFromEquip === 'function' && isSkillBannedFromEquip(id)) return false;
    return true;
  };

  const eligibleSkillsInGrave = [];
  grave.forEach((skId, gIdx) => {
    if (isKatherineSkill(skId)) {
      eligibleSkillsInGrave.push({
        id: skId,
        graveIndex: gIdx,
        name: cardsDatabase[skId]?.nombre || skId,
        owner: isPlayer ? 'player' : 'opponent'
      });
    }
  });

  if (eligibleSkillsInGrave.length === 0) {
    addLog(`${tag} No hay ninguna Skill propia de Katherine en el cementerio para portar.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false, { reason: 'no_katherine_skills_in_grave' });
    return;
  }

  const executeEffect = (chosenTargetSlotIndex, chosenGraveIndices) => {
    usedGlobal.push('Tormenta digital');
    if (!usedGlobal.includes('BBX-SP407')) usedGlobal.push('BBX-SP407');

    const targetObj = katherineSlots.find(k => k.slotIndex === chosenTargetSlotIndex) || katherineSlots[0];
    const targetSlot = targetObj.slot;

    // Recalcular eligibleSkillsInGrave actual
    const currentEligible = [];
    grave.forEach((skId, gIdx) => {
      if (isKatherineSkill(skId)) {
        currentEligible.push({
          id: skId,
          graveIndex: gIdx,
          name: cardsDatabase[skId]?.nombre || skId
        });
      }
    });

    let itemsToEquip = [];
    if (chosenGraveIndices && Array.isArray(chosenGraveIndices)) {
      if (chosenGraveIndices.length > 0 && typeof chosenGraveIndices[0] === 'number') {
        const isRelative = chosenGraveIndices.every(idx => idx >= 0 && idx < currentEligible.length);
        if (isRelative && currentEligible.length >= chosenGraveIndices.length) {
          itemsToEquip = chosenGraveIndices.slice(0, 3).map(idx => currentEligible[idx]);
        } else {
          itemsToEquip = chosenGraveIndices.slice(0, 3).map(gIdx => ({
            id: grave[gIdx],
            graveIndex: gIdx,
            name: cardsDatabase[grave[gIdx]]?.nombre || grave[gIdx]
          })).filter(it => it.id && isKatherineSkill(it.id));
        }
      }
    } else if (testOptions && testOptions.chosenSkillIds && Array.isArray(testOptions.chosenSkillIds)) {
      testOptions.chosenSkillIds.slice(0, 3).forEach(id => {
        const found = currentEligible.find(it => it.id === id && !itemsToEquip.some(eq => eq.graveIndex === it.graveIndex));
        if (found) itemsToEquip.push(found);
      });
    }

    if (itemsToEquip.length === 0) {
      itemsToEquip = currentEligible.slice(0, 3);
    }

    // Ordenar itemsToEquip por graveIndex descendente para splice seguro
    itemsToEquip.sort((a, b) => b.graveIndex - a.graveIndex);

    const equippedIds = [];
    targetSlot.skills = targetSlot.skills || [];

    itemsToEquip.forEach(item => {
      let removedId = null;
      if (grave[item.graveIndex] === item.id) {
        removedId = grave.splice(item.graveIndex, 1)[0];
      } else {
        const idx = grave.indexOf(item.id);
        if (idx !== -1) {
          removedId = grave.splice(idx, 1)[0];
        }
      }
      if (removedId) {
        targetSlot.skills.push(removedId);
        equippedIds.push(removedId);
      }
    });

    const equippedNames = equippedIds.map(id => cardsDatabase[id]?.nombre || id).join(', ');
    if (isPlayer) {
      addLog(`${tag} Portaste a <strong>${targetObj.name}</strong> (Slot ${targetObj.slotIndex + 1}) ${equippedIds.length} Skill(s) propia(s) de Katherine desde tu cementerio: [<strong>${equippedNames}</strong>].`, 'var(--accent-purple)');
    } else {
      addLog(`${tag} El rival portó a <strong>${targetObj.name}</strong> (Slot ${targetObj.slotIndex + 1}) ${equippedIds.length} Skill(s) propia(s) de Katherine desde su cementerio: [<strong>${equippedNames}</strong>].`, 'var(--accent-purple)');
    }

    if (typeof checkAndTriggerInestabilidad === 'function') {
      checkAndTriggerInestabilidad(owner);
    }
    if (typeof updatePlaytestView === 'function') updatePlaytestView();
    if (typeof onDone === 'function') onDone(true, { targetSlotIndex: targetObj.slotIndex, equippedIds });
  };

  const chooseTargetAndSkills = () => {
    if (testOptions) {
      if (testOptions.autoAccept === false || testOptions.autoActivate === false) {
        if (typeof onDone === 'function') onDone(false, { reason: 'user_declined' });
        return;
      }
      const chosenSlot = (testOptions.chosenTargetSlotIndex !== undefined) 
        ? testOptions.chosenTargetSlotIndex 
        : (testOptions.targetSlotIndex !== undefined ? testOptions.targetSlotIndex : katherineSlots[0].slotIndex);
      executeEffect(chosenSlot, testOptions.chosenGraveIndices);
      return;
    }

    if (!isPlayer || typeof document === 'undefined' || typeof openUpToMultiCardChooserModal !== 'function') {
      executeEffect(katherineSlots[0].slotIndex, null);
      return;
    }

    const promptSkillsSelection = (chosenSlotIdx) => {
      const freshEligible = [];
      grave.forEach((skId, gIdx) => {
        if (isKatherineSkill(skId)) {
          freshEligible.push({
            id: skId,
            graveIndex: gIdx,
            owner: 'player',
            text: cardsDatabase[skId]?.nombre || skId
          });
        }
      });

      if (freshEligible.length === 0) {
        addLog(`${tag} Ya no hay Skills propias de Katherine en el cementerio.`, 'var(--text-muted)');
        if (typeof onDone === 'function') onDone(false, { reason: 'no_katherine_skills_in_grave' });
        return;
      }

      const maxQty = Math.min(3, freshEligible.length);
      openUpToMultiCardChooserModal(freshEligible, `Tormenta digital: Selecciona hasta ${maxQty} Skill(s) de Katherine desde tu cementerio`, maxQty, (selectedIndices) => {
        if (!selectedIndices || selectedIndices.length === 0) {
          addLog(`${tag} Decidiste no portar ninguna Skill.`, 'var(--text-muted)');
          if (typeof onDone === 'function') onDone(false, { reason: 'no_selection' });
          return;
        }
        executeEffect(chosenSlotIdx, selectedIndices);
      });
    };

    if (katherineSlots.length === 1) {
      promptSkillsSelection(katherineSlots[0].slotIndex);
    } else {
      const chooserTargets = katherineSlots.map(kItem => ({
        id: kItem.slot.character,
        owner: 'player',
        text: `Katherine en Slot ${kItem.slotIndex + 1} (${kItem.name})`
      }));
      openCardChooserModal(chooserTargets, "Tormenta digital: Selecciona a qué Katherine portarle las Skills", (chosenIdx) => {
        promptSkillsSelection(katherineSlots[chosenIdx].slotIndex);
      });
    }
  };

  // Confirmar si desea activar ("puedes...")
  if (testOptions && (testOptions.autoAccept !== undefined || testOptions.autoActivate !== undefined || testOptions.chosenGraveIndices !== undefined || testOptions.chosenSkillIds !== undefined || testOptions.chosenTargetSlotIndex !== undefined)) {
    if (testOptions.autoAccept === false || testOptions.autoActivate === false) {
      if (typeof onDone === 'function') onDone(false, { reason: 'user_declined' });
      return;
    }
    chooseTargetAndSkills();
    return;
  }

  if (!isPlayer || typeof showContextMenu !== 'function' || typeof window === 'undefined') {
    chooseTargetAndSkills();
    return;
  }

  const items = [
    {
      text: "⚡ Activar Tormenta digital (Portar hasta 3 Skills de Katherine desde el cementerio)",
      action: () => {
        chooseTargetAndSkills();
      }
    },
    {
      text: "❌ No activar Tormenta digital",
      action: () => {
        addLog(`${tag} Decidiste no activar el efecto de Tormenta digital.`, 'var(--text-muted)');
        if (typeof updatePlaytestView === 'function') updatePlaytestView();
        if (typeof onDone === 'function') onDone(false, { reason: 'user_declined' });
      }
    }
  ];

  const dummyEvent = { clientX: window.innerWidth / 2 - 140, clientY: window.innerHeight / 2 - 80 };
  showContextMenu(dummyEvent, items);
}
if (typeof window !== 'undefined') {
  window.checkAndTriggerTormentaDigitalSP407 = checkAndTriggerTormentaDigitalSP407;
}

// Flama certera (BBX-SP413): "Si esta carta es enviada al cementerio desde tu deck puedes portarla a 1 Personaje Roy que controles y si lo haces puedes barajar al deck 1 Skill portada en el campo de tu adversario o una en su cementerio."
function checkAndTriggerFlamaCerteraSP413(cardId, fromZone = 'deck', owner = 'player', testOptions = {}, onDone = null) {
  if (cardId !== 'BBX-SP413') {
    if (typeof onDone === 'function') onDone(false, { reason: 'not_target_card' });
    return;
  }
  if (fromZone !== 'deck') {
    if (typeof onDone === 'function') onDone(false, { reason: 'not_from_deck' });
    return;
  }

  const isPlayer = (owner === 'player');
  const tag = isPlayer ? '[Efecto Flama certera BBX-SP413]' : '[Rival - Efecto Flama certera BBX-SP413]';
  const grave = isPlayer ? playtestState.grave : playtestState.opponentGrave;
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;
  const oppSlots = isPlayer ? playtestState.opponentSlots : playtestState.slots;
  const oppGrave = isPlayer ? playtestState.opponentGrave : playtestState.grave;
  const oppDeck = isPlayer ? playtestState.opponentDeck : playtestState.deck;

  // 1. Verificar presencia en el cementerio
  if (!grave || !grave.includes('BBX-SP413')) {
    if (typeof onDone === 'function') onDone(false, { reason: 'not_in_grave' });
    return;
  }

  // 2. Verificar bloqueos de cementerio o restricciones de equipamiento
  if (typeof isCardGraveEffectBlocked === 'function' && isCardGraveEffectBlocked(owner, 'BBX-SP413')) {
    addLog(`${tag} El efecto en el cementerio de Flama certera está bloqueado.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false, { reason: 'grave_effect_blocked' });
    return;
  }

  if (typeof isSkillEffectBlocked === 'function' && isSkillEffectBlocked('BBX-SP413', owner)) {
    addLog(`${tag} El efecto de Flama certera está negado.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false, { reason: 'skill_effect_negated' });
    return;
  }

  if (typeof isSkillBannedFromEquip === 'function' && isSkillBannedFromEquip('BBX-SP413')) {
    addLog(`${tag} Flama certera no puede ser portada por efectos de restricción.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false, { reason: 'equip_banned' });
    return;
  }

  // 3. Buscar Personajes Roy controlados
  const roySlots = [];
  slots.forEach((s, sIdx) => {
    if (s && s.character && cardsDatabase[s.character]?.nombre?.includes("Roy")) {
      roySlots.push({
        slot: s,
        slotIndex: sIdx,
        name: cardsDatabase[s.character]?.nombre || `Roy (Slot ${sIdx + 1})`
      });
    }
  });

  if (roySlots.length === 0) {
    addLog(`${tag} Enviada al cementerio desde el deck, pero no controlas a ningún Personaje Roy en el campo.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false, { reason: 'no_roy_on_field' });
    return;
  }

  const executeEffect = (chosenRoySlotIndex) => {
    // 1. Portar BBX-SP413 al Roy seleccionado
    const royObj = roySlots.find(r => r.slotIndex === chosenRoySlotIndex) || roySlots[0];
    const targetSlot = royObj.slot;

    const gIdx = grave.indexOf('BBX-SP413');
    if (gIdx === -1) {
      if (typeof onDone === 'function') onDone(false, { reason: 'card_missing_from_grave' });
      return;
    }
    grave.splice(gIdx, 1);

    targetSlot.skills = targetSlot.skills || [];
    targetSlot.skills.push('BBX-SP413');

    if (isPlayer) {
      addLog(`${tag} Portaste <strong>Flama certera</strong> a <strong>${royObj.name}</strong> (Slot ${royObj.slotIndex + 1}) desde tu cementerio.`, 'var(--accent-purple)');
    } else {
      addLog(`${tag} El rival portó <strong>Flama certera</strong> a <strong>${royObj.name}</strong> (Slot ${royObj.slotIndex + 1}) desde su cementerio.`, 'var(--accent-purple)');
    }

    if (typeof checkAndTriggerInestabilidad === 'function') {
      checkAndTriggerInestabilidad(owner);
    }

    // 2. Efecto secundario: barajar 1 Skill rival (campo o cementerio) al deck
    const candidateTargets = [];

    // Skills en campo rival
    oppSlots.forEach((oS, oIdx) => {
      if (oS && oS.character && Array.isArray(oS.skills)) {
        oS.skills.forEach((skId) => {
          const canRemove = (typeof canRemoveSkillByEffect !== 'function') ||
            canRemoveSkillByEffect(skId, isPlayer, owner, oS, 'deck', 'BBX-SP413', 'skill', false);
          if (canRemove) {
            candidateTargets.push({
              id: skId,
              from: 'field',
              owner: isPlayer ? 'opponent' : 'player',
              slotIdx: oIdx,
              slot: oS,
              charName: cardsDatabase[oS.character]?.nombre || `Slot ${oIdx + 1}`,
              text: `${cardsDatabase[skId]?.nombre || skId} (⚔ ${cardsDatabase[oS.character]?.nombre || `Slot ${oIdx + 1}`})`
            });
          }
        });
      }
    });

    // Skills en cementerio rival
    if (Array.isArray(oppGrave)) {
      oppGrave.forEach((skId, gIdx) => {
        if (cardsDatabase[skId]?.tipo === 'Skill') {
          candidateTargets.push({
            id: skId,
            from: 'grave',
            owner: isPlayer ? 'opponent' : 'player',
            graveIdx: gIdx,
            text: `${cardsDatabase[skId]?.nombre || skId} (🪦 Cementerio)`
          });
        }
      });
    }

    const finishWithoutShuffle = (reason = 'skipped_or_no_targets') => {
      if (typeof updatePlaytestView === 'function') updatePlaytestView();
      if (typeof onDone === 'function') onDone(true, { roySlotIndex: royObj.slotIndex, shuffledCard: null, reason });
    };

    if (candidateTargets.length === 0) {
      addLog(`${tag} No hay ninguna Skill válida en el campo ni en el cementerio del adversario para barajar.`, 'var(--text-muted)');
      finishWithoutShuffle('no_valid_targets');
      return;
    }

    const executeShuffle = (targetItem) => {
      if (!targetItem) {
        finishWithoutShuffle('no_target_selected');
        return;
      }

      const targetId = targetItem.id;
      const targetName = cardsDatabase[targetId]?.nombre || targetId;

      if (targetItem.from === 'field') {
        const sIndex = targetItem.slot.skills.indexOf(targetId);
        if (sIndex !== -1) {
          targetItem.slot.skills.splice(sIndex, 1);
        }
      } else if (targetItem.from === 'grave') {
        const gIndex = oppGrave.indexOf(targetId);
        if (gIndex !== -1) {
          oppGrave.splice(gIndex, 1);
        }
      }

      oppDeck.push(targetId);
      if (typeof shuffleArray === 'function') {
        shuffleArray(oppDeck);
      }

      const locDesc = targetItem.from === 'field' 
        ? `del campo de <strong>${targetItem.charName}</strong>`
        : `del cementerio adversario`;

      if (isPlayer) {
        addLog(`${tag} Barajaste <strong>${targetName}</strong> (${locDesc}) al deck del rival.`, 'var(--accent-cyan)');
      } else {
        addLog(`${tag} El rival barajó <strong>${targetName}</strong> (${locDesc}) a tu deck.`, 'var(--accent-cyan)');
      }

      if (typeof checkAndTriggerInestabilidad === 'function') {
        checkAndTriggerInestabilidad(owner);
      }
      if (typeof updatePlaytestView === 'function') updatePlaytestView();
      if (typeof onDone === 'function') onDone(true, { roySlotIndex: royObj.slotIndex, shuffledCard: targetId, targetItem });
    };

    // Modo tests
    if (testOptions && (testOptions.skipShuffle !== undefined || testOptions.chosenTargetIdx !== undefined || testOptions.chosenTargetId !== undefined || testOptions.autoActivate !== undefined || testOptions.autoAccept !== undefined)) {
      if (testOptions.skipShuffle) {
        addLog(`${tag} Decidiste no barajar ninguna Skill al deck.`, 'var(--text-muted)');
        finishWithoutShuffle('user_declined_shuffle');
        return;
      }
      let targetToPick = null;
      if (testOptions.chosenTargetIdx !== undefined) {
        targetToPick = candidateTargets[testOptions.chosenTargetIdx];
      } else if (testOptions.chosenTargetId) {
        targetToPick = candidateTargets.find(t => t.id === testOptions.chosenTargetId);
      }
      if (!targetToPick) targetToPick = candidateTargets[0];
      executeShuffle(targetToPick);
      return;
    }

    // Modo rival / no jugador
    if (!isPlayer || typeof openCardChooserModal !== 'function' || typeof document === 'undefined') {
      executeShuffle(candidateTargets[0]);
      return;
    }

    // Modal unificado: campo y cementerio juntos
    openCardChooserModal(
      candidateTargets,
      "Flama certera: Selecciona 1 Skill rival para barajar a su deck",
      (chosenIndex) => {
        executeShuffle(candidateTargets[chosenIndex]);
      },
      () => {
        addLog(`${tag} Decidiste no barajar ninguna Skill al deck del rival.`, 'var(--text-muted)');
        finishWithoutShuffle('user_cancelled_shuffle');
      }
    );
  };

  const chooseRoyAndExecute = () => {
    if (testOptions && (testOptions.chosenRoySlotIndex !== undefined || testOptions.targetSlotIndex !== undefined)) {
      const chosen = (testOptions.chosenRoySlotIndex !== undefined) ? testOptions.chosenRoySlotIndex : testOptions.targetSlotIndex;
      executeEffect(chosen);
      return;
    }

    if (roySlots.length === 1) {
      executeEffect(roySlots[0].slotIndex);
      return;
    }

    if (!isPlayer || typeof openCardChooserModal !== 'function' || typeof document === 'undefined') {
      executeEffect(roySlots[0].slotIndex);
      return;
    }

    const royChooserTargets = roySlots.map(rItem => ({
      id: rItem.slot.character,
      owner: 'player',
      from: 'field',
      text: `${rItem.name} (Slot ${rItem.slotIndex + 1})`
    }));

    openCardChooserModal(
      royChooserTargets,
      "Flama certera: Selecciona a qué Roy portar la Skill",
      (chosenIdx) => {
        executeEffect(roySlots[chosenIdx].slotIndex);
      },
      () => {
        addLog(`${tag} Decidiste no activar el efecto de Flama certera.`, 'var(--text-muted)');
        if (typeof onDone === 'function') onDone(false, { reason: 'user_cancelled_roy_selection' });
      }
    );
  };

  if (testOptions && (testOptions.autoAccept !== undefined || testOptions.autoActivate !== undefined || testOptions.chosenRoySlotIndex !== undefined || testOptions.chosenTargetIdx !== undefined)) {
    if (testOptions.autoAccept === false || testOptions.autoActivate === false) {
      if (typeof onDone === 'function') onDone(false, { reason: 'user_declined' });
      return;
    }
    chooseRoyAndExecute();
    return;
  }

  if (!isPlayer || typeof showContextMenu !== 'function' || typeof window === 'undefined') {
    chooseRoyAndExecute();
    return;
  }

  const items = [
    {
      text: "🔥 Activar Flama certera (Portar a Roy y barajar 1 Skill rival al deck)",
      action: () => {
        chooseRoyAndExecute();
      }
    },
    {
      text: "❌ No activar Flama certera",
      action: () => {
        addLog(`${tag} Decidiste no activar el efecto de Flama certera.`, 'var(--text-muted)');
        if (typeof updatePlaytestView === 'function') updatePlaytestView();
        if (typeof onDone === 'function') onDone(false, { reason: 'user_declined' });
      }
    }
  ];

  const dummyEvent = { clientX: window.innerWidth / 2 - 140, clientY: window.innerHeight / 2 - 80 };
  showContextMenu(dummyEvent, items);
}

if (typeof window !== 'undefined') {
  window.checkAndTriggerFlamaCerteraSP413 = checkAndTriggerFlamaCerteraSP413;
}

// Recursos (BBX-SP404): "Al final del turno de tu adversario en el que esta carta fue enviada al cementerio, si no tienes Personajes en tu mano y campo (revela tu mano para demostrar), puedes jugar 1 Personaje a tu campo directamente desde tu banca. Solo puedes usar este efecto de \"Recursos\" una vez por partida."
function checkAndTriggerRecursosSP404(owner = 'player', testOptions = {}, onDone = null) {
  const isPlayer = (owner === 'player');
  const tag = isPlayer ? '[Efecto Recursos BBX-SP404]' : '[Rival - Efecto Recursos BBX-SP404]';
  const grave = isPlayer ? playtestState.grave : playtestState.opponentGrave;
  const hand = isPlayer ? playtestState.hand : playtestState.opponentHand;
  const bench = isPlayer ? playtestState.bench : playtestState.opponentBench;
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;
  const usedPerGame = isPlayer 
    ? (playtestState.usedPerGameEffects = playtestState.usedPerGameEffects || []) 
    : (playtestState.opponentUsedPerGameEffects = playtestState.opponentUsedPerGameEffects || []);

  // 1. Verificar presencia de Recursos en el cementerio
  if (!grave || !grave.includes('BBX-SP404')) {
    if (typeof onDone === 'function') onDone(false, { reason: 'not_in_grave' });
    return;
  }

  // 2. Verificar que haya sido enviada en el turno del adversario que concluye
  const currentTurn = playtestState.turnCount || 1;
  const sentTurn = isPlayer ? playtestState.recursosSP404SentTurn : playtestState.opponentRecursosSP404SentTurn;
  const skipTurnCheck = testOptions && testOptions.ignoreTurnSent;
  if (!skipTurnCheck) {
    if (sentTurn !== currentTurn) {
      if (typeof onDone === 'function') onDone(false, { reason: 'not_sent_this_turn' });
      return;
    }
  }

  // 3. Verificar Hard Once Per Game (HOPG - una vez por partida)
  if (usedPerGame.includes('Recursos') || usedPerGame.includes('BBX-SP404')) {
    if (typeof onDone === 'function') onDone(false, { reason: 'already_used_in_game' });
    return;
  }

  // 4. Bloqueos de cementerio y Skill
  if (typeof isCardGraveEffectBlocked === 'function' && isCardGraveEffectBlocked(owner, 'BBX-SP404')) {
    addLog(`${tag} No se puede activar: Los efectos en el cementerio están bloqueados.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false, { reason: 'grave_effect_blocked' });
    return;
  }
  if (typeof isSkillEffectBlocked === 'function' && isSkillEffectBlocked('BBX-SP404', owner)) {
    addLog(`${tag} No se puede activar: El efecto de la Skill está bloqueado.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false, { reason: 'skill_effect_blocked' });
    return;
  }

  // 5. Condición: NO tener Personajes en campo
  const hasCharOnField = slots && slots.some(s => s && s.character);
  if (hasCharOnField) {
    if (typeof onDone === 'function') onDone(false, { reason: 'has_characters_on_field' });
    return;
  }

  // 6. Condición: NO tener Personajes en mano
  const hasCharInHand = hand && hand.some(id => cardsDatabase[id] && cardsDatabase[id].tipo === 'Personaje');
  if (hasCharInHand) {
    if (typeof onDone === 'function') onDone(false, { reason: 'has_characters_in_hand' });
    return;
  }

  // 7. Condición: Debe haber al menos 1 Personaje en banca (objetivo legal indispensable)
  const benchChars = [];
  if (bench && bench.length > 0) {
    bench.forEach((b, idx) => {
      const bId = (typeof b === 'string') ? b : b.id;
      if (cardsDatabase[bId] && cardsDatabase[bId].tipo === 'Personaje') {
        benchChars.push({ id: bId, benchIndex: idx, name: cardsDatabase[bId].nombre });
      }
    });
  }

  if (benchChars.length === 0) {
    addLog(`${tag} No se puede activar: No hay ningún Personaje en la banca para jugar al campo.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false, { reason: 'no_character_in_bench' });
    return;
  }

  const executeRecursos = (chosenBenchIndex) => {
    usedPerGame.push('Recursos');
    if (!usedPerGame.includes('BBX-SP404')) usedPerGame.push('BBX-SP404');

    // Revelar la mano para demostrar que no contiene Personajes
    if (hand && hand.length > 0) {
      const handNames = hand.map(id => cardsDatabase[id]?.nombre || id).join(', ');
      addLog(`${tag} Revelaste tu mano para demostrar que no tienes Personajes: [${handNames}].`, 'var(--accent-cyan)');
    } else {
      addLog(`${tag} Tu mano está vacía (se demuestra que no tienes Personajes).`, 'var(--accent-cyan)');
    }

    // Retirar de la banca
    const removedItem = bench.splice(chosenBenchIndex, 1)[0];
    const charId = (typeof removedItem === 'string') ? removedItem : removedItem.id;

    // Jugar directamente al campo (Slot 1 central)
    slots[1].character = charId;
    slots[1].skills = [];
    slots[1].effectUsed = false;
    slots[1].isRotated = false;
    slots[1].isFaceDown = false;

    const charName = cardsDatabase[charId]?.nombre || charId;
    if (isPlayer) {
      addLog(`${tag} Jugaste a <strong>${charName}</strong> directamente a tu campo desde tu banca.`, 'var(--accent-purple)');
    } else {
      addLog(`${tag} El rival jugó a <strong>${charName}</strong> directamente a su campo desde su banca.`, 'var(--accent-purple)');
    }

    if (typeof updatePlaytestView === 'function') updatePlaytestView();
    if (typeof checkAndTriggerInestabilidad === 'function') checkAndTriggerInestabilidad(owner);
    if (charId === 'BBX-SP377' && typeof checkAndTriggerLynaSP377Play === 'function') checkAndTriggerLynaSP377Play(1, owner);
    if (charId === 'BBX-SP384' && typeof checkAndTriggerRoySP384Play === 'function') checkAndTriggerRoySP384Play(1, owner);
    if (charId === 'BBX-SP388' && typeof checkAndTriggerTageroSP388Play === 'function') checkAndTriggerTageroSP388Play(1, owner);
    if (charId === 'BBX-SP393' && typeof checkAndTriggerRyuChanSP393Play === 'function') checkAndTriggerRyuChanSP393Play(1, owner);
    if (charId === 'BBX-SP395' && typeof checkAndTriggerSophiaSP395Play === 'function') checkAndTriggerSophiaSP395Play(1, owner);

    if (typeof onDone === 'function') onDone(true, { characterId: charId });
  };

  if (testOptions && testOptions.autoActivate !== undefined) {
    if (testOptions.autoActivate === false) {
      addLog(`${tag} Decidiste no activar el efecto de Recursos.`, 'var(--text-muted)');
      if (typeof onDone === 'function') onDone(false, { reason: 'user_declined' });
      return;
    }
    let chosenIdx = benchChars[0].benchIndex;
    if (testOptions.chosenBenchIndex !== undefined) {
      chosenIdx = testOptions.chosenBenchIndex;
    } else if (testOptions.chosenCharacterId) {
      const found = benchChars.find(b => b.id === testOptions.chosenCharacterId);
      if (found) chosenIdx = found.benchIndex;
    }
    executeRecursos(chosenIdx);
    return;
  }

  if (!isPlayer || typeof showContextMenu !== 'function' || typeof window === 'undefined') {
    executeRecursos(benchChars[0].benchIndex);
    return;
  }

  const items = [
    {
      text: "📦 Activar Recursos (Jugar Personaje desde la Banca)",
      action: () => {
        if (benchChars.length === 1) {
          executeRecursos(benchChars[0].benchIndex);
        } else {
          const targets = benchChars.map(b => ({ id: b.id, text: b.name, benchIndex: b.benchIndex }));
          openCardChooserModal(targets, "Recursos: Selecciona 1 Personaje de tu banca para jugar al campo", (chosenIdx) => {
            executeRecursos(benchChars[chosenIdx].benchIndex);
          });
        }
      }
    },
    {
      text: "❌ No activar Recursos",
      action: () => {
        addLog(`${tag} Decidiste no activar el efecto de Recursos.`, 'var(--text-muted)');
        if (typeof onDone === 'function') onDone(false, { reason: 'user_declined' });
      }
    }
  ];

  const dummyEvent = { clientX: window.innerWidth / 2 - 140, clientY: window.innerHeight / 2 - 80 };
  showContextMenu(dummyEvent, items, () => {
    addLog(`${tag} Decidiste no activar el efecto de Recursos.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false, { reason: 'user_declined' });
  });
}

function checkRecursosSP404OrProceed(nextCallback) {
  const proceed = () => {
    if (typeof nextCallback === 'function') nextCallback();
  };

  const currentTurnOwner = playtestState.turnOwner;
  // Si el turno que finaliza es del oponente, el jugador comprueba Recursos
  if (currentTurnOwner === 'opponent') {
    checkAndTriggerRecursosSP404('player', {}, () => {
      proceed();
    });
  } else if (currentTurnOwner === 'player' && !playtestState.isOnlineMatch) {
    // Si el turno que finaliza es del jugador, el rival comprueba Recursos
    checkAndTriggerRecursosSP404('opponent', {}, () => {
      proceed();
    });
  } else {
    proceed();
  }
}
window.checkAndTriggerRecursosSP404 = checkAndTriggerRecursosSP404;
window.checkRecursosSP404OrProceed = checkRecursosSP404OrProceed;

function checkAndTriggerTageroSP176(skillId, removedByOpponentEffect = false) {
  if (!removedByOpponentEffect) return;
  const isTageroSkill = id => cardsDatabase[id].tipo === 'Skill' && cardsDatabase[id].portador && cardsDatabase[id].portador.includes("Tagero");
  if (!isTageroSkill(skillId)) return;

  if (!playtestState.hand.includes('BBX-SP176')) return;
  if (isDrawByCharacterBlocked() || playtestState.cannotDrawByEffectsThisTurn) return;
  if (playtestState.deck.length < 2) return;

  const items = [
    {
      text: "⚡ Activar Tagero (SP176) de tu Mano (Robar 2 cartas)",
      action: () => {
        const tHandIdx = playtestState.hand.indexOf('BBX-SP176');
        if (tHandIdx === -1) {
          updatePlaytestView();
          return;
        }
        const discardedId = playtestState.hand.splice(tHandIdx, 1)[0];
        playtestState.grave.push(discardedId);
        addLog(`[Efecto Tagero SP176] Enviaste a Tagero de tu mano al cementerio.`, 'var(--accent-purple)');

        checkAndTriggerAlBorde(discardedId);
        checkAndTriggerReflejo(discardedId);
        checkAndTriggerEstrategia(discardedId);
        checkAndTriggerHackeo(discardedId);
        checkAndTriggerLlamarada(discardedId);
        checkAndTriggerEspiral(discardedId);
        checkAndTriggerFirewall(discardedId);
        checkAndTriggerFervor(discardedId);
        checkAndTriggerApunteIgneo(discardedId);
        checkAndTriggerCrimenNocturno(discardedId);
        checkAndTriggerAlmacenamientoFallido(discardedId, 'hand');
        checkAndTriggerKatshi159(discardedId);
        checkAndTriggerFulgorOfensivo(discardedId);
        checkAndTriggerEspiralDigital(discardedId, 'hand');
        checkAndTriggerBolaDeFuego(discardedId, 'hand');

        if (playtestState.deck.length >= 2) {
          const drawn1 = playtestState.deck.shift();
          playtestState.hand.push(drawn1);
          const drawn2 = playtestState.deck.shift();
          playtestState.hand.push(drawn2);

          addLog(`[Efecto Tagero SP176] Robaste 2 cartas de tu deck: <strong>${cardsDatabase[drawn1].nombre}</strong> y <strong>${cardsDatabase[drawn2].nombre}</strong>.`, 'var(--accent-purple)');
          checkAndTriggerInestabilidad('player');
          checkAndTriggerServicioImpecable('player', 'Tagero SP176');
        }
        updatePlaytestView();
      }
    },
    {
      text: "💥 No activar Tagero",
      action: () => {
        addLog(`[Efecto Tagero SP176] Decidiste no activar el efecto de Tagero.`, 'var(--text-muted)');
        updatePlaytestView();
      }
    }
  ];

  addLog(`[Trigger] Tu Skill propia de Tagero (${cardsDatabase[skillId].nombre}) fue enviada al cementerio por efecto rival teniendo a Tagero en mano.`, 'var(--accent-cyan)');
  const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
  showContextMenu(dummyEvent, items);
}

// Candidez BBX-SP372: Helper directo para protección de Skills portadas contra barajado al deck
function checkAndProtectCandidezSP372(targetOwner, count, onCancel, onProceed) {
  const isPlayer = targetOwner === 'player';
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;
  const deck = isPlayer ? playtestState.deck : playtestState.opponentDeck;
  const adversaryOwner = isPlayer ? 'opponent' : 'player';

  const candidezSlots = [];
  slots.forEach((s, sIdx) => {
    if (s.character && s.skills) {
      s.skills.forEach((skId, skIdx) => {
        if (skId === 'BBX-SP372' && (typeof isSkillEffectBlocked !== 'function' || !isSkillEffectBlocked('BBX-SP372', targetOwner, s))) {
          candidezSlots.push({
            slot: s,
            sIdx,
            skIdx,
            charName: cardsDatabase[s.character]?.nombre || 'Personaje'
          });
        }
      });
    }
  });

  if (candidezSlots.length === 0) {
    if (onProceed) onProceed();
    return;
  }

  const applyCandidez = (chosenSlotInfo) => {
    const slot = chosenSlotInfo.slot;
    let cIdx = chosenSlotInfo.skIdx;
    if (slot.skills[cIdx] !== 'BBX-SP372') {
      cIdx = slot.skills.indexOf('BBX-SP372');
    }
    if (cIdx !== -1) {
      slot.skills.splice(cIdx, 1);
      deck.push('BBX-SP372');
      shuffleArray(deck);

      if (isPlayer) {
        addLog(`[Efecto Candidez BBX-SP372] Barajaste a Candidez portada (de ${chosenSlotInfo.charName}) a tu deck en lugar de barajar las Skills portadas.`, 'var(--accent-purple)');
      } else {
        addLog(`[Efecto Candidez BBX-SP372] El adversario barajó a Candidez portada (de ${chosenSlotInfo.charName}) a su deck en su lugar. Sus Skills portadas fueron protegidas de ser barajadas al deck.`, 'var(--accent-purple)');
      }

      if (typeof notifySkillsRemovedByEffect === 'function') {
        notifySkillsRemovedByEffect(1, 'deck', adversaryOwner);
      }
      updatePlaytestView();
    }
    if (onCancel) onCancel();
  };

  const items = [
    {
      text: isPlayer
        ? "🛡️ Activar Candidez (SP372) portada (Barajar al deck en su lugar)"
        : "🛡️ Activar Candidez (SP372) del rival portada (Barajar al deck en su lugar)",
      action: () => {
        if (candidezSlots.length === 1) {
          applyCandidez(candidezSlots[0]);
        } else {
          const options = candidezSlots.map(cs => ({
            text: `Barajar Candidez de ${cs.charName} (Slot ${cs.sIdx + 1})`,
            action: () => applyCandidez(cs)
          }));
          const dummyEv = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 60 };
          showContextMenu(dummyEv, options);
        }
      }
    },
    {
      text: isPlayer
        ? "❌ No activar Candidez (Permitir que las Skills sean barajadas)"
        : "❌ No activar Candidez del rival (Permitir que las Skills sean barajadas)",
      action: () => {
        if (onProceed) onProceed();
      }
    }
  ];

  const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
  showContextMenu(dummyEvent, items);
}

