function checkAndTriggerFulgorProminentePlayer(cardId) {
  if (cardId !== 'BBX-SP124') return;

  const getEquippedSkills = () => {
    const list = [];
    playtestState.slots.forEach((s, sIdx) => {
      if (s.character) {
        s.skills.forEach((skId, skIdx) => {
          list.push({ id: skId, owner: 'player', charName: cardsDatabase[s.character].nombre, slotIdx: sIdx, skIdx });
        });
      }
    });
    playtestState.opponentSlots.forEach((s, sIdx) => {
      if (s.character) {
        s.skills.forEach((skId, skIdx) => {
          if (canRemoveSkillByEffect(skId, true, 'player')) {
            list.push({ id: skId, owner: 'opponent', charName: cardsDatabase[s.character].nombre, slotIdx: sIdx, skIdx });
          }
        });
      }
    });
    return list;
  };

  const targetableSkills = getEquippedSkills();
  if (targetableSkills.length === 0) {
    addLog(`[Efecto ¡Fulgor prominente!] No se puede activar: No hay Habilidades portadas elegibles en el campo para destruir.`, 'var(--text-muted)');
    return;
  }

  const items = [
    {
      text: "⚡ Activar ¡Fulgor prominente! (Destruir 1 Skill portada)",
      action: () => {
        const chooserTargets = targetableSkills.map(item => {
          return {
            id: item.id,
            owner: item.owner,
            text: `"${cardsDatabase[item.id].nombre}" (de ${item.charName} - ${item.owner === 'player' ? 'Tú' : 'Rival'})`
          };
        });

        openCardChooserModal(chooserTargets, "¡Fulgor prominente!: Selecciona 1 Skill portada para enviar al cementerio", (chosenIdx) => {
          const target = targetableSkills[chosenIdx];
          
          if (target.owner === 'player') {
            const pSlot = playtestState.slots[target.slotIdx];
            const removedId = pSlot.skills.splice(target.skIdx, 1)[0];
            playtestState.grave.push(removedId);
            addLog(`[Efecto ¡Fulgor prominente!] Enviaste al cementerio tu Skill <strong>${cardsDatabase[removedId].nombre}</strong> (de ${target.charName}).`, 'var(--accent-purple)');
            
            checkAndTriggerSupportPlan(removedId);
            checkAndTriggerDesechos(removedId);
            checkAndTriggerSplash(removedId);
            checkAndTriggerArremetida(removedId);
            checkAndTriggerCargaSorpresa(removedId);
            checkAndTriggerRomperElPiso(removedId);
            checkAndTriggerReflejo(removedId);
            checkAndTriggerRemembranza(removedId, 'player');
            updatePlaytestView();
          } else {
            checkAndProtectSendSkillsToGrave('opponent', () => {
              updatePlaytestView();
            }, () => {
              const oSlot = playtestState.opponentSlots[target.slotIdx];
              const removedId = oSlot.skills.splice(target.skIdx, 1)[0];
              playtestState.opponentGrave.push(removedId);
              addLog(`[Efecto ¡Fulgor prominente!] Enviaste al cementerio del Rival su Skill <strong>${cardsDatabase[removedId].nombre}</strong> (de ${target.charName}).`, 'var(--accent-purple)');
              checkAndTriggerRemembranza(removedId, 'opponent');
              updatePlaytestView();
            });
          }
        });
      }
    },
    {
      text: "❌ No activar ¡Fulgor prominente!",
      action: () => {
        addLog(`[Efecto ¡Fulgor prominente!] Decidiste no activar su efecto.`, 'var(--text-muted)');
      }
    }
  ];

  const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
  showContextMenu(dummyEvent, items);
}

