function checkAndTriggerDesdeLaSombraPlayer(cardId) {
  if (cardId !== 'BBX-SP134') return;

  if (isPuntoDeControlActive()) {
    addLog(`[Punto de control] Efecto de "Desde la sombra" bloqueado: Ningún jugador puede regresar cartas del cementerio al deck.`, 'var(--text-muted)');
    return;
  }

  const isEligible = id => cardsDatabase[id].nombre !== 'Desde la sombra';
  const playerGraveCards = playtestState.grave.filter(isEligible);
  const opponentGraveCards = playtestState.opponentGrave.filter(isEligible);

  if (playerGraveCards.length === 0 && opponentGraveCards.length === 0) {
    addLog(`[Efecto Desde la sombra] No se puede activar: No hay cartas elegibles en los cementerios.`, 'var(--text-muted)');
    return;
  }

  const items = [
    {
      text: "⚡ Activar Desde la sombra (Barajar 1 carta del cementerio al deck)",
      action: () => {
        const choices = [];
        playerGraveCards.forEach(id => choices.push({ id, owner: 'player', label: `"${cardsDatabase[id].nombre}" (Tu Cementerio)` }));
        opponentGraveCards.forEach(id => choices.push({ id, owner: 'opponent', label: `"${cardsDatabase[id].nombre}" (Cementerio Rival)` }));

        const chooserTargets = choices.map(opt => {
          return {
            id: opt.id,
            owner: opt.owner,
            text: opt.label
          };
        });

        openCardChooserModal(chooserTargets, "Desde la sombra: Selecciona 1 carta para barajar al deck de su dueño", (chosenIdx) => {
          const chosen = choices[chosenIdx];
          
          if (chosen.owner === 'player') {
            const idxInGrave = playtestState.grave.indexOf(chosen.id);
            if (idxInGrave !== -1) {
              playtestState.grave.splice(idxInGrave, 1);
            }
            playtestState.deck.push(chosen.id);
            shuffleArray(playtestState.deck);
            addLog(`[Efecto Desde la sombra] Barajaste <strong>${cardsDatabase[chosen.id].nombre}</strong> de tu cementerio a tu mazo.`, 'var(--accent-purple)');
          } else {
            const idxInGrave = playtestState.opponentGrave.indexOf(chosen.id);
            if (idxInGrave !== -1) {
              playtestState.opponentGrave.splice(idxInGrave, 1);
            }
            playtestState.opponentDeck.push(chosen.id);
            shuffleArray(playtestState.opponentDeck);
            addLog(`[Efecto Desde la sombra] Barajaste <strong>${cardsDatabase[chosen.id].nombre}</strong> del cementerio del Rival a su mazo.`, 'var(--accent-purple)');
          }

          updatePlaytestView();
        });
      }
    },
    {
      text: "❌ No activar Desde la sombra",
      action: () => {
        addLog(`[Efecto Desde la sombra] Decidiste no activar su efecto.`, 'var(--text-muted)');
      }
    }
  ];

  const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
  showContextMenu(dummyEvent, items);
}

