// Drago-fulgor (BBX-SP303): Si esta carta es enviada al cementerio por el efecto de una carta, puedes agregar a tu mano desde tu deck 1 Personaje Ryu-chan.
let lastDragoFulgorTriggerTime = 0;
function checkAndTriggerDragoFulgor(cardId, owner = 'player') {
  if (cardId !== 'BBX-SP303') return;

  const now = Date.now();
  if (now - lastDragoFulgorTriggerTime < 250) return;
  lastDragoFulgorTriggerTime = now;

  if (owner === 'player') {
    const ryuChanInDeck = [];
    playtestState.deck.forEach((id, idx) => {
      const c = cardsDatabase[id];
      if (c && c.tipo === 'Personaje' && c.nombre.includes("Ryu-chan")) {
        ryuChanInDeck.push({ id, idx });
      }
    });

    if (ryuChanInDeck.length === 0) {
      addLog(`[Drago-fulgor BBX-SP303] Enviada al cementerio por efecto, pero no tienes ningún Personaje Ryu-chan en tu deck.`, 'var(--text-muted)');
      return;
    }

    const items = [
      {
        text: `🐉 Activar Drago-fulgor (Agregar 1 Ryu-chan de tu deck a tu mano)`,
        action: () => {
          const chooserTargets = ryuChanInDeck.map(item => ({ id: item.id, owner: 'player', from: 'deck' }));
          openCardChooserModal(chooserTargets, "Drago-fulgor (SP303): Selecciona 1 Personaje Ryu-chan para agregar a tu mano", (chosenIdx) => {
            const chosen = ryuChanInDeck[chosenIdx];
            const realIdx = playtestState.deck.indexOf(chosen.id);
            if (realIdx !== -1) {
              playtestState.deck.splice(realIdx, 1);
              playtestState.hand.push(chosen.id);
            }
            shuffleArray(playtestState.deck);
            addLog(`[Efecto Drago-fulgor BBX-SP303] Agregaste a <strong>${cardsDatabase[chosen.id].nombre}</strong> de tu deck a tu mano y barajaste tu deck.`, 'var(--accent-purple)');
            checkAndTriggerInestabilidad('player');
            updatePlaytestView();
          });
        }
      },
      {
        text: `❌ No activar Drago-fulgor`,
        action: () => {
          addLog(`[Efecto Drago-fulgor BBX-SP303] Decidiste no activar su efecto.`, 'var(--text-muted)');
          updatePlaytestView();
        }
      }
    ];

    addLog(`[Trigger] Se envió a <strong>Drago-fulgor (SP303)</strong> a tu cementerio por efecto de una carta: puedes agregar a tu mano 1 Personaje Ryu-chan desde tu deck.`, 'var(--accent-cyan)');
    const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
    showContextMenu(dummyEvent, items);
  } else {
    const ryuChanInOppDeck = [];
    playtestState.opponentDeck.forEach((id, idx) => {
      const c = cardsDatabase[id];
      if (c && c.tipo === 'Personaje' && c.nombre.includes("Ryu-chan")) {
        ryuChanInOppDeck.push({ id, idx });
      }
    });

    if (ryuChanInOppDeck.length === 0) {
      addLog(`[Drago-fulgor BBX-SP303 Rival] Enviada al cementerio por efecto, pero el rival no tiene ningún Personaje Ryu-chan en su deck.`, 'var(--text-muted)');
      return;
    }

    const items = [
      {
        text: `🐉 [Rival] Activar Drago-fulgor (Agregar 1 Ryu-chan de su deck a su mano)`,
        action: () => {
          const chosen = ryuChanInOppDeck[0];
          const realIdx = playtestState.opponentDeck.indexOf(chosen.id);
          if (realIdx !== -1) {
            playtestState.opponentDeck.splice(realIdx, 1);
            playtestState.opponentHand.push(chosen.id);
          }
          shuffleArray(playtestState.opponentDeck);
          addLog(`[Efecto Drago-fulgor BBX-SP303 Rival] El rival agregó a <strong>${cardsDatabase[chosen.id].nombre}</strong> de su deck a su mano y barajó su deck.`, 'var(--accent-purple)');
          checkAndTriggerInestabilidad('opponent');
          updatePlaytestView();
        }
      },
      {
        text: `❌ [Rival] No activar Drago-fulgor`,
        action: () => {
          addLog(`[Efecto Drago-fulgor BBX-SP303 Rival] El rival decidió no activar su efecto.`, 'var(--text-muted)');
          updatePlaytestView();
        }
      }
    ];

    addLog(`[Trigger Rival] Se envió a <strong>Drago-fulgor (SP303)</strong> al cementerio del rival por efecto de una carta: puede agregar a su mano 1 Personaje Ryu-chan desde su deck.`, 'var(--accent-cyan)');
    const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
    showContextMenu(dummyEvent, items);
  }
}

// Alumbrar (BBX-SP347): "Si esta carta es enviada al cementerio desde tu deck, puedes jugar a tu campo 1 Personaje Roy directamente desde tu deck."
let lastAlumbrarTriggerTime = 0;
function checkAndTriggerAlumbrarSP347(cardId, fromZone = 'deck', owner = 'player') {
  if (cardId !== 'BBX-SP347') return;
  if (fromZone !== 'deck') return;

  const now = Date.now();
  if (now - lastAlumbrarTriggerTime < 250) return;
  lastAlumbrarTriggerTime = now;

  // Comprobar bloqueo de Skills en cementerio (Secretos de Fafnirland BBX-SP332)
  if (window.RulesEngine && typeof window.RulesEngine.isSkillGraveEffectBlocked === 'function' && window.RulesEngine.isSkillGraveEffectBlocked()) {
    addLog(`[Efecto Alumbrar BBX-SP347] No se puede activar: Bloqueado por Secretos de Fafnirland (BBX-SP332): Ningún jugador puede usar efectos de Skills desde sus cementerios.`, 'var(--text-muted)');
    return;
  }

  // Comprobar bloqueo de jugar Personajes (¡Inmovilizar! BBX-SP045)
  const isInmovilizarActive = (playtestState.slots || []).some(s => s.character && s.skills.includes('BBX-SP045')) || 
                              (playtestState.opponentSlots || []).some(s => s.character && s.skills.includes('BBX-SP045'));
  if (isInmovilizarActive) {
    addLog(`[Efecto Alumbrar BBX-SP347] No se puede activar: Bloqueado por el efecto de <strong>¡Inmovilizar!</strong> (ningún jugador puede jugar Personajes desde su mano o mazo).`, 'var(--text-muted)');
    return;
  }

  // Comprobar bloqueo de jugar Personajes desde el deck (Katherine BBX-SP350)
  if (typeof isPlayCharacterFromDeckBlocked === 'function' && isPlayCharacterFromDeckBlocked()) {
    addLog(`[Efecto Alumbrar BBX-SP347 ${owner === 'player' ? '' : 'Rival'}] No se puede activar: Bloqueado por el efecto continuo de <strong>Katherine (BBX-SP350)</strong> (ningún jugador puede jugar Personajes directamente desde sus decks por efectos de cartas).`, 'var(--text-muted)');
    return;
  }

  if (owner === 'player') {
    const freeSlotIndices = (playtestState.slots || []).map((s, idx) => (!s.character ? idx : -1)).filter(idx => idx !== -1);
    if (freeSlotIndices.length === 0) {
      addLog(`[Efecto Alumbrar BBX-SP347] Se envió al cementerio desde tu deck, pero no tienes ningún slot libre en tu campo para jugar a un Personaje Roy.`, 'var(--text-muted)');
      return;
    }

    const roysInDeck = (playtestState.deck || []).filter(id => {
      const c = cardsDatabase[id];
      return c && c.tipo === 'Personaje' && c.nombre && c.nombre.includes("Roy");
    });
    if (roysInDeck.length === 0) {
      addLog(`[Efecto Alumbrar BBX-SP347] Se envió al cementerio desde tu deck, pero no hay ningún Personaje Roy en tu deck.`, 'var(--text-muted)');
      return;
    }

    const items = [
      {
        text: "⚡ Activar Alumbrar (Jugar 1 Roy desde tu deck)",
        action: () => {
          if (typeof notifySkillInGraveEffectUsed === 'function') {
            notifySkillInGraveEffectUsed('player');
          }
          const chooserTargets = roysInDeck.map(id => ({ id, owner: 'player', from: 'deck' }));
          openCardChooserModal(chooserTargets, "Alumbrar (SP347): Selecciona 1 Personaje Roy de tu deck para jugar al campo", (chosenIdx) => {
            const chosenCharId = roysInDeck[chosenIdx];
            const charCard = cardsDatabase[chosenCharId] || { nombre: chosenCharId };

            const deployToSlot = (targetSlotIdx) => {
              const dIdx = playtestState.deck.indexOf(chosenCharId);
              if (dIdx !== -1) {
                playtestState.deck.splice(dIdx, 1);
              }
              const targetSlot = playtestState.slots[targetSlotIdx];
              targetSlot.character = chosenCharId;
              targetSlot.skills = [];
              targetSlot.usedSkills = [];
              targetSlot.usedSkillIndexes = [];
              targetSlot.isRotated = false;
              targetSlot.effectUsed = false;

              shuffleArray(playtestState.deck);
              addLog(`[Efecto Alumbrar BBX-SP347] Jugaste a <strong>${charCard.nombre}</strong> directamente desde tu deck al Slot ${targetSlotIdx + 1} y barajaste tu deck.`, 'var(--accent-purple)');
              checkAndTriggerInestabilidad('player');
              if (typeof notifyCharacterPlayedDirectlyFromDeck === 'function') {
                notifyCharacterPlayedDirectlyFromDeck('player', chosenCharId, targetSlotIdx);
              }
              updatePlaytestView();
            };

            const currentFreeSlots = playtestState.slots.map((s, idx) => (!s.character ? idx : -1)).filter(idx => idx !== -1);
            if (currentFreeSlots.length === 0) {
              addLog(`[Efecto Alumbrar BBX-SP347] No hay slots libres disponibles en tu campo.`, 'var(--text-muted)');
              updatePlaytestView();
              return;
            }
            if (currentFreeSlots.length === 1) {
              deployToSlot(currentFreeSlots[0]);
            } else {
              const slotItems = currentFreeSlots.map(sIdx => ({
                text: `📍 Jugar en Slot ${sIdx + 1}`,
                action: () => deployToSlot(sIdx)
              }));
              const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
              showContextMenu(dummyEvent, slotItems);
            }
          });
        }
      },
      {
        text: "❌ No activar Alumbrar",
        action: () => {
          addLog(`[Efecto Alumbrar BBX-SP347] Decidiste no activar el efecto de Alumbrar.`, 'var(--text-muted)');
          updatePlaytestView();
        }
      }
    ];

    addLog(`[Trigger] Se envió a <strong>Alumbrar (SP347)</strong> al cementerio desde tu deck: puedes jugar 1 Personaje Roy de tu deck a tu campo.`, 'var(--accent-cyan)');
    const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
    showContextMenu(dummyEvent, items);
  } else {
    // owner === 'opponent'
    const freeSlotIndices = (playtestState.opponentSlots || []).map((s, idx) => (!s.character ? idx : -1)).filter(idx => idx !== -1);
    if (freeSlotIndices.length === 0) {
      addLog(`[Efecto Alumbrar BBX-SP347 Rival] Se envió al cementerio desde el deck rival, pero el rival no tiene slots libres en su campo.`, 'var(--text-muted)');
      return;
    }

    const roysInDeck = (playtestState.opponentDeck || []).filter(id => {
      const c = cardsDatabase[id];
      return c && c.tipo === 'Personaje' && c.nombre && c.nombre.includes("Roy");
    });
    if (roysInDeck.length === 0) {
      addLog(`[Efecto Alumbrar BBX-SP347 Rival] Se envió al cementerio desde el deck rival, pero no hay ningún Personaje Roy en el deck rival.`, 'var(--text-muted)');
      return;
    }

    const items = [
      {
        text: "⚡ [Rival] Activar Alumbrar (Jugar 1 Roy desde el deck rival)",
        action: () => {
          if (typeof notifySkillInGraveEffectUsed === 'function') {
            notifySkillInGraveEffectUsed('opponent');
          }
          const chooserTargets = roysInDeck.map(id => ({ id, owner: 'opponent', from: 'deck' }));
          openCardChooserModal(chooserTargets, "[Rival] Alumbrar (SP347): Selecciona 1 Personaje Roy del deck rival para jugar al campo", (chosenIdx) => {
            const chosenCharId = roysInDeck[chosenIdx];
            const charCard = cardsDatabase[chosenCharId] || { nombre: chosenCharId };

            const deployToOppSlot = (targetSlotIdx) => {
              const dIdx = playtestState.opponentDeck.indexOf(chosenCharId);
              if (dIdx !== -1) {
                playtestState.opponentDeck.splice(dIdx, 1);
              }
              const targetSlot = playtestState.opponentSlots[targetSlotIdx];
              targetSlot.character = chosenCharId;
              targetSlot.skills = [];
              targetSlot.usedSkills = [];
              targetSlot.usedSkillIndexes = [];
              targetSlot.isRotated = false;
              targetSlot.effectUsed = false;

              shuffleArray(playtestState.opponentDeck);
              addLog(`[Efecto Alumbrar BBX-SP347 Rival] El rival jugó a <strong>${charCard.nombre}</strong> directamente desde su deck al Slot ${targetSlotIdx + 1} rival y barajó su deck.`, 'var(--accent-purple)');
              checkAndTriggerInestabilidad('opponent');
              if (typeof notifyCharacterPlayedDirectlyFromDeck === 'function') {
                notifyCharacterPlayedDirectlyFromDeck('opponent', chosenCharId, targetSlotIdx);
              }
              updatePlaytestView();
            };

            const currentFreeSlots = playtestState.opponentSlots.map((s, idx) => (!s.character ? idx : -1)).filter(idx => idx !== -1);
            if (currentFreeSlots.length === 0) {
              addLog(`[Efecto Alumbrar BBX-SP347 Rival] No hay slots libres disponibles en el campo rival.`, 'var(--text-muted)');
              updatePlaytestView();
              return;
            }
            if (currentFreeSlots.length === 1) {
              deployToOppSlot(currentFreeSlots[0]);
            } else {
              const slotItems = currentFreeSlots.map(sIdx => ({
                text: `📍 Jugar en Slot ${sIdx + 1} Rival`,
                action: () => deployToOppSlot(sIdx)
              }));
              const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
              showContextMenu(dummyEvent, slotItems);
            }
          });
        }
      },
      {
        text: "❌ [Rival] No activar Alumbrar",
        action: () => {
          addLog(`[Efecto Alumbrar BBX-SP347 Rival] El rival decidió no activar el efecto de Alumbrar.`, 'var(--text-muted)');
          updatePlaytestView();
        }
      }
    ];

    addLog(`[Trigger Rival] Se envió a <strong>Alumbrar (SP347)</strong> al cementerio desde el deck rival: puede jugar 1 Personaje Roy de su deck a su campo.`, 'var(--accent-cyan)');
    const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
    showContextMenu(dummyEvent, items);
  }
}

// Helica BBX-SP335:
// "Mientras esta carta se encuentre en la banca: Cuando 1 Personaje que controles es objetivo de un ataque, puedes barajar al deck Skills portadas hasta la cantidad de Personajes en tu banca."
function checkAndTriggerHelicaBenchSP335(defenderOwner, defenderSlot, onContinue) {
  const benchList = defenderOwner === 'player' ? playtestState.bench : playtestState.opponentBench;
  const hasHelicaBench = (benchList || []).some(b => {
    const bId = (typeof b === 'object' && b !== null) ? b.id : b;
    return bId === 'BBX-SP335';
  });

  if (!hasHelicaBench) {
    onContinue();
    return;
  }

  // Comprobar bloqueos de banca y de efectos de personaje
  if (typeof isBenchEffectBlocked === 'function' ? isBenchEffectBlocked(defenderOwner) : (typeof isAislamientoActive === 'function' && isAislamientoActive())) {
    onContinue();
    return;
  }
  if (typeof isCharacterEffectBlocked === 'function' && isCharacterEffectBlocked(defenderOwner)) {
    onContinue();
    return;
  }

  // Reunir todas las Skills portadas en cualquier campo que puedan ser removidas al deck por defenderOwner
  const candidates = [];
  playtestState.slots.forEach((s, sIdx) => {
    if (s.character && s.skills) {
      const isOppSlot = defenderOwner === 'opponent';
      s.skills.forEach((skId, skIdx) => {
        if (canRemoveSkillByEffect(skId, isOppSlot, defenderOwner, s, 'deck')) {
          candidates.push({
            id: skId,
            owner: 'player',
            slotIndex: sIdx,
            skillIndex: skIdx,
            from: 'field',
            charName: cardsDatabase[s.character] ? cardsDatabase[s.character].nombre : 'Personaje'
          });
        }
      });
    }
  });

  playtestState.opponentSlots.forEach((s, sIdx) => {
    if (s.character && s.skills) {
      const isOppSlot = defenderOwner === 'player';
      s.skills.forEach((skId, skIdx) => {
        if (canRemoveSkillByEffect(skId, isOppSlot, defenderOwner, s, 'deck')) {
          candidates.push({
            id: skId,
            owner: 'opponent',
            slotIndex: sIdx,
            skillIndex: skIdx,
            from: 'field',
            charName: cardsDatabase[s.character] ? cardsDatabase[s.character].nombre : 'Personaje'
          });
        }
      });
    }
  });

  if (candidates.length === 0) {
    onContinue();
    return;
  }

  const maxQty = Math.min(benchList.length, candidates.length);

  const resolveShuffle = (chosenIndices) => {
    if (!chosenIndices || chosenIndices.length === 0) {
      onContinue();
      return;
    }

    const selectedItems = chosenIndices.map(idx => candidates[idx]);
    // Ordenar de mayor a menor índice para no alterar los índices de skills restantes en el slot
    selectedItems.sort((a, b) => {
      if (a.owner !== b.owner) return a.owner === 'player' ? -1 : 1;
      if (a.slotIndex !== b.slotIndex) return a.slotIndex - b.slotIndex;
      return b.skillIndex - a.skillIndex;
    });

    let shufflePlayer = false;
    let shuffleOpponent = false;
    const logs = [];

    selectedItems.forEach(item => {
      const isPlayer = item.owner === 'player';
      const targetSlot = isPlayer ? playtestState.slots[item.slotIndex] : playtestState.opponentSlots[item.slotIndex];
      let idx = item.skillIndex;
      if (targetSlot.skills[idx] !== item.id) {
        idx = targetSlot.skills.indexOf(item.id);
      }
      if (idx !== -1) {
        const removedId = targetSlot.skills.splice(idx, 1)[0];
        const skName = cardsDatabase[removedId] ? cardsDatabase[removedId].nombre : removedId;
        if (isPlayer) {
          playtestState.deck.push(removedId);
          shufflePlayer = true;
          logs.push(`"${skName}" (de ${item.charName} - Tú)`);
        } else {
          playtestState.opponentDeck.push(removedId);
          shuffleOpponent = true;
          logs.push(`"${skName}" (de ${item.charName} - Rival)`);
        }
      }
    });

    if (shufflePlayer) shuffleArray(playtestState.deck);
    if (shuffleOpponent) shuffleArray(playtestState.opponentDeck);

    const prefix = defenderOwner === 'player' ? '[Efecto Helica BBX-SP335]' : '[Efecto Helica BBX-SP335 Rival]';
    addLog(`${prefix} Barajaste al deck ${logs.length} Skill(s) portada(s) (Banca: ${benchList.length}): ${logs.join(', ')}.`, 'var(--accent-purple)');

    if (typeof notifySkillsRemovedByEffect === 'function') {
      notifySkillsRemovedByEffect(logs.length, null, defenderOwner);
    }

    updatePlaytestView();
    onContinue();
  };

  if (defenderOwner === 'player') {
    const items = [
      {
        text: `💥 No activar Helica (BBX-SP335)`,
        action: () => {
          onContinue();
        }
      },
      {
        text: `🛡️ Activar Helica (Banca: Barajar hasta ${maxQty} Skill(s) portadas al deck)`,
        action: () => {
          openUpToMultiCardChooserModal(candidates, `Helica (Banca): Selecciona hasta ${maxQty} Skill(s) portadas para barajar al deck`, maxQty, resolveShuffle);
        }
      }
    ];
    const dummyEvent = { clientX: window.innerWidth / 2 - 140, clientY: window.innerHeight / 2 - 80 };
    showContextMenu(dummyEvent, items, () => {
      onContinue();
    });
  } else {
    const items = [
      {
        text: `💥 No activar Helica del Rival`,
        action: () => {
          onContinue();
        }
      },
      {
        text: `🛡️ [Rival] Activar Helica (Banca: Barajar hasta ${maxQty} Skill(s) portadas al deck)`,
        action: () => {
          openUpToMultiCardChooserModal(candidates, `[Rival] Helica (Banca): Selecciona hasta ${maxQty} Skill(s) portadas para barajar al deck`, maxQty, resolveShuffle);
        }
      }
    ];
    const dummyEvent = { clientX: window.innerWidth / 2 - 140, clientY: window.innerHeight / 2 - 80 };
    showContextMenu(dummyEvent, items, () => {
      onContinue();
    });
  }
}

// BBX-SP309 Alterar pacto:
// "Si el Personaje que porta esta Skill es objetivo de un ataque, puedes devolver a la mano hasta 3 Skills portadas en el campo de tu adversario. Cada Personaje solo puede portar 1 'Alterar pacto' a la vez."
function checkAndTriggerAlterarPacto(targetOwner, targetSlot, onContinue) {
  if (!targetSlot || !targetSlot.skills || !targetSlot.skills.includes('BBX-SP309')) {
    onContinue();
    return;
  }

  const charCard = cardsDatabase[targetSlot.character];
  if (!charCard || !charCard.nombre.includes("Void-oh")) {
    onContinue();
    return;
  }

  if (targetOwner === 'player') {
    if (isSkillEffectBlocked('BBX-SP309', 'player', targetSlot)) {
      onContinue();
      return;
    }

    const oppTargetable = [];
    playtestState.opponentSlots.forEach((s, sIdx) => {
      if (s.character && s.skills && s.skills.length > 0) {
        s.skills.forEach((sk, skIdx) => {
          if (canRemoveSkillByEffect(sk, true, 'player', s, 'hand')) {
            oppTargetable.push({
              id: sk,
              slotIndex: sIdx,
              skillIndex: skIdx,
              owner: 'opponent'
            });
          }
        });
      }
    });

    if (oppTargetable.length === 0) {
      onContinue();
      return;
    }

    const maxQty = Math.min(3, oppTargetable.length);
    const items = [
      {
        text: `💥 No activar "Alterar pacto"`,
        action: () => {
          onContinue();
        }
      },
      {
        text: `🛡️ Activar "Alterar pacto" (Devolver hasta ${maxQty} Skill(s) del rival a su mano)`,
        action: () => {
          openUpToMultiCardChooserModal(oppTargetable, `Alterar pacto: Selecciona hasta ${maxQty} Skill(s) portadas del rival para devolver a su mano`, maxQty, (chosenIndices) => {
            if (!chosenIndices || chosenIndices.length === 0) {
              onContinue();
              return;
            }

            const selectedItems = chosenIndices.map(idx => oppTargetable[idx]);
            selectedItems.sort((a, b) => b.skillIndex - a.skillIndex);

            const returnedNames = [];
            selectedItems.forEach(item => {
              const oppSlot = playtestState.opponentSlots[item.slotIndex];
              if (oppSlot && oppSlot.skills && oppSlot.skills[item.skillIndex] === item.id) {
                const removedId = oppSlot.skills.splice(item.skillIndex, 1)[0];
                playtestState.opponentHand.push(removedId);
                returnedNames.push(cardsDatabase[removedId].nombre);
              }
            });

            addLog(`[Efecto Alterar pacto BBX-SP309] Devolviste a la mano del adversario ${returnedNames.length} Skill(s) portada(s): <strong>${returnedNames.join(', ')}</strong>.`, 'var(--accent-purple)');
            updatePlaytestView();
            onContinue();
          });
        }
      }
    ];
    const dummyEvent = { clientX: window.innerWidth / 2 - 140, clientY: window.innerHeight / 2 - 80 };
    showContextMenu(dummyEvent, items, () => {
      onContinue();
    });
  } else {
    if (isSkillEffectBlocked('BBX-SP309', 'opponent', targetSlot)) {
      onContinue();
      return;
    }

    const playerTargetable = [];
    playtestState.slots.forEach((s, sIdx) => {
      if (s.character && s.skills && s.skills.length > 0) {
        s.skills.forEach((sk, skIdx) => {
          if (canRemoveSkillByEffect(sk, true, 'opponent', s, 'hand')) {
            playerTargetable.push({
              id: sk,
              slotIndex: sIdx,
              skillIndex: skIdx,
              owner: 'player'
            });
          }
        });
      }
    });

    if (playerTargetable.length === 0) {
      onContinue();
      return;
    }

    const maxQty = Math.min(3, playerTargetable.length);
    const items = [
      {
        text: `💥 No activar "Alterar pacto" del Rival`,
        action: () => {
          onContinue();
        }
      },
      {
        text: `🛡️ [Rival] Activar "Alterar pacto" (Devolver hasta ${maxQty} de tus Skills a tu mano)`,
        action: () => {
          openUpToMultiCardChooserModal(playerTargetable, `[Rival] Alterar pacto: Selecciona hasta ${maxQty} de tus Skills portadas para devolver a tu mano`, maxQty, (chosenIndices) => {
            if (!chosenIndices || chosenIndices.length === 0) {
              onContinue();
              return;
            }

            const selectedItems = chosenIndices.map(idx => playerTargetable[idx]);
            selectedItems.sort((a, b) => b.skillIndex - a.skillIndex);

            const returnedNames = [];
            selectedItems.forEach(item => {
              const pSlot = playtestState.slots[item.slotIndex];
              if (pSlot && pSlot.skills && pSlot.skills[item.skillIndex] === item.id) {
                const removedId = pSlot.skills.splice(item.skillIndex, 1)[0];
                playtestState.hand.push(removedId);
                returnedNames.push(cardsDatabase[removedId].nombre);
              }
            });

            addLog(`[Efecto Alterar pacto BBX-SP309 Rival] El rival devolvió a tu mano ${returnedNames.length} Skill(s) portada(s): <strong>${returnedNames.join(', ')}</strong>.`, 'var(--accent-purple)');
            updatePlaytestView();
            onContinue();
          });
        }
      }
    ];
    const dummyEvent = { clientX: window.innerWidth / 2 - 140, clientY: window.innerHeight / 2 - 80 };
    showContextMenu(dummyEvent, items, () => {
      onContinue();
    });
  }
}

// Katshi (BBX-SP344):
// "Si un Personaje Katshi que controles es objetivo de un ataque, puedes enviar esta carta en tu mano al cementerio, entonces porta desde tu cementerio 1 Skill propia de Katshi a 1 Personaje que controles."
function checkAndTriggerKatshiHandSP344(defenderOwner, defenderSlot, onContinue) {
  const isPlayer = defenderOwner === 'player';
  const hand = isPlayer ? playtestState.hand : playtestState.opponentHand;
  const grave = isPlayer ? playtestState.grave : playtestState.opponentGrave;
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;

  // 1. Debe haber un Personaje Katshi que controles como objetivo del ataque
  if (!defenderSlot || !defenderSlot.character) {
    onContinue();
    return;
  }
  const defCard = cardsDatabase[defenderSlot.character];
  if (!defCard || !defCard.nombre || !defCard.nombre.includes('Katshi')) {
    onContinue();
    return;
  }

  // 2. Debe tener BBX-SP344 en mano
  if (!hand.includes('BBX-SP344')) {
    onContinue();
    return;
  }

  // 3. Comprobar bloqueos de efectos de personajes en mano (Ahogarse, Nobuko)
  if (typeof isCharacterHandEffectBlocked === 'function' && isCharacterHandEffectBlocked(defenderOwner)) {
    onContinue();
    return;
  }

  // 4. Comprobar si puede portar skills desde el cementerio (Katherine BBX-SP085)
  if (typeof canEquipFromZone === 'function' && !canEquipFromZone('grave')) {
    onContinue();
    return;
  }

  // 5. Debe haber al menos 1 Skill propia de Katshi en el cementerio del defensor
  const eligibleSkills = grave.filter(id => {
    const c = cardsDatabase[id];
    return c && c.tipo === 'Skill' && c.portador && c.portador.includes('Katshi');
  });
  if (eligibleSkills.length === 0) {
    onContinue();
    return;
  }

  // 6. Debe haber al menos 1 Personaje en el campo para portarle la Skill
  const eligibleChars = [];
  slots.forEach((s, sIdx) => {
    if (s.character && cardsDatabase[s.character]) {
      eligibleChars.push({
        slot: s,
        slotIndex: sIdx,
        name: cardsDatabase[s.character].nombre
      });
    }
  });
  if (eligibleChars.length === 0) {
    onContinue();
    return;
  }

  const executeActivation = () => {
    const handIdx = hand.indexOf('BBX-SP344');
    if (handIdx === -1) {
      onContinue();
      return;
    }

    // Coste: Enviar BBX-SP344 de la mano al cementerio
    const discardedId = hand.splice(handIdx, 1)[0];
    grave.push(discardedId);
    addLog(`[Efecto Katshi BBX-SP344 ${isPlayer ? '' : 'Rival'}] ${isPlayer ? 'Enviaste' : 'El rival envió'} a <strong>Katshi</strong> de su mano al cementerio como costo.`, 'var(--accent-purple)');

    // Triggers de descarte de mano
    checkAndTriggerAlBorde(discardedId);
    checkAndTriggerReflejo(discardedId);
    checkAndTriggerEstrategia(discardedId);
    checkAndTriggerHackeo(discardedId);
    checkAndTriggerLlamarada(discardedId);
    checkAndTriggerEspiral(discardedId);
    checkAndTriggerFirewall(discardedId);
    checkAndTriggerFervor(discardedId);
    checkAndTriggerApunteIgneo(discardedId);
    checkAndTriggerCrimenNocturno(discardedId);
    checkAndTriggerAlmacenamientoFallido(discardedId, 'hand');
    checkAndTriggerKatshi159(discardedId);
    checkAndTriggerFulgorOfensivo(discardedId);
    checkAndTriggerEspiralDigital(discardedId, 'hand');
    checkAndTriggerBolaDeFuego(discardedId, 'hand');
    checkAndTriggerKatshi205(discardedId);
    checkAndTriggerRemembranza(discardedId, isPlayer ? 'player' : 'opponent');

    updatePlaytestView();

    // Re-evaluar skills disponibles en cementerio
    const currentEligibleSkills = grave.filter(id => {
      const c = cardsDatabase[id];
      return c && c.tipo === 'Skill' && c.portador && c.portador.includes('Katshi');
    });

    if (currentEligibleSkills.length === 0) {
      addLog(`[Efecto Katshi BBX-SP344 ${isPlayer ? '' : 'Rival'}] No quedan Skills propias de Katshi en el cementerio para portar.`, 'var(--text-muted)');
      onContinue();
      return;
    }

    const chooserTargets = currentEligibleSkills.map(id => ({
      id,
      owner: defenderOwner,
      from: 'grave'
    }));

    const modalTitle = isPlayer
      ? "Katshi (SP344): Selecciona 1 Skill propia de Katshi de tu cementerio para portar"
      : "[Rival] Katshi (SP344): Selecciona 1 Skill propia de Katshi de su cementerio para portar";

    openCardChooserModal(chooserTargets, modalTitle, (chosenIdx) => {
      const chosenSkillId = currentEligibleSkills[chosenIdx];

      // Re-evaluar personajes actuales en campo
      const currentEligibleChars = [];
      slots.forEach((s, sIdx) => {
        if (s.character && cardsDatabase[s.character]) {
          currentEligibleChars.push({
            slot: s,
            slotIndex: sIdx,
            name: cardsDatabase[s.character].nombre
          });
        }
      });

      if (currentEligibleChars.length === 0) {
        addLog(`[Efecto Katshi BBX-SP344 ${isPlayer ? '' : 'Rival'}] No hay Personajes en el campo para portar la Skill.`, 'var(--text-muted)');
        onContinue();
        return;
      }

      const portToTargetChar = (targetSlotObj) => {
        const gIdx = grave.indexOf(chosenSkillId);
        if (gIdx !== -1) {
          grave.splice(gIdx, 1);
        }
        targetSlotObj.slot.skills = targetSlotObj.slot.skills || [];
        targetSlotObj.slot.skills.push(chosenSkillId);

        const skillName = cardsDatabase[chosenSkillId] ? cardsDatabase[chosenSkillId].nombre : chosenSkillId;
        addLog(`[Efecto Katshi BBX-SP344 ${isPlayer ? '' : 'Rival'}] ${isPlayer ? 'Portaste' : 'El rival portó'} <strong>${skillName}</strong> desde el cementerio a <strong>${targetSlotObj.name}</strong> (Slot ${targetSlotObj.slotIndex + 1}).`, 'var(--accent-purple)');

        checkAndTriggerInestabilidad(defenderOwner);
        updatePlaytestView();
        onContinue();
      };

      if (currentEligibleChars.length === 1) {
        portToTargetChar(currentEligibleChars[0]);
      } else {
        const charItems = currentEligibleChars.map(c => ({
          text: `🛡️ Portar a ${c.name} (Slot ${c.slotIndex + 1})`,
          action: () => portToTargetChar(c)
        }));
        const dummyEvent2 = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
        showContextMenu(dummyEvent2, charItems, () => onContinue());
      }
    });
  };

  // Menú contextual para decidir si activar o no
  if (isPlayer) {
    const items = [
      {
        text: `🛡️ Activar Katshi (SP344) en Mano (Portar Skill de Katshi desde el cementerio)`,
        action: executeActivation
      },
      {
        text: `💥 No activar Katshi (BBX-SP344)`,
        action: () => {
          addLog(`[Trigger Katshi BBX-SP344] Decidiste no activar el efecto de Katshi desde tu mano.`, 'var(--text-muted)');
          onContinue();
        }
      }
    ];
    addLog(`[Trigger Katshi BBX-SP344] Tu Personaje Katshi (<strong>${defCard.nombre}</strong>) es objetivo de un ataque. Puedes activar a <strong>Katshi (SP344)</strong> desde tu mano.`, 'var(--accent-cyan)');
    const dummyEvent = { clientX: window.innerWidth / 2 - 140, clientY: window.innerHeight / 2 - 80 };
    showContextMenu(dummyEvent, items, () => onContinue());
  } else {
    const items = [
      {
        text: `🛡️ [RIVAL] Activar Katshi (SP344) en Mano (Portar Skill de Katshi desde su cementerio)`,
        action: executeActivation
      },
      {
        text: `💥 [RIVAL] No activar Katshi (BBX-SP344)`,
        action: () => {
          addLog(`[Trigger Katshi BBX-SP344 Rival] El rival decidió no activar el efecto de Katshi desde su mano.`, 'var(--text-muted)');
          onContinue();
        }
      }
    ];
    addLog(`[Trigger Katshi BBX-SP344 Rival] El Personaje Katshi rival (<strong>${defCard.nombre}</strong>) es objetivo de un ataque. El rival puede activar a <strong>Katshi (SP344)</strong> desde su mano.`, 'var(--accent-cyan)');
    const dummyEvent = { clientX: window.innerWidth / 2 - 140, clientY: window.innerHeight / 2 - 80 };
    showContextMenu(dummyEvent, items, () => onContinue());
  }
}

// Doble colisión (BBX-SP409): "Si tu adversario controla 2 o más Personajes y un Personaje de tu adversario declara un ataque, puedes portarle esta Skill desde tu mano o cementerio a 1 Personaje que controles. Solo puedes usar este efecto de \"Doble colisión\" una vez por turno."
function checkAndTriggerDobleColisionSP409(attackerOwner, targetSlot, onContinue, testOptions = {}) {
  const proceed = () => {
    if (typeof onContinue === 'function') onContinue();
  };

  const isPlayerAttacker = (attackerOwner === 'player');
  const defenderOwner = isPlayerAttacker ? 'opponent' : 'player';
  const isDefenderPlayer = (defenderOwner === 'player');
  const tag = isDefenderPlayer ? '[Efecto Doble colisión BBX-SP409]' : '[Rival - Efecto Doble colisión BBX-SP409]';

  // 1. El adversario del defensor (el atacante) debe controlar 2 o más Personajes en el campo
  const attackerSlots = isPlayerAttacker ? playtestState.slots : playtestState.opponentSlots;
  const attackerCharsCount = (attackerSlots || []).filter(s => s && s.character).length;
  if (attackerCharsCount < 2) {
    proceed();
    return;
  }

  // 2. Restricción Once Per Turn (HOPT)
  const usedGlobal = isDefenderPlayer
    ? (playtestState.usedGlobalEffects = playtestState.usedGlobalEffects || [])
    : (playtestState.opponentUsedGlobalEffects = playtestState.opponentUsedGlobalEffects || []);

  if (usedGlobal.includes('Doble colisión') || usedGlobal.includes('BBX-SP409')) {
    proceed();
    return;
  }

  // 3. Comprobar bloqueo general de efecto de Skill
  if (typeof isSkillEffectBlocked === 'function' && isSkillEffectBlocked('BBX-SP409', defenderOwner)) {
    proceed();
    return;
  }

  // 4. Comprobar disponibilidad de BBX-SP409 en Mano y/o Cementerio del defensor
  const defenderHand = isDefenderPlayer ? playtestState.hand : playtestState.opponentHand;
  const defenderGrave = isDefenderPlayer ? playtestState.grave : playtestState.opponentGrave;
  const defenderSlots = isDefenderPlayer ? playtestState.slots : playtestState.opponentSlots;

  const hasInHand = (defenderHand || []).includes('BBX-SP409');
  const handEffectBlocked = typeof isSkillHandEffectBlocked === 'function' && isSkillHandEffectBlocked(defenderOwner);
  const canEquipHand = hasInHand && !handEffectBlocked && (typeof canEquipFromZone === 'function' ? canEquipFromZone('hand', 'BBX-SP409') : true);

  const hasInGrave = (defenderGrave || []).includes('BBX-SP409');
  const graveEffectBlocked = typeof isCardGraveEffectBlocked === 'function' && isCardGraveEffectBlocked(defenderOwner, 'BBX-SP409');
  const canEquipGrave = hasInGrave && !graveEffectBlocked && (typeof canEquipFromZone === 'function' ? canEquipFromZone('grave', 'BBX-SP409') : true);

  if (!canEquipHand && !canEquipGrave) {
    proceed();
    return;
  }

  // 5. El defensor debe controlar al menos 1 Personaje en el campo para portar la Skill
  const eligibleDefenderSlots = [];
  (defenderSlots || []).forEach((s, idx) => {
    if (s && s.character && cardsDatabase[s.character]) {
      const canEquipEishet = typeof canEquipSkillToSlotDueToEishetSP320 === 'function' ? canEquipSkillToSlotDueToEishetSP320('BBX-SP409', s) : true;
      if (canEquipEishet) {
        eligibleDefenderSlots.push({ slot: s, index: idx, name: cardsDatabase[s.character].nombre });
      }
    }
  });

  if (eligibleDefenderSlots.length === 0) {
    proceed();
    return;
  }

  // Opción del usuario para omitir/declinar en testOptions
  if (testOptions && (testOptions.autoAccept === false || testOptions.autoActivate === false)) {
    addLog(`${tag} ${isDefenderPlayer ? 'Decidiste' : 'El rival decidió'} no activar el efecto de Doble colisión.`, 'var(--text-muted)');
    proceed();
    return;
  }

  // Función para ejecutar el equipamiento
  const executeEquip = (fromZone, targetSlotObj) => {
    const sourceArr = fromZone === 'hand' ? defenderHand : defenderGrave;
    const skIdx = sourceArr.indexOf('BBX-SP409');
    if (skIdx === -1) {
      proceed();
      return;
    }
    sourceArr.splice(skIdx, 1);

    targetSlotObj.slot.skills = targetSlotObj.slot.skills || [];
    targetSlotObj.slot.skills.push('BBX-SP409');

    // Registrar HOPT
    usedGlobal.push('Doble colisión');
    if (!usedGlobal.includes('BBX-SP409')) usedGlobal.push('BBX-SP409');

    if (fromZone === 'grave' && typeof notifySkillInGraveEffectUsed === 'function') {
      notifySkillInGraveEffectUsed(defenderOwner);
    }

    addLog(`${tag} ${isDefenderPlayer ? 'Activaste' : 'El rival activó'} <strong>Doble colisión</strong> y se la portó desde ${fromZone === 'hand' ? 'la Mano' : 'el Cementerio'} a <strong>${targetSlotObj.name}</strong> (Slot ${targetSlotObj.index + 1}).`, 'var(--accent-purple)');

    if (typeof checkAndTriggerInestabilidad === 'function') {
      checkAndTriggerInestabilidad(defenderOwner);
    }
    if (typeof updatePlaytestView === 'function') updatePlaytestView();

    proceed();
  };

  // Función para seleccionar objetivo del personaje
  const chooseTargetAndEquip = (fromZone) => {
    if (testOptions && testOptions.targetSlotIndex !== undefined) {
      const match = eligibleDefenderSlots.find(e => e.index === testOptions.targetSlotIndex) || eligibleDefenderSlots[0];
      executeEquip(fromZone, match);
      return;
    }

    if (eligibleDefenderSlots.length === 1) {
      executeEquip(fromZone, eligibleDefenderSlots[0]);
    } else {
      if (testOptions && testOptions.autoAccept) {
        executeEquip(fromZone, eligibleDefenderSlots[0]);
        return;
      }
      const charItems = eligibleDefenderSlots.map(c => ({
        text: `🛡️ Portar a ${c.name} (Slot ${c.index + 1})`,
        action: () => executeEquip(fromZone, c)
      }));
      const dummyEvent2 = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
      showContextMenu(dummyEvent2, charItems, () => proceed());
    }
  };

  // Determinar zona (mano o cementerio)
  const chooseZoneAndProceed = () => {
    if (testOptions && testOptions.sourceZone) {
      chooseTargetAndEquip(testOptions.sourceZone);
      return;
    }

    if (canEquipHand && !canEquipGrave) {
      chooseTargetAndEquip('hand');
    } else if (!canEquipHand && canEquipGrave) {
      chooseTargetAndEquip('grave');
    } else {
      // Ambas disponibles
      if (testOptions && testOptions.autoAccept) {
        chooseTargetAndEquip('hand');
        return;
      }
      const itemsZone = [
        {
          text: `🖐️ Portar "Doble colisión" desde la Mano`,
          action: () => chooseTargetAndEquip('hand')
        },
        {
          text: `🪦 Portar "Doble colisión" desde el Cementerio`,
          action: () => chooseTargetAndEquip('grave')
        }
      ];
      const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
      showContextMenu(dummyEvent, itemsZone, () => proceed());
    }
  };

  // Si testOptions.autoAccept es true, ejecutar directo
  if (testOptions && testOptions.autoAccept) {
    chooseZoneAndProceed();
    return;
  }

  // Interfaz de decisión
  const items = [
    {
      text: `⚡ ${isDefenderPlayer ? '' : '[RIVAL] '}Activar "Doble colisión" (Portar desde ${canEquipHand && canEquipGrave ? 'Mano o Cementerio' : canEquipHand ? 'Mano' : 'Cementerio'})`,
      action: () => {
        chooseZoneAndProceed();
      }
    },
    {
      text: `❌ ${isDefenderPlayer ? '' : '[RIVAL] '}No activar "Doble colisión"`,
      action: () => {
        addLog(`${tag} ${isDefenderPlayer ? 'Decidiste' : 'El rival decidió'} no activar el efecto de Doble colisión.`, 'var(--text-muted)');
        proceed();
      }
    }
  ];

  addLog(`${tag} El adversario controla 2 o más Personajes y declaró un ataque. Puedes activar <strong>Doble colisión</strong>.`, 'var(--accent-cyan)');
  const dummyEvent = { clientX: window.innerWidth / 2 - 140, clientY: window.innerHeight / 2 - 80 };
  showContextMenu(dummyEvent, items, () => proceed());
}

if (typeof window !== 'undefined') {
  window.checkAndTriggerDobleColisionSP409 = checkAndTriggerDobleColisionSP409;
}

// Marina BBX-SP410: "Una vez por turno, si 1 Skill es enviada al cementerio por el efecto de una carta de tu adversario, puedes barajarla al deck y si lo haces puedes robar 1 carta de tu deck."
function checkAndTriggerMarinaSP410(skillId, sourceOwner = 'opponent', skillOwner = 'player', onDone = null, testOptions = {}) {
  // 1. Debe ser una Skill
  const skillCard = cardsDatabase[skillId];
  if (!skillCard || skillCard.tipo !== 'Skill') {
    if (typeof onDone === 'function') onDone(false, { reason: 'not_a_skill' });
    return;
  }

  // 2. Debe ser enviada por efecto del adversario (sourceOwner !== skillOwner)
  if (sourceOwner === skillOwner) {
    if (typeof onDone === 'function') onDone(false, { reason: 'not_opponent_effect' });
    return;
  }

  const isPlayer = skillOwner === 'player';
  const tag = isPlayer ? '[Efecto Marina BBX-SP410]' : '[Rival - Efecto Marina BBX-SP410]';
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;

  // 3. El controlador debe tener a Marina BBX-SP410 en el campo y no tener sus efectos de personaje bloqueados
  const activeMarinaSlot = slots.find(s => {
    if (!s || s.character !== 'BBX-SP410') return false;
    if (typeof isCharacterEffectBlocked === 'function' && isCharacterEffectBlocked(skillOwner, s)) {
      return false;
    }
    return true;
  });

  if (!activeMarinaSlot) {
    if (typeof onDone === 'function') onDone(false, { reason: 'no_active_marina' });
    return;
  }

  // 4. HOPT (Hard Once Per Turn)
  const usedGlobal = isPlayer
    ? (playtestState.usedGlobalEffects = playtestState.usedGlobalEffects || [])
    : (playtestState.opponentUsedGlobalEffects = playtestState.opponentUsedGlobalEffects || []);

  if (usedGlobal.includes('Marina SP410') || usedGlobal.includes('BBX-SP410')) {
    if (typeof onDone === 'function') onDone(false, { reason: 'hopt_already_used' });
    return;
  }

  // 5. La Skill debe estar en el cementerio del controlador
  const grave = isPlayer ? playtestState.grave : playtestState.opponentGrave;
  const graveIdx = grave.lastIndexOf(skillId);
  if (graveIdx === -1) {
    if (typeof onDone === 'function') onDone(false, { reason: 'skill_not_in_grave' });
    return;
  }

  const executeActivation = () => {
    const currentGraveIdx = grave.lastIndexOf(skillId);
    if (currentGraveIdx === -1) {
      if (typeof onDone === 'function') onDone(false, { reason: 'skill_not_in_grave' });
      return;
    }

    // Marcar HOPT
    if (!usedGlobal.includes('Marina SP410')) usedGlobal.push('Marina SP410');
    if (!usedGlobal.includes('BBX-SP410')) usedGlobal.push('BBX-SP410');

    // Barajar la Skill al deck
    const [shuffledCard] = grave.splice(currentGraveIdx, 1);
    const deck = isPlayer ? playtestState.deck : playtestState.opponentDeck;
    deck.push(shuffledCard);
    if (typeof shuffleArray === 'function') {
      shuffleArray(deck);
    }

    // "y si lo haces puedes robar 1 carta de tu deck"
    let drewCard = false;
    const isDrawBlocked = (isPlayer ? playtestState.cannotDrawByEffectsThisTurn : playtestState.opponentCannotDrawByEffectsThisTurn) ||
                          (typeof isDrawByCharacterBlocked === 'function' && isDrawByCharacterBlocked(skillOwner, 1));
    const shouldAttemptDraw = (!testOptions || testOptions.skipDraw !== true);

    if (!isDrawBlocked && shouldAttemptDraw && deck.length > 0) {
      const handBefore = isPlayer ? playtestState.hand.length : playtestState.opponentHand.length;
      if (isPlayer) {
        if (typeof drawCard === 'function') {
          drawCard('character');
        } else if (deck.length > 0) {
          playtestState.hand.push(deck.shift());
        }
      } else {
        if (typeof opponentDrawCard === 'function') {
          opponentDrawCard('character');
        } else if (deck.length > 0) {
          playtestState.opponentHand.push(deck.shift());
        }
      }
      const handAfter = isPlayer ? playtestState.hand.length : playtestState.opponentHand.length;
      drewCard = handAfter > handBefore;
    }

    const skillName = skillCard.nombre;
    addLog(`${tag} Barajaste <strong>${skillName}</strong> a tu deck${drewCard ? ' y robaste 1 carta' : ''}.`, 'var(--accent-purple)');

    if (typeof updatePlaytestView === 'function') {
      updatePlaytestView();
    }
    if (typeof onDone === 'function') {
      onDone(true, { drewCard, shuffledCard });
    }
  };

  // Manejo de testOptions para pruebas automatizadas
  if (testOptions && (testOptions.autoAccept !== undefined || testOptions.activateMarina !== undefined)) {
    const shouldActivate = testOptions.autoAccept !== undefined ? testOptions.autoAccept : testOptions.activateMarina;
    if (!shouldActivate) {
      addLog(`${tag} Decidió no activar el efecto de Marina.`, 'var(--text-muted)');
      if (typeof onDone === 'function') onDone(false, { reason: 'user_declined' });
      return;
    }
    executeActivation();
    return;
  }

  if (isPlayer) {
    const items = [
      {
        text: `🌊 Barajar "${skillCard.nombre}" al deck y robar 1 carta (Marina)`,
        action: () => executeActivation()
      },
      {
        text: `❌ No activar el efecto de Marina`,
        action: () => {
          addLog(`${tag} Decidiste no activar el efecto de Marina.`, 'var(--text-muted)');
          if (typeof onDone === 'function') onDone(false, { reason: 'user_declined' });
        }
      }
    ];
    addLog(`[Trigger Marina BBX-SP410] Una Skill (<strong>${skillCard.nombre}</strong>) fue enviada a tu cementerio por el efecto de una carta de tu adversario: ¿Deseas barajarla al deck y robar 1 carta?`, 'var(--accent-cyan)');
    const dummyEvent = { clientX: window.innerWidth / 2 - 140, clientY: window.innerHeight / 2 - 80 };
    showContextMenu(dummyEvent, items);
  } else {
    if (playtestState.isOnlineMatch) {
      if (typeof MultiplayerEngine !== 'undefined' && MultiplayerEngine.isConnected() && typeof MultiplayerEngine.sendReactionTriggerToPeer === 'function') {
        MultiplayerEngine.sendReactionTriggerToPeer('MARINA_SP410', { skillId }, onDone);
      } else if (typeof onDone === 'function') {
        onDone(false, { reason: 'online_skipped' });
      }
      return;
    }
    addLog(`[Trigger Marina BBX-SP410 Rival] Una Skill fue enviada al cementerio del rival por efecto de tu carta: el rival baraja <strong>${skillCard.nombre}</strong> al deck y roba 1 carta.`, 'var(--accent-cyan)');
    executeActivation();
  }
}

if (typeof window !== 'undefined') {
  window.checkAndTriggerMarinaSP410 = checkAndTriggerMarinaSP410;
}

// Holoescudo (BBX-SP310): Si esta Skill portada es enviada al cementerio, puedes portar directamente desde tu deck hasta 2 Skills "Holoescudo" a 1 Personaje Chiako que controles.
let lastHoloescudoTriggerTime = 0;
function checkAndTriggerHoloescudo(skillId, owner = 'player') {
  if (skillId !== 'BBX-SP310') return;

  const now = Date.now();
  if (now - lastHoloescudoTriggerTime < 200) return;
  lastHoloescudoTriggerTime = now;

  if (owner === 'player') {
    const eligibleSlots = [];
    playtestState.slots.forEach((s, idx) => {
      if (s.character && cardsDatabase[s.character] && cardsDatabase[s.character].nombre.includes("Chiako")) {
        eligibleSlots.push({ slot: s, index: idx, name: cardsDatabase[s.character].nombre });
      }
    });

    if (eligibleSlots.length === 0) {
      addLog(`[Holoescudo BBX-SP310] Enviada al cementerio, pero no controlas ningún Personaje Chiako en el campo.`, 'var(--text-muted)');
      return;
    }

    const holoescudosInDeck = playtestState.deck.filter(id => id === 'BBX-SP310');
    if (holoescudosInDeck.length === 0) {
      addLog(`[Holoescudo BBX-SP310] Enviada al cementerio, pero no tienes ninguna copia de "Holoescudo" en tu deck.`, 'var(--text-muted)');
      return;
    }

    const maxToEquip = Math.min(2, holoescudosInDeck.length);
    const proceedEquip = (chosenSlotIdx) => {
      const targetSlot = playtestState.slots[chosenSlotIdx];
      const targetCharName = cardsDatabase[targetSlot.character].nombre;

      if (maxToEquip === 1) {
        const idxInDeck = playtestState.deck.indexOf('BBX-SP310');
        if (idxInDeck !== -1) {
          const pulledId = playtestState.deck.splice(idxInDeck, 1)[0];
          targetSlot.skills = targetSlot.skills || [];
          targetSlot.skills.push(pulledId);
          shuffleArray(playtestState.deck);
          addLog(`[Efecto Holoescudo BBX-SP310] Portaste 1 copia de <strong>Holoescudo</strong> directamente desde tu deck a <strong>${targetCharName}</strong> (Slot ${chosenSlotIdx + 1}) y barajaste tu deck.`, 'var(--accent-purple)');
          checkAndTriggerInestabilidad('player');
          updatePlaytestView();
        }
      } else {
        const itemsCount = [
          {
            text: `🛡️ Portar 2 copias de "Holoescudo"`,
            action: () => {
              for (let i = 0; i < 2; i++) {
                const idxInDeck = playtestState.deck.indexOf('BBX-SP310');
                if (idxInDeck !== -1) {
                  const pulledId = playtestState.deck.splice(idxInDeck, 1)[0];
                  targetSlot.skills = targetSlot.skills || [];
                  targetSlot.skills.push(pulledId);
                }
              }
              shuffleArray(playtestState.deck);
              addLog(`[Efecto Holoescudo BBX-SP310] Portaste 2 copias de <strong>Holoescudo</strong> directamente desde tu deck a <strong>${targetCharName}</strong> (Slot ${chosenSlotIdx + 1}) y barajaste tu deck.`, 'var(--accent-purple)');
              checkAndTriggerInestabilidad('player');
              updatePlaytestView();
            }
          },
          {
            text: `🛡️ Portar 1 copia de "Holoescudo"`,
            action: () => {
              const idxInDeck = playtestState.deck.indexOf('BBX-SP310');
              if (idxInDeck !== -1) {
                const pulledId = playtestState.deck.splice(idxInDeck, 1)[0];
                targetSlot.skills = targetSlot.skills || [];
                targetSlot.skills.push(pulledId);
              }
              shuffleArray(playtestState.deck);
              addLog(`[Efecto Holoescudo BBX-SP310] Portaste 1 copia de <strong>Holoescudo</strong> directamente desde tu deck a <strong>${targetCharName}</strong> (Slot ${chosenSlotIdx + 1}) y barajaste tu deck.`, 'var(--accent-purple)');
              checkAndTriggerInestabilidad('player');
              updatePlaytestView();
            }
          }
        ];
        const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 60 };
        showContextMenu(dummyEvent, itemsCount);
      }
    };

    const confirmOptions = [
      {
        text: `💥 No activar efecto de Holoescudo`,
        action: () => {
          addLog(`[Holoescudo BBX-SP310] Decidiste no activar su efecto.`, 'var(--text-muted)');
        }
      },
      {
        text: `🛡️ Activar Holoescudo (Portar hasta ${maxToEquip} desde el Deck)`,
        action: () => {
          if (eligibleSlots.length === 1) {
            proceedEquip(eligibleSlots[0].index);
          } else {
            const chiakoOptions = eligibleSlots.map(es => ({
              text: `Equipar a ${es.name} (Slot ${es.index + 1})`,
              action: () => proceedEquip(es.index)
            }));
            const dummyEv = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 60 };
            showContextMenu(dummyEv, chiakoOptions);
          }
        }
      }
    ];
    const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
    showContextMenu(dummyEvent, confirmOptions);
  } else {
    const eligibleOppSlots = [];
    playtestState.opponentSlots.forEach((s, idx) => {
      if (s.character && cardsDatabase[s.character] && cardsDatabase[s.character].nombre.includes("Chiako")) {
        eligibleOppSlots.push({ slot: s, index: idx, name: cardsDatabase[s.character].nombre });
      }
    });

    if (eligibleOppSlots.length === 0) {
      addLog(`[Holoescudo BBX-SP310 Rival] Enviada al cementerio, pero el rival no controla ningún Personaje Chiako.`, 'var(--text-muted)');
      return;
    }

    const holoescudosInOppDeck = playtestState.opponentDeck.filter(id => id === 'BBX-SP310');
    if (holoescudosInOppDeck.length === 0) {
      addLog(`[Holoescudo BBX-SP310 Rival] Enviada al cementerio, pero el rival no tiene ninguna copia en su deck.`, 'var(--text-muted)');
      return;
    }

    const maxToEquip = Math.min(2, holoescudosInOppDeck.length);
    const chosenSlot = eligibleOppSlots[0];
    for (let i = 0; i < maxToEquip; i++) {
      const idxInDeck = playtestState.opponentDeck.indexOf('BBX-SP310');
      if (idxInDeck !== -1) {
        const pulledId = playtestState.opponentDeck.splice(idxInDeck, 1)[0];
        chosenSlot.slot.skills = chosenSlot.slot.skills || [];
        chosenSlot.slot.skills.push(pulledId);
      }
    }
    shuffleArray(playtestState.opponentDeck);
    addLog(`[Efecto Holoescudo BBX-SP310 Rival] El rival portó ${maxToEquip} copia(s) de <strong>Holoescudo</strong> directamente desde su deck a <strong>${chosenSlot.name}</strong> (Slot ${chosenSlot.index + 1}) y barajó su deck.`, 'var(--accent-purple)');
    checkAndTriggerInestabilidad('opponent');
    updatePlaytestView();
  }
}

// Lyna (BBX-SP312): Si una Skill propia de Lyna es destruida por una batalla, puedes enviar esta carta en tu mano al cementerio, entonces envía al cementerio 1 Skill portada y si lo haces puedes robar 1 carta de tu deck.
function checkAndTriggerLynaSP312(destroyedSkillId, owner = 'player') {
  const destroyedCard = cardsDatabase[destroyedSkillId];
  if (!destroyedCard || destroyedCard.tipo !== 'Skill' || !destroyedCard.portador || !destroyedCard.portador.includes("Lyna")) {
    return;
  }

  if (owner === 'player') {
    if (!playtestState.hand.includes('BBX-SP312')) return;
    if (isCharacterHandEffectBlocked()) return;

    const eligibleFieldSkills = [];
    playtestState.slots.forEach((s, sIdx) => {
      if (s.character && s.skills) {
        s.skills.forEach((skId, skIdx) => {
          eligibleFieldSkills.push({
            id: skId,
            owner: 'player',
            slotIndex: sIdx,
            skillIndex: skIdx,
            charName: cardsDatabase[s.character].nombre,
            skillName: cardsDatabase[skId].nombre
          });
        });
      }
    });

    playtestState.opponentSlots.forEach((s, sIdx) => {
      if (s.character && s.skills) {
        s.skills.forEach((skId, skIdx) => {
          if (canRemoveSkillByEffect(skId, true, 'player', s, 'grave')) {
            eligibleFieldSkills.push({
              id: skId,
              owner: 'opponent',
              slotIndex: sIdx,
              skillIndex: skIdx,
              charName: cardsDatabase[s.character].nombre,
              skillName: cardsDatabase[skId].nombre
            });
          }
        });
      }
    });

    if (eligibleFieldSkills.length === 0) return;

    const items = [
      {
        text: `💥 No activar efecto de Lyna en mano`,
        action: () => {
          addLog(`[Lyna BBX-SP312] Decidiste no activar su efecto desde la mano.`, 'var(--text-muted)');
        }
      },
      {
        text: `🛡️ Activar Lyna (Mano): Descartar, enviar 1 Skill al cementerio y robar 1`,
        action: () => {
          const lynaHandIdx = playtestState.hand.indexOf('BBX-SP312');
          if (lynaHandIdx === -1) return;

          const discardedId = playtestState.hand.splice(lynaHandIdx, 1)[0];
          playtestState.grave.push(discardedId);
          addLog(`[Efecto Lyna BBX-SP312] Enviaste a Lyna de tu mano al cementerio.`, 'var(--accent-purple)');

          checkAndTriggerReflejo(discardedId);
          checkAndTriggerEstrategia(discardedId);
          checkAndTriggerHackeo(discardedId);
          checkAndTriggerRemembranza(discardedId, 'player');
          updatePlaytestView();

          const chooserTargets = eligibleFieldSkills.map(efs => ({
            id: efs.id,
            from: efs.owner === 'player' ? `Tuyo (${efs.charName})` : `Rival (${efs.charName})`
          }));

          openCardChooserModal(chooserTargets, "Lyna (SP312): Selecciona 1 Skill portada para enviar al cementerio", (chosenIdx) => {
            const targetItem = eligibleFieldSkills[chosenIdx];
            let removedSkId = null;

            if (targetItem.owner === 'player') {
              const slot = playtestState.slots[targetItem.slotIndex];
              if (slot && slot.skills && slot.skills[targetItem.skillIndex] === targetItem.id) {
                removedSkId = slot.skills.splice(targetItem.skillIndex, 1)[0];
                playtestState.grave.push(removedSkId);
                onEquippedSkillSentToGraveByEffect(removedSkId, 'player', 'player');
              }
            } else {
              const oppSlot = playtestState.opponentSlots[targetItem.slotIndex];
              if (oppSlot && oppSlot.skills && oppSlot.skills[targetItem.skillIndex] === targetItem.id) {
                removedSkId = oppSlot.skills.splice(targetItem.skillIndex, 1)[0];
                playtestState.opponentGrave.push(removedSkId);
                onEquippedSkillSentToGraveByEffect(removedSkId, 'opponent', 'player');
              }
            }

            if (removedSkId) {
              addLog(`[Efecto Lyna BBX-SP312] Enviaste al cementerio la Skill portada <strong>${cardsDatabase[removedSkId].nombre}</strong> (${targetItem.charName}).`, 'var(--accent-purple)');

              if (playtestState.deck.length > 0 && !playtestState.cannotDrawByEffectsThisTurn && !isDrawBySkillBlocked('player', 1)) {
                const drawnId = playtestState.deck.shift();
                playtestState.hand.push(drawnId);
                addLog(`[Efecto Lyna BBX-SP312] Robaste 1 carta de tu deck: <strong>${cardsDatabase[drawnId].nombre}</strong>.`, 'var(--accent-purple)');
              } else if (playtestState.deck.length === 0) {
                addLog(`[Efecto Lyna BBX-SP312] No tienes cartas en tu deck para robar.`, 'var(--text-muted)');
              }
              updatePlaytestView();
            }
          });
        }
      }
    ];

    const dummyEvent = { clientX: window.innerWidth / 2 - 140, clientY: window.innerHeight / 2 - 80 };
    showContextMenu(dummyEvent, items);
  } else {
    if (!playtestState.opponentHand.includes('BBX-SP312')) return;
    if (isCharacterHandEffectBlocked()) return;

    const oppFieldSkills = [];
    playtestState.slots.forEach((s, sIdx) => {
      if (s.character && s.skills) {
        s.skills.forEach((skId, skIdx) => {
          if (canRemoveSkillByEffect(skId, true, 'opponent', s, 'grave')) {
            oppFieldSkills.push({
              id: skId,
              owner: 'player',
              slotIndex: sIdx,
              skillIndex: skIdx,
              charName: cardsDatabase[s.character].nombre,
              skillName: cardsDatabase[skId].nombre
            });
          }
        });
      }
    });

    playtestState.opponentSlots.forEach((s, sIdx) => {
      if (s.character && s.skills) {
        s.skills.forEach((skId, skIdx) => {
          oppFieldSkills.push({
            id: skId,
            owner: 'opponent',
            slotIndex: sIdx,
            skillIndex: skIdx,
            charName: cardsDatabase[s.character].nombre,
            skillName: cardsDatabase[skId].nombre
          });
        });
      }
    });

    if (oppFieldSkills.length === 0) return;

    const itemsOpp = [
      {
        text: `💥 [RIVAL] No activar efecto de Lyna en mano`,
        action: () => {
          addLog(`[Lyna BBX-SP312 Rival] El rival decidió no activar su efecto desde la mano.`, 'var(--text-muted)');
        }
      },
      {
        text: `🛡️ [RIVAL] Activar Lyna (Mano): Descartar, enviar 1 Skill al cementerio y robar 1`,
        action: () => {
          const lynaHandIdx = playtestState.opponentHand.indexOf('BBX-SP312');
          if (lynaHandIdx === -1) return;

          const discardedId = playtestState.opponentHand.splice(lynaHandIdx, 1)[0];
          playtestState.opponentGrave.push(discardedId);
          addLog(`[Efecto Lyna BBX-SP312 Rival] El rival envió a Lyna de su mano al cementerio.`, 'var(--accent-purple)');
          checkAndTriggerRemembranza(discardedId, 'opponent');
          updatePlaytestView();

          const targetItem = oppFieldSkills.find(s => s.owner === 'player') || oppFieldSkills[0];
          let removedSkId = null;

          if (targetItem.owner === 'player') {
            const slot = playtestState.slots[targetItem.slotIndex];
            if (slot && slot.skills && slot.skills[targetItem.skillIndex] === targetItem.id) {
              removedSkId = slot.skills.splice(targetItem.skillIndex, 1)[0];
              playtestState.grave.push(removedSkId);
              onEquippedSkillSentToGraveByEffect(removedSkId, 'player', 'opponent');
            }
          } else {
            const oppSlot = playtestState.opponentSlots[targetItem.slotIndex];
            if (oppSlot && oppSlot.skills && oppSlot.skills[targetItem.skillIndex] === targetItem.id) {
              removedSkId = oppSlot.skills.splice(targetItem.skillIndex, 1)[0];
              playtestState.opponentGrave.push(removedSkId);
              onEquippedSkillSentToGraveByEffect(removedSkId, 'opponent', 'opponent');
            }
          }

          if (removedSkId) {
            addLog(`[Efecto Lyna BBX-SP312 Rival] El rival envió al cementerio la Skill portada <strong>${cardsDatabase[removedSkId].nombre}</strong> (${targetItem.charName}).`, 'var(--accent-purple)');

            if (playtestState.opponentDeck.length > 0 && !isDrawBySkillBlocked('opponent', 1)) {
              const drawnId = playtestState.opponentDeck.shift();
              playtestState.opponentHand.push(drawnId);
              addLog(`[Efecto Lyna BBX-SP312 Rival] El rival robó 1 carta de su deck.`, 'var(--accent-purple)');
            }
            updatePlaytestView();
          }
        }
      }
    ];

    const dummyEvent = { clientX: window.innerWidth / 2 - 140, clientY: window.innerHeight / 2 - 80 };
    showContextMenu(dummyEvent, itemsOpp);
  }
}

function activateOpponentControlDelPensar(slotIndex, skIndex) {
  const oppSlot = playtestState.opponentSlots[slotIndex];
  if (!oppSlot || !oppSlot.character) return;

  const playerSkillsWithContext = [];
  playtestState.slots.forEach((s, sIdx) => {
    if (s.character && s.skills) {
      s.skills.forEach((skId, skIdx) => {
        if (canRemoveSkillByEffect(skId, false, 'opponent', s, 'grave')) {
          playerSkillsWithContext.push({
            slotIdx: sIdx,
            skId,
            skIdx,
            charName: cardsDatabase[s.character]?.nombre || 'Personaje',
            skillName: cardsDatabase[skId]?.nombre || skId
          });
        }
      });
    }
  });

  if (playerSkillsWithContext.length === 0) {
    addLog(`[Rival] No hay Skills tuyas elegibles para enviar al cementerio con Control del pensar.`, 'var(--text-muted)');
    return;
  }

  const skillIds = playerSkillsWithContext.map(ctx => ctx.skId);
  openCardChooserModal(skillIds, "Control del pensar (Rival): Selecciona qué Skill tuya enviará al cementerio el rival", (chosenIdx) => {
    const chosenCtx = playerSkillsWithContext[chosenIdx];
    const targetSlot = playtestState.slots[chosenCtx.slotIdx];
    const removedSkillId = targetSlot.skills.splice(chosenCtx.skIdx, 1)[0];
    playtestState.grave.push(removedSkillId);

    addLog(`[Efecto Control del pensar Rival] El rival envió al cementerio tu Skill <strong>${cardsDatabase[removedSkillId].nombre}</strong> equipada en <strong>${chosenCtx.charName}</strong> (Slot ${chosenCtx.slotIdx + 1}).`, 'var(--accent-purple)');

    oppSlot.usedSkills = oppSlot.usedSkills || [];
    oppSlot.usedSkills.push('BBX-SP012');
    if (typeof skIndex === 'number' && skIndex >= 0) {
      oppSlot.usedSkillIndexes = oppSlot.usedSkillIndexes || [];
      if (!oppSlot.usedSkillIndexes.includes(skIndex)) oppSlot.usedSkillIndexes.push(skIndex);
    }

    onEquippedSkillSentToGraveByEffect(removedSkillId, 'player', 'opponent');
    updatePlaytestView();
    if (typeof notifySkillsRemovedByEffect === 'function') {
      notifySkillsRemovedByEffect(1, null, 'opponent');
    }

    // Trigger de Bao (BBX-SP356)
    checkAndTriggerBaoSP356(() => {
      updatePlaytestView();
    });
  });
}

// Bao (BBX-SP356): "Mientras esta carta se encuentre en el cementerio, cada vez que una Skill es enviada al cementerio por el efecto de \"Control del pensar\", puedes enviar 1 Skill portada al cementerio."
function checkAndTriggerBaoSP356(callback, onlyLocalPlayer = false) {
  const getBaoTargetableSkills = (activatorOwner) => {
    const list = [];
    playtestState.slots.forEach((s, sIdx) => {
      if (s.character && s.skills) {
        const cName = cardsDatabase[s.character]?.nombre || 'Personaje';
        s.skills.forEach((skId, skIdx) => {
          const isOppSlot = (activatorOwner === 'opponent');
          if (canRemoveSkillByEffect(skId, isOppSlot, activatorOwner, s, 'grave')) {
            list.push({
              id: skId,
              owner: 'player',
              slotIndex: sIdx,
              skillIndex: skIdx,
              charName: cName,
              skillName: cardsDatabase[skId]?.nombre || skId,
              label: `"${cardsDatabase[skId]?.nombre}" (de ${cName} - Jugador)`
            });
          }
        });
      }
    });
    playtestState.opponentSlots.forEach((s, sIdx) => {
      if (s.character && s.skills) {
        const cName = cardsDatabase[s.character]?.nombre || 'Personaje';
        s.skills.forEach((skId, skIdx) => {
          const isOppSlot = (activatorOwner === 'player');
          if (canRemoveSkillByEffect(skId, isOppSlot, activatorOwner, s, 'grave')) {
            list.push({
              id: skId,
              owner: 'opponent',
              slotIndex: sIdx,
              skillIndex: skIdx,
              charName: cName,
              skillName: cardsDatabase[skId]?.nombre || skId,
              label: `"${cardsDatabase[skId]?.nombre}" (de ${cName} - Rival)`
            });
          }
        });
      }
    });
    return list;
  };

  const queue = [];
  const playerBaoCount = playtestState.grave.filter(id => id === 'BBX-SP356').length;
  const isPlayerGraveBlocked = typeof isCardGraveEffectBlocked === 'function' && isCardGraveEffectBlocked('player', 'BBX-SP356');
  if (!isPlayerGraveBlocked && playerBaoCount > 0) {
    for (let i = 0; i < playerBaoCount; i++) {
      queue.push({ owner: 'player', copyNumber: i + 1, total: playerBaoCount });
    }
  }

  const oppBaoCount = playtestState.opponentGrave.filter(id => id === 'BBX-SP356').length;
  const isOppGraveBlocked = typeof isCardGraveEffectBlocked === 'function' && isCardGraveEffectBlocked('opponent', 'BBX-SP356');
  const shouldDelegateOppBaoOnline = !onlyLocalPlayer && playtestState.isOnlineMatch && typeof MultiplayerEngine !== 'undefined' && MultiplayerEngine.isConnected() && typeof MultiplayerEngine.sendReactionTriggerToPeer === 'function';
  if (!onlyLocalPlayer && !shouldDelegateOppBaoOnline && !isOppGraveBlocked && oppBaoCount > 0) {
    for (let i = 0; i < oppBaoCount; i++) {
      queue.push({ owner: 'opponent', copyNumber: i + 1, total: oppBaoCount });
    }
  }

  const finishAllBao = () => {
    if (shouldDelegateOppBaoOnline && !isOppGraveBlocked && oppBaoCount > 0) {
      updatePlaytestView();
      MultiplayerEngine.sendReactionTriggerToPeer('BAO_SP356', {}, callback);
      return;
    }
    if (typeof callback === 'function') callback();
  };

  if (queue.length === 0) {
    finishAllBao();
    return;
  }

  const processNextTrigger = (qIndex) => {
    if (qIndex >= queue.length) {
      finishAllBao();
      return;
    }

    const item = queue[qIndex];
    const isPlayer = item.owner === 'player';
    const targetable = getBaoTargetableSkills(item.owner);

    if (targetable.length === 0) {
      addLog(`[Efecto Bao BBX-SP356${isPlayer ? '' : ' Rival'}] Disparado por Control del pensar, pero no hay Skills portadas elegibles en el campo para enviar al cementerio.`, 'var(--text-muted)');
      processNextTrigger(qIndex + 1);
      return;
    }

    const tagMsg = isPlayer
      ? `[Trigger Bao (BBX-SP356)] Se envió una Skill al cementerio por Control del pensar: ¿Deseas activar el efecto de Bao${item.total > 1 ? ` (Copia ${item.copyNumber})` : ''} en tu cementerio?`
      : `[Trigger Rival Bao (BBX-SP356)] Se envió una Skill al cementerio por Control del pensar: ¿Activar el efecto de Bao${item.total > 1 ? ` (Copia ${item.copyNumber})` : ''} rival en cementerio?`;

    addLog(tagMsg, isPlayer ? 'var(--accent-cyan)' : 'var(--accent-purple)');

    if (isPlayer) {
      const menuItems = [
        {
          text: `💥 Activar Bao (Enviar 1 Skill portada al cementerio)${item.total > 1 ? ` [Copia ${item.copyNumber}]` : ''}`,
          action: () => {
            const freshTargets = getBaoTargetableSkills('player');
            if (freshTargets.length === 0) {
              addLog(`[Efecto Bao BBX-SP356] Ya no quedan Skills portadas elegibles en el campo.`, 'var(--text-muted)');
              processNextTrigger(qIndex + 1);
              return;
            }

            openCardChooserModal(freshTargets.map(t => ({ id: t.id, owner: t.owner })), "Bao (SP356): Selecciona 1 Skill portada para enviar al cementerio", (chosenIdx) => {
              const chosen = freshTargets[chosenIdx];
              const targetSlot = (chosen.owner === 'player') ? playtestState.slots[chosen.slotIndex] : playtestState.opponentSlots[chosen.slotIndex];
              if (targetSlot && targetSlot.skills) {
                const sIdx = targetSlot.skills.indexOf(chosen.id);
                if (sIdx !== -1) {
                  const removedId = targetSlot.skills.splice(sIdx, 1)[0];
                  if (chosen.owner === 'player') {
                    playtestState.grave.push(removedId);
                  } else {
                    playtestState.opponentGrave.push(removedId);
                  }
                  addLog(`[Efecto Bao BBX-SP356] Enviaste al cementerio la Skill <strong>${cardsDatabase[removedId].nombre}</strong> de <strong>${chosen.charName}</strong> (${chosen.owner === 'player' ? 'Tú' : 'Rival'}).`, 'var(--accent-purple)');
                  onEquippedSkillSentToGraveByEffect(removedId, chosen.owner, 'player');
                  if (typeof notifySkillsRemovedByEffect === 'function') {
                    notifySkillsRemovedByEffect(1, null, 'player');
                  }
                  updatePlaytestView();
                }
              }
              processNextTrigger(qIndex + 1);
            });
          }
        },
        {
          text: `❌ No activar efecto de Bao${item.total > 1 ? ` (Copia ${item.copyNumber})` : ''}`,
          action: () => {
            addLog(`[Efecto Bao BBX-SP356] Decidiste no activar el efecto de Bao.`, 'var(--text-muted)');
            updatePlaytestView();
            processNextTrigger(qIndex + 1);
          }
        }
      ];
      const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
      showContextMenu(dummyEvent, menuItems);
    } else {
      // Rival
      const menuItems = [
        {
          text: `💥 [RIVAL] Activar Bao (Enviar 1 Skill portada al cementerio)${item.total > 1 ? ` [Copia ${item.copyNumber}]` : ''}`,
          action: () => {
            const freshTargets = getBaoTargetableSkills('opponent');
            if (freshTargets.length === 0) {
              addLog(`[Efecto Bao BBX-SP356 Rival] Ya no quedan Skills portadas elegibles en el campo.`, 'var(--text-muted)');
              processNextTrigger(qIndex + 1);
              return;
            }

            openCardChooserModal(freshTargets.map(t => ({ id: t.id, owner: t.owner })), "[RIVAL] Bao (SP356): Selecciona 1 Skill portada para enviar al cementerio", (chosenIdx) => {
              const chosen = freshTargets[chosenIdx];
              const targetSlot = (chosen.owner === 'player') ? playtestState.slots[chosen.slotIndex] : playtestState.opponentSlots[chosen.slotIndex];
              if (targetSlot && targetSlot.skills) {
                const sIdx = targetSlot.skills.indexOf(chosen.id);
                if (sIdx !== -1) {
                  const removedId = targetSlot.skills.splice(sIdx, 1)[0];
                  if (chosen.owner === 'player') {
                    playtestState.grave.push(removedId);
                  } else {
                    playtestState.opponentGrave.push(removedId);
                  }
                  addLog(`[Efecto Bao BBX-SP356 Rival] El rival envió al cementerio la Skill <strong>${cardsDatabase[removedId].nombre}</strong> de <strong>${chosen.charName}</strong> (${chosen.owner === 'player' ? 'Tú' : 'Rival'}).`, 'var(--accent-purple)');
                  onEquippedSkillSentToGraveByEffect(removedId, chosen.owner, 'opponent');
                  if (typeof notifySkillsRemovedByEffect === 'function') {
                    notifySkillsRemovedByEffect(1, null, 'opponent');
                  }
                  updatePlaytestView();
                }
              }
              processNextTrigger(qIndex + 1);
            });
          }
        },
        {
          text: `❌ [RIVAL] No activar efecto de Bao${item.total > 1 ? ` (Copia ${item.copyNumber})` : ''}`,
          action: () => {
            addLog(`[Efecto Bao BBX-SP356 Rival] Se decidió no activar el efecto de Bao rival.`, 'var(--text-muted)');
            updatePlaytestView();
            processNextTrigger(qIndex + 1);
          }
        }
      ];
      const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
      showContextMenu(dummyEvent, menuItems);
    }
  };

  processNextTrigger(0);
}

// Eishet (BBX-SP357): "Si tu adversario agrega a su mano desde tu deck 1 o más cartas por el efecto de una carta (no incluye robar), puedes enviar esta carta en tu mano al cementerio y robar 2 cartas de tu deck."
function checkAndTriggerEishetSP357(victimOwner = 'player', onDone = null) {
  const isPlayerVictim = (victimOwner === 'player');
  // Si la víctima es 'player', el adversario (opponent) agregó cartas del deck del jugador a la mano rival.
  // Quien activa Eishet de su mano es 'player'.
  // Si la víctima es 'opponent', quien activa Eishet de su mano es 'opponent'.
  const activatorOwner = isPlayerVictim ? 'player' : 'opponent';
  const hand = isPlayerVictim ? playtestState.hand : playtestState.opponentHand;
  const deck = isPlayerVictim ? playtestState.deck : playtestState.opponentDeck;

  const hasEishetInHand = hand.includes('BBX-SP357');
  const isHandBlocked = typeof isCharacterHandEffectBlocked === 'function' && isCharacterHandEffectBlocked(activatorOwner);
  // Requisito estricto: como mínimo 2 cartas en tu deck para poder robar las 2 cartas
  const has2CardsInDeck = deck.length >= 2;
  const isDrawBlocked = isPlayerVictim ? !!playtestState.cannotDrawByEffectsThisTurn : !!playtestState.opponentCannotDrawByEffectsThisTurn;

  if (!hasEishetInHand || isHandBlocked || !has2CardsInDeck || isDrawBlocked) {
    if (typeof onDone === 'function') onDone();
    return;
  }

  if (isPlayerVictim) {
    const items = [
      {
        text: "⚡ Activar Eishet (SP357): Enviar al cementerio y robar 2 cartas de tu deck",
        action: () => {
          executeEishetSP357Activation('player', -1, onDone);
        }
      },
      {
        text: "❌ No activar Eishet (SP357)",
        action: () => {
          addLog(`[Eishet BBX-SP357] Decidiste no activar el efecto de Eishet.`, 'var(--text-muted)');
          if (typeof onDone === 'function') onDone();
        }
      }
    ];
    addLog(`[Trigger Eishet BBX-SP357] El adversario agregó carta(s) a su mano desde tu deck por efecto (no incluye robar). ¿Deseas activar a <strong>Eishet</strong> desde tu mano?`, 'var(--accent-cyan)');
    const dummyEvent = { clientX: window.innerWidth / 2 - 150, clientY: window.innerHeight / 2 - 80 };
    showContextMenu(dummyEvent, items);
  } else {
    if (playtestState.isOnlineMatch && typeof MultiplayerEngine !== 'undefined' && MultiplayerEngine.isConnected() && typeof MultiplayerEngine.sendReactionTriggerToPeer === 'function') {
      updatePlaytestView();
      MultiplayerEngine.sendReactionTriggerToPeer('EISHET_SP357', {}, onDone);
      return;
    }
    const oppItems = [
      {
        text: "⚡ [RIVAL] Activar Eishet (SP357): Enviar al cementerio y robar 2 cartas de su deck",
        action: () => {
          executeEishetSP357Activation('opponent', -1, onDone);
        }
      },
      {
        text: "❌ [RIVAL] No activar Eishet (SP357)",
        action: () => {
          addLog(`[Eishet BBX-SP357 Rival] El rival decidió no activar el efecto de Eishet.`, 'var(--text-muted)');
          if (typeof onDone === 'function') onDone();
        }
      }
    ];
    addLog(`[Trigger Eishet BBX-SP357 Rival] Agregaste carta(s) a tu mano desde el deck del rival por efecto (no incluye robar). El rival puede activar a <strong>Eishet</strong> desde su mano.`, 'var(--accent-cyan)');
    const dummyEvent = { clientX: window.innerWidth / 2 - 150, clientY: window.innerHeight / 2 - 80 };
    showContextMenu(dummyEvent, oppItems);
  }
}

function executeEishetSP357Activation(activatorOwner = 'player', handIndex = -1, onDone = null) {
  const isPlayer = (activatorOwner === 'player');
  const hand = isPlayer ? playtestState.hand : playtestState.opponentHand;
  const grave = isPlayer ? playtestState.grave : playtestState.opponentGrave;
  const deck = isPlayer ? playtestState.deck : playtestState.opponentDeck;

  const eIdx = (handIndex >= 0 && hand[handIndex] === 'BBX-SP357')
    ? handIndex
    : hand.indexOf('BBX-SP357');

  if (eIdx === -1) {
    if (typeof onDone === 'function') onDone();
    return;
  }

  if (typeof isCharacterHandEffectBlocked === 'function' && isCharacterHandEffectBlocked(activatorOwner)) {
    addLog(`[Efecto Eishet BBX-SP357 ${isPlayer ? '' : 'Rival'}] No se puede activar: Efectos de Personajes en mano bloqueados.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone();
    return;
  }

  // Requisito estricto: Como mínimo 2 cartas en el propio deck para poder robar las 2 cartas
  if (deck.length < 2) {
    addLog(`[Efecto Eishet BBX-SP357 ${isPlayer ? '' : 'Rival'}] No se puede activar: Se requieren como mínimo 2 cartas en tu deck para robar 2 (hay ${deck.length}).`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone();
    return;
  }

  if (isPlayer && playtestState.cannotDrawByEffectsThisTurn) {
    addLog(`[Efecto Eishet BBX-SP357] No se puede activar: No puedes robar cartas por efectos este turno.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone();
    return;
  }

  // 1. Enviar esta carta en tu mano al cementerio
  const discardedId = hand.splice(eIdx, 1)[0];
  grave.push(discardedId);
  addLog(`[Efecto Eishet BBX-SP357 ${isPlayer ? '' : 'Rival'}] ${isPlayer ? 'Enviaste' : 'El rival envió'} a <strong>Eishet</strong> de su mano al cementerio.`, 'var(--accent-purple)');

  checkAndTriggerAlBorde(discardedId);
  checkAndTriggerReflejo(discardedId);
  checkAndTriggerEstrategia(discardedId);
  checkAndTriggerHackeo(discardedId);
  checkAndTriggerLlamarada(discardedId);
  checkAndTriggerEspiral(discardedId);
  checkAndTriggerFirewall(discardedId);
  checkAndTriggerFervor(discardedId);
  checkAndTriggerApunteIgneo(discardedId);
  checkAndTriggerCrimenNocturno(discardedId);
  checkAndTriggerAlmacenamientoFallido(discardedId, 'hand');
  checkAndTriggerKatshi159(discardedId);
  checkAndTriggerFulgorOfensivo(discardedId);
  checkAndTriggerEspiralDigital(discardedId, 'hand');
  checkAndTriggerBolaDeFuego(discardedId, 'hand');
  checkAndTriggerKatshi205(discardedId);
  checkAndTriggerRemembranza(discardedId, isPlayer ? 'player' : 'opponent');

  // 2. "...y robar 2 cartas de tu deck."
  const drawn1 = deck.shift();
  const drawn2 = deck.shift();
  hand.push(drawn1, drawn2);

  if (isPlayer) {
    addLog(`[Efecto Eishet BBX-SP357] Robaste 2 cartas de tu deck: <strong>${cardsDatabase[drawn1]?.nombre || drawn1}</strong> y <strong>${cardsDatabase[drawn2]?.nombre || drawn2}</strong>.`, 'var(--accent-purple)');
  } else {
    addLog(`[Efecto Eishet BBX-SP357 Rival] El rival robó 2 cartas de su deck.`, 'var(--accent-purple)');
  }

  updatePlaytestView();
  if (typeof onDone === 'function') onDone();
}

// Roy (BBX-SP359): "Puedes enviar esta carta en tu mano al cementerio, revela las primeras 2 cartas del tope de tu deck, entonces, por cada Skill propia de Roy revelada puedes enviar al cementerio 1 Skill portada en el campo de tu adversario."
function executeRoySP359Activation(activatorOwner = 'player', handIndex = -1, onDone = null) {
  const isPlayer = activatorOwner === 'player';
  const hand = isPlayer ? playtestState.hand : playtestState.opponentHand;
  const deck = isPlayer ? playtestState.deck : playtestState.opponentDeck;
  const grave = isPlayer ? playtestState.grave : playtestState.opponentGrave;
  const oppSlots = isPlayer ? playtestState.opponentSlots : playtestState.slots;
  const oppGrave = isPlayer ? playtestState.opponentGrave : playtestState.grave;
  const oppOwner = isPlayer ? 'opponent' : 'player';

  const rIdx = (handIndex >= 0 && hand[handIndex] === 'BBX-SP359')
    ? handIndex
    : hand.indexOf('BBX-SP359');

  if (rIdx === -1) {
    if (typeof onDone === 'function') onDone();
    return;
  }

  if (typeof isCharacterHandEffectBlocked === 'function' && isCharacterHandEffectBlocked(activatorOwner)) {
    addLog(`[Efecto Roy BBX-SP359 ${isPlayer ? '' : 'Rival'}] No se puede activar: Efectos de Personajes en mano bloqueados.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone();
    return;
  }

  if (deck.length < 2) {
    addLog(`[Efecto Roy BBX-SP359 ${isPlayer ? '' : 'Rival'}] No se puede activar: Se requieren al menos 2 cartas en tu deck para revelar el tope (hay ${deck.length}).`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone();
    return;
  }

  const tag = isPlayer ? '[Efecto Roy BBX-SP359]' : '[Rival - Efecto Roy BBX-SP359]';

  // 1. Enviar esta carta en tu mano al cementerio
  const discardedId = hand.splice(rIdx, 1)[0];
  grave.push(discardedId);
  addLog(`${tag} ${isPlayer ? 'Enviaste' : 'El rival envió'} a <strong>Roy</strong> de su mano al cementerio como costo.`, 'var(--accent-purple)');

  checkAndTriggerAlBorde(discardedId);
  checkAndTriggerReflejo(discardedId);
  checkAndTriggerEstrategia(discardedId);
  checkAndTriggerHackeo(discardedId);
  checkAndTriggerLlamarada(discardedId);
  checkAndTriggerEspiral(discardedId);
  checkAndTriggerFirewall(discardedId);
  checkAndTriggerFervor(discardedId);
  checkAndTriggerApunteIgneo(discardedId);
  checkAndTriggerCrimenNocturno(discardedId);
  checkAndTriggerAlmacenamientoFallido(discardedId, 'hand');
  checkAndTriggerKatshi159(discardedId);
  checkAndTriggerFulgorOfensivo(discardedId);
  checkAndTriggerEspiralDigital(discardedId, 'hand');
  checkAndTriggerBolaDeFuego(discardedId, 'hand');
  checkAndTriggerKatshi205(discardedId);
  checkAndTriggerRemembranza(discardedId, activatorOwner);

  if (window.GraveEffects && typeof window.GraveEffects.dispatch === 'function') {
    window.GraveEffects.dispatch(discardedId, activatorOwner, { fromZone: 'hand' });
  }

  // 2. Extraer y revelar las primeras 2 cartas del tope del mazo
  const card1 = deck.shift();
  const card2 = deck.shift();
  const revealedCards = [card1, card2];
  const card1Data = cardsDatabase[card1];
  const card2Data = cardsDatabase[card2];

  addLog(`${tag} Reveló las primeras 2 cartas del tope de su deck: <strong>${card1Data?.nombre || card1}</strong> y <strong>${card2Data?.nombre || card2}</strong>.`, 'var(--accent-cyan)');

  // Contar cuántas Skills propias de Roy fueron reveladas y separar para barajar
  let roySkillsCount = 0;
  const skillsToShuffle = [];
  const nonSkillsToTop = [];

  revealedCards.forEach(cId => {
    const cData = cardsDatabase[cId];
    if (cData && cData.tipo === 'Skill') {
      skillsToShuffle.push(cId);
      if (cData.portador && cData.portador.includes("Roy")) {
        roySkillsCount++;
      }
    } else {
      nonSkillsToTop.push(cId);
    }
  });

  // Las Skills reveladas se barajan al deck
  if (skillsToShuffle.length > 0) {
    skillsToShuffle.forEach(sId => deck.push(sId));
    shuffleArray(deck);
    addLog(`${tag} Se barajaron al deck ${skillsToShuffle.length} Skill(s) revelada(s): ${skillsToShuffle.map(sId => cardsDatabase[sId]?.nombre || sId).join(', ')}.`, 'var(--accent-purple)');
  }

  // Las cartas que no son Skills permanecen en la parte superior del mazo
  if (nonSkillsToTop.length > 0) {
    for (let i = nonSkillsToTop.length - 1; i >= 0; i--) {
      deck.unshift(nonSkillsToTop[i]);
    }
  }

  updatePlaytestView();

  // 3. "...entonces, por cada Skill propia de Roy revelada puedes enviar al cementerio 1 Skill portada en el campo de tu adversario."
  if (roySkillsCount === 0) {
    addLog(`${tag} No se reveló ninguna Skill propia de Roy, por lo que no se envía ninguna Skill del adversario.`, 'var(--text-muted)');
    updatePlaytestView();
    if (typeof onDone === 'function') onDone();
    return;
  }

  // Obtener Skills elegibles del campo adversario
  const getOppEligibleSkills = () => {
    const list = [];
    oppSlots.forEach((s, sIdx) => {
      if (s.character && s.skills) {
        const cName = cardsDatabase[s.character]?.nombre || 'Personaje';
        s.skills.forEach((skId, skIdx) => {
          const isOppSlot = isPlayer;
          if (canRemoveSkillByEffect(skId, isOppSlot, activatorOwner, s, 'grave')) {
            list.push({
              id: skId,
              slotIndex: sIdx,
              skillIndex: skIdx,
              charName: cName,
              skillName: cardsDatabase[skId]?.nombre || skId,
              label: `"${cardsDatabase[skId]?.nombre || skId}" (de ${cName})`
            });
          }
        });
      }
    });
    return list;
  };

  const oppEligible = getOppEligibleSkills();
  if (oppEligible.length === 0) {
    addLog(`${tag} Reveló ${roySkillsCount} Skill(s) propia(s) de Roy, pero el adversario no controla Skills portadas elegibles para enviar al cementerio.`, 'var(--text-muted)');
    updatePlaytestView();
    if (typeof onDone === 'function') onDone();
    return;
  }

  const maxToSend = Math.min(roySkillsCount, oppEligible.length);

  // Preguntar al activador si desea enviar Skills (es opcional: "puedes")
  const askItems = [
    {
      text: `💥 Enviar hasta ${maxToSend} Skill(s) portada(s) del adversario al cementerio`,
      action: () => {
        const chooserTargets = oppEligible.map(item => ({
          id: item.id,
          owner: oppOwner,
          from: item.charName,
          text: item.label
        }));

        const title = isPlayer
          ? `Roy: Selecciona hasta ${maxToSend} Skill(s) del rival para enviar al cementerio`
          : `[Rival] Roy: Selecciona hasta ${maxToSend} Skill(s) para enviar al cementerio`;

        openUpToCardChooserModal(chooserTargets, title, maxToSend, (chosenIndices) => {
          if (!chosenIndices || chosenIndices.length === 0) {
            addLog(`${tag} Decidiste no enviar ninguna Skill portada al cementerio.`, 'var(--text-muted)');
            updatePlaytestView();
            if (typeof onDone === 'function') onDone();
            return;
          }

          const removalsBySlot = {};
          const removedNames = [];
          const selectedItems = chosenIndices.map(idx => oppEligible[idx]);

          selectedItems.forEach(item => {
            if (!removalsBySlot[item.slotIndex]) removalsBySlot[item.slotIndex] = [];
            removalsBySlot[item.slotIndex].push(item.skillIndex);
          });

          Object.keys(removalsBySlot).forEach(sIdxStr => {
            const sIdx = parseInt(sIdxStr, 10);
            const indices = removalsBySlot[sIdx].sort((a, b) => b - a);
            const targetSlot = oppSlots[sIdx];
            indices.forEach(skIdx => {
              const removedSkId = targetSlot.skills.splice(skIdx, 1)[0];
              oppGrave.push(removedSkId);
              removedNames.push(`"${cardsDatabase[removedSkId]?.nombre || removedSkId}"`);
              onEquippedSkillSentToGraveByEffect(removedSkId, oppOwner, activatorOwner);
            });
          });

          addLog(`${tag} Enviaste al cementerio ${removedNames.length} Skill(s) portada(s) del adversario: ${removedNames.join(', ')}.`, 'var(--accent-purple)');
          if (typeof notifySkillsRemovedByEffect === 'function') {
            notifySkillsRemovedByEffect(removedNames.length, 'grave', activatorOwner);
          }
          updatePlaytestView();
          if (typeof onDone === 'function') onDone();
        });
      }
    },
    {
      text: `❌ No enviar ninguna Skill del adversario`,
      action: () => {
        addLog(`${tag} Decidiste no enviar ninguna Skill del adversario al cementerio.`, 'var(--text-muted)');
        updatePlaytestView();
        if (typeof onDone === 'function') onDone();
      }
    }
  ];

  const dummyEvent = { clientX: window.innerWidth / 2 - 140, clientY: window.innerHeight / 2 - 80 };
  showContextMenu(dummyEvent, askItems);
}

// Chiako (BBX-SP360): "Puedes enviar esta carta en tu mano al cementerio, entonces agrega a tu mano desde tu deck o cementerio 1 Skill \"¡Sistema alerta!\" y si lo haces puedes portar 1 Skill \"Encriptar\" directamente desde tu deck a 1 Personaje Chiako que controles."
function executeChiakoSP360Activation(activatorOwner = 'player', handIndex = -1, onDone = null) {
  const isPlayer = activatorOwner === 'player';
  const hand = isPlayer ? playtestState.hand : playtestState.opponentHand;
  const deck = isPlayer ? playtestState.deck : playtestState.opponentDeck;
  const grave = isPlayer ? playtestState.grave : playtestState.opponentGrave;
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;

  const cIdx = (handIndex >= 0 && hand[handIndex] === 'BBX-SP360')
    ? handIndex
    : hand.indexOf('BBX-SP360');

  if (cIdx === -1) {
    if (typeof onDone === 'function') onDone();
    return;
  }

  if (typeof isCharacterHandEffectBlocked === 'function' && isCharacterHandEffectBlocked(activatorOwner)) {
    addLog(`[Efecto Chiako BBX-SP360 ${isPlayer ? '' : 'Rival'}] No se puede activar: Efectos de Personajes en mano bloqueados.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone();
    return;
  }

  const isGraveBlocked = typeof isGraveToHandBlocked === 'function' && isGraveToHandBlocked();
  const hasInDeck = deck.includes('BBX-SP297');
  const hasInGrave = !isGraveBlocked && grave.includes('BBX-SP297');

  if (!hasInDeck && !hasInGrave) {
    addLog(`[Efecto Chiako BBX-SP360 ${isPlayer ? '' : 'Rival'}] No se puede activar: No hay "¡Sistema alerta!" en tu deck ni cementerio${isGraveBlocked ? ' (efectos de cementerio a mano bloqueados)' : ''}.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone();
    return;
  }

  const tag = isPlayer ? '[Efecto Chiako BBX-SP360]' : '[Rival - Efecto Chiako BBX-SP360]';

  // Costo: enviar esta carta en tu mano al cementerio
  const discardedId = hand.splice(cIdx, 1)[0];
  grave.push(discardedId);
  addLog(`${tag} ${isPlayer ? 'Enviaste' : 'El rival envió'} a <strong>Chiako</strong> de su mano al cementerio como costo.`, 'var(--accent-purple)');

  checkAndTriggerAlBorde(discardedId);
  checkAndTriggerReflejo(discardedId);
  checkAndTriggerEstrategia(discardedId);
  checkAndTriggerHackeo(discardedId);
  checkAndTriggerLlamarada(discardedId);
  checkAndTriggerEspiral(discardedId);
  checkAndTriggerFirewall(discardedId);
  checkAndTriggerFervor(discardedId);
  checkAndTriggerApunteIgneo(discardedId);
  checkAndTriggerCrimenNocturno(discardedId);
  checkAndTriggerAlmacenamientoFallido(discardedId, 'hand');
  checkAndTriggerKatshi159(discardedId);
  checkAndTriggerFulgorOfensivo(discardedId);
  checkAndTriggerEspiralDigital(discardedId, 'hand');
  checkAndTriggerBolaDeFuego(discardedId, 'hand');
  checkAndTriggerKatshi205(discardedId);
  checkAndTriggerRemembranza(discardedId, activatorOwner);

  if (window.GraveEffects && typeof window.GraveEffects.dispatch === 'function') {
    window.GraveEffects.dispatch(discardedId, activatorOwner, { fromZone: 'hand' });
  }

  // Continuación: Portar Encriptar (Paso 2)
  const proceedToEquipEncriptar = () => {
    const hasEncriptarInDeck = deck.includes('BBX-SP314');
    const canEquipDeck = typeof canEquipFromZone === 'function' ? canEquipFromZone('deck', 'BBX-SP314') : true;

    const eligibleChiakoSlots = [];
    slots.forEach((s, sIdx) => {
      if (s.character) {
        const charData = cardsDatabase[s.character];
        if (charData && charData.nombre && charData.nombre.includes("Chiako")) {
          const canEquipEishet = typeof canEquipSkillToSlotDueToEishetSP320 === 'function'
            ? canEquipSkillToSlotDueToEishetSP320('BBX-SP314', s)
            : true;
          if (canEquipEishet) {
            eligibleChiakoSlots.push({ slot: s, slotIndex: sIdx, charName: charData.nombre });
          }
        }
      }
    });

    if (!hasEncriptarInDeck || !canEquipDeck || eligibleChiakoSlots.length === 0) {
      if (!hasEncriptarInDeck) {
        addLog(`${tag} No hay copias de "Encriptar" en tu deck para portar.`, 'var(--text-muted)');
      } else if (!canEquipDeck) {
        addLog(`${tag} No puedes portar Skills directamente desde el deck en este momento.`, 'var(--text-muted)');
      } else if (eligibleChiakoSlots.length === 0) {
        addLog(`${tag} No controlas ningún Personaje Chiako al que puedas portar "Encriptar".`, 'var(--text-muted)');
      }
      updatePlaytestView();
      if (typeof onDone === 'function') onDone();
      return;
    }

    const doPort = (targetSlotIdx) => {
      const eIdx = deck.indexOf('BBX-SP314');
      if (eIdx !== -1) {
        const encriptarId = deck.splice(eIdx, 1)[0];
        if (!slots[targetSlotIdx].skills) slots[targetSlotIdx].skills = [];
        slots[targetSlotIdx].skills.push(encriptarId);
        shuffleArray(deck);
        addLog(`${tag} ${isPlayer ? 'Portaste' : 'El rival portó'} <strong>"Encriptar"</strong> directamente desde el deck a <strong>${cardsDatabase[slots[targetSlotIdx].character]?.nombre || 'Chiako'}</strong> (Slot ${targetSlotIdx + 1}) y barajó el mazo.`, 'var(--accent-purple)');
        if (typeof checkAndTriggerInestabilidad === 'function') {
          checkAndTriggerInestabilidad(activatorOwner);
        }
      }
      updatePlaytestView();
      if (typeof onDone === 'function') onDone();
    };

    if (!isPlayer) {
      // Rival siempre porta si puede
      doPort(eligibleChiakoSlots[0].slotIndex);
      return;
    }

    // Para el jugador, preguntar si desea portar (efecto opcional: "puedes")
    const equipItems = [
      {
        text: `⚡ Portar "Encriptar" desde tu deck a Chiako`,
        action: () => {
          if (eligibleChiakoSlots.length > 1) {
            const slotItems = eligibleChiakoSlots.map(cs => ({
              text: `Portar a ${cs.charName} en Slot ${cs.slotIndex + 1}`,
              action: () => doPort(cs.slotIndex)
            }));
            const dummyE = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 60 };
            showContextMenu(dummyE, slotItems);
          } else {
            doPort(eligibleChiakoSlots[0].slotIndex);
          }
        }
      },
      {
        text: `❌ No portar "Encriptar"`,
        action: () => {
          addLog(`${tag} Decidiste no portar "Encriptar".`, 'var(--text-muted)');
          updatePlaytestView();
          if (typeof onDone === 'function') onDone();
        }
      }
    ];

    const dummyEvent = { clientX: window.innerWidth / 2 - 140, clientY: window.innerHeight / 2 - 80 };
    showContextMenu(dummyEvent, equipItems);
  };

  // Paso 1: Agregar a tu mano 1 Skill "¡Sistema alerta!" desde deck o cementerio
  if (isPlayer) {
    const choices = [];
    deck.forEach((id, idx) => {
      if (id === 'BBX-SP297') {
        choices.push({ id, from: 'deck', originalIndex: idx });
      }
    });
    if (!isGraveBlocked) {
      grave.forEach((id, idx) => {
        if (id === 'BBX-SP297') {
          choices.push({ id, from: 'grave', originalIndex: idx });
        }
      });
    }

    if (choices.length > 1) {
      openCardChooserModal(choices, "Chiako: Selecciona la copia de '¡Sistema alerta!' a agregar a tu mano", (chosenIdx) => {
        const chosen = choices[chosenIdx];
        if (chosen.from === 'deck') {
          const idxInDeck = deck.indexOf('BBX-SP297');
          if (idxInDeck !== -1) {
            hand.push(deck.splice(idxInDeck, 1)[0]);
            shuffleArray(deck);
            addLog(`${tag} Agregaste a tu mano <strong>¡Sistema alerta!</strong> desde tu deck y barajaste el mazo.`, 'var(--accent-purple)');
          }
        } else {
          const idxInGrave = grave.indexOf('BBX-SP297');
          if (idxInGrave !== -1) {
            hand.push(grave.splice(idxInGrave, 1)[0]);
            addLog(`${tag} Agregaste a tu mano <strong>¡Sistema alerta!</strong> desde tu cementerio.`, 'var(--accent-purple)');
          }
        }
        updatePlaytestView();
        proceedToEquipEncriptar();
      });
    } else {
      // Solo hay 1 copia disponible (ya sea en deck o en grave)
      const chosen = choices[0];
      if (chosen.from === 'deck') {
        const idxInDeck = deck.indexOf('BBX-SP297');
        if (idxInDeck !== -1) {
          hand.push(deck.splice(idxInDeck, 1)[0]);
          shuffleArray(deck);
          addLog(`${tag} Agregaste a tu mano <strong>¡Sistema alerta!</strong> desde tu deck y barajaste el mazo.`, 'var(--accent-purple)');
        }
      } else {
        const idxInGrave = grave.indexOf('BBX-SP297');
        if (idxInGrave !== -1) {
          hand.push(grave.splice(idxInGrave, 1)[0]);
          addLog(`${tag} Agregaste a tu mano <strong>¡Sistema alerta!</strong> desde tu cementerio.`, 'var(--accent-purple)');
        }
      }
      updatePlaytestView();
      proceedToEquipEncriptar();
    }
  } else {
    // Modo Rival
    if (hasInDeck) {
      const idxInDeck = deck.indexOf('BBX-SP297');
      if (idxInDeck !== -1) {
        hand.push(deck.splice(idxInDeck, 1)[0]);
        shuffleArray(deck);
        addLog(`${tag} El rival agregó a su mano <strong>¡Sistema alerta!</strong> desde su deck y barajó su mazo.`, 'var(--accent-purple)');
      }
    } else if (hasInGrave) {
      const idxInGrave = grave.indexOf('BBX-SP297');
      if (idxInGrave !== -1) {
        hand.push(grave.splice(idxInGrave, 1)[0]);
        addLog(`${tag} El rival agregó a su mano <strong>¡Sistema alerta!</strong> desde su cementerio.`, 'var(--accent-purple)');
      }
    }
    updatePlaytestView();
    proceedToEquipEncriptar();
  }
}

// Katherine (BBX-SP364): "Puedes enviar esta carta en tu mano al cementerio, envía 1 Skill portada al cementerio and si lo haces, puedes enviar 1 Skill propia de Katherine de tu deck al cementerio, excepto \"Firewall\"."
function executeKatherineSP364Activation(activatorOwner = 'player', handIndex = -1, onDone = null) {
  const isPlayer = activatorOwner === 'player';
  const hand = isPlayer ? playtestState.hand : playtestState.opponentHand;
  const deck = isPlayer ? playtestState.deck : playtestState.opponentDeck;
  const grave = isPlayer ? playtestState.grave : playtestState.opponentGrave;

  const cIdx = (handIndex >= 0 && hand[handIndex] === 'BBX-SP364')
    ? handIndex
    : hand.indexOf('BBX-SP364');

  if (cIdx === -1) {
    if (typeof onDone === 'function') onDone();
    return;
  }

  if (typeof isCharacterHandEffectBlocked === 'function' && isCharacterHandEffectBlocked(activatorOwner)) {
    addLog(`[Efecto Katherine BBX-SP364 ${isPlayer ? '' : 'Rival'}] No se puede activar: Efectos de Personajes en mano bloqueados.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone();
    return;
  }

  // Recopilar candidatos de Skills portadas en ambos campos
  const candidates = [];
  playtestState.slots.forEach((s, sIdx) => {
    if (s.character && s.skills) {
      s.skills.forEach((skId, skIdx) => {
        const isOppSlot = !isPlayer;
        if (canRemoveSkillByEffect(skId, isOppSlot, activatorOwner, s, 'grave')) {
          candidates.push({
            id: skId,
            owner: 'player',
            slotIdx: sIdx,
            skIdx: skIdx,
            charName: cardsDatabase[s.character] ? cardsDatabase[s.character].nombre : 'Personaje'
          });
        }
      });
    }
  });

  playtestState.opponentSlots.forEach((s, sIdx) => {
    if (s.character && s.skills) {
      s.skills.forEach((skId, skIdx) => {
        const isOppSlot = isPlayer;
        if (canRemoveSkillByEffect(skId, isOppSlot, activatorOwner, s, 'grave')) {
          candidates.push({
            id: skId,
            owner: 'opponent',
            slotIdx: sIdx,
            skIdx: skIdx,
            charName: cardsDatabase[s.character] ? cardsDatabase[s.character].nombre : 'Personaje'
          });
        }
      });
    }
  });

  if (candidates.length === 0) {
    addLog(`[Efecto Katherine BBX-SP364 ${isPlayer ? '' : 'Rival'}] No hay Skills portadas elegibles en el campo para enviar al cementerio.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone();
    return;
  }

  const tag = isPlayer ? '[Efecto Katherine BBX-SP364]' : '[Rival - Efecto Katherine BBX-SP364]';

  // Costo: enviar Katherine en tu mano al cementerio
  const discardedId = hand.splice(cIdx, 1)[0];
  grave.push(discardedId);
  addLog(`${tag} ${isPlayer ? 'Enviaste' : 'El rival envió'} a <strong>Katherine</strong> de su mano al cementerio como costo.`, 'var(--accent-purple)');

  checkAndTriggerAlBorde(discardedId);
  checkAndTriggerReflejo(discardedId);
  checkAndTriggerEstrategia(discardedId);
  checkAndTriggerHackeo(discardedId);
  checkAndTriggerLlamarada(discardedId);
  checkAndTriggerEspiral(discardedId);
  checkAndTriggerFirewall(discardedId);
  checkAndTriggerFervor(discardedId);
  checkAndTriggerApunteIgneo(discardedId);
  checkAndTriggerCrimenNocturno(discardedId);
  checkAndTriggerAlmacenamientoFallido(discardedId, 'hand');
  checkAndTriggerKatshi159(discardedId);
  checkAndTriggerFulgorOfensivo(discardedId);
  checkAndTriggerEspiralDigital(discardedId, 'hand');
  checkAndTriggerBolaDeFuego(discardedId, 'hand');
  checkAndTriggerKatshi205(discardedId);
  checkAndTriggerRemembranza(discardedId, activatorOwner);

  if (window.GraveEffects && typeof window.GraveEffects.dispatch === 'function') {
    window.GraveEffects.dispatch(discardedId, activatorOwner, { fromZone: 'hand' });
  }

  // Paso 2: Opción de enviar 1 Skill de Katherine del deck al cementerio (excepto Firewall)
  const proceedToDeckSkill = () => {
    const isKatherineSkill = id => {
      const c = cardsDatabase[id];
      return c && c.tipo === 'Skill' && c.portador && c.portador.includes("Katherine") && c.nombre !== "Firewall" && id !== 'BBX-SP094';
    };

    const eligibleSkills = [];
    deck.forEach((id, idx) => {
      if (isKatherineSkill(id)) {
        eligibleSkills.push({ id, originalIndex: idx, name: cardsDatabase[id]?.nombre || id });
      }
    });

    if (eligibleSkills.length === 0) {
      addLog(`${tag} No hay Skills propias de Katherine (excepto "Firewall") en ${isPlayer ? 'tu deck' : 'el deck rival'} para enviar al cementerio.`, 'var(--text-muted)');
      updatePlaytestView();
      if (typeof onDone === 'function') onDone();
      return;
    }

    if (!isPlayer) {
      // Modo Rival: envía la primera Skill de Katherine elegible
      const chosen = eligibleSkills[0];
      const idxInDeck = deck.indexOf(chosen.id);
      if (idxInDeck !== -1) {
        const sentId = deck.splice(idxInDeck, 1)[0];
        grave.push(sentId);
        shuffleArray(deck);
        addLog(`${tag} El rival envió a <strong>${chosen.name}</strong> de su deck al cementerio y barajó su mazo.`, 'var(--accent-purple)');

        if (typeof dispatchGraveTriggers === 'function') {
          dispatchGraveTriggers(sentId, 'opponent', { fromZone: 'deck', reasonOwner: 'opponent' });
        }
        if (typeof checkAndTriggerInestabilidad === 'function') {
          checkAndTriggerInestabilidad('opponent');
        }
      }
      updatePlaytestView();
      if (typeof onDone === 'function') onDone();
      return;
    }

    // Modo Jugador: Confirmación y selección interactiva
    const sendDeckSkill = (chosenItem) => {
      const idxInDeck = deck.indexOf(chosenItem.id);
      if (idxInDeck !== -1) {
        const sentId = deck.splice(idxInDeck, 1)[0];
        grave.push(sentId);
        shuffleArray(deck);
        addLog(`${tag} Enviaste a <strong>${chosenItem.name}</strong> de tu deck al cementerio y barajaste tu mazo.`, 'var(--accent-purple)');

        if (typeof dispatchGraveTriggers === 'function') {
          dispatchGraveTriggers(sentId, 'player', { fromZone: 'deck', reasonOwner: 'player' });
        }
        if (typeof checkAndTriggerInestabilidad === 'function') {
          checkAndTriggerInestabilidad('player');
        }
      }
      updatePlaytestView();
      if (typeof onDone === 'function') onDone();
    };

    const promptItems = [
      {
        text: `📖 Enviar 1 Skill de Katherine del deck al cementerio (${eligibleSkills.length} disponible(s))`,
        action: () => {
          if (eligibleSkills.length === 1) {
            sendDeckSkill(eligibleSkills[0]);
          } else {
            const chooserTargets = eligibleSkills.map(e => ({
              id: e.id,
              from: 'deck',
              owner: 'player'
            }));
            openCardChooserModal(chooserTargets, "Katherine (SP364): Selecciona 1 Skill de Katherine para enviar al cementerio", (chosenIdx) => {
              sendDeckSkill(eligibleSkills[chosenIdx]);
            });
          }
        }
      },
      {
        text: `❌ No enviar ninguna Skill del deck`,
        action: () => {
          addLog(`${tag} Decidiste no enviar ninguna Skill de Katherine de tu deck al cementerio.`, 'var(--text-muted)');
          updatePlaytestView();
          if (typeof onDone === 'function') onDone();
        }
      }
    ];

    const dummyEvent = { clientX: window.innerWidth / 2 - 140, clientY: window.innerHeight / 2 - 80 };
    showContextMenu(dummyEvent, promptItems);
  };

  // Paso 1: Enviar 1 Skill portada al cementerio
  const executeRemoval = (chosenItem) => {
    const isTargetOpponent = chosenItem.owner === 'opponent';
    const targetSlot = isTargetOpponent ? playtestState.opponentSlots[chosenItem.slotIdx] : playtestState.slots[chosenItem.slotIdx];
    let idx = chosenItem.skIdx;
    if (targetSlot.skills[idx] !== chosenItem.id) {
      idx = targetSlot.skills.indexOf(chosenItem.id);
    }
    if (idx === -1) {
      if (typeof onDone === 'function') onDone();
      return;
    }

    const removedId = targetSlot.skills.splice(idx, 1)[0];
    const skillName = cardsDatabase[removedId] ? cardsDatabase[removedId].nombre : removedId;

    if (isTargetOpponent) {
      playtestState.opponentGrave.push(removedId);
      if (isPlayer) {
        addLog(`${tag} Enviaste al cementerio del rival la Skill <strong>${skillName}</strong> portada en <strong>${chosenItem.charName}</strong>.`, 'var(--accent-purple)');
      } else {
        addLog(`${tag} El rival envió a su cementerio la Skill <strong>${skillName}</strong> portada en <strong>${chosenItem.charName}</strong>.`, 'var(--accent-purple)');
      }
      onEquippedSkillSentToGraveByEffect(removedId, 'opponent', activatorOwner);
    } else {
      playtestState.grave.push(removedId);
      if (isPlayer) {
        addLog(`${tag} Enviaste a tu cementerio la Skill <strong>${skillName}</strong> portada en <strong>${chosenItem.charName}</strong>.`, 'var(--accent-purple)');
      } else {
        addLog(`${tag} El rival envió a tu cementerio la Skill <strong>${skillName}</strong> portada en <strong>${chosenItem.charName}</strong>.`, 'var(--accent-purple)');
      }
      onEquippedSkillSentToGraveByEffect(removedId, 'player', activatorOwner);
    }

    if (typeof notifySkillsRemovedByEffect === 'function') {
      notifySkillsRemovedByEffect(1, 'grave', activatorOwner);
    }

    updatePlaytestView();
    proceedToDeckSkill();
  };

  if (isPlayer) {
    if (candidates.length === 1) {
      executeRemoval(candidates[0]);
    } else {
      const chooserTargets = candidates.map(c => ({
        id: c.id,
        from: 'field',
        owner: c.owner,
        charName: c.charName
      }));
      openCardChooserModal(chooserTargets, "Katherine (SP364): Selecciona 1 Skill portada para enviar al cementerio", (chosenIdx) => {
        executeRemoval(candidates[chosenIdx]);
      });
    }
  } else {
    // Modo Rival: prioriza skills del jugador, si no hay, sus propias skills
    const oppSkills = candidates.filter(c => c.owner === 'player');
    const chosen = oppSkills.length > 0 ? oppSkills[0] : candidates[0];
    executeRemoval(chosen);
  }
}

// Fredlard (BBX-SP368): "Puedes enviar esta carta en tu mano al cementerio, tu adversario roba 1 carta de su deck y si lo haces, puedes barajar al deck 1 Skill portada."
function executeFredlardSP368Activation(activatorOwner = 'player', handIndex = -1, onDone = null, testOptions = {}) {
  const isPlayer = activatorOwner === 'player';
  const hand = isPlayer ? playtestState.hand : playtestState.opponentHand;
  const oppDeck = isPlayer ? playtestState.opponentDeck : playtestState.deck;
  const oppHand = isPlayer ? playtestState.opponentHand : playtestState.hand;
  const grave = isPlayer ? playtestState.grave : playtestState.opponentGrave;

  const cIdx = (handIndex >= 0 && hand[handIndex] === 'BBX-SP368')
    ? handIndex
    : hand.indexOf('BBX-SP368');

  if (cIdx === -1) {
    if (typeof onDone === 'function') onDone();
    return;
  }

  if (typeof isCharacterHandEffectBlocked === 'function' && isCharacterHandEffectBlocked(activatorOwner)) {
    addLog(`[Efecto Fredlard BBX-SP368 ${isPlayer ? '' : 'Rival'}] No se puede activar: Efectos de Personajes en mano bloqueados.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone();
    return;
  }

  const oppCannotDraw = isPlayer ? !!playtestState.opponentCannotDrawByEffectsThisTurn : !!playtestState.cannotDrawByEffectsThisTurn;
  const hasHelica = playtestState.slots.some(s => s.character === 'BBX-SP135') || playtestState.opponentSlots.some(s => s.character === 'BBX-SP135');
  if (oppDeck.length === 0 || oppCannotDraw || hasHelica) {
    addLog(`[Efecto Fredlard BBX-SP368 ${isPlayer ? '' : 'Rival'}] No se puede activar: El adversario no puede robar cartas de su deck.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone();
    return;
  }

  const tag = isPlayer ? '[Efecto Fredlard BBX-SP368]' : '[Rival - Efecto Fredlard BBX-SP368]';

  // Costo: enviar Fredlard en tu mano al cementerio
  const discardedId = hand.splice(cIdx, 1)[0];
  grave.push(discardedId);
  addLog(`${tag} Enviaste a Fredlard de tu mano al cementerio.`, 'var(--accent-purple)');

  checkAndTriggerFirewall(discardedId);
  checkAndTriggerFervor(discardedId);
  checkAndTriggerApunteIgneo(discardedId);
  checkAndTriggerCrimenNocturno(discardedId);
  checkAndTriggerAlmacenamientoFallido(discardedId, 'hand');
  checkAndTriggerKatshi159(discardedId);
  checkAndTriggerFulgorOfensivo(discardedId);
  checkAndTriggerEspiralDigital(discardedId, 'hand');
  checkAndTriggerBolaDeFuego(discardedId, 'hand');
  checkAndTriggerKatshi205(discardedId);
  checkAndTriggerRemembranza(discardedId, activatorOwner);

  if (window.GraveEffects && typeof window.GraveEffects.dispatch === 'function') {
    window.GraveEffects.dispatch(discardedId, activatorOwner, { fromZone: 'hand' });
  }

  // Paso 1: Tu adversario roba 1 carta de su deck
  const drawnId = oppDeck.shift();
  oppHand.push(drawnId);
  const drawnName = cardsDatabase[drawnId] ? cardsDatabase[drawnId].nombre : drawnId;
  if (isPlayer) {
    addLog(`${tag} Tu adversario robó 1 carta de su deck: <strong>${drawnName}</strong>.`, 'var(--accent-purple)');
  } else {
    addLog(`${tag} El rival te hizo robar 1 carta de tu deck: <strong>${drawnName}</strong>.`, 'var(--accent-purple)');
  }

  if (typeof checkAndTriggerInestabilidad === 'function') {
    checkAndTriggerInestabilidad(isPlayer ? 'opponent' : 'player');
  }

  // Paso 2 ("y si lo haces, puedes barajar al deck 1 Skill portada"):
  const candidates = [];
  playtestState.slots.forEach((s, sIdx) => {
    if (s.character && s.skills) {
      s.skills.forEach((skId, skIdx) => {
        const isOppSlot = !isPlayer;
        if (canRemoveSkillByEffect(skId, isOppSlot, activatorOwner, s, 'deck')) {
          candidates.push({
            id: skId,
            owner: 'player',
            slotIdx: sIdx,
            skIdx: skIdx,
            charName: cardsDatabase[s.character] ? cardsDatabase[s.character].nombre : 'Personaje'
          });
        }
      });
    }
  });

  playtestState.opponentSlots.forEach((s, sIdx) => {
    if (s.character && s.skills) {
      s.skills.forEach((skId, skIdx) => {
        const isOppSlot = isPlayer;
        if (canRemoveSkillByEffect(skId, isOppSlot, activatorOwner, s, 'deck')) {
          candidates.push({
            id: skId,
            owner: 'opponent',
            slotIdx: sIdx,
            skIdx: skIdx,
            charName: cardsDatabase[s.character] ? cardsDatabase[s.character].nombre : 'Personaje'
          });
        }
      });
    }
  });

  const doShuffle = (chosen) => {
    const isPlayerTarget = chosen.owner === 'player';
    const targetSlot = isPlayerTarget ? playtestState.slots[chosen.slotIdx] : playtestState.opponentSlots[chosen.slotIdx];
    let sIdx = chosen.skIdx;
    if (targetSlot.skills[sIdx] !== chosen.id) {
      sIdx = targetSlot.skills.indexOf(chosen.id);
    }
    if (sIdx !== -1) {
      const performActualShuffle = () => {
        targetSlot.skills.splice(sIdx, 1);
        const targetDeck = isPlayerTarget ? playtestState.deck : playtestState.opponentDeck;
        targetDeck.push(chosen.id);
        shuffleArray(targetDeck);

        const skillName = cardsDatabase[chosen.id]?.nombre || chosen.id;
        const targetOwnerDesc = isPlayerTarget ? (isPlayer ? 'tu deck' : 'el deck del jugador') : (isPlayer ? 'el deck del rival' : 'su deck');
        addLog(`${tag} Barajó a ${targetOwnerDesc} la Skill portada <strong>${skillName}</strong> (equipada a ${chosen.charName}).`, 'var(--accent-purple)');

        if (typeof notifySkillsRemovedByEffect === 'function') {
          notifySkillsRemovedByEffect(1, null, activatorOwner);
        }
        updatePlaytestView();
        if (typeof onDone === 'function') onDone();
      };

      if (chosen.owner !== activatorOwner && typeof checkAndProtectShuffleSkillByRyuChan === 'function') {
        checkAndProtectShuffleSkillByRyuChan(chosen.owner, () => {
          updatePlaytestView();
          if (typeof onDone === 'function') onDone();
        }, () => {
          performActualShuffle();
        }, 1);
      } else {
        performActualShuffle();
      }
    } else {
      updatePlaytestView();
      if (typeof onDone === 'function') onDone();
    }
  };

  if (candidates.length === 0) {
    addLog(`${tag} No hay Skills portadas elegibles en el campo para barajar al deck.`, 'var(--text-muted)');
    updatePlaytestView();
    if (typeof onDone === 'function') onDone();
    return;
  }

  // Opciones directas para pruebas o llamadas automatizadas
  if (testOptions && testOptions.skipShuffle) {
    addLog(`${tag} Decidiste no barajar ninguna Skill portada al deck.`, 'var(--text-muted)');
    updatePlaytestView();
    if (typeof onDone === 'function') onDone();
    return;
  }
  if (testOptions && typeof testOptions.selectedCandidateIndex === 'number') {
    const chosen = candidates[testOptions.selectedCandidateIndex];
    if (chosen) {
      doShuffle(chosen);
      return;
    }
  }

  if (!isPlayer) {
    // Modo Rival: prioriza barajar una Skill del jugador
    const playerSkill = candidates.find(c => c.owner === 'player');
    const chosen = playerSkill || candidates[0];
    doShuffle(chosen);
    return;
  }

  // Modo Jugador: Modal interactivo o menú
  const chooserTargets = candidates.map(item => ({
    id: item.id,
    from: 'field',
    owner: item.owner,
    charName: item.charName,
    text: `"${cardsDatabase[item.id]?.nombre || item.id}" (de ${item.charName} - ${item.owner === 'player' ? 'Tú' : 'Rival'})`
  }));

  const dummyEvent = {
    clientX: (typeof window !== 'undefined' ? window.innerWidth / 2 - 140 : 0),
    clientY: (typeof window !== 'undefined' ? window.innerHeight / 2 - 80 : 0)
  };

  const promptItems = [
    {
      text: "⚡ Barajar 1 Skill portada al deck",
      action: () => {
        if (candidates.length === 1) {
          doShuffle(candidates[0]);
        } else if (typeof openCardChooserModal === 'function') {
          openCardChooserModal(chooserTargets, "Fredlard (BBX-SP368): Selecciona 1 Skill portada para barajar a su deck", (chosenIdx) => {
            doShuffle(candidates[chosenIdx]);
          });
        } else {
          doShuffle(candidates[0]);
        }
      }
    },
    {
      text: "❌ No barajar ninguna Skill",
      action: () => {
        addLog(`${tag} Decidiste no barajar ninguna Skill portada al deck.`, 'var(--text-muted)');
        updatePlaytestView();
        if (typeof onDone === 'function') onDone();
      }
    }
  ];

  if (typeof showContextMenu === 'function') {
    showContextMenu(dummyEvent, promptItems);
  } else {
    doShuffle(candidates[0]);
  }
}

// Eishet (BBX-SP370): "Una vez por turno, puedes enviar 1 Skill propia de Eishet en tu deck al cementerio and si lo haces puedes enviar 1 Skill portada al cementerio."
function executeEishetSP370Activation(slotIndex, activatorOwner = 'player', testOptions = {}, onDone = null) {
  const isPlayer = activatorOwner === 'player';
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;
  const deck = isPlayer ? playtestState.deck : playtestState.opponentDeck;
  const grave = isPlayer ? playtestState.grave : playtestState.opponentGrave;
  const slot = slots[slotIndex];

  if (!slot || slot.character !== 'BBX-SP370') {
    if (typeof onDone === 'function') onDone();
    return;
  }

  if (slot.effectUsed) {
    if (typeof alert === 'function') alert("Este efecto de personaje ya se usó este turno.");
    if (typeof onDone === 'function') onDone();
    return;
  }

  const isEishetSkill = id => {
    const c = cardsDatabase[id];
    return c && c.tipo === 'Skill' && (c.portador === 'Eishet' || (c.portador && c.portador.includes('Eishet')));
  };

  const eishetSkillsInDeck = deck.filter(isEishetSkill);
  if (eishetSkillsInDeck.length === 0) {
    const msg = isPlayer
      ? "No tienes ninguna Skill propia de Eishet en tu deck para enviar al cementerio."
      : "El mazo rival no contiene ninguna Skill propia de Eishet.";
    if (typeof alert === 'function') alert(msg);
    if (typeof onDone === 'function') onDone();
    return;
  }

  const tag = isPlayer ? '[Efecto Eishet BBX-SP370]' : '[Rival - Efecto Eishet BBX-SP370]';

  const proceedWithFieldSkillRemoval = () => {
    // Buscar Skills portadas elegibles en el campo (propias y del rival)
    const candidates = [];
    playtestState.slots.forEach((s, sIdx) => {
      if (s.character && s.skills) {
        s.skills.forEach((skId, skIdx) => {
          if (canRemoveSkillByEffect(skId, !isPlayer, activatorOwner, s, 'grave', 'BBX-SP370', 'character', false)) {
            candidates.push({
              id: skId,
              owner: 'player',
              slotIdx: sIdx,
              skIdx: skIdx,
              charName: cardsDatabase[s.character] ? cardsDatabase[s.character].nombre : 'Personaje',
              text: `"${cardsDatabase[skId]?.nombre || skId}" (de ${cardsDatabase[s.character]?.nombre || 'Personaje'} - ${isPlayer ? 'Tú' : 'Jugador'})`
            });
          }
        });
      }
    });

    playtestState.opponentSlots.forEach((s, sIdx) => {
      if (s.character && s.skills) {
        s.skills.forEach((skId, skIdx) => {
          if (canRemoveSkillByEffect(skId, isPlayer, activatorOwner, s, 'grave', 'BBX-SP370', 'character', false)) {
            candidates.push({
              id: skId,
              owner: 'opponent',
              slotIdx: sIdx,
              skIdx: skIdx,
              charName: cardsDatabase[s.character] ? cardsDatabase[s.character].nombre : 'Personaje',
              text: `"${cardsDatabase[skId]?.nombre || skId}" (de ${cardsDatabase[s.character]?.nombre || 'Personaje'} - ${isPlayer ? 'Rival' : 'Tú'})`
            });
          }
        });
      }
    });

    if (candidates.length === 0) {
      addLog(`${tag} No hay Skills portadas elegibles en el campo para enviar al cementerio.`, 'var(--text-muted)');
      updatePlaytestView();
      if (typeof onDone === 'function') onDone();
      return;
    }

    // Como dice "puedes", enviar una Skill portada es opcional
    if (testOptions && testOptions.skipFieldSkillRemoval) {
      addLog(`${tag} Decidiste no enviar ninguna Skill portada al cementerio.`, 'var(--text-muted)');
      updatePlaytestView();
      if (typeof onDone === 'function') onDone();
      return;
    }

    const doSendFieldSkill = (chosenItem) => {
      const isOppTarget = chosenItem.owner !== activatorOwner;
      const targetSlot = chosenItem.owner === 'player' ? playtestState.slots[chosenItem.slotIdx] : playtestState.opponentSlots[chosenItem.slotIdx];
      let idx = chosenItem.skIdx;
      if (targetSlot.skills[idx] !== chosenItem.id) {
        idx = targetSlot.skills.indexOf(chosenItem.id);
      }
      if (idx === -1) {
        updatePlaytestView();
        if (typeof onDone === 'function') onDone();
        return;
      }

      const performSend = () => {
        const removedId = targetSlot.skills.splice(idx, 1)[0];
        const skillName = cardsDatabase[removedId] ? cardsDatabase[removedId].nombre : removedId;
        const targetGrave = chosenItem.owner === 'player' ? playtestState.grave : playtestState.opponentGrave;
        targetGrave.push(removedId);

        const targetOwnerDesc = chosenItem.owner === activatorOwner ? 'su propio cementerio' : (isPlayer ? 'el cementerio del rival' : 'tu cementerio');
        addLog(`${tag} Envió a ${targetOwnerDesc} la Skill <strong>${skillName}</strong> portada en <strong>${chosenItem.charName}</strong>.`, 'var(--accent-purple)');

        if (typeof onEquippedSkillSentToGraveByEffect === 'function') {
          onEquippedSkillSentToGraveByEffect(removedId, chosenItem.owner, activatorOwner);
        }

        if (typeof notifySkillsRemovedByEffect === 'function') {
          notifySkillsRemovedByEffect(1, 'grave', activatorOwner);
        }

        updatePlaytestView();
        if (typeof onDone === 'function') onDone();
      };

      if (isOppTarget && typeof checkAndProtectSendSkillsToGrave === 'function') {
        checkAndProtectSendSkillsToGrave(chosenItem.owner, () => {
          updatePlaytestView();
          if (typeof onDone === 'function') onDone();
        }, () => {
          performSend();
        }, 1);
      } else {
        performSend();
      }
    };

    if (testOptions && typeof testOptions.selectedFieldSkillIndex === 'number') {
      const chosen = candidates[testOptions.selectedFieldSkillIndex];
      if (chosen) {
        doSendFieldSkill(chosen);
        return;
      }
    }

    if (!isPlayer) {
      // Modo Rival: prioriza enviar una Skill del jugador
      const playerSkill = candidates.find(c => c.owner === 'player');
      const chosen = playerSkill || candidates[0];
      doSendFieldSkill(chosen);
      return;
    }

    // Modo Jugador: menú interactivo ("Enviar Skill portada" o "No enviar")
    const selectTarget = () => {
      if (candidates.length === 1) {
        doSendFieldSkill(candidates[0]);
      } else if (typeof openCardChooserModal === 'function') {
        const chooserTargets = candidates.map(c => ({
          id: c.id,
          owner: c.owner,
          from: 'field',
          charName: c.charName,
          text: c.text
        }));
        openCardChooserModal(chooserTargets, "Eishet (BBX-SP370): Selecciona 1 Skill portada para enviar al cementerio", (chosenIdx) => {
          doSendFieldSkill(candidates[chosenIdx]);
        });
      } else {
        doSendFieldSkill(candidates[0]);
      }
    };

    const dummyEvent = {
      clientX: (typeof window !== 'undefined' ? window.innerWidth / 2 - 140 : 0),
      clientY: (typeof window !== 'undefined' ? window.innerHeight / 2 - 80 : 0)
    };

    const promptItems = [
      {
        text: "💥 Enviar 1 Skill portada al cementerio",
        action: () => {
          selectTarget();
        }
      },
      {
        text: "❌ No enviar ninguna Skill portada al cementerio",
        action: () => {
          addLog(`${tag} Decidiste no enviar ninguna Skill portada al cementerio.`, 'var(--text-muted)');
          updatePlaytestView();
          if (typeof onDone === 'function') onDone();
        }
      }
    ];

    if (typeof showContextMenu === 'function') {
      showContextMenu(dummyEvent, promptItems);
    } else {
      selectTarget();
    }
  };

  const doSendDeckSkill = (chosenSkillId) => {
    const dIdx = deck.indexOf(chosenSkillId);
    if (dIdx !== -1) {
      deck.splice(dIdx, 1);
    }
    grave.push(chosenSkillId);
    shuffleArray(deck);

    const sentName = cardsDatabase[chosenSkillId] ? cardsDatabase[chosenSkillId].nombre : chosenSkillId;
    addLog(`${tag} Envió a <strong>${sentName}</strong> de su deck al cementerio y barajó su deck.`, 'var(--accent-purple)');

    slot.effectUsed = true;

    if (typeof dispatchGraveTriggers === 'function') {
      dispatchGraveTriggers(chosenSkillId, activatorOwner, { fromZone: 'deck', reasonOwner: activatorOwner });
    } else {
      if (typeof checkAndTriggerRemembranza === 'function') checkAndTriggerRemembranza(chosenSkillId, activatorOwner);
      if (typeof checkAndTriggerEscape === 'function') checkAndTriggerEscape(chosenSkillId, activatorOwner);
      if (typeof checkAndTriggerDesvelo === 'function') checkAndTriggerDesvelo(chosenSkillId, activatorOwner);
      if (typeof checkAndTriggerAlumbrarSP347 === 'function') checkAndTriggerAlumbrarSP347(chosenSkillId, 'deck', activatorOwner);
      if (typeof checkAndTriggerFlamaCerteraSP413 === 'function' && chosenSkillId === 'BBX-SP413') checkAndTriggerFlamaCerteraSP413(chosenSkillId, 'deck', activatorOwner);
    }

    if (typeof notifySkillsRemovedByEffect === 'function') {
      notifySkillsRemovedByEffect(1, null, activatorOwner);
    }

    updatePlaytestView();

    proceedWithFieldSkillRemoval();
  };

  if (testOptions && typeof testOptions.selectedDeckSkillIndex === 'number') {
    const chosenId = eishetSkillsInDeck[testOptions.selectedDeckSkillIndex] || eishetSkillsInDeck[0];
    doSendDeckSkill(chosenId);
    return;
  }

  if (!isPlayer || eishetSkillsInDeck.length === 1) {
    doSendDeckSkill(eishetSkillsInDeck[0]);
  } else if (typeof openCardChooserModal === 'function') {
    const chooserTargets = eishetSkillsInDeck.map(id => ({
      id,
      owner: activatorOwner,
      from: 'deck',
      text: `"${cardsDatabase[id]?.nombre || id}"`
    }));
    openCardChooserModal(chooserTargets, "Eishet (BBX-SP370): Selecciona 1 Skill propia de Eishet de tu deck para enviar al cementerio", (chosenIdx) => {
      doSendDeckSkill(eishetSkillsInDeck[chosenIdx]);
    });
  } else {
    doSendDeckSkill(eishetSkillsInDeck[0]);
  }
}

// Florete (BBX-SP371): "Mientras esta carta se encuentre en el cementerio, puedes enviar 1 Skill portada al cementerio. Solo puedes usar este efecto de \"Florete\" una vez por turno."
function executeFloreteSP371Activation(activatorOwner = 'player', testOptions = {}, onDone = null) {
  const isPlayer = activatorOwner === 'player';
  const grave = isPlayer ? playtestState.grave : playtestState.opponentGrave;
  const tag = isPlayer ? '[Efecto Florete BBX-SP371]' : '[Rival - Efecto Florete BBX-SP371]';

  if (playtestState.turnOwner !== activatorOwner) {
    const msg = isPlayer
      ? "Solo puedes activar el efecto de Florete durante tu turno."
      : "Solo se puede activar el efecto de Florete durante el turno del rival.";
    if (typeof alert === 'function') alert(msg);
    if (typeof onDone === 'function') onDone();
    return;
  }

  // 1. Debe encontrarse en el cementerio
  if (!grave.includes('BBX-SP371')) {
    const msg = isPlayer
      ? "Florete (BBX-SP371) no se encuentra en tu cementerio."
      : "Florete (BBX-SP371) no se encuentra en el cementerio del rival.";
    if (typeof alert === 'function') alert(msg);
    if (typeof onDone === 'function') onDone();
    return;
  }

  // 2. Verificar bloqueo de cementerio
  if (typeof isCardGraveEffectBlocked === 'function' && isCardGraveEffectBlocked(activatorOwner, 'BBX-SP371')) {
    const msg = isPlayer
      ? "Los efectos de cartas en el cementerio están bloqueados este turno."
      : "Los efectos de cartas en el cementerio del rival están bloqueados este turno.";
    if (typeof alert === 'function') alert(msg);
    if (typeof onDone === 'function') onDone();
    return;
  }

  // 3. Verificar HOPT (una vez por turno)
  const yaUsadoTurno = isPlayer
    ? (playtestState.usedFlorete371ThisTurn || (playtestState.usedGlobalEffects || []).includes('BBX-SP371') || (playtestState.usedGlobalEffects || []).includes('Florete'))
    : (playtestState.opponentUsedFlorete371ThisTurn || (playtestState.opponentUsedGlobalEffects || []).includes('BBX-SP371') || (playtestState.opponentUsedGlobalEffects || []).includes('Florete'));

  if (yaUsadoTurno) {
    const msg = isPlayer
      ? "Ya se usó el efecto de \"Florete\" en este turno."
      : "El rival ya usó el efecto de \"Florete\" en este turno.";
    if (typeof alert === 'function') alert(msg);
    if (typeof onDone === 'function') onDone();
    return;
  }

  // 4. Buscar Skills portadas elegibles en el campo (propias y del rival)
  const candidates = [];
  playtestState.slots.forEach((s, sIdx) => {
    if (s.character && s.skills) {
      s.skills.forEach((skId, skIdx) => {
        if (canRemoveSkillByEffect(skId, false, activatorOwner, s, 'grave', 'BBX-SP371', 'grave_skill', false)) {
          candidates.push({
            id: skId,
            owner: 'player',
            slotIdx: sIdx,
            skIdx: skIdx,
            charName: cardsDatabase[s.character] ? cardsDatabase[s.character].nombre : 'Personaje',
            text: `"${cardsDatabase[skId]?.nombre || skId}" (de ${cardsDatabase[s.character]?.nombre || 'Personaje'} - ${isPlayer ? 'Tú' : 'Jugador'})`
          });
        }
      });
    }
  });

  playtestState.opponentSlots.forEach((s, sIdx) => {
    if (s.character && s.skills) {
      s.skills.forEach((skId, skIdx) => {
        if (canRemoveSkillByEffect(skId, true, activatorOwner, s, 'grave', 'BBX-SP371', 'grave_skill', false)) {
          candidates.push({
            id: skId,
            owner: 'opponent',
            slotIdx: sIdx,
            skIdx: skIdx,
            charName: cardsDatabase[s.character] ? cardsDatabase[s.character].nombre : 'Personaje',
            text: `"${cardsDatabase[skId]?.nombre || skId}" (de ${cardsDatabase[s.character]?.nombre || 'Personaje'} - ${isPlayer ? 'Rival' : 'Tú'})`
          });
        }
      });
    }
  });

  if (candidates.length === 0) {
    const msg = "No hay Skills portadas elegibles en el campo para enviar al cementerio.";
    addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof alert === 'function') alert(msg);
    if (typeof onDone === 'function') onDone();
    return;
  }

  // Marcar efecto como usado este turno
  if (isPlayer) {
    playtestState.usedFlorete371ThisTurn = true;
    if (!playtestState.usedGlobalEffects) playtestState.usedGlobalEffects = [];
    playtestState.usedGlobalEffects.push('BBX-SP371');
  } else {
    playtestState.opponentUsedFlorete371ThisTurn = true;
    if (!playtestState.opponentUsedGlobalEffects) playtestState.opponentUsedGlobalEffects = [];
    playtestState.opponentUsedGlobalEffects.push('BBX-SP371');
  }

  if (typeof notifySkillInGraveEffectUsed === 'function') {
    notifySkillInGraveEffectUsed(activatorOwner);
  }

  // Como dice "puedes", enviar una Skill portada es opcional si el usuario decide omitir
  if (testOptions && testOptions.skipFieldSkillRemoval) {
    addLog(`${tag} Decidiste no enviar ninguna Skill portada al cementerio.`, 'var(--text-muted)');
    updatePlaytestView();
    if (typeof onDone === 'function') onDone();
    return;
  }

  const doSendFieldSkill = (chosenItem) => {
    const isOppTarget = chosenItem.owner !== activatorOwner;
    const targetSlot = chosenItem.owner === 'player' ? playtestState.slots[chosenItem.slotIdx] : playtestState.opponentSlots[chosenItem.slotIdx];
    let idx = chosenItem.skIdx;
    if (targetSlot.skills[idx] !== chosenItem.id) {
      idx = targetSlot.skills.indexOf(chosenItem.id);
    }
    if (idx === -1) {
      updatePlaytestView();
      if (typeof onDone === 'function') onDone();
      return;
    }

    const performSend = () => {
      const removedId = targetSlot.skills.splice(idx, 1)[0];
      const skillName = cardsDatabase[removedId] ? cardsDatabase[removedId].nombre : removedId;
      const targetGrave = chosenItem.owner === 'player' ? playtestState.grave : playtestState.opponentGrave;
      targetGrave.push(removedId);

      const targetOwnerDesc = chosenItem.owner === activatorOwner ? 'su propio cementerio' : (isPlayer ? 'el cementerio del rival' : 'tu cementerio');
      addLog(`${tag} Activó su efecto desde el cementerio y envió a ${targetOwnerDesc} la Skill <strong>${skillName}</strong> portada en <strong>${chosenItem.charName}</strong>.`, 'var(--accent-purple)');

      if (typeof onEquippedSkillSentToGraveByEffect === 'function') {
        onEquippedSkillSentToGraveByEffect(removedId, chosenItem.owner, activatorOwner);
      }

      if (typeof notifySkillsRemovedByEffect === 'function') {
        notifySkillsRemovedByEffect(1, 'grave', activatorOwner);
      }

      updatePlaytestView();
      if (typeof onDone === 'function') onDone();
    };

    if (isOppTarget && typeof checkAndProtectSendSkillsToGrave === 'function') {
      checkAndProtectSendSkillsToGrave(chosenItem.owner, () => {
        updatePlaytestView();
        if (typeof onDone === 'function') onDone();
      }, () => {
        performSend();
      }, 1);
    } else {
      performSend();
    }
  };

  if (testOptions && typeof testOptions.selectedFieldSkillIndex === 'number') {
    const chosen = candidates[testOptions.selectedFieldSkillIndex];
    if (chosen) {
      doSendFieldSkill(chosen);
      return;
    }
  } else if (testOptions && testOptions.selectedFieldSkillId) {
    const chosen = candidates.find(c => c.id === testOptions.selectedFieldSkillId);
    if (chosen) {
      doSendFieldSkill(chosen);
      return;
    }
  }

  if (!isPlayer) {
    // Modo Rival: prioriza enviar una Skill del jugador
    const playerSkill = candidates.find(c => c.owner === 'player');
    const chosen = playerSkill || candidates[0];
    doSendFieldSkill(chosen);
    return;
  }

  // Modo Jugador: selección visual directa de la Skill portada mediante el modal de cartas
  const chooserTargets = candidates.map(c => ({
    id: c.id,
    owner: c.owner,
    from: 'field',
    charName: c.charName,
    text: c.text
  }));

  const handleCancelFlorete = () => {
    if (isPlayer) {
      playtestState.usedFlorete371ThisTurn = false;
      if (playtestState.usedGlobalEffects) {
        const gIdx = playtestState.usedGlobalEffects.lastIndexOf('BBX-SP371');
        if (gIdx !== -1) playtestState.usedGlobalEffects.splice(gIdx, 1);
      }
    }
    addLog(`${tag} Cancelaste la selección de Skill portada.`, 'var(--text-muted)');
    updatePlaytestView();
    if (typeof onDone === 'function') onDone();
  };

  if (typeof openCardChooserModal === 'function') {
    openCardChooserModal(
      chooserTargets,
      "Florete (BBX-SP371): Selecciona 1 Skill portada para enviar al cementerio",
      (chosenIdx) => {
        doSendFieldSkill(candidates[chosenIdx]);
      },
      handleCancelFlorete
    );
  } else {
    doSendFieldSkill(candidates[0]);
  }
}

// Katherine (BBX-SP373): "Puedes enviar esta carta en tu mano al cementerio, entonces agrega a tu mano desde tu deck or cementerio 1 Skill \"Atender\", entonces puedes robar 1 carta de tu deck."
function executeKatherineSP373Activation(activatorOwner = 'player', handIndex = -1, testOptions = {}, onDone = null) {
  const isPlayer = activatorOwner === 'player';
  const hand = isPlayer ? playtestState.hand : playtestState.opponentHand;
  const deck = isPlayer ? playtestState.deck : playtestState.opponentDeck;
  const grave = isPlayer ? playtestState.grave : playtestState.opponentGrave;

  const cIdx = (handIndex >= 0 && hand[handIndex] === 'BBX-SP373')
    ? handIndex
    : hand.indexOf('BBX-SP373');

  if (cIdx === -1) {
    if (typeof onDone === 'function') onDone();
    return;
  }

  if (typeof isCharacterHandEffectBlocked === 'function' && isCharacterHandEffectBlocked(activatorOwner)) {
    addLog(`[Efecto Katherine BBX-SP373 ${isPlayer ? '' : 'Rival'}] No se puede activar: Efectos de Personajes en mano bloqueados.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone();
    return;
  }

  const isAtenderCard = id => id === 'BBX-SP262' || (cardsDatabase[id] && cardsDatabase[id].nombre === 'Atender');

  const deckAtenders = deck.map((id, idx) => ({ id, source: 'deck', originalIdx: idx })).filter(item => isAtenderCard(item.id));
  const graveAtenders = (typeof isGraveToHandBlocked === 'function' && isGraveToHandBlocked())
    ? []
    : grave.map((id, idx) => ({ id, source: 'grave', originalIdx: idx })).filter(item => isAtenderCard(item.id));

  if (deckAtenders.length === 0 && graveAtenders.length === 0) {
    addLog(`[Efecto Katherine BBX-SP373 ${isPlayer ? '' : 'Rival'}] No hay ninguna Skill "Atender" en ${isPlayer ? 'tu' : 'el'} deck ni cementerio para agregar a la mano.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone();
    return;
  }

  const tag = isPlayer ? '[Efecto Katherine BBX-SP373]' : '[Rival - Efecto Katherine BBX-SP373]';

  // Costo: enviar Katherine en tu mano al cementerio
  const discardedId = hand.splice(cIdx, 1)[0];
  grave.push(discardedId);
  addLog(`${tag} ${isPlayer ? 'Enviaste' : 'El rival envió'} a <strong>Katherine</strong> de su mano al cementerio como costo.`, 'var(--accent-purple)');

  checkAndTriggerAlBorde(discardedId);
  checkAndTriggerReflejo(discardedId);
  checkAndTriggerEstrategia(discardedId);
  checkAndTriggerHackeo(discardedId);
  checkAndTriggerLlamarada(discardedId);
  checkAndTriggerEspiral(discardedId);
  checkAndTriggerFirewall(discardedId);
  checkAndTriggerFervor(discardedId);
  checkAndTriggerApunteIgneo(discardedId);
  checkAndTriggerCrimenNocturno(discardedId);
  checkAndTriggerAlmacenamientoFallido(discardedId, 'hand');
  checkAndTriggerKatshi159(discardedId);
  checkAndTriggerFulgorOfensivo(discardedId);
  checkAndTriggerEspiralDigital(discardedId, 'hand');
  checkAndTriggerBolaDeFuego(discardedId, 'hand');
  checkAndTriggerKatshi205(discardedId);
  checkAndTriggerRemembranza(discardedId, activatorOwner);

  if (window.GraveEffects && typeof window.GraveEffects.dispatch === 'function') {
    window.GraveEffects.dispatch(discardedId, activatorOwner, { fromZone: 'hand' });
  }

  // Paso 2: Selección y adición de "Atender" a la mano
  const handleChosenAtender = (sourceZone) => {
    if (sourceZone === 'deck') {
      const dIdx = deck.findIndex(isAtenderCard);
      if (dIdx !== -1) {
        const chosenId = deck.splice(dIdx, 1)[0];
        hand.push(chosenId);
        // IMPORTANTE: Siempre que se extrae una carta del deck este se baraja inmediatamente:
        shuffleArray(deck);
        addLog(`${tag} ${isPlayer ? 'Agregaste' : 'El rival agregó'} a <strong>${cardsDatabase[chosenId]?.nombre || 'Atender'}</strong> a su mano desde el deck y barajó su mazo.`, 'var(--accent-purple)');
      }
    } else {
      const gIdx = grave.findIndex(isAtenderCard);
      if (gIdx !== -1) {
        const chosenId = grave.splice(gIdx, 1)[0];
        hand.push(chosenId);
        addLog(`${tag} ${isPlayer ? 'Recuperaste' : 'El rival recuperó'} a <strong>${cardsDatabase[chosenId]?.nombre || 'Atender'}</strong> a su mano desde el cementerio.`, 'var(--accent-purple)');
      }
    }

    if (typeof checkAndTriggerInestabilidad === 'function') {
      checkAndTriggerInestabilidad(activatorOwner);
    }
    updatePlaytestView();

    // Paso 3: Opción de robar 1 carta del deck ("entonces puedes robar 1 carta de tu deck")
    proceedToOptionalDraw();
  };

  const proceedToOptionalDraw = () => {
    const cannotDraw = (typeof isDrawByCharacterBlocked === 'function' && isDrawByCharacterBlocked(activatorOwner, 1)) ||
      (isPlayer ? !!playtestState.cannotDrawByEffectsThisTurn : !!playtestState.opponentCannotDrawByEffectsThisTurn);

    if (cannotDraw) {
      addLog(`${tag} No se puede robar cartas por efecto de Personaje este turno.`, 'var(--text-muted)');
      updatePlaytestView();
      if (typeof onDone === 'function') onDone();
      return;
    }

    if (deck.length === 0) {
      addLog(`${tag} No hay cartas en ${isPlayer ? 'tu' : 'el'} deck para robar.`, 'var(--text-muted)');
      updatePlaytestView();
      if (typeof onDone === 'function') onDone();
      return;
    }

    if (testOptions && testOptions.skipDraw) {
      addLog(`${tag} Decidiste no robar carta del deck.`, 'var(--text-muted)');
      updatePlaytestView();
      if (typeof onDone === 'function') onDone();
      return;
    }

    if (testOptions && testOptions.forceDraw) {
      const drawnId = deck.shift();
      hand.push(drawnId);
      addLog(`${tag} ${isPlayer ? 'Robaste' : 'El rival robó'} 1 carta de su deck: <strong>${cardsDatabase[drawnId]?.nombre || drawnId}</strong>.`, 'var(--accent-purple)');
      if (typeof checkAndTriggerServicioImpecable === 'function') {
        checkAndTriggerServicioImpecable(activatorOwner, 'character');
      }
      updatePlaytestView();
      if (typeof onDone === 'function') onDone();
      return;
    }

    if (!isPlayer) {
      // Rival roba automáticamente si está disponible
      const drawnId = deck.shift();
      hand.push(drawnId);
      addLog(`${tag} El rival robó 1 carta de su deck: <strong>${cardsDatabase[drawnId]?.nombre || drawnId}</strong>.`, 'var(--accent-purple)');
      if (typeof checkAndTriggerServicioImpecable === 'function') {
        checkAndTriggerServicioImpecable('opponent', 'character');
      }
      updatePlaytestView();
      if (typeof onDone === 'function') onDone();
      return;
    }

    // Para el jugador, preguntar si desea robar 1 carta
    const items = [
      {
        text: "🃏 Sí, robar 1 carta del deck",
        action: () => {
          if (deck.length > 0) {
            const drawnId = deck.shift();
            hand.push(drawnId);
            addLog(`${tag} Robaste 1 carta de tu deck: <strong>${cardsDatabase[drawnId]?.nombre || drawnId}</strong>.`, 'var(--accent-purple)');
            if (typeof checkAndTriggerServicioImpecable === 'function') {
              checkAndTriggerServicioImpecable('player', 'character');
            }
            updatePlaytestView();
          }
          if (typeof onDone === 'function') onDone();
        }
      },
      {
        text: "❌ No robar",
        action: () => {
          addLog(`${tag} Decidiste no robar carta del deck.`, 'var(--text-muted)');
          updatePlaytestView();
          if (typeof onDone === 'function') onDone();
        }
      }
    ];

    addLog(`[Trigger] Efecto Katherine: ¿Deseas robar 1 carta de tu deck?`, 'var(--accent-cyan)');
    const dummyEvent = {
      clientX: (typeof window !== 'undefined' ? window.innerWidth / 2 - 120 : 0),
      clientY: (typeof window !== 'undefined' ? window.innerHeight / 2 - 80 : 0)
    };
    if (typeof showContextMenu === 'function') {
      showContextMenu(dummyEvent, items);
    } else {
      items[0].action();
    }
  };

  // Resolución del Paso 2 (Elegir origen de "Atender")
  if (testOptions && testOptions.selectedSource) {
    handleChosenAtender(testOptions.selectedSource);
    return;
  }

  const hasDeck = deckAtenders.length > 0;
  const hasGrave = graveAtenders.length > 0;

  if (hasDeck && !hasGrave) {
    handleChosenAtender('deck');
  } else if (!hasDeck && hasGrave) {
    handleChosenAtender('grave');
  } else {
    // Ambos disponibles (Deck y Cementerio)
    if (isPlayer) {
      const chooseOptions = [
        {
          id: 'deck',
          text: `Skill "Atender" desde el Deck (${deckAtenders.length} disponible${deckAtenders.length > 1 ? 's' : ''})`
        },
        {
          id: 'grave',
          text: `Skill "Atender" desde el Cementerio (${graveAtenders.length} disponible${graveAtenders.length > 1 ? 's' : ''})`
        }
      ];

      if (typeof openCardChooserModal === 'function') {
        openCardChooserModal(chooseOptions, "Katherine: Selecciona desde dónde agregar \"Atender\"", (chosenIdx) => {
          handleChosenAtender(chooseOptions[chosenIdx].id);
        });
      } else {
        handleChosenAtender('deck');
      }
    } else {
      // Rival prefiere recuperar del cementerio para conservar deck, o deck si no
      handleChosenAtender('grave');
    }
  }
}

// Contener ira (BBX-SP374): "Si tu adversario controla 2 o más Personajes and el total de Skills portadas en su campo son de 4 o más, puedes enviar al cementerio 3 Skills portadas en el campo de tu adversario. Solo puedes usar este efecto de \"Contener ira\" una vez por turno."
function executeContenerIraSP374(activatorOwner = 'player', slotIndex, skIndex, testOptions = {}, onDone = null) {
  const isPlayer = activatorOwner === 'player';
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;
  const oppSlots = isPlayer ? playtestState.opponentSlots : playtestState.slots;
  const oppGrave = isPlayer ? playtestState.opponentGrave : playtestState.grave;
  const slot = slots[slotIndex];

  if (!slot || !slot.character) {
    if (typeof onDone === 'function') onDone();
    return;
  }

  const effectiveSkIndex = (typeof skIndex === 'number')
    ? skIndex
    : (slot.skills ? slot.skills.indexOf('BBX-SP374') : -1);

  const tag = isPlayer ? '[Efecto Contener ira BBX-SP374]' : '[Rival - Efecto Contener ira BBX-SP374]';

  // 1. Verificar HOPT
  const usedGlobal = isPlayer
    ? (playtestState.usedGlobalEffects || [])
    : (playtestState.opponentUsedGlobalEffects || []);

  if (usedGlobal.includes('Contener ira') || usedGlobal.includes('BBX-SP374')) {
    const msg = isPlayer
      ? "Solo puedes usar este efecto de 'Contener ira' una vez por turno."
      : "El rival ya usó el efecto de 'Contener ira' este turno.";
    if (typeof alert === 'function') alert(msg);
    if (typeof onDone === 'function') onDone();
    return;
  }

  // 2. Verificar condición de Personajes rivales (>= 2)
  const oppChars = oppSlots.filter(s => s.character).length;
  if (oppChars < 2) {
    const msg = isPlayer
      ? "El adversario debe controlar 2 o más Personajes en el campo."
      : "No controlas 2 o más Personajes en el campo.";
    if (typeof alert === 'function') alert(msg);
    if (typeof onDone === 'function') onDone();
    return;
  }

  // 3. Verificar total de Skills portadas en campo rival (>= 4)
  const oppTotalSkills = oppSlots.reduce((acc, s) => acc + (s.character && s.skills ? s.skills.length : 0), 0);
  if (oppTotalSkills < 4) {
    const msg = isPlayer
      ? "El total de Skills portadas en el campo del adversario debe ser de 4 o más."
      : "El total de Skills portadas en tu campo debe ser de 4 o más.";
    if (typeof alert === 'function') alert(msg);
    if (typeof onDone === 'function') onDone();
    return;
  }

  // 4. Recolectar Skills elegibles para enviar al cementerio
  const candidates = [];
  oppSlots.forEach((s, sIdx) => {
    if (s.character && s.skills) {
      const charName = cardsDatabase[s.character]?.nombre || `Slot ${sIdx + 1}`;
      s.skills.forEach((skId, skIdx) => {
        if (canRemoveSkillByEffect(skId, isPlayer, activatorOwner, s, 'grave')) {
          candidates.push({
            id: skId,
            owner: isPlayer ? 'opponent' : 'player',
            slotIdx: sIdx,
            skIdx: skIdx,
            charName: charName,
            name: cardsDatabase[skId]?.nombre || skId
          });
        }
      });
    }
  });

  if (candidates.length < 3) {
    const msg = isPlayer
      ? "El adversario no tiene suficientes Skills portadas elegibles para enviar al cementerio (se requieren al menos 3)."
      : "No tienes suficientes Skills portadas elegibles para que el rival las envíe al cementerio.";
    if (typeof alert === 'function') alert(msg);
    if (typeof onDone === 'function') onDone();
    return;
  }

  const markUsed = () => {
    if (isPlayer) {
      playtestState.usedGlobalEffects = playtestState.usedGlobalEffects || [];
      playtestState.usedGlobalEffects.push('Contener ira');
    } else {
      playtestState.opponentUsedGlobalEffects = playtestState.opponentUsedGlobalEffects || [];
      playtestState.opponentUsedGlobalEffects.push('Contener ira');
    }
    slot.usedSkills = slot.usedSkills || [];
    slot.usedSkills.push('BBX-SP374');
    if (effectiveSkIndex !== -1) {
      slot.usedSkillIndexes = slot.usedSkillIndexes || [];
      slot.usedSkillIndexes.push(effectiveSkIndex);
    }
  };

  const proceedWithSelectedSkills = (selectedSkills) => {
    const oppOwner = isPlayer ? 'opponent' : 'player';

    if (typeof checkAndProtectSendSkillsToGrave === 'function') {
      checkAndProtectSendSkillsToGrave(oppOwner, () => {
        // Interceptado / protegido por Lyna, Nara, etc.
        markUsed();
        updatePlaytestView();
        if (typeof onDone === 'function') onDone();
      }, () => {
        performSkillRemoval(selectedSkills);
      }, selectedSkills.length);
    } else {
      performSkillRemoval(selectedSkills);
    }
  };

  const performSkillRemoval = (selectedSkills) => {
    const bySlot = {};
    selectedSkills.forEach(item => {
      if (!bySlot[item.slotIdx]) bySlot[item.slotIdx] = [];
      bySlot[item.slotIdx].push(item.skIdx);
    });

    const removedNames = [];
    Object.keys(bySlot).forEach(sIdxStr => {
      const sIdx = parseInt(sIdxStr, 10);
      const targetSlot = oppSlots[sIdx];
      const indices = bySlot[sIdx].sort((a, b) => b - a);
      indices.forEach(idx => {
        const removedId = targetSlot.skills.splice(idx, 1)[0];
        oppGrave.push(removedId);
        removedNames.push(`"${cardsDatabase[removedId]?.nombre || removedId}"`);
        if (typeof onEquippedSkillSentToGraveByEffect === 'function') {
          onEquippedSkillSentToGraveByEffect(removedId, isPlayer ? 'opponent' : 'player', activatorOwner);
        }
        if (typeof checkAndTriggerRemembranza === 'function') {
          checkAndTriggerRemembranza(removedId, isPlayer ? 'opponent' : 'player');
        }
      });
    });

    addLog(`${tag} Se enviaron al cementerio 3 Skills portadas del campo de ${isPlayer ? 'tu adversario' : 'tu campo'}: ${removedNames.join(', ')}.`, 'var(--accent-purple)');

    markUsed();

    if (typeof notifySkillsRemovedByEffect === 'function') {
      notifySkillsRemovedByEffect(selectedSkills.length, 'grave', activatorOwner);
    }
    updatePlaytestView();
    if (typeof onDone === 'function') onDone();
  };

  // Selección de las 3 Skills
  if (testOptions && testOptions.selectedCandidateIndices) {
    const chosen = testOptions.selectedCandidateIndices.map(i => candidates[i]);
    proceedWithSelectedSkills(chosen);
    return;
  }

  if (candidates.length === 3) {
    proceedWithSelectedSkills(candidates);
  } else {
    if (!isPlayer) {
      // Modo rival: toma las 3 primeras candidatas automáticamente
      proceedWithSelectedSkills(candidates.slice(0, 3));
    } else {
      const chooserTargets = candidates.map(c => ({
        id: c.id,
        owner: 'opponent',
        text: `"${c.name}" (portada por ${c.charName})`
      }));
      if (typeof openMultiCardChooserModal === 'function') {
        openMultiCardChooserModal(chooserTargets, "Contener ira: Selecciona 3 Skills portadas del adversario para enviar al cementerio", 3, (chosenIndices) => {
          const chosen = chosenIndices.map(i => candidates[i]);
          proceedWithSelectedSkills(chosen);
        });
      } else {
        proceedWithSelectedSkills(candidates.slice(0, 3));
      }
    }
  }
}

// ¡Bomba Skill! (BBX-SP376): "Puedes enviar las 3 primeras cartas del tope del deck de tu adversario al cementerio y si lo haces agrega a tu mano desde tu deck o cementerio 1 Skill \"Explosión\". Solo puedes usar este efecto de \"¡Bomba Skill!\" una vez por turno."
function executeBombaSkillSP376(activatorOwner = 'player', slotIndex, skIndex, testOptions = {}, onDone = null) {
  const isPlayer = activatorOwner === 'player';
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;
  const oppSlots = isPlayer ? playtestState.opponentSlots : playtestState.slots;
  const oppDeck = isPlayer ? playtestState.opponentDeck : playtestState.deck;
  const oppGrave = isPlayer ? playtestState.opponentGrave : playtestState.grave;
  const myDeck = isPlayer ? playtestState.deck : playtestState.opponentDeck;
  const myGrave = isPlayer ? playtestState.grave : playtestState.opponentGrave;
  const myHand = isPlayer ? playtestState.hand : playtestState.opponentHand;
  const slot = slots[slotIndex];

  if (!slot || !slot.character) return;

  const effectiveSkIndex = typeof skIndex === 'number'
    ? skIndex
    : (slot.skills ? slot.skills.indexOf('BBX-SP376') : -1);

  const tag = isPlayer ? '[Efecto ¡Bomba Skill! BBX-SP376]' : '[Rival - Efecto ¡Bomba Skill! BBX-SP376]';

  // 1. Hard Once Per Turn (HOPT)
  const usedGlobal = isPlayer
    ? (playtestState.usedGlobalEffects || [])
    : (playtestState.opponentUsedGlobalEffects || []);

  if (usedGlobal.includes('¡Bomba Skill!') || usedGlobal.includes('BBX-SP376')) {
    if (isPlayer) alert("Solo puedes usar el efecto de '¡Bomba Skill!' una vez por turno (Límite Global).");
    else addLog(`${tag} Ya se utilizó el efecto de "¡Bomba Skill!" este turno.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone();
    return;
  }

  // 2. Comprobar si ya fue usada en este slot este turno
  const yaUsadoCard = (slot.usedSkills || []).includes('BBX-SP376');
  const yaUsadoIndex = effectiveSkIndex !== -1 && (slot.usedSkillIndexes || []).includes(effectiveSkIndex);
  if (yaUsadoCard || yaUsadoIndex) {
    if (isPlayer) alert("Esta copia de '¡Bomba Skill!' ya ha utilizado su efecto este turno.");
    else addLog(`${tag} Esta copia de "¡Bomba Skill!" ya ha sido usada este turno.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone();
    return;
  }

  // 3. Bloqueo de efectos de Skill
  if (typeof isSkillEffectBlocked === 'function' && isSkillEffectBlocked('BBX-SP376', activatorOwner, slot)) {
    if (isPlayer) alert("El efecto de esta Skill está bloqueado.");
    else addLog(`${tag} El efecto de esta Skill está bloqueado.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone();
    return;
  }

  // 4. Requisito: Adversario debe tener al menos 3 cartas en su deck
  if (oppDeck.length < 3) {
    if (isPlayer) alert("Requisito no cumplido: Tu adversario debe tener al menos 3 cartas en su deck.");
    else addLog(`${tag} El adversario no tiene al menos 3 cartas en su deck.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone();
    return;
  }

  // 5. Requisito: Debe existir al menos 1 copia de Explosión (BBX-SP318) en deck o cementerio
  const isExplosionSkill = (id) => id === 'BBX-SP318' || (cardsDatabase[id]?.nombre === 'Explosión' && cardsDatabase[id]?.tipo === 'Skill');
  const deckMatches = myDeck.filter(isExplosionSkill);
  const isGraveBlocked = typeof isGraveToHandBlocked === 'function' && isGraveToHandBlocked();
  const graveMatches = !isGraveBlocked ? myGrave.filter(isExplosionSkill) : [];

  if (deckMatches.length === 0 && graveMatches.length === 0) {
    const reasonMsg = isGraveBlocked
      ? "No tienes copias de 'Explosión' (BBX-SP318) en tu deck y los efectos para recuperar del cementerio están bloqueados."
      : "No tienes ninguna copia de 'Explosión' (BBX-SP318) en tu deck ni en tu cementerio.";
    if (isPlayer) alert(`Requisito no cumplido: ${reasonMsg}`);
    else addLog(`${tag} Requisito no cumplido: ${reasonMsg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone();
    return;
  }

  // Construir opciones de Explosión
  const choices = [];
  deckMatches.forEach(id => {
    choices.push({
      id: id,
      from: 'deck',
      owner: activatorOwner,
      text: `${cardsDatabase[id]?.nombre || 'Explosión'} (Deck)`
    });
  });
  graveMatches.forEach(id => {
    choices.push({
      id: id,
      from: 'grave',
      owner: activatorOwner,
      text: `${cardsDatabase[id]?.nombre || 'Explosión'} (Cementerio)`
    });
  });

  // Paso 1: Enviar las 3 primeras cartas del tope del deck del adversario al cementerio ("y si lo haces")
  const sentCardIds = oppDeck.splice(0, 3);
  const sentNames = [];
  sentCardIds.forEach(cId => {
    oppGrave.push(cId);
    sentNames.push(`"${cardsDatabase[cId]?.nombre || cId}"`);
    if (typeof dispatchGraveTriggers === 'function') {
      dispatchGraveTriggers(cId, isPlayer ? 'opponent' : 'player', { fromZone: 'deck', reasonOwner: activatorOwner });
    }
    if (typeof checkAndTriggerRemembranza === 'function') {
      checkAndTriggerRemembranza(cId, isPlayer ? 'opponent' : 'player');
    }
  });

  addLog(`${tag} Se enviaron las 3 cartas del tope del deck de ${isPlayer ? 'tu adversario' : 'tu deck'} al cementerio: ${sentNames.join(', ')}.`, isPlayer ? 'var(--accent-purple)' : 'var(--accent-danger)');

  // Paso 2: Agregar a tu mano desde tu deck o cementerio 1 Skill "Explosión"
  const resolveAddExplosion = (chosenChoice) => {
    if (chosenChoice.from === 'deck') {
      const dIdx = myDeck.indexOf(chosenChoice.id);
      if (dIdx !== -1) {
        myDeck.splice(dIdx, 1);
        myHand.push(chosenChoice.id);
      }
      // Regla oficial: Barajar inmediatamente al extraer del deck
      if (typeof shuffleArray === 'function') {
        shuffleArray(myDeck);
      }
      addLog(`${tag} Agregaste a ${isPlayer ? 'tu mano' : 'su mano'} <strong>${cardsDatabase[chosenChoice.id]?.nombre || 'Explosión'}</strong> desde tu deck y barajaste el mazo.`, isPlayer ? 'var(--accent-purple)' : 'var(--accent-danger)');
    } else {
      const gIdx = myGrave.indexOf(chosenChoice.id);
      if (gIdx !== -1) {
        myGrave.splice(gIdx, 1);
        myHand.push(chosenChoice.id);
      }
      addLog(`${tag} Agregaste a ${isPlayer ? 'tu mano' : 'su mano'} <strong>${cardsDatabase[chosenChoice.id]?.nombre || 'Explosión'}</strong> desde tu cementerio.`, isPlayer ? 'var(--accent-purple)' : 'var(--accent-danger)');
    }

    // Registrar HOPT
    if (isPlayer) {
      playtestState.usedGlobalEffects = playtestState.usedGlobalEffects || [];
      playtestState.usedGlobalEffects.push('¡Bomba Skill!');
    } else {
      playtestState.opponentUsedGlobalEffects = playtestState.opponentUsedGlobalEffects || [];
      playtestState.opponentUsedGlobalEffects.push('¡Bomba Skill!');
    }

    // Marcar slot como usado este turno
    slot.usedSkills = slot.usedSkills || [];
    slot.usedSkills.push('BBX-SP376');
    if (effectiveSkIndex !== -1) {
      slot.usedSkillIndexes = slot.usedSkillIndexes || [];
      slot.usedSkillIndexes.push(effectiveSkIndex);
    }

    // Disparar Inestabilidad por agregar carta a la mano
    if (typeof checkAndTriggerInestabilidad === 'function') {
      checkAndTriggerInestabilidad(activatorOwner);
    }

    if (typeof updatePlaytestView === 'function') {
      updatePlaytestView();
    }
    if (typeof onDone === 'function') {
      onDone();
    }
  };

  // Soporte de pruebas automatizadas
  if (testOptions && testOptions.chosenIndex !== undefined) {
    const idx = testOptions.chosenIndex;
    resolveAddExplosion(choices[idx] || choices[0]);
    return;
  }

  // Si solo hay 1 copia disponible, se agrega directamente
  if (choices.length === 1) {
    resolveAddExplosion(choices[0]);
  } else {
    if (!isPlayer) {
      // Modo rival: toma la primera opción disponible
      resolveAddExplosion(choices[0]);
    } else {
      if (typeof openCardChooserModal === 'function') {
        openCardChooserModal(choices, "¡Bomba Skill!: Selecciona 1 Skill 'Explosión' para agregar a tu mano", (chosenIdx) => {
          resolveAddExplosion(choices[chosenIdx] || choices[0]);
        });
      } else {
        resolveAddExplosion(choices[0]);
      }
    }
  }
}

// Serenidad (BBX-SP378): "Puedes barajar a tu deck 1 Skill en tu cementerio y si lo haces puedes agregar a tu mano desde tu deck 1 Personaje Marina. Solo puedes usar este efecto de \"Serenidad\" una vez por turno."
function executeSerenidadSP378(activatorOwner = 'player', slotIndex, skIndex, testOptions = {}, onDone = null) {
  const isPlayer = activatorOwner === 'player';
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;
  const myDeck = isPlayer ? playtestState.deck : playtestState.opponentDeck;
  const myGrave = isPlayer ? playtestState.grave : playtestState.opponentGrave;
  const myHand = isPlayer ? playtestState.hand : playtestState.opponentHand;
  const slot = slots ? slots[slotIndex] : null;

  if (!slot || !slot.character) {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const effectiveSkIndex = typeof skIndex === 'number'
    ? skIndex
    : (slot.skills ? slot.skills.indexOf('BBX-SP378') : -1);

  const tag = isPlayer ? '[Efecto Serenidad BBX-SP378]' : '[Rival - Efecto Serenidad BBX-SP378]';

  // 1. Hard Once Per Turn (HOPT)
  const usedGlobal = isPlayer
    ? (playtestState.usedGlobalEffects || [])
    : (playtestState.opponentUsedGlobalEffects || []);

  if (usedGlobal.includes('Serenidad') || usedGlobal.includes('BBX-SP378')) {
    if (isPlayer) alert("Solo puedes usar el efecto de 'Serenidad' una vez por turno (Límite Global).");
    else addLog(`${tag} Ya se utilizó el efecto de "Serenidad" este turno.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 2. Comprobar si ya fue usada en este slot este turno
  const yaUsadoCard = (slot.usedSkills || []).includes('BBX-SP378');
  const yaUsadoIndex = effectiveSkIndex !== -1 && (slot.usedSkillIndexes || []).includes(effectiveSkIndex);
  if (yaUsadoCard || yaUsadoIndex) {
    if (isPlayer) alert("Esta copia de 'Serenidad' ya ha utilizado su efecto este turno.");
    else addLog(`${tag} Esta copia de "Serenidad" ya ha sido usada este turno.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 3. Bloqueo de efectos de Skill
  if (typeof isSkillEffectBlocked === 'function' && isSkillEffectBlocked('BBX-SP378', activatorOwner, slot)) {
    if (isPlayer) alert("El efecto de esta Skill está bloqueado.");
    else addLog(`${tag} El efecto de esta Skill está bloqueado.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 4. Requisito 1: Debe haber al menos 1 Skill en el cementerio
  const skillsInGrave = [];
  myGrave.forEach((cId) => {
    const c = cardsDatabase[cId];
    if (c && c.tipo === 'Skill') {
      skillsInGrave.push(cId);
    }
  });

  if (skillsInGrave.length === 0) {
    const msg = "Requisito no cumplido: No tienes ninguna Skill en tu cementerio para barajar al deck.";
    if (isPlayer) alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 5. Requisito 2: Debe haber al menos 1 Personaje Marina en el deck
  const isMarinaChar = (id) => {
    const c = cardsDatabase[id];
    return c && c.tipo === 'Personaje' && (c.nombre === 'Marina' || (c.nombre && c.nombre.includes('Marina')));
  };

  const marinaInDeck = myDeck.filter(isMarinaChar);
  if (marinaInDeck.length === 0) {
    const msg = "Requisito no cumplido: No tienes ningún Personaje Marina en tu deck para agregar a la mano.";
    if (isPlayer) alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const finishActivation = () => {
    // Registrar HOPT
    if (isPlayer) {
      playtestState.usedGlobalEffects = playtestState.usedGlobalEffects || [];
      playtestState.usedGlobalEffects.push('Serenidad');
      playtestState.usedGlobalEffects.push('BBX-SP378');
    } else {
      playtestState.opponentUsedGlobalEffects = playtestState.opponentUsedGlobalEffects || [];
      playtestState.opponentUsedGlobalEffects.push('Serenidad');
      playtestState.opponentUsedGlobalEffects.push('BBX-SP378');
    }

    // Marcar slot y copia como usados este turno
    slot.usedSkills = slot.usedSkills || [];
    slot.usedSkills.push('BBX-SP378');
    if (effectiveSkIndex !== -1) {
      slot.usedSkillIndexes = slot.usedSkillIndexes || [];
      slot.usedSkillIndexes.push(effectiveSkIndex);
    }

    if (typeof updatePlaytestView === 'function') {
      updatePlaytestView();
    }
    if (typeof onDone === 'function') {
      onDone(true);
    }
  };

  // Función para resolver el Paso 2 tras barajar la Skill al mazo
  const resolveStep2 = () => {
    // Buscar Personajes Marina en el mazo (ahora que el mazo incluye la skill barajada)
    const availableMarinas = myDeck.filter(isMarinaChar);
    if (availableMarinas.length === 0) {
      addLog(`${tag} No hay Personajes Marina en el deck para agregar a la mano.`, 'var(--text-muted)');
      finishActivation();
      return;
    }

    // El paso 2 es opcional ("puedes agregar...")
    if (testOptions && testOptions.addToHand === false) {
      addLog(`${tag} Decidiste no agregar ningún Personaje Marina a tu mano.`, 'var(--text-muted)');
      finishActivation();
      return;
    }

    if (testOptions && testOptions.chosenDeckMarinaIndex !== undefined) {
      const chosenMarinaId = availableMarinas[testOptions.chosenDeckMarinaIndex] || availableMarinas[0];
      const dIdx = myDeck.indexOf(chosenMarinaId);
      if (dIdx !== -1) {
        myDeck.splice(dIdx, 1);
        myHand.push(chosenMarinaId);
        // Barajar mazo obligatoriamente al extraer carta
        if (typeof shuffleArray === 'function') {
          shuffleArray(myDeck);
        }
        addLog(`${tag} Agregaste a ${isPlayer ? 'tu mano' : 'su mano'} <strong>${cardsDatabase[chosenMarinaId]?.nombre || chosenMarinaId}</strong> desde el deck y barajaste el mazo.`, isPlayer ? 'var(--accent-purple)' : 'var(--accent-danger)');
        if (typeof checkAndTriggerInestabilidad === 'function') {
          checkAndTriggerInestabilidad(activatorOwner);
        }
      }
      finishActivation();
      return;
    }

    // Modo interactivo en navegador
    if (!isPlayer) {
      // Rival toma el primer Marina disponible
      const chosenMarinaId = availableMarinas[0];
      const dIdx = myDeck.indexOf(chosenMarinaId);
      if (dIdx !== -1) {
        myDeck.splice(dIdx, 1);
        myHand.push(chosenMarinaId);
        if (typeof shuffleArray === 'function') shuffleArray(myDeck);
        addLog(`${tag} El rival agregó <strong>${cardsDatabase[chosenMarinaId]?.nombre || chosenMarinaId}</strong> desde su deck a su mano y barajó el mazo.`, 'var(--accent-danger)');
        if (typeof checkAndTriggerInestabilidad === 'function') {
          checkAndTriggerInestabilidad(activatorOwner);
        }
      }
      finishActivation();
      return;
    }

    // Jugador interactivo: Preguntar si desea agregar Personaje Marina (opcional)
    const askItems = [
      {
        text: `🃏 Agregar Personaje Marina a tu mano (${availableMarinas.length} disponible${availableMarinas.length > 1 ? 's' : ''})`,
        action: () => {
          if (typeof openCardChooserModal === 'function') {
            openCardChooserModal(availableMarinas, "Serenidad: Selecciona 1 Personaje Marina de tu deck para agregar a tu mano", (chosenLocalIdx) => {
              const chosenMarinaId = availableMarinas[chosenLocalIdx] || availableMarinas[0];
              const dIdx = myDeck.indexOf(chosenMarinaId);
              if (dIdx !== -1) {
                myDeck.splice(dIdx, 1);
                myHand.push(chosenMarinaId);
                if (typeof shuffleArray === 'function') {
                  shuffleArray(myDeck);
                }
                addLog(`${tag} Agregaste a tu mano <strong>${cardsDatabase[chosenMarinaId]?.nombre || chosenMarinaId}</strong> desde tu deck y barajaste el mazo.`, 'var(--accent-purple)');
                if (typeof checkAndTriggerInestabilidad === 'function') {
                  checkAndTriggerInestabilidad(activatorOwner);
                }
              }
              finishActivation();
            });
          } else {
            const chosenMarinaId = availableMarinas[0];
            const dIdx = myDeck.indexOf(chosenMarinaId);
            if (dIdx !== -1) {
              myDeck.splice(dIdx, 1);
              myHand.push(chosenMarinaId);
              if (typeof shuffleArray === 'function') shuffleArray(myDeck);
              addLog(`${tag} Agregaste a tu mano <strong>${cardsDatabase[chosenMarinaId]?.nombre || chosenMarinaId}</strong> desde tu deck y barajaste el mazo.`, 'var(--accent-purple)');
              if (typeof checkAndTriggerInestabilidad === 'function') {
                checkAndTriggerInestabilidad(activatorOwner);
              }
            }
            finishActivation();
          }
        }
      },
      {
        text: `❌ No agregar Personaje Marina`,
        action: () => {
          addLog(`${tag} Decidiste no agregar ningún Personaje Marina a tu mano.`, 'var(--text-muted)');
          finishActivation();
        }
      }
    ];

    const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
    if (typeof showContextMenu === 'function') {
      showContextMenu(dummyEvent, askItems);
    } else {
      const chosenMarinaId = availableMarinas[0];
      const dIdx = myDeck.indexOf(chosenMarinaId);
      if (dIdx !== -1) {
        myDeck.splice(dIdx, 1);
        myHand.push(chosenMarinaId);
        if (typeof shuffleArray === 'function') shuffleArray(myDeck);
        addLog(`${tag} Agregaste a tu mano <strong>${cardsDatabase[chosenMarinaId]?.nombre || chosenMarinaId}</strong> desde tu deck y barajaste el mazo.`, 'var(--accent-purple)');
        if (typeof checkAndTriggerInestabilidad === 'function') {
          checkAndTriggerInestabilidad(activatorOwner);
        }
      }
      finishActivation();
    }
  };

  // Paso 1: Barajar a tu deck 1 Skill en tu cementerio
  const executeStep1 = (chosenSkillId) => {
    const gIdx = myGrave.indexOf(chosenSkillId);
    if (gIdx !== -1) {
      myGrave.splice(gIdx, 1);
      myDeck.push(chosenSkillId);
      // Barajar el deck obligatoriamente
      if (typeof shuffleArray === 'function') {
        shuffleArray(myDeck);
      }
      addLog(`${tag} Barajaste la Skill <strong>${cardsDatabase[chosenSkillId]?.nombre || chosenSkillId}</strong> de tu cementerio a tu deck.`, isPlayer ? 'var(--accent-purple)' : 'var(--accent-danger)');
      resolveStep2();
    } else {
      if (typeof onDone === 'function') onDone(false);
    }
  };

  // Selector para Paso 1
  if (testOptions && testOptions.chosenGraveSkillIndex !== undefined) {
    const chosenSkillId = skillsInGrave[testOptions.chosenGraveSkillIndex] || skillsInGrave[0];
    executeStep1(chosenSkillId);
    return;
  }

  if (skillsInGrave.length === 1) {
    executeStep1(skillsInGrave[0]);
  } else {
    if (!isPlayer) {
      executeStep1(skillsInGrave[0]);
    } else {
      if (typeof openCardChooserModal === 'function') {
        openCardChooserModal(skillsInGrave, "Serenidad: Selecciona 1 Skill de tu cementerio para barajar a tu deck", (chosenIdx) => {
          const chosenSkillId = skillsInGrave[chosenIdx] || skillsInGrave[0];
          executeStep1(chosenSkillId);
        });
      } else {
        executeStep1(skillsInGrave[0]);
      }
    }
  }
}

// Katshi (BBX-SP379): "[Requisito: 4 o más Skills] Una vez por turno, puedes barajar al deck 3 Skills portadas en esta carta y entonces baraja al deck 1 Personaje en la banca de cualquier jugador."
function executeKatshiSP379(slotIndex, activatorOwner = 'player', testOptions = {}, onDone = null) {
  const isPlayer = activatorOwner === 'player';
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;
  const myDeck = isPlayer ? playtestState.deck : playtestState.opponentDeck;
  const slot = slots ? slots[slotIndex] : null;

  if (!slot || slot.character !== 'BBX-SP379') {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const tag = isPlayer ? '[Efecto Katshi BBX-SP379]' : '[Rival - Efecto Katshi BBX-SP379]';

  // 1. Una vez por turno por copia/slot
  if (slot.effectUsed) {
    const msg = "Este efecto de personaje ya se usó este turno.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 2. Comprobar bloqueo de efecto de Personaje
  if (typeof isCharacterEffectBlocked === 'function' && isCharacterEffectBlocked(activatorOwner, slot)) {
    const msg = "El efecto de este personaje está bloqueado este turno.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // Bloqueo por Apertura en el cielo BBX-SP424 (impide barajar Personajes en banca)
  if (typeof isAperturaEnElCieloActive === 'function' && isAperturaEnElCieloActive()) {
    const msg = "No se puede activar el efecto: «Apertura en el cielo» impide barajar Personajes en la banca.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 3. Requisito: 4 o más Skills
  if (!slot.skills || slot.skills.length < 4) {
    const msg = "No se cumple el requisito: Katshi debe estar portando 4 o más Skills.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 4. Requisito: Debe haber al menos 1 Personaje en la banca de cualquier jugador
  const benchTargets = [];
  (playtestState.bench || []).forEach((item, bIdx) => {
    const charId = typeof item === 'object' && item !== null ? item.id : item;
    if (charId && cardsDatabase[charId]?.tipo === 'Personaje') {
      benchTargets.push({
        owner: 'player',
        benchIndex: bIdx,
        cardId: charId,
        nombre: cardsDatabase[charId]?.nombre || charId,
        text: `"${cardsDatabase[charId]?.nombre || charId}" (Banca de ${isPlayer ? 'tu campo' : 'Jugador'})`
      });
    }
  });

  (playtestState.opponentBench || []).forEach((item, bIdx) => {
    const charId = typeof item === 'object' && item !== null ? item.id : item;
    if (charId && cardsDatabase[charId]?.tipo === 'Personaje') {
      benchTargets.push({
        owner: 'opponent',
        benchIndex: bIdx,
        cardId: charId,
        nombre: cardsDatabase[charId]?.nombre || charId,
        text: `"${cardsDatabase[charId]?.nombre || charId}" (Banca de ${isPlayer ? 'tu adversario' : 'tu campo'})`
      });
    }
  });

  if (benchTargets.length === 0) {
    const msg = "Requisito no cumplido: No hay ningún Personaje en la banca de ningún jugador para barajar.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const executeBenchShuffle = (target) => {
    const targetBench = target.owner === 'player' ? playtestState.bench : playtestState.opponentBench;
    const targetDeck = target.owner === 'player' ? playtestState.deck : playtestState.opponentDeck;

    // Buscar y retirar el personaje de la banca
    let bIdx = targetBench.findIndex((item, i) => {
      const charId = typeof item === 'object' && item !== null ? item.id : item;
      return charId === target.cardId && (i === target.benchIndex || targetBench.length === 1);
    });

    if (bIdx === -1) {
      bIdx = targetBench.findIndex(item => {
        const charId = typeof item === 'object' && item !== null ? item.id : item;
        return charId === target.cardId;
      });
    }

    if (bIdx !== -1) {
      const removed = targetBench.splice(bIdx, 1)[0];
      const charId = typeof removed === 'object' && removed !== null ? removed.id : removed;
      targetDeck.push(charId);

      // Barajar obligatoriamente el deck de destino
      if (typeof shuffleArray === 'function') {
        shuffleArray(targetDeck);
      }

      addLog(`${tag} Barajaste a <strong>${cardsDatabase[charId]?.nombre || charId}</strong> de la banca de ${target.owner === 'player' ? (isPlayer ? 'tu campo' : 'Jugador') : (isPlayer ? 'tu adversario' : 'su propio campo')} a su deck y se barajó dicho deck.`, isPlayer ? 'var(--accent-purple)' : 'var(--accent-danger)');
    }

    slot.effectUsed = true;
    if (typeof updatePlaytestView === 'function') {
      updatePlaytestView();
    }
    if (typeof onDone === 'function') {
      onDone(true);
    }
  };

  // Función para resolver el paso 2: barajar 1 Personaje en la banca
  const proceedStep2 = () => {
    if (testOptions && testOptions.chosenBenchTargetIndex !== undefined) {
      const target = benchTargets[testOptions.chosenBenchTargetIndex] || benchTargets[0];
      executeBenchShuffle(target);
      return;
    }

    if (benchTargets.length === 1 || !isPlayer) {
      let chosenTarget = benchTargets[0];
      if (!isPlayer) {
        // La IA prefiere barajar un personaje de la banca del jugador si existe
        const playerTarget = benchTargets.find(t => t.owner === 'player');
        if (playerTarget) chosenTarget = playerTarget;
      }
      executeBenchShuffle(chosenTarget);
      return;
    }

    // Modo interactivo en navegador: mostrar selector para elegir 1 Personaje en la banca
    const chooserList = benchTargets.map(t => ({
      id: t.cardId,
      owner: t.owner,
      text: t.text
    }));

    if (typeof openCardChooserModal === 'function') {
      openCardChooserModal(chooserList, "Katshi: Selecciona 1 Personaje de la banca para barajar a su deck", (chosenIdx) => {
        executeBenchShuffle(benchTargets[chosenIdx] || benchTargets[0]);
      });
    } else {
      executeBenchShuffle(benchTargets[0]);
    }
  };

  // Paso 1: Barajar al deck 3 Skills portadas en esta carta
  const executeSkillShuffle = (chosenIndices) => {
    const sortedIndices = [...chosenIndices].sort((a, b) => b - a);
    const removedSkillNames = [];

    sortedIndices.forEach(idx => {
      if (idx >= 0 && idx < slot.skills.length) {
        const skId = slot.skills.splice(idx, 1)[0];
        myDeck.push(skId);
        removedSkillNames.push(cardsDatabase[skId]?.nombre || skId);
      }
    });

    // Barajar mazo obligatoriamente
    if (typeof shuffleArray === 'function') {
      shuffleArray(myDeck);
    }

    if (typeof notifySkillsRemovedByEffect === 'function') {
      notifySkillsRemovedByEffect(3, 'deck', activatorOwner);
    }

    addLog(`${tag} Barajaste a tu deck 3 Skills portadas (${removedSkillNames.join(', ')}) y se barajó el mazo.`, isPlayer ? 'var(--accent-purple)' : 'var(--accent-danger)');

    proceedStep2();
  };

  // Selección de 3 Skills portadas:
  if (testOptions && Array.isArray(testOptions.chosenSkillIndices) && testOptions.chosenSkillIndices.length === 3) {
    executeSkillShuffle(testOptions.chosenSkillIndices);
    return;
  }

  // Si tiene exactamente 4 Skills o más, en modo interactivo:
  if (!isPlayer) {
    executeSkillShuffle([0, 1, 2]);
    return;
  }

  const skillChoices = slot.skills.map((skId, idx) => ({
    id: skId,
    index: idx,
    text: `${cardsDatabase[skId]?.nombre || skId} (Skill #${idx + 1})`
  }));

  if (typeof openMultiCardChooserModal === 'function') {
    openMultiCardChooserModal(skillChoices, "Katshi: Selecciona 3 Skills portadas en esta carta para barajar a tu deck", 3, (chosenIndices) => {
      executeSkillShuffle(chosenIndices);
    });
  } else {
    executeSkillShuffle([0, 1, 2]);
  }
}

// Crepúsculo (BBX-SP380): "Puedes enviar esta Skill portada al cementerio, entonces recupera a tu mano 1 Personaje Eishet en tu banca. Solo puedes usar este efecto de \"Crepúsculo\" una vez por partida."
function executeCrepusculoSP380(activatorOwner = 'player', slotIndex, skIndex, testOptions = {}, onDone = null) {
  const isPlayer = activatorOwner === 'player';
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;
  const myGrave = isPlayer ? playtestState.grave : playtestState.opponentGrave;
  const myBench = isPlayer ? playtestState.bench : playtestState.opponentBench;
  const myHand = isPlayer ? playtestState.hand : playtestState.opponentHand;
  const slot = slots ? slots[slotIndex] : null;

  if (!slot || !slot.character) {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const effectiveSkIndex = typeof skIndex === 'number'
    ? skIndex
    : (slot.skills ? slot.skills.indexOf('BBX-SP380') : -1);

  if (effectiveSkIndex === -1 || !slot.skills || slot.skills[effectiveSkIndex] !== 'BBX-SP380') {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const tag = isPlayer ? '[Efecto Crepúsculo BBX-SP380]' : '[Rival - Efecto Crepúsculo BBX-SP380]';

  // 1. Hard Once Per Game (HOPG)
  const usedPerGame = isPlayer
    ? (playtestState.usedPerGameEffects || [])
    : (playtestState.opponentUsedPerGameEffects || []);

  const flagCheck = isPlayer ? playtestState.usedCrepusculo380ThisGame : playtestState.opponentUsedCrepusculo380ThisGame;

  if (flagCheck || usedPerGame.includes('Crepúsculo') || usedPerGame.includes('BBX-SP380')) {
    const msg = "Solo puedes usar el efecto de 'Crepúsculo' una vez por partida.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 2. Comprobar bloqueo de Skill
  if (typeof isSkillEffectBlocked === 'function' && isSkillEffectBlocked('BBX-SP380', activatorOwner, slot)) {
    const msg = "El efecto de esta Skill está bloqueado.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // Bloqueo por Apertura en el cielo BBX-SP424 (impide recuperar Personajes en banca)
  if (typeof isAperturaEnElCieloActive === 'function' && isAperturaEnElCieloActive()) {
    const msg = "No se puede activar el efecto: «Apertura en el cielo» impide recuperar Personajes en la banca.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 3. Requisito de objetivo: Al menos 1 Personaje Eishet en la banca del activador
  const isEishetChar = (item) => {
    const cId = typeof item === 'object' && item !== null ? item.id : item;
    const c = cardsDatabase[cId];
    return c && c.tipo === 'Personaje' && (c.nombre === 'Eishet' || (c.nombre && c.nombre.includes('Eishet')));
  };

  const eishetCandidates = [];
  myBench.forEach((item, bIdx) => {
    if (isEishetChar(item)) {
      const cId = typeof item === 'object' && item !== null ? item.id : item;
      eishetCandidates.push({
        benchIndex: bIdx,
        id: cId,
        nombre: cardsDatabase[cId]?.nombre || cId,
        text: `"${cardsDatabase[cId]?.nombre || cId}" (${cId})`
      });
    }
  });

  if (eishetCandidates.length === 0) {
    const msg = "Requisito no cumplido: No tienes ningún Personaje Eishet en tu banca para recuperar a la mano.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // Coste: Enviar esta Skill portada al cementerio
  slot.skills.splice(effectiveSkIndex, 1);
  myGrave.push('BBX-SP380');

  if (typeof dispatchGraveTriggers === 'function') {
    dispatchGraveTriggers('BBX-SP380', activatorOwner, { fromZone: 'field', isEquipped: true, byEffect: true });
  }
  if (typeof checkAndTriggerRemembranza === 'function') {
    checkAndTriggerRemembranza('BBX-SP380', activatorOwner);
  }
  if (typeof notifySkillsRemovedByEffect === 'function') {
    notifySkillsRemovedByEffect(1, 'grave', activatorOwner);
  }

  addLog(`${tag} Se envió la Skill <strong>Crepúsculo</strong> portada al cementerio como coste.`, isPlayer ? 'var(--accent-purple)' : 'var(--accent-danger)');

  // Registrar HOPG
  if (isPlayer) {
    playtestState.usedPerGameEffects = playtestState.usedPerGameEffects || [];
    playtestState.usedPerGameEffects.push('Crepúsculo');
    playtestState.usedPerGameEffects.push('BBX-SP380');
    playtestState.usedCrepusculo380ThisGame = true;
  } else {
    playtestState.opponentUsedPerGameEffects = playtestState.opponentUsedPerGameEffects || [];
    playtestState.opponentUsedPerGameEffects.push('Crepúsculo');
    playtestState.opponentUsedPerGameEffects.push('BBX-SP380');
    playtestState.opponentUsedCrepusculo380ThisGame = true;
  }

  // Efecto: Recuperar a tu mano 1 Personaje Eishet en tu banca
  const finishRecovery = (chosenCandidate) => {
    let actualIdx = myBench.findIndex((item, i) => {
      const cId = typeof item === 'object' && item !== null ? item.id : item;
      return cId === chosenCandidate.id && (i === chosenCandidate.benchIndex || eishetCandidates.length === 1);
    });

    if (actualIdx === -1) {
      actualIdx = myBench.findIndex(item => {
        const cId = typeof item === 'object' && item !== null ? item.id : item;
        return cId === chosenCandidate.id;
      });
    }

    if (actualIdx !== -1) {
      const removedItem = myBench.splice(actualIdx, 1)[0];
      const charId = typeof removedItem === 'object' && removedItem !== null ? removedItem.id : removedItem;
      myHand.push(charId);

      addLog(`${tag} Recuperaste a <strong>${cardsDatabase[charId]?.nombre || charId}</strong> de tu banca a tu mano.`, isPlayer ? 'var(--accent-purple)' : 'var(--accent-danger)');

      if (typeof checkAndTriggerInestabilidad === 'function') {
        checkAndTriggerInestabilidad(activatorOwner);
      }
    }

    if (typeof updatePlaytestView === 'function') {
      updatePlaytestView();
    }
    if (typeof onDone === 'function') {
      onDone(true);
    }
  };

  // Soporte para pruebas automatizadas
  if (testOptions && testOptions.chosenBenchEishetIndex !== undefined) {
    const candidate = eishetCandidates[testOptions.chosenBenchEishetIndex] || eishetCandidates[0];
    finishRecovery(candidate);
    return;
  }

  if (eishetCandidates.length === 1 || !isPlayer) {
    finishRecovery(eishetCandidates[0]);
    return;
  }

  // Interactivo con más de 1 Eishet en banca
  if (typeof openCardChooserModal === 'function') {
    const chooserList = eishetCandidates.map(c => ({
      id: c.id,
      text: c.text
    }));
    openCardChooserModal(chooserList, "Crepúsculo: Selecciona 1 Personaje Eishet de tu banca para recuperar a tu mano", (chosenIdx) => {
      finishRecovery(eishetCandidates[chosenIdx] || eishetCandidates[0]);
    });
  } else {
    finishRecovery(eishetCandidates[0]);
  }
}

// Corriente de pánico (BBX-SP381): "Si tu adversario controla 3 Personajes, puedes barajar al deck hasta 3 Skills portadas en su campo. Solo puedes usar este efecto de \"Corriente de pánico\" una vez por turno."
function executeCorrienteDePanicoSP381(activatorOwner = 'player', slotIndex, skIndex, testOptions = {}, onDone = null) {
  const isPlayer = activatorOwner === 'player';
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;
  const oppSlots = isPlayer ? playtestState.opponentSlots : playtestState.slots;
  const oppDeck = isPlayer ? playtestState.opponentDeck : playtestState.deck;
  const slot = slots ? slots[slotIndex] : null;

  if (!slot || !slot.character) {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const effectiveSkIndex = typeof skIndex === 'number'
    ? skIndex
    : (slot.skills ? slot.skills.indexOf('BBX-SP381') : -1);

  if (effectiveSkIndex === -1 || !slot.skills || slot.skills[effectiveSkIndex] !== 'BBX-SP381') {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const tag = isPlayer ? '[Efecto Corriente de pánico BBX-SP381]' : '[Rival - Efecto Corriente de pánico BBX-SP381]';

  // 1. Hard Once Per Turn (HOPT)
  const usedGlobal = isPlayer
    ? (playtestState.usedGlobalEffects || [])
    : (playtestState.opponentUsedGlobalEffects || []);

  if (usedGlobal.includes('Corriente de pánico') || usedGlobal.includes('BBX-SP381')) {
    const msg = "Solo puedes usar el efecto de 'Corriente de pánico' una vez por turno.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 2. Comprobar bloqueo de Skill
  if (typeof isSkillEffectBlocked === 'function' && isSkillEffectBlocked('BBX-SP381', activatorOwner, slot)) {
    const msg = "El efecto de esta Skill está bloqueado.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 3. Requisito: "Si tu adversario controla 3 Personajes"
  const oppCharsCount = oppSlots.filter(s => s && s.character).length;
  if (oppCharsCount < 3) {
    const msg = "Requisito no cumplido: Tu adversario debe controlar 3 Personajes en su campo.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 4. Objetivos elegibles: Skills portadas en el campo del adversario
  const targetable = [];
  oppSlots.forEach((s, sIdx) => {
    if (s && s.character && Array.isArray(s.skills)) {
      s.skills.forEach((sk, kIdx) => {
        if (typeof canRemoveSkillByEffect === 'function' && !canRemoveSkillByEffect(sk, !isPlayer, activatorOwner, s, 'deck')) {
          return;
        }
        targetable.push({
          slotIndex: sIdx,
          skillIndex: kIdx,
          id: sk,
          cardId: sk,
          charName: s.character.nombre || (cardsDatabase[s.character.id || s.character]?.nombre) || 'Personaje',
          skillName: cardsDatabase[sk]?.nombre || sk,
          owner: isPlayer ? 'opponent' : 'player',
          slotRef: s
        });
      });
    }
  });

  if (targetable.length === 0) {
    const msg = "No hay Skills portadas en el campo del adversario que puedan ser barajadas al deck.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const markHOPT = () => {
    if (isPlayer) {
      playtestState.usedGlobalEffects = playtestState.usedGlobalEffects || [];
      playtestState.usedGlobalEffects.push('Corriente de pánico');
      playtestState.usedGlobalEffects.push('BBX-SP381');
      slot.usedSkills = slot.usedSkills || [];
      if (!slot.usedSkills.includes('BBX-SP381')) slot.usedSkills.push('BBX-SP381');
      slot.usedSkillIndexes = slot.usedSkillIndexes || [];
      if (!slot.usedSkillIndexes.includes(effectiveSkIndex)) slot.usedSkillIndexes.push(effectiveSkIndex);
    } else {
      playtestState.opponentUsedGlobalEffects = playtestState.opponentUsedGlobalEffects || [];
      playtestState.opponentUsedGlobalEffects.push('Corriente de pánico');
      playtestState.opponentUsedGlobalEffects.push('BBX-SP381');
      slot.usedSkills = slot.usedSkills || [];
      if (!slot.usedSkills.includes('BBX-SP381')) slot.usedSkills.push('BBX-SP381');
      slot.usedSkillIndexes = slot.usedSkillIndexes || [];
      if (!slot.usedSkillIndexes.includes(effectiveSkIndex)) slot.usedSkillIndexes.push(effectiveSkIndex);
    }
  };

  const proceedWithSelection = (selectedItems) => {
    if (!selectedItems || selectedItems.length === 0) {
      if (typeof onDone === 'function') onDone(false);
      return;
    }

    const targetOwner = isPlayer ? 'opponent' : 'player';

    const onProtected = () => {
      markHOPT();
      addLog(`${tag} El efecto de barajar Skills a deck fue protegido/cancelado por un efecto defensivo.`, 'var(--text-muted)');
      if (typeof updatePlaytestView === 'function') updatePlaytestView();
      if (typeof onDone === 'function') onDone(true);
    };

    const onProceed = () => {
      markHOPT();

      const removalsBySlot = {};
      selectedItems.forEach(item => {
        if (!removalsBySlot[item.slotIndex]) removalsBySlot[item.slotIndex] = [];
        removalsBySlot[item.slotIndex].push(item.skillIndex);
      });

      const logs = [];
      let countShuffled = 0;

      Object.keys(removalsBySlot).forEach(sIdxStr => {
        const sIdx = parseInt(sIdxStr, 10);
        const indices = removalsBySlot[sIdx].sort((a, b) => b - a);
        const targetSlot = oppSlots[sIdx];
        indices.forEach(skIdx => {
          if (targetSlot && Array.isArray(targetSlot.skills) && skIdx < targetSlot.skills.length) {
            const removedId = targetSlot.skills.splice(skIdx, 1)[0];
            oppDeck.push(removedId);
            countShuffled++;
            logs.push(`"${cardsDatabase[removedId]?.nombre || removedId}"`);
          }
        });
      });

      if (typeof shuffleArray === 'function') {
        shuffleArray(oppDeck);
      }

      addLog(`${tag} ${isPlayer ? 'Barajaste' : 'El rival barajó'} al deck ${countShuffled} Skill(s) portada(s) en el campo: ${logs.join(', ')}.`, isPlayer ? 'var(--accent-purple)' : 'var(--accent-danger)');

      if (typeof notifySkillsRemovedByEffect === 'function') {
        notifySkillsRemovedByEffect(countShuffled, 'deck', activatorOwner);
      }

      if (typeof updatePlaytestView === 'function') {
        updatePlaytestView();
      }
      if (typeof onDone === 'function') {
        onDone(true);
      }
    };

    if (typeof checkAndProtectShuffleSkillByRyuChan === 'function') {
      checkAndProtectShuffleSkillByRyuChan(targetOwner, onProtected, onProceed, selectedItems.length);
    } else {
      onProceed();
    }
  };

  // Modo testing / opciones predefinidas
  if (testOptions && Array.isArray(testOptions.chosenTargets)) {
    const selected = testOptions.chosenTargets.map(idx => targetable[idx]).filter(Boolean);
    proceedWithSelection(selected.slice(0, 3));
    return;
  }

  if (testOptions && typeof testOptions.chosenTargetCount === 'number') {
    const count = Math.min(3, Math.max(1, testOptions.chosenTargetCount));
    proceedWithSelection(targetable.slice(0, count));
    return;
  }

  // Si no es el jugador o si sólo hay 1 objetivo y no se usa modal interactivo
  if (!isPlayer) {
    proceedWithSelection(targetable.slice(0, Math.min(3, targetable.length)));
    return;
  }

  // Interfaz de usuario para el jugador
  if (typeof openUpToCardChooserModal === 'function') {
    const chooserTargets = targetable.map(item => ({
      id: item.id,
      owner: 'opponent',
      text: `"${item.skillName}" en ${item.charName}`
    }));
    openUpToCardChooserModal(chooserTargets, "Corriente de pánico: Selecciona hasta 3 Skills portadas del adversario para barajar a su deck", Math.min(3, targetable.length), (chosenIndices) => {
      const selectedItems = chosenIndices.map(idx => targetable[idx]);
      proceedWithSelection(selectedItems);
    });
  } else {
    proceedWithSelection(targetable.slice(0, Math.min(3, targetable.length)));
  }
}

// Modal para declarar 1 nombre de Personaje (con buscador e imagen ampliada)
function openCharacterDeclarationModal(title, onSelect, onCancel) {
  if (typeof document === 'undefined' || !document.createElement) {
    if (typeof onSelect === 'function') onSelect('Kael');
    return;
  }

  const allUniqueChars = Object.values(cardsDatabase)
    .filter(c => c && c.tipo === 'Personaje' && c.nombre)
    .sort((a, b) => a.nombre.localeCompare(b.nombre));

  const uniqueChars = [];
  const seenNames = new Set();
  allUniqueChars.forEach(c => {
    if (!seenNames.has(c.nombre)) {
      seenNames.add(c.nombre);
      uniqueChars.push(c);
    }
  });

  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay';
  overlay.style.zIndex = '6500';
  overlay.style.display = 'flex';
  overlay.style.alignItems = 'center';
  overlay.style.justifyContent = 'center';

  overlay.innerHTML = `
    <div class="modal-content glass-panel" style="width: 580px; max-width: 95vw; height: 80vh; max-height: 680px; display: flex; flex-direction: column; padding: 18px; position: relative;">
      <div class="modal-header" style="display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 12px; margin-bottom: 12px;">
        <h3 style="margin: 0; font-size: 1.15rem; color: var(--accent-cyan);">${title}</h3>
        <button id="btn-close-char-declaration" class="btn-secondary" style="padding: 4px 10px; font-size: 0.85rem; cursor: pointer;">✕ Cerrar</button>
      </div>
      <div style="margin-bottom: 8px;">
        <input type="text" id="char-declaration-search-input" placeholder="🔍 Buscar Personaje por nombre..." style="width: 100%; box-sizing: border-box; padding: 9px 14px; border-radius: 6px; border: 1px solid rgba(0, 242, 254, 0.4); background: rgba(10, 15, 30, 0.7); color: #fff; font-size: 0.95rem; outline: none;">
      </div>
      <div style="font-size: 0.8rem; color: var(--accent-cyan); margin-bottom: 10px; opacity: 0.9;">
        💡 Pasa el cursor sobre la miniatura para verla ampliada. Haz clic en la fila para declarar ese Personaje.
      </div>
      <div id="char-declaration-list" style="flex: 1; overflow-y: auto; display: flex; flex-direction: column; gap: 6px; padding-right: 4px;">
      </div>
    </div>
    <div id="char-declaration-hover-preview" style="display: none; position: fixed; width: 260px; height: 364px; z-index: 7000; pointer-events: none; border-radius: 8px; overflow: hidden; box-shadow: 0 12px 36px rgba(0,0,0,0.92); border: 2px solid var(--accent-cyan); background: #000;">
      <img id="char-declaration-preview-img" src="" style="width: 100%; height: 100%; object-fit: contain;">
    </div>
  `;

  document.body.appendChild(overlay);

  const searchInput = overlay.querySelector('#char-declaration-search-input');
  const listContainer = overlay.querySelector('#char-declaration-list');
  const closeBtn = overlay.querySelector('#btn-close-char-declaration');
  const hoverPreview = overlay.querySelector('#char-declaration-hover-preview');
  const previewImg = overlay.querySelector('#char-declaration-preview-img');

  const closeModal = () => {
    if (hoverPreview) hoverPreview.style.display = 'none';
    if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
  };

  if (closeBtn) {
    closeBtn.addEventListener('click', () => {
      closeModal();
      if (typeof onCancel === 'function') onCancel();
    });
  }

  if (!listContainer) {
    if (typeof onSelect === 'function') onSelect('Haruka');
    return;
  }

  const renderList = (filterText = '') => {
    listContainer.innerHTML = '';
    const cleanFilter = filterText.trim().toLowerCase();
    const filtered = uniqueChars.filter(c => c.nombre.toLowerCase().includes(cleanFilter));

    if (filtered.length === 0) {
      listContainer.innerHTML = `<div style="text-align: center; color: var(--text-muted); padding: 30px 0;">No se encontraron Personajes que coincidan.</div>`;
      return;
    }

    filtered.forEach(c => {
      const row = document.createElement('div');
      row.className = 'declaration-item-row';
      row.style.display = 'flex';
      row.style.alignItems = 'center';
      row.style.justifyContent = 'space-between';
      row.style.padding = '8px 12px';
      row.style.borderRadius = '6px';
      row.style.background = 'rgba(255, 255, 255, 0.04)';
      row.style.border = '1px solid rgba(255, 255, 255, 0.08)';
      row.style.cursor = 'pointer';
      row.style.transition = 'all 0.15s ease';

      row.innerHTML = `
        <div style="display: flex; align-items: center; gap: 12px; flex: 1;">
          <div class="thumb-container" style="position: relative; width: 44px; height: 62px; flex-shrink: 0; border-radius: 4px; overflow: hidden; border: 1px solid rgba(255,255,255,0.25); cursor: zoom-in; background: #111; transition: transform 0.15s ease, border-color 0.15s ease;">
            <img src="/imagenes/${c.imagen}" alt="${c.nombre}" style="width: 100%; height: 100%; object-fit: cover;">
          </div>
          <div style="display: flex; flex-direction: column;">
            <span style="font-weight: bold; color: #fff; font-size: 0.95rem;">${c.nombre}</span>
            <span style="font-size: 0.75rem; color: var(--text-muted);">${c.clase ? `Clase: ${c.clase}` : 'Personaje'}</span>
          </div>
        </div>
        <button class="btn-primary btn-select-char" style="padding: 5px 12px; font-size: 0.8rem; pointer-events: none;">Declarar</button>
      `;

      row.addEventListener('mouseenter', () => {
        row.style.background = 'rgba(0, 242, 254, 0.12)';
        row.style.borderColor = 'var(--accent-cyan)';
      });
      row.addEventListener('mouseleave', () => {
        row.style.background = 'rgba(255, 255, 255, 0.04)';
        row.style.borderColor = 'rgba(255, 255, 255, 0.08)';
      });

      const thumbEl = row.querySelector('.thumb-container');
      if (thumbEl) {
        thumbEl.addEventListener('mouseenter', () => {
          thumbEl.style.borderColor = 'var(--accent-cyan)';
          thumbEl.style.transform = 'scale(1.08)';
          if (hoverPreview && previewImg) {
            previewImg.src = `/imagenes/${c.imagen}`;
            hoverPreview.style.display = 'block';
            const rect = thumbEl.getBoundingClientRect();
            let topPos = rect.top - 100;
            if (topPos < 10) topPos = 10;
            if (topPos + 370 > window.innerHeight) topPos = window.innerHeight - 380;
            hoverPreview.style.top = `${topPos}px`;
            hoverPreview.style.left = `${rect.right + 14}px`;
          }
        });
        thumbEl.addEventListener('mouseleave', () => {
          thumbEl.style.borderColor = 'rgba(255,255,255,0.25)';
          thumbEl.style.transform = 'scale(1)';
          if (hoverPreview) hoverPreview.style.display = 'none';
        });
      }

      row.addEventListener('click', () => {
        closeModal();
        if (typeof onSelect === 'function') onSelect(c.nombre, c);
      });

      listContainer.appendChild(row);
    });
  };

  renderList();
  if (searchInput) {
    searchInput.focus();
    searchInput.addEventListener('input', (e) => renderList(e.target.value));
  }
}

// Dardos Skill (BBX-SP382): "Una vez por turno, puedes declarar 1 nombre de Personaje; tu adversario revela la carta del tope de su deck, y si era 1 Personaje del nombre declarado, envíalo al cementerio y roba 2 cartas de tu deck, de lo contrario, tu adversario debe agregar esa carta a su mano."
function executeDardosSkillSP382(activatorOwner = 'player', slotIndex, skIndex, testOptions = {}, onDone = null) {
  const isPlayer = activatorOwner === 'player';
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;
  const oppDeck = isPlayer ? playtestState.opponentDeck : playtestState.deck;
  const oppGrave = isPlayer ? playtestState.opponentGrave : playtestState.grave;
  const oppHand = isPlayer ? playtestState.opponentHand : playtestState.hand;
  const slot = slots ? slots[slotIndex] : null;

  if (!slot || !slot.character) {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const effectiveSkIndex = typeof skIndex === 'number'
    ? skIndex
    : (slot.skills ? slot.skills.indexOf('BBX-SP382') : -1);

  if (effectiveSkIndex === -1 || !slot.skills || slot.skills[effectiveSkIndex] !== 'BBX-SP382') {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const tag = isPlayer ? '[Efecto Dardos Skill BBX-SP382]' : '[Rival - Efecto Dardos Skill BBX-SP382]';

  // 1. Una vez por turno (SOPT por copia / slot)
  const yaUsadoCard = (slot.usedSkills || []).includes('BBX-SP382');
  const yaUsadoIndex = effectiveSkIndex !== -1 && (slot.usedSkillIndexes || []).includes(effectiveSkIndex);
  if (yaUsadoCard || yaUsadoIndex) {
    const msg = "Ya has usado el efecto de esta copia de 'Dardos Skill' este turno.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 2. Comprobar bloqueo de Skill
  if (typeof isSkillEffectBlocked === 'function' && isSkillEffectBlocked('BBX-SP382', activatorOwner, slot)) {
    const msg = "El efecto de esta Skill está bloqueado.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 3. Requisito de deck rival: Debe haber al menos 1 carta
  if (!oppDeck || oppDeck.length === 0) {
    const msg = "Requisito no cumplido: Tu adversario no tiene cartas en su deck para revelar.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const proceedWithDeclaredName = (declaredName) => {
    if (!declaredName) {
      if (typeof onDone === 'function') onDone(false);
      return;
    }

    // Marcar como usada este turno
    slot.usedSkills = slot.usedSkills || [];
    if (!slot.usedSkills.includes('BBX-SP382')) slot.usedSkills.push('BBX-SP382');
    slot.usedSkillIndexes = slot.usedSkillIndexes || [];
    if (effectiveSkIndex !== -1 && !slot.usedSkillIndexes.includes(effectiveSkIndex)) {
      slot.usedSkillIndexes.push(effectiveSkIndex);
    }

    const topCardId = oppDeck[0];
    const topCard = cardsDatabase[topCardId] || { nombre: topCardId, tipo: 'Desconocido' };

    addLog(`${tag} Declaraste: <strong>${declaredName}</strong>. Revelando la carta del tope del deck del adversario...`, isPlayer ? 'var(--accent-cyan)' : 'var(--accent-danger)');

    const resolveOutcome = () => {
      // Comparar: "¿era 1 Personaje del nombre declarado?"
      const isChar = topCard.tipo === 'Personaje';
      const nameMatches = (topCard.nombre || '').trim().toLowerCase() === declaredName.trim().toLowerCase();
      const isHit = isChar && nameMatches;

      if (isHit) {
        // Acierto: envíalo al cementerio y roba 2 cartas de tu deck
        const removedId = oppDeck.shift();
        oppGrave.push(removedId);

        addLog(`${tag} ¡Acierto! La carta revelada es <strong>${topCard.nombre}</strong> (Personaje). Fue enviada al cementerio del adversario. Robas 2 cartas de tu deck.`, isPlayer ? 'var(--accent-purple)' : 'var(--accent-danger)');

        if (typeof dispatchGraveTriggers === 'function') {
          dispatchGraveTriggers(removedId, isPlayer ? 'opponent' : 'player', { fromZone: 'deck', byEffect: true });
        }
        if (typeof checkAndTriggerRemembranza === 'function') {
          checkAndTriggerRemembranza(removedId, isPlayer ? 'opponent' : 'player');
        }

        // Robar 2 cartas
        if (isPlayer) {
          if (typeof drawCard === 'function') {
            drawCard('skill');
            drawCard('skill');
          }
        } else {
          if (typeof drawOpponentCard === 'function') {
            drawOpponentCard('skill');
            drawOpponentCard('skill');
          }
        }
      } else {
        // Fallo: de lo contrario, tu adversario debe agregar esa carta a su mano
        const removedId = oppDeck.shift();
        oppHand.push(removedId);

        addLog(`${tag} No coincidió. La carta revelada es <strong>${topCard.nombre}</strong> (${topCard.tipo || 'Carta'}). Tu adversario la agrega a su mano.`, 'var(--accent-warning)');
      }

      if (typeof updatePlaytestView === 'function') {
        updatePlaytestView();
      }
      if (typeof onDone === 'function') {
        onDone(true, { hit: isHit, revealedCardId: topCardId, declaredName });
      }
    };

    // Animación / visualización si está disponible
    if (typeof revealCardsSequentially === 'function' && typeof document !== 'undefined' && document.getElementById && document.getElementById('reveal-modal')) {
      revealCardsSequentially([topCardId], `${isPlayer ? 'Carta revelada del rival' : 'Carta revelada'} (Dardos Skill)`, () => {
        resolveOutcome();
      });
    } else {
      resolveOutcome();
    }
  };

  // Modo testing / opciones predefinidas
  if (testOptions && testOptions.declaredName) {
    proceedWithDeclaredName(testOptions.declaredName);
    return;
  }

  // Si es activado por la IA / Rival
  if (!isPlayer) {
    const defaultAIChars = ['Kael', 'Roy', 'Chiako', 'Marina', 'Nobuko', 'Haruka', 'Eishet', 'Sophia', 'Helica', 'Ryu-chan', 'Tagero', 'Deida', 'Nara'];
    const chosenName = defaultAIChars[Math.floor(Math.random() * defaultAIChars.length)];
    proceedWithDeclaredName(chosenName);
    return;
  }

  // Interactivo para el Jugador: abrir modal de declaración de Personaje
  if (typeof openCharacterDeclarationModal === 'function') {
    openCharacterDeclarationModal("Dardos Skill: Declara 1 nombre de Personaje", (name) => {
      proceedWithDeclaredName(name);
    }, () => {
      if (typeof onDone === 'function') onDone(false);
    });
  } else {
    const promptName = typeof prompt === 'function' ? prompt("Declara 1 nombre de Personaje para Dardos Skill:", "Kael") : "Kael";
    if (promptName) {
      proceedWithDeclaredName(promptName);
    } else {
      if (typeof onDone === 'function') onDone(false);
    }
  }
}

// Torbellino siniestro (BBX-SP383): "Puedes enviar esta Skill portada al cementerio, entonces devuelve a la mano 1 Skill portada en el campo de tu adversario y si lo haces envía 1 carta al azar de la mano de tu adversario al cementerio. Solo puedes usar este efecto de \"Torbellino siniestro\" una vez por turno."
function executeTorbellinoSiniestroSP383(activatorOwner = 'player', slotIndex, skIndex, testOptions = {}, onDone = null) {
  const isPlayer = activatorOwner === 'player';
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;
  const oppSlots = isPlayer ? playtestState.opponentSlots : playtestState.slots;
  const myGrave = isPlayer ? playtestState.grave : playtestState.opponentGrave;
  const oppHand = isPlayer ? playtestState.opponentHand : playtestState.hand;
  const oppGrave = isPlayer ? playtestState.opponentGrave : playtestState.grave;
  const slot = slots ? slots[slotIndex] : null;

  if (!slot || !slot.character) {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const effectiveSkIndex = typeof skIndex === 'number'
    ? skIndex
    : (slot.skills ? slot.skills.indexOf('BBX-SP383') : -1);

  if (effectiveSkIndex === -1 || !slot.skills || slot.skills[effectiveSkIndex] !== 'BBX-SP383') {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const tag = isPlayer ? '[Efecto Torbellino siniestro BBX-SP383]' : '[Rival - Efecto Torbellino siniestro BBX-SP383]';

  // 1. Hard Once Per Turn (HOPT)
  const usedGlobal = isPlayer
    ? (playtestState.usedGlobalEffects || [])
    : (playtestState.opponentUsedGlobalEffects || []);

  if (usedGlobal.includes('Torbellino siniestro') || usedGlobal.includes('BBX-SP383')) {
    const msg = "Solo puedes usar el efecto de 'Torbellino siniestro' una vez por turno.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 2. Comprobar bloqueo de Skill
  if (typeof isSkillEffectBlocked === 'function' && isSkillEffectBlocked('BBX-SP383', activatorOwner, slot)) {
    const msg = "El efecto de esta Skill está bloqueado.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 3. Requisito de objetivo: Al menos 1 Skill portada en el campo del adversario que pueda ser devuelta a la mano
  const targetable = [];
  oppSlots.forEach((s, sIdx) => {
    if (s && s.character && Array.isArray(s.skills)) {
      s.skills.forEach((sk, kIdx) => {
        if (typeof canRemoveSkillByEffect === 'function' && !canRemoveSkillByEffect(sk, !isPlayer, activatorOwner, s, 'hand')) {
          return;
        }
        targetable.push({
          slotIndex: sIdx,
          skillIndex: kIdx,
          id: sk,
          cardId: sk,
          charName: s.character.nombre || (cardsDatabase[s.character.id || s.character]?.nombre) || 'Personaje',
          skillName: cardsDatabase[sk]?.nombre || sk,
          owner: isPlayer ? 'opponent' : 'player',
          slotRef: s
        });
      });
    }
  });

  if (targetable.length === 0) {
    const msg = "Requisito no cumplido: Tu adversario no tiene ninguna Skill portada en su campo que pueda ser devuelta a la mano.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // Coste: Enviar esta Skill portada al cementerio
  slot.skills.splice(effectiveSkIndex, 1);
  myGrave.push('BBX-SP383');

  if (typeof dispatchGraveTriggers === 'function') {
    dispatchGraveTriggers('BBX-SP383', activatorOwner, { fromZone: 'field', isEquipped: true, byEffect: true });
  }
  if (typeof checkAndTriggerRemembranza === 'function') {
    checkAndTriggerRemembranza('BBX-SP383', activatorOwner);
  }
  if (typeof notifySkillsRemovedByEffect === 'function') {
    notifySkillsRemovedByEffect(1, 'grave', activatorOwner);
  }

  addLog(`${tag} Se envió la Skill <strong>Torbellino siniestro</strong> portada al cementerio como coste.`, isPlayer ? 'var(--accent-purple)' : 'var(--accent-danger)');

  // Registrar HOPT
  if (isPlayer) {
    playtestState.usedGlobalEffects = playtestState.usedGlobalEffects || [];
    playtestState.usedGlobalEffects.push('Torbellino siniestro');
    playtestState.usedGlobalEffects.push('BBX-SP383');
  } else {
    playtestState.opponentUsedGlobalEffects = playtestState.opponentUsedGlobalEffects || [];
    playtestState.opponentUsedGlobalEffects.push('Torbellino siniestro');
    playtestState.opponentUsedGlobalEffects.push('BBX-SP383');
  }

  const finishResolution = (chosenTarget) => {
    if (!chosenTarget) {
      if (typeof updatePlaytestView === 'function') updatePlaytestView();
      if (typeof onDone === 'function') onDone(false);
      return;
    }

    const targetSlot = oppSlots[chosenTarget.slotIndex];
    if (!targetSlot || !Array.isArray(targetSlot.skills)) {
      if (typeof updatePlaytestView === 'function') updatePlaytestView();
      if (typeof onDone === 'function') onDone(false);
      return;
    }

    let actualSkIdx = targetSlot.skills.indexOf(chosenTarget.id);
    if (actualSkIdx === -1 && chosenTarget.skillIndex < targetSlot.skills.length) {
      actualSkIdx = chosenTarget.skillIndex;
    }

    if (actualSkIdx === -1) {
      if (typeof updatePlaytestView === 'function') updatePlaytestView();
      if (typeof onDone === 'function') onDone(false);
      return;
    }

    // 1. Devolver a la mano 1 Skill portada en el campo de tu adversario
    const returnedId = targetSlot.skills.splice(actualSkIdx, 1)[0];
    oppHand.push(returnedId);

    addLog(`${tag} Devolviste a la mano del adversario la Skill portada <strong>${cardsDatabase[returnedId]?.nombre || returnedId}</strong>.`, isPlayer ? 'var(--accent-purple)' : 'var(--accent-danger)');

    if (typeof notifySkillsRemovedByEffect === 'function') {
      notifySkillsRemovedByEffect(1, 'hand', activatorOwner);
    }

    // 2. "y si lo haces envía 1 carta al azar de la mano de tu adversario al cementerio"
    if (oppHand.length > 0) {
      const randIdx = (testOptions && typeof testOptions.randomHandIndex === 'number')
        ? testOptions.randomHandIndex
        : Math.floor(Math.random() * oppHand.length);
      const clampedIdx = Math.max(0, Math.min(oppHand.length - 1, randIdx));

      if (!isPlayer) {
        // El rival descarta de la mano del jugador:
        if (typeof discardPlayerCardByEffect === 'function') {
          discardPlayerCardByEffect(clampedIdx, true);
        } else {
          const discardedId = playtestState.hand.splice(clampedIdx, 1)[0];
          playtestState.grave.push(discardedId);
          addLog(`${tag} El rival envió al azar de tu mano al cementerio: <strong>${cardsDatabase[discardedId]?.nombre || discardedId}</strong>.`, 'var(--accent-danger)');
          if (typeof checkAndTriggerHoraDelTe === 'function') {
            checkAndTriggerHoraDelTe(discardedId, 'player');
          }
          if (typeof checkAndTriggerMarinaSP410 === 'function') {
            checkAndTriggerMarinaSP410(discardedId, 'opponent', 'player');
          }
          if (typeof dispatchGraveTriggers === 'function') {
            dispatchGraveTriggers(discardedId, 'player', { fromZone: 'hand', byEffect: true });
          }
        }
      } else {
        // El jugador descarta de la mano del rival:
        const discardedId = playtestState.opponentHand.splice(clampedIdx, 1)[0];
        playtestState.opponentGrave.push(discardedId);

        addLog(`${tag} Se envió al azar de la mano del adversario al cementerio: <strong>${cardsDatabase[discardedId]?.nombre || discardedId}</strong>.`, 'var(--accent-purple)');

        if (typeof checkAndTriggerHoraDelTe === 'function') {
          checkAndTriggerHoraDelTe(discardedId, 'opponent');
        }
        if (typeof checkAndTriggerMarinaSP410 === 'function') {
          checkAndTriggerMarinaSP410(discardedId, 'player', 'opponent');
        }
        if (typeof dispatchGraveTriggers === 'function') {
          dispatchGraveTriggers(discardedId, 'opponent', { fromZone: 'hand', byEffect: true });
        }
        if (typeof checkAndTriggerRemembranza === 'function') {
          checkAndTriggerRemembranza(discardedId, 'opponent');
        }
      }
    }

    if (typeof updatePlaytestView === 'function') {
      updatePlaytestView();
    }
    if (typeof onDone === 'function') {
      onDone(true, { returnedId });
    }
  };

  // Modo testing / opciones predefinidas
  if (testOptions && typeof testOptions.chosenTargetIndex === 'number') {
    const chosen = targetable[testOptions.chosenTargetIndex] || targetable[0];
    finishResolution(chosen);
    return;
  }

  // Si no es el jugador o si sólo hay 1 objetivo disponible
  if (!isPlayer || targetable.length === 1) {
    finishResolution(targetable[0]);
    return;
  }

  // Interactivo con más de 1 objetivo
  if (typeof openCardChooserModal === 'function') {
    const chooserList = targetable.map(t => ({
      id: t.id,
      owner: 'opponent',
      text: `"${t.skillName}" en ${t.charName}`
    }));
    openCardChooserModal(chooserList, "Torbellino siniestro: Selecciona 1 Skill portada del adversario para devolver a su mano", (chosenIdx) => {
      finishResolution(targetable[chosenIdx] || targetable[0]);
    });
  } else {
    finishResolution(targetable[0]);
  }
}

// Apuesta Skill (BBX-SP386): "Una vez por turno, ambos jugadores revelan las 5 cartas del tope de sus decks, el jugador que revele la mayor cantidad of Skills puede agregar 1 de esas Skills a su mano, de ser empate ningún jugador agrega."
function executeApuestaSkillSP386(activatorOwner = 'player', slotIndex, skIndex, testOptions = {}, onDone = null) {
  const isPlayer = activatorOwner === 'player';
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;
  const slot = slots ? slots[slotIndex] : null;

  if (!slot || !slot.character) {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const effectiveSkIndex = typeof skIndex === 'number'
    ? skIndex
    : (slot.skills ? slot.skills.indexOf('BBX-SP386') : -1);

  if (effectiveSkIndex === -1 || !slot.skills || slot.skills[effectiveSkIndex] !== 'BBX-SP386') {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const tag = isPlayer ? '[Efecto Apuesta Skill BBX-SP386]' : '[Rival - Efecto Apuesta Skill BBX-SP386]';

  // 1. Una vez por turno (SOPT por copia / slot)
  const yaUsadoCard = (slot.usedSkills || []).includes('BBX-SP386');
  const yaUsadoIndex = effectiveSkIndex !== -1 && (slot.usedSkillIndexes || []).includes(effectiveSkIndex);
  if (yaUsadoCard || yaUsadoIndex) {
    const msg = "Ya has usado el efecto de esta copia de 'Apuesta Skill' este turno.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 2. Comprobar bloqueo de Skill
  if (typeof isSkillEffectBlocked === 'function' && isSkillEffectBlocked('BBX-SP386', activatorOwner, slot)) {
    const msg = "El efecto de esta Skill está bloqueado.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const playerDeck = playtestState.deck || [];
  const oppDeck = playtestState.opponentDeck || [];

  // 3. Requisito: Ambos jugadores deben tener cartas en sus decks para poder revelar
  if (playerDeck.length === 0 || oppDeck.length === 0) {
    const msg = "Ambos jugadores deben tener al menos 1 carta en su deck para activar Apuesta Skill.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // Marcar como usada este turno en el slot
  slot.usedSkills = slot.usedSkills || [];
  if (!slot.usedSkills.includes('BBX-SP386')) slot.usedSkills.push('BBX-SP386');
  slot.usedSkillIndexes = slot.usedSkillIndexes || [];
  if (effectiveSkIndex !== -1 && !slot.usedSkillIndexes.includes(effectiveSkIndex)) {
    slot.usedSkillIndexes.push(effectiveSkIndex);
  }

  // Revelar hasta 5 cartas del tope de ambos decks
  const playerRevealedCount = Math.min(5, playerDeck.length);
  const oppRevealedCount = Math.min(5, oppDeck.length);
  const playerRevealed = playerDeck.slice(0, playerRevealedCount);
  const oppRevealed = oppDeck.slice(0, oppRevealedCount);

  // Filtrar Skills entre las cartas reveladas
  const playerSkills = playerRevealed.filter(id => cardsDatabase[id]?.tipo === 'Skill');
  const oppSkills = oppRevealed.filter(id => cardsDatabase[id]?.tipo === 'Skill');

  const playerSkillCount = playerSkills.length;
  const oppSkillCount = oppSkills.length;

  const playerCardNames = playerRevealed.map(id => cardsDatabase[id]?.nombre || id).join(', ');
  const oppCardNames = oppRevealed.map(id => cardsDatabase[id]?.nombre || id).join(', ');

  addLog(`${tag} Ambos jugadores revelan el tope de sus decks:`, 'var(--accent-purple)');
  addLog(`&nbsp;&nbsp;• <strong>Jugador</strong> (${playerSkillCount} Skill${playerSkillCount !== 1 ? 's' : ''}): ${playerCardNames}`, 'var(--accent-cyan)');
  addLog(`&nbsp;&nbsp;• <strong>Rival</strong> (${oppSkillCount} Skill${oppSkillCount !== 1 ? 's' : ''}): ${oppCardNames}`, 'var(--accent-danger)');

  const finishApuesta = (winner, addedCardId) => {
    // Barajar ambos decks tras la revelación y extracción
    if (typeof shuffleArray === 'function') {
      shuffleArray(playerDeck);
      shuffleArray(oppDeck);
    }
    if (typeof checkAndTriggerInestabilidad === 'function') {
      checkAndTriggerInestabilidad('player');
      checkAndTriggerInestabilidad('opponent');
    }
    if (addedCardId && winner === 'player' && typeof checkAndTriggerMarinaSP391 === 'function') {
      checkAndTriggerMarinaSP391('player', addedCardId, 'deck', false);
    }
    if (addedCardId && winner === 'player' && typeof checkAndTriggerDiscordiaSiniestraSP399 === 'function') {
      checkAndTriggerDiscordiaSiniestraSP399('player', addedCardId, 'deck', false);
    }
    if (addedCardId && winner === 'player' && typeof checkAndTriggerCiclonDePalmaSP429 === 'function') {
      checkAndTriggerCiclonDePalmaSP429('player', addedCardId, 'deck', false);
    }
    if (addedCardId && winner === 'opponent' && typeof checkAndTriggerMarinaSP391 === 'function') {
      checkAndTriggerMarinaSP391('opponent', addedCardId, 'deck', false);
    }
    if (addedCardId && winner === 'opponent' && typeof checkAndTriggerDiscordiaSiniestraSP399 === 'function') {
      checkAndTriggerDiscordiaSiniestraSP399('opponent', addedCardId, 'deck', false);
    }
    if (addedCardId && winner === 'opponent' && typeof checkAndTriggerCiclonDePalmaSP429 === 'function') {
      checkAndTriggerCiclonDePalmaSP429('opponent', addedCardId, 'deck', false);
    }
    if (typeof updatePlaytestView === 'function') {
      updatePlaytestView();
    }
    if (typeof onDone === 'function') {
      onDone(true, { winner, addedCardId, playerSkillCount, oppSkillCount });
    }
  };

  // Comparación de cantidades de Skills
  if (playerSkillCount > oppSkillCount) {
    // Gana el Jugador: puede agregar 1 de esas Skills a su mano
    addLog(`${tag} ¡El <strong>Jugador</strong> reveló más Skills (${playerSkillCount} vs ${oppSkillCount})! Puede agregar 1 de esas Skills a su mano.`, 'var(--accent-purple)');

    const addSkillToPlayerHand = (chosenSkillId) => {
      const idx = playerDeck.indexOf(chosenSkillId);
      if (idx !== -1) {
        playerDeck.splice(idx, 1);
        playtestState.hand.push(chosenSkillId);
        addLog(`${tag} El jugador agregó <strong>${cardsDatabase[chosenSkillId]?.nombre || chosenSkillId}</strong> a su mano desde las cartas reveladas.`, 'var(--accent-purple)');
      }
      finishApuesta('player', chosenSkillId);
    };

    if (testOptions && testOptions.addSkill === false) {
      addLog(`${tag} El jugador decidió no agregar ninguna Skill a su mano.`, 'var(--text-muted)');
      finishApuesta('player', null);
      return;
    }
    if (testOptions && testOptions.chosenSkillIndex !== undefined) {
      const chosenId = playerSkills[testOptions.chosenSkillIndex] || playerSkills[0];
      addSkillToPlayerHand(chosenId);
      return;
    }

    // Modo interactivo en interfaz:
    if (typeof openCardChooserModal === 'function') {
      openCardChooserModal(playerSkills, `Apuesta Skill: Selecciona 1 Skill revelada para agregar a tu mano`, (chosenLocalIdx) => {
        const chosenSkillId = playerSkills[chosenLocalIdx] || playerSkills[0];
        addSkillToPlayerHand(chosenSkillId);
      });
    } else {
      addSkillToPlayerHand(playerSkills[0]);
    }
  } else if (oppSkillCount > playerSkillCount) {
    // Gana el Rival: puede agregar 1 de esas Skills a su mano
    addLog(`${tag} ¡El <strong>Rival</strong> reveló más Skills (${oppSkillCount} vs ${playerSkillCount})! Agrega 1 de esas Skills a su mano.`, 'var(--accent-danger)');

    const addSkillToOppHand = (chosenSkillId) => {
      const idx = oppDeck.indexOf(chosenSkillId);
      if (idx !== -1) {
        oppDeck.splice(idx, 1);
        playtestState.opponentHand.push(chosenSkillId);
        addLog(`${tag} El rival agregó <strong>${cardsDatabase[chosenSkillId]?.nombre || chosenSkillId}</strong> a su mano desde las cartas reveladas.`, 'var(--accent-danger)');
      }
      finishApuesta('opponent', chosenSkillId);
    };

    if (testOptions && testOptions.addSkill === false) {
      addLog(`${tag} El rival decidió no agregar ninguna Skill a su mano.`, 'var(--text-muted)');
      finishApuesta('opponent', null);
      return;
    }
    if (testOptions && testOptions.chosenSkillIndex !== undefined) {
      const chosenId = oppSkills[testOptions.chosenSkillIndex] || oppSkills[0];
      addSkillToOppHand(chosenId);
      return;
    }

    // Por defecto IA rival elige la primera Skill
    addSkillToOppHand(oppSkills[0]);
  } else {
    // Empate: ningún jugador agrega
    addLog(`${tag} Empate (${playerSkillCount} vs ${oppSkillCount} Skills): Ningún jugador agrega cartas a su mano. Ambos decks fueron barajados.`, 'var(--accent-warning)');
    finishApuesta('tie', null);
  }
}

// Destello perspicaz BBX-SP390: Baraja 1 carta en tu mano y si lo haces puedes portarle a 1 Personaje que controles 1 Skill propia de Haruka desde tu cementerio. Solo una vez por turno.
function executeDestelloPerspicazSP390(activatorOwner = 'player', slotIndex, skIndex, testOptions = {}, onDone = null) {
  const isPlayer = activatorOwner === 'player';
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;
  const slot = slots ? slots[slotIndex] : null;

  if (!slot || !slot.character) {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const effectiveSkIndex = typeof skIndex === 'number'
    ? skIndex
    : (slot.skills ? slot.skills.indexOf('BBX-SP390') : -1);

  if (effectiveSkIndex === -1 || !slot.skills || slot.skills[effectiveSkIndex] !== 'BBX-SP390') {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const tag = isPlayer ? '[Efecto Destello perspicaz BBX-SP390]' : '[Rival - Efecto Destello perspicaz BBX-SP390]';

  // HOPT Check
  const usedGlobals = isPlayer
    ? (playtestState.usedGlobalEffects = playtestState.usedGlobalEffects || [])
    : (playtestState.opponentUsedGlobalEffects = playtestState.opponentUsedGlobalEffects || []);

  if (usedGlobals.includes('Destello perspicaz') || usedGlobals.includes('BBX-SP390')) {
    addLog(`${tag} Ya has usado el efecto de "Destello perspicaz" este turno.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // Blocked Check
  if (typeof isSkillEffectBlocked === 'function' && isSkillEffectBlocked('BBX-SP390', activatorOwner, slot)) {
    addLog(`${tag} El efecto de Destello perspicaz está bloqueado o anulado.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const hand = isPlayer ? playtestState.hand : playtestState.opponentHand;
  const deck = isPlayer ? playtestState.deck : playtestState.opponentDeck;
  const grave = isPlayer ? playtestState.grave : playtestState.opponentGrave;

  if (!hand || hand.length === 0) {
    addLog(`${tag} No tienes ninguna carta en mano para barajar.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const canGrave = typeof canEquipFromZone === 'function' ? canEquipFromZone('grave') : true;
  if (!canGrave) {
    addLog(`${tag} No se permite portar Skills desde el cementerio debido a una restricción activa.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const isHarukaSkill = id => cardsDatabase[id]?.tipo === 'Skill' && cardsDatabase[id]?.portador && cardsDatabase[id]?.portador.includes("Haruka");
  const harukaSkillsInGrave = grave.filter(isHarukaSkill);
  if (harukaSkillsInGrave.length === 0) {
    addLog(`${tag} No hay ninguna Skill propia de Haruka en el cementerio para portar.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const eligibleChars = [];
  slots.forEach((s, idx) => {
    if (s.character && cardsDatabase[s.character]) {
      eligibleChars.push({
        slot: s,
        slotIndex: idx,
        name: cardsDatabase[s.character].nombre
      });
    }
  });

  if (eligibleChars.length === 0) {
    addLog(`${tag} No controlas ningún Personaje para portarle la Skill.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // Marcar HOPT y usedSkill
  usedGlobals.push('Destello perspicaz');
  usedGlobals.push('BBX-SP390');
  slot.usedSkills = slot.usedSkills || [];
  slot.usedSkills.push('BBX-SP390');
  slot.usedSkillIndexes = slot.usedSkillIndexes || [];
  slot.usedSkillIndexes.push(effectiveSkIndex);

  // Helper para resolver la segunda parte del efecto (portar Skill de Haruka del cementerio)
  const resolveEquipHarukaSkill = () => {
    const freshHarukaSkills = grave.filter(isHarukaSkill);
    if (freshHarukaSkills.length === 0) {
      addLog(`${tag} Ya no hay Skills propias de Haruka en el cementerio.`, 'var(--text-muted)');
      if (typeof updatePlaytestView === 'function') updatePlaytestView();
      if (typeof onDone === 'function') onDone(true);
      return;
    }

    const freshEligibleChars = [];
    slots.forEach((s, idx) => {
      if (s.character && cardsDatabase[s.character]) {
        freshEligibleChars.push({
          slot: s,
          slotIndex: idx,
          name: cardsDatabase[s.character].nombre
        });
      }
    });

    if (freshEligibleChars.length === 0) {
      addLog(`${tag} Ya no controlas ningún Personaje para portarle la Skill.`, 'var(--text-muted)');
      if (typeof updatePlaytestView === 'function') updatePlaytestView();
      if (typeof onDone === 'function') onDone(true);
      return;
    }

    // Si testOptions.equipSkill === false
    if (testOptions && testOptions.equipSkill === false) {
      addLog(`${tag} Decidiste no portar ninguna Skill de Haruka.`, 'var(--text-muted)');
      if (typeof updatePlaytestView === 'function') updatePlaytestView();
      if (typeof onDone === 'function') onDone(true);
      return;
    }

    const portChosenSkillToChar = (chosenSkillId, targetCharObj) => {
      const gIdx = grave.indexOf(chosenSkillId);
      if (gIdx !== -1) {
        grave.splice(gIdx, 1);
      }
      targetCharObj.slot.skills = targetCharObj.slot.skills || [];
      targetCharObj.slot.skills.push(chosenSkillId);

      const skillName = cardsDatabase[chosenSkillId]?.nombre || chosenSkillId;
      addLog(`${tag} ${isPlayer ? 'Portaste' : 'El rival portó'} <strong>${skillName}</strong> desde el cementerio a <strong>${targetCharObj.name}</strong> (Slot ${targetCharObj.slotIndex + 1}).`, 'var(--accent-purple)');

      if (typeof checkAndTriggerInestabilidad === 'function') {
        checkAndTriggerInestabilidad(activatorOwner);
      }
      if (typeof updatePlaytestView === 'function') updatePlaytestView();
      if (typeof onDone === 'function') onDone(true);
    };

    const chooseTargetCharacter = (chosenSkillId) => {
      if (testOptions && testOptions.targetSlotIndex !== undefined) {
        const target = freshEligibleChars.find(c => c.slotIndex === testOptions.targetSlotIndex) || freshEligibleChars[0];
        portChosenSkillToChar(chosenSkillId, target);
        return;
      }

      if (!isPlayer || freshEligibleChars.length === 1) {
        const defaultChar = freshEligibleChars.find(c => c.slotIndex === slotIndex) || freshEligibleChars[0];
        portChosenSkillToChar(chosenSkillId, defaultChar);
      } else {
        if (typeof showContextMenu === 'function') {
          const charItems = freshEligibleChars.map(c => ({
            text: `🛡️ Portar a ${c.name} (Slot ${c.slotIndex + 1})`,
            action: () => portChosenSkillToChar(chosenSkillId, c)
          }));
          const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
          showContextMenu(dummyEvent, charItems);
        } else {
          const defaultChar = freshEligibleChars.find(c => c.slotIndex === slotIndex) || freshEligibleChars[0];
          portChosenSkillToChar(chosenSkillId, defaultChar);
        }
      }
    };

    // Selección de la Skill de Haruka del cementerio
    if (testOptions && testOptions.graveSkillId !== undefined) {
      const chosenSkillId = freshHarukaSkills.includes(testOptions.graveSkillId) ? testOptions.graveSkillId : freshHarukaSkills[0];
      chooseTargetCharacter(chosenSkillId);
      return;
    }
    if (testOptions && testOptions.graveSkillIndex !== undefined) {
      const chosenSkillId = freshHarukaSkills[testOptions.graveSkillIndex] || freshHarukaSkills[0];
      chooseTargetCharacter(chosenSkillId);
      return;
    }

    if (!isPlayer) {
      chooseTargetCharacter(freshHarukaSkills[0]);
    } else if (typeof openCardChooserModal === 'function') {
      const chooserTargets = freshHarukaSkills.map(id => ({ id, owner: activatorOwner, from: 'grave' }));
      openCardChooserModal(chooserTargets, "Destello perspicaz: Selecciona 1 Skill propia de Haruka de tu cementerio para portar", (chosenIdx) => {
        const chosenSkillId = freshHarukaSkills[chosenIdx] || freshHarukaSkills[0];
        chooseTargetCharacter(chosenSkillId);
      });
    } else {
      chooseTargetCharacter(freshHarukaSkills[0]);
    }
  };

  // Paso 1: Barajar 1 carta de la mano en el deck
  const doShuffleCardFromHand = (handIdx) => {
    const cardId = hand.splice(handIdx, 1)[0];
    deck.push(cardId);
    if (typeof shuffleArray === 'function') {
      shuffleArray(deck);
    }
    const cardName = cardsDatabase[cardId]?.nombre || cardId;
    addLog(`${tag} ${isPlayer ? 'Barajaste' : 'El rival barajó'} <strong>${cardName}</strong> de su mano en su deck.`, 'var(--accent-purple)');
    if (typeof updatePlaytestView === 'function') updatePlaytestView();

    resolveEquipHarukaSkill();
  };

  if (testOptions && testOptions.handCardIndex !== undefined) {
    const idx = (testOptions.handCardIndex >= 0 && testOptions.handCardIndex < hand.length) ? testOptions.handCardIndex : 0;
    doShuffleCardFromHand(idx);
    return;
  }
  if (testOptions && testOptions.handCardId !== undefined) {
    const idx = hand.indexOf(testOptions.handCardId);
    doShuffleCardFromHand(idx !== -1 ? idx : 0);
    return;
  }

  if (!isPlayer) {
    doShuffleCardFromHand(0);
  } else if (typeof openCardChooserModal === 'function') {
    const chooserTargets = hand.map(id => ({ id, owner: 'player', from: 'hand' }));
    openCardChooserModal(chooserTargets, "Destello perspicaz: Selecciona 1 carta de tu mano para barajar en tu deck", (chosenIdx) => {
      const actualIdx = (chosenIdx >= 0 && chosenIdx < hand.length) ? chosenIdx : 0;
      doShuffleCardFromHand(actualIdx);
    });
  } else {
    doShuffleCardFromHand(0);
  }
}

// Pequeño incidente (BBX-SP414): "Envía al cementerio 1 Skill portada en tu lado del campo excepto "Pequeño incidente" y si lo haces puedes barajar al deck 1 Skill en el cementerio de cualquier jugador. Solo puedes usar este efecto de "Pequeño incidente" una vez por turno."
function executePequenoIncidenteSP414(activatorOwner = 'player', slotIndex, skIndex, testOptions = {}, onDone = null) {
  const isPlayer = activatorOwner === 'player';
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;
  const slot = slots ? slots[slotIndex] : null;

  if (!slot || !slot.character) {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const effectiveSkIndex = typeof skIndex === 'number'
    ? skIndex
    : (slot.skills ? slot.skills.indexOf('BBX-SP414') : -1);

  if (effectiveSkIndex === -1 || !slot.skills || slot.skills[effectiveSkIndex] !== 'BBX-SP414') {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const tag = isPlayer ? '[Efecto Pequeño incidente BBX-SP414]' : '[Rival - Efecto Pequeño incidente BBX-SP414]';

  // 1. HOPT Check
  const usedGlobal = isPlayer
    ? (playtestState.usedGlobalEffects || [])
    : (playtestState.opponentUsedGlobalEffects || []);

  if (usedGlobal.includes('Pequeño incidente') || usedGlobal.includes('BBX-SP414')) {
    const msg = "Solo puedes usar el efecto de 'Pequeño incidente' una vez por turno.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 2. Comprobar bloqueo de Skill
  if (typeof isSkillEffectBlocked === 'function' && isSkillEffectBlocked('BBX-SP414', activatorOwner, slot)) {
    const msg = "El efecto de esta Skill está bloqueado.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 3. Buscar posibles Skills para el coste en el campo del activador (excepto "Pequeño incidente")
  const candidateCostSkills = [];
  slots.forEach((s, sIdx) => {
    if (s && s.character && Array.isArray(s.skills)) {
      const charName = cardsDatabase[s.character]?.nombre || `Slot ${sIdx + 1}`;
      s.skills.forEach((sid, sidIdx) => {
        const cardData = cardsDatabase[sid];
        if (sid !== 'BBX-SP414' && (!cardData || cardData.nombre !== 'Pequeño incidente')) {
          if (typeof canRemoveSkillByEffect !== 'function' || canRemoveSkillByEffect(sid, !isPlayer, activatorOwner, s, 'grave', 'BBX-SP414', 'skill', true)) {
            candidateCostSkills.push({
              id: sid,
              slotIndex: sIdx,
              skillIndex: sidIdx,
              charName: charName,
              cardName: cardData?.nombre || sid,
              owner: activatorOwner,
              from: 'field',
              slotRef: s
            });
          }
        }
      });
    }
  });

  if (candidateCostSkills.length === 0) {
    const msg = "Requisito no cumplido: No hay otra Skill portada en tu lado del campo para enviar al cementerio como coste.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // Resolución del efecto secundario tras pagar coste:
  // "y si lo haces puedes barajar al deck 1 Skill en el cementerio de cualquier jugador"
  const resolveGraveyardShuffle = () => {
    // Verificar bloqueo por Punto de control (BBX-SP198)
    if (typeof isPuntoDeControlActive === 'function' && isPuntoDeControlActive()) {
      addLog(`[Punto de control] Efecto de "Pequeño incidente" bloqueado: Ningún jugador puede regresar cartas del cementerio al deck.`, 'var(--text-muted)');
      if (typeof updatePlaytestView === 'function') updatePlaytestView();
      if (typeof onDone === 'function') onDone(true, { puntoBlocked: true });
      return;
    }

    // Recolectar Skills del cementerio de ambos jugadores en un modal unificado
    const candidateGraveSkills = [];

    // Cementerio del Jugador
    if (Array.isArray(playtestState.grave)) {
      playtestState.grave.forEach((skId, gIdx) => {
        if (cardsDatabase[skId]?.tipo === 'Skill') {
          candidateGraveSkills.push({
            id: skId,
            from: 'grave',
            owner: 'player',
            graveOwner: 'player',
            graveIdx: gIdx,
            cardName: cardsDatabase[skId]?.nombre || skId,
            text: `${cardsDatabase[skId]?.nombre || skId} (🪦 Tu Cementerio)`
          });
        }
      });
    }

    // Cementerio del Rival
    if (Array.isArray(playtestState.opponentGrave)) {
      playtestState.opponentGrave.forEach((skId, gIdx) => {
        if (cardsDatabase[skId]?.tipo === 'Skill') {
          candidateGraveSkills.push({
            id: skId,
            from: 'grave',
            owner: 'opponent',
            graveOwner: 'opponent',
            graveIdx: gIdx,
            cardName: cardsDatabase[skId]?.nombre || skId,
            text: `${cardsDatabase[skId]?.nombre || skId} (🪦 Cementerio Rival)`
          });
        }
      });
    }

    const finishWithoutGraveShuffle = (reason = 'skipped_or_no_targets') => {
      if (typeof updatePlaytestView === 'function') updatePlaytestView();
      if (typeof onDone === 'function') onDone(true, { shuffledCard: null, reason });
    };

    if (candidateGraveSkills.length === 0) {
      addLog(`${tag} No hay ninguna Skill en el cementerio de ningún jugador para barajar al deck.`, 'var(--text-muted)');
      finishWithoutGraveShuffle('no_grave_skills');
      return;
    }

    const executeGraveShuffle = (chosenTarget) => {
      if (!chosenTarget) {
        finishWithoutGraveShuffle('no_target_selected');
        return;
      }

      const targetGrave = chosenTarget.graveOwner === 'player' ? playtestState.grave : playtestState.opponentGrave;
      const targetDeck = chosenTarget.graveOwner === 'player' ? playtestState.deck : playtestState.opponentDeck;
      const cardName = cardsDatabase[chosenTarget.id]?.nombre || chosenTarget.id;
      const ownerDesc = chosenTarget.graveOwner === 'player' ? 'tu cementerio' : 'el cementerio del rival';
      const deckDesc = chosenTarget.graveOwner === 'player' ? 'tu deck' : 'el deck del rival';

      let gIdx = -1;
      if (typeof chosenTarget.graveIdx === 'number' && targetGrave[chosenTarget.graveIdx] === chosenTarget.id) {
        gIdx = chosenTarget.graveIdx;
      } else {
        gIdx = targetGrave.indexOf(chosenTarget.id);
      }

      if (gIdx !== -1) {
        targetGrave.splice(gIdx, 1);
        targetDeck.push(chosenTarget.id);
        if (typeof shuffleArray === 'function') {
          shuffleArray(targetDeck);
        }

        if (isPlayer) {
          addLog(`${tag} Barajaste <strong>${cardName}</strong> de ${ownerDesc} a ${deckDesc}.`, 'var(--accent-cyan)');
        } else {
          addLog(`${tag} El rival barajó <strong>${cardName}</strong> de ${ownerDesc} a ${deckDesc}.`, 'var(--accent-cyan)');
        }
      }

      if (typeof checkAndTriggerInestabilidad === 'function') {
        checkAndTriggerInestabilidad(activatorOwner);
      }
      if (typeof updatePlaytestView === 'function') updatePlaytestView();
      if (typeof onDone === 'function') onDone(true, { shuffledCard: chosenTarget.id, graveOwner: chosenTarget.graveOwner });
    };

    // Modo tests u opciones automáticas
    if (testOptions && (testOptions.skipShuffle !== undefined || testOptions.chosenGraveIdx !== undefined || testOptions.chosenGraveId !== undefined || testOptions.chosenGraveOwner !== undefined)) {
      if (testOptions.skipShuffle) {
        addLog(`${tag} ${isPlayer ? 'Decidiste' : 'El rival decidió'} no barajar ninguna Skill al deck.`, 'var(--text-muted)');
        finishWithoutGraveShuffle('skipped_shuffle');
        return;
      }
      let picked = null;
      if (testOptions.chosenGraveIdx !== undefined) {
        picked = candidateGraveSkills[testOptions.chosenGraveIdx];
      } else if (testOptions.chosenGraveId) {
        if (testOptions.chosenGraveOwner) {
          picked = candidateGraveSkills.find(c => c.id === testOptions.chosenGraveId && c.graveOwner === testOptions.chosenGraveOwner);
        } else {
          picked = candidateGraveSkills.find(c => c.id === testOptions.chosenGraveId);
        }
      }
      if (!picked) picked = candidateGraveSkills[0];
      executeGraveShuffle(picked);
      return;
    }

    if (!isPlayer) {
      executeGraveShuffle(candidateGraveSkills[0]);
      return;
    }

    // Jugador humano: Modal unificado con opciones para cancelar (efecto opcional "puedes")
    if (typeof openCardChooserModal === 'function') {
      openCardChooserModal(
        candidateGraveSkills,
        "Pequeño incidente: Selecciona 1 Skill del cementerio de cualquier jugador para barajar al deck",
        (chosenIdx) => {
          const picked = candidateGraveSkills[chosenIdx] || candidateGraveSkills[0];
          executeGraveShuffle(picked);
        },
        () => {
          addLog(`${tag} Decidiste no barajar ninguna Skill al deck.`, 'var(--text-muted)');
          finishWithoutGraveShuffle('skipped_shuffle');
        }
      );
    } else {
      executeGraveShuffle(candidateGraveSkills[0]);
    }
  };

  // Función para procesar el pago del coste
  const payCostAndProceed = (chosenCost) => {
    // 1. Marcar HOPT global y de slot
    if (isPlayer) {
      playtestState.usedGlobalEffects = playtestState.usedGlobalEffects || [];
      playtestState.usedGlobalEffects.push('Pequeño incidente');
      playtestState.usedGlobalEffects.push('BBX-SP414');
    } else {
      playtestState.opponentUsedGlobalEffects = playtestState.opponentUsedGlobalEffects || [];
      playtestState.opponentUsedGlobalEffects.push('Pequeño incidente');
      playtestState.opponentUsedGlobalEffects.push('BBX-SP414');
    }

    if (slot) {
      slot.usedSkills = slot.usedSkills || [];
      slot.usedSkills.push('BBX-SP414');
      if (typeof effectiveSkIndex === 'number' && effectiveSkIndex >= 0) {
        slot.usedSkillIndexes = slot.usedSkillIndexes || [];
        slot.usedSkillIndexes.push(effectiveSkIndex);
      }
    }

    // 2. Remover la Skill seleccionada de su slot y enviarla al cementerio
    const targetSlot = slots[chosenCost.slotIndex];
    let actualIndex = -1;
    if (targetSlot && Array.isArray(targetSlot.skills)) {
      if (targetSlot.skills[chosenCost.skillIndex] === chosenCost.id) {
        actualIndex = chosenCost.skillIndex;
      } else {
        actualIndex = targetSlot.skills.indexOf(chosenCost.id);
      }
    }

    if (actualIndex === -1) {
      if (typeof onDone === 'function') onDone(false);
      return;
    }

    const removedSkillId = targetSlot.skills.splice(actualIndex, 1)[0];
    const myGrave = isPlayer ? playtestState.grave : playtestState.opponentGrave;
    myGrave.push(removedSkillId);

    addLog(`${tag} ${isPlayer ? 'Enviaste' : 'El rival envió'} la Skill <strong>${chosenCost.cardName}</strong> portada en <strong>${chosenCost.charName}</strong> al cementerio como coste.`, isPlayer ? 'var(--accent-purple)' : 'var(--accent-danger)');

    if (typeof dispatchGraveTriggers === 'function') {
      dispatchGraveTriggers(removedSkillId, activatorOwner, { fromZone: 'field', isEquipped: true, byEffect: true });
    }
    if (typeof checkAndTriggerRemembranza === 'function') {
      checkAndTriggerRemembranza(removedSkillId, activatorOwner);
    }
    if (typeof notifySkillsRemovedByEffect === 'function') {
      notifySkillsRemovedByEffect(1, 'grave', activatorOwner);
    }
    if (typeof checkAndTriggerReflejo === 'function') {
      checkAndTriggerReflejo(removedSkillId, activatorOwner);
    }

    if (typeof updatePlaytestView === 'function') updatePlaytestView();

    // 3. Resolver efecto secundario
    resolveGraveyardShuffle();
  };

  // Verificación de testOptions de coste
  if (testOptions && testOptions.cancelCost) {
    addLog(`${tag} Activación cancelada por el jugador.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  if (testOptions && (testOptions.costSkillIndex !== undefined || testOptions.costSkillId !== undefined)) {
    let chosen = null;
    if (testOptions.costSkillIndex !== undefined) {
      chosen = candidateCostSkills[testOptions.costSkillIndex];
    } else if (testOptions.costSkillId !== undefined) {
      chosen = candidateCostSkills.find(c => c.id === testOptions.costSkillId);
    }
    payCostAndProceed(chosen || candidateCostSkills[0]);
    return;
  }

  // Si solo hay 1 candidata o es la IA, proceder directamente
  if (candidateCostSkills.length === 1 || !isPlayer) {
    payCostAndProceed(candidateCostSkills[0]);
    return;
  }

  // Jugador con múltiples opciones: abrir modal de selección
  if (typeof openCardChooserModal === 'function') {
    openCardChooserModal(
      candidateCostSkills,
      "Pequeño incidente: Selecciona 1 Skill portada en tu campo para enviar al cementerio",
      (chosenIdx) => {
        const chosen = candidateCostSkills[chosenIdx] || candidateCostSkills[0];
        payCostAndProceed(chosen);
      },
      () => {
        addLog(`${tag} Activación cancelada por el jugador.`, 'var(--text-muted)');
        if (typeof onDone === 'function') onDone(false);
      }
    );
  } else {
    payCostAndProceed(candidateCostSkills[0]);
  }
}
window.executePequenoIncidenteSP414 = executePequenoIncidenteSP414;

// Ascensión (BBX-SP415): "Baraja al deck 1 Personaje Helica en tu banca y si lo haces puedes recuperar a tu mano 1 Skill propia de Helica en tu cementerio. Solo puedes usar este efecto de "Ascensión" una vez por partida."
function executeAscensionSP415(activatorOwner = 'player', slotIndex, skIndex, testOptions = {}, onDone = null) {
  const isPlayer = activatorOwner === 'player';
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;
  const slot = slots ? slots[slotIndex] : null;

  if (!slot || !slot.character) {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const effectiveSkIndex = typeof skIndex === 'number'
    ? skIndex
    : (slot.skills ? slot.skills.indexOf('BBX-SP415') : -1);

  if (effectiveSkIndex === -1 || !slot.skills || slot.skills[effectiveSkIndex] !== 'BBX-SP415') {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const tag = isPlayer ? '[Efecto Ascensión BBX-SP415]' : '[Rival - Efecto Ascensión BBX-SP415]';

  // 1. Verificar Hard Once Per Game (HOPG - una vez por partida)
  const usedPerGame = isPlayer
    ? (playtestState.usedPerGameEffects || [])
    : (playtestState.opponentUsedPerGameEffects || []);

  const flagCheck = isPlayer ? playtestState.usedAscension415ThisGame : playtestState.opponentUsedAscension415ThisGame;

  if (flagCheck || usedPerGame.includes('Ascensión') || usedPerGame.includes('BBX-SP415')) {
    const msg = "Solo puedes usar el efecto de 'Ascensión' una vez por partida.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 2. Comprobar bloqueo de Skill
  if (typeof isSkillEffectBlocked === 'function' && isSkillEffectBlocked('BBX-SP415', activatorOwner, slot)) {
    const msg = "El efecto de esta Skill está bloqueado.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // Bloqueo por Apertura en el cielo BBX-SP424 (impide barajar Personajes en banca)
  if (typeof isAperturaEnElCieloActive === 'function' && isAperturaEnElCieloActive()) {
    const msg = "No se puede activar el efecto: «Apertura en el cielo» impide barajar Personajes en la banca.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 3. Requisito de coste: Barajar al deck 1 Personaje Helica en tu banca
  const bench = isPlayer ? playtestState.bench : playtestState.opponentBench;
  const isHelicaChar = (item) => {
    const cId = typeof item === 'object' && item !== null ? item.id : item;
    const c = cardsDatabase[cId];
    return c && c.tipo === 'Personaje' && (c.nombre === 'Helica' || (c.nombre && c.nombre.includes('Helica')));
  };

  const helicaCandidates = [];
  (bench || []).forEach((item, bIdx) => {
    if (isHelicaChar(item)) {
      const cId = typeof item === 'object' && item !== null ? item.id : item;
      helicaCandidates.push({
        id: cId,
        benchIndex: bIdx,
        charName: cardsDatabase[cId]?.nombre || 'Helica',
        owner: activatorOwner,
        from: 'bench',
        itemRef: item
      });
    }
  });

  if (helicaCandidates.length === 0) {
    const msg = "Requisito no cumplido: No tienes ningún Personaje Helica en tu banca para barajar al deck.";
    if (isPlayer && typeof alert === 'function') alert(msg);
    else addLog(`${tag} ${msg}`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // Resolución tras barajar al deck el Personaje Helica de la banca:
  // "y si lo haces puedes recuperar a tu mano 1 Skill propia de Helica en tu cementerio."
  const resolveSkillRecovery = () => {
    // Verificar si la recuperación de cartas del cementerio a la mano está bloqueada por Haruka (BBX-SP251)
    if (typeof isGraveToHandBlocked === 'function' && isGraveToHandBlocked()) {
      addLog(`[Haruka BBX-SP251] Efecto de "Ascensión" bloqueado: Ningún jugador puede recuperar cartas del cementerio a su mano.`, 'var(--text-muted)');
      if (typeof updatePlaytestView === 'function') updatePlaytestView();
      if (typeof onDone === 'function') onDone(true, { graveBlocked: true });
      return;
    }

    const myGrave = isPlayer ? playtestState.grave : playtestState.opponentGrave;
    const myHand = isPlayer ? playtestState.hand : playtestState.opponentHand;

    const isHelicaSkill = (id) => {
      const c = cardsDatabase[id];
      return c && c.tipo === 'Skill' && c.portador && c.portador.includes('Helica');
    };

    const eligibleGraveSkills = [];
    (myGrave || []).forEach((skId, gIdx) => {
      if (isHelicaSkill(skId)) {
        eligibleGraveSkills.push({
          id: skId,
          from: 'grave',
          owner: activatorOwner,
          graveIdx: gIdx,
          cardName: cardsDatabase[skId]?.nombre || skId,
          text: `${cardsDatabase[skId]?.nombre || skId} (🪦 Cementerio)`
        });
      }
    });

    const finishWithoutRecovery = (reason = 'skipped_or_no_targets') => {
      if (typeof updatePlaytestView === 'function') updatePlaytestView();
      if (typeof onDone === 'function') onDone(true, { recoveredCard: null, reason });
    };

    if (eligibleGraveSkills.length === 0) {
      addLog(`${tag} No hay ninguna Skill propia de Helica en tu cementerio para recuperar a tu mano.`, 'var(--text-muted)');
      finishWithoutRecovery('no_helica_skills_in_grave');
      return;
    }

    const executeRecovery = (chosenTarget) => {
      if (!chosenTarget) {
        finishWithoutRecovery('no_target_selected');
        return;
      }

      let gIdx = -1;
      if (typeof chosenTarget.graveIdx === 'number' && myGrave[chosenTarget.graveIdx] === chosenTarget.id) {
        gIdx = chosenTarget.graveIdx;
      } else {
        gIdx = myGrave.indexOf(chosenTarget.id);
      }

      if (gIdx !== -1) {
        const recoveredCardId = myGrave.splice(gIdx, 1)[0];
        myHand.push(recoveredCardId);
        const cardName = cardsDatabase[recoveredCardId]?.nombre || recoveredCardId;

        if (isPlayer) {
          addLog(`${tag} Recuperaste <strong>${cardName}</strong> de tu cementerio a tu mano.`, 'var(--accent-cyan)');
        } else {
          addLog(`${tag} El rival recuperó <strong>${cardName}</strong> de su cementerio a su mano.`, 'var(--accent-cyan)');
        }
      }

      if (typeof updatePlaytestView === 'function') updatePlaytestView();
      if (typeof onDone === 'function') onDone(true, { recoveredCard: chosenTarget.id });
    };

    // Modo tests u opciones automáticas
    if (testOptions && (testOptions.skipRecovery !== undefined || testOptions.chosenGraveIdx !== undefined || testOptions.chosenGraveId !== undefined)) {
      if (testOptions.skipRecovery) {
        addLog(`${tag} ${isPlayer ? 'Decidiste' : 'El rival decidió'} no recuperar ninguna Skill a la mano.`, 'var(--text-muted)');
        finishWithoutRecovery('skipped_recovery');
        return;
      }
      let picked = null;
      if (testOptions.chosenGraveIdx !== undefined) {
        picked = eligibleGraveSkills[testOptions.chosenGraveIdx];
      } else if (testOptions.chosenGraveId) {
        picked = eligibleGraveSkills.find(c => c.id === testOptions.chosenGraveId);
      }
      if (!picked) picked = eligibleGraveSkills[0];
      executeRecovery(picked);
      return;
    }

    if (!isPlayer) {
      executeRecovery(eligibleGraveSkills[0]);
      return;
    }

    // Modal para el jugador (con botón de cancelar ya que el efecto es opcional "puedes")
    if (typeof openCardChooserModal === 'function') {
      openCardChooserModal(
        eligibleGraveSkills,
        "Ascensión: Selecciona 1 Skill propia de Helica de tu cementerio para recuperar a tu mano",
        (chosenIdx) => {
          const picked = eligibleGraveSkills[chosenIdx] || eligibleGraveSkills[0];
          executeRecovery(picked);
        },
        () => {
          addLog(`${tag} Decidiste no recuperar ninguna Skill a tu mano.`, 'var(--text-muted)');
          finishWithoutRecovery('skipped_recovery');
        }
      );
    } else {
      executeRecovery(eligibleGraveSkills[0]);
    }
  };

  // Función para procesar el coste (barajar Helica de la banca al deck)
  const payCostAndProceed = (chosenHelica) => {
    // 1. Marcar una vez por partida
    if (isPlayer) {
      playtestState.usedPerGameEffects = playtestState.usedPerGameEffects || [];
      playtestState.usedPerGameEffects.push('Ascensión');
      playtestState.usedPerGameEffects.push('BBX-SP415');
      playtestState.usedAscension415ThisGame = true;
    } else {
      playtestState.opponentUsedPerGameEffects = playtestState.opponentUsedPerGameEffects || [];
      playtestState.opponentUsedPerGameEffects.push('Ascensión');
      playtestState.opponentUsedPerGameEffects.push('BBX-SP415');
      playtestState.opponentUsedAscension415ThisGame = true;
    }

    if (slot) {
      slot.usedSkills = slot.usedSkills || [];
      slot.usedSkills.push('BBX-SP415');
      if (typeof effectiveSkIndex === 'number' && effectiveSkIndex >= 0) {
        slot.usedSkillIndexes = slot.usedSkillIndexes || [];
        slot.usedSkillIndexes.push(effectiveSkIndex);
      }
    }

    // 2. Remover de banca y barajar en el deck
    let actualIdx = -1;
    if (typeof chosenHelica.benchIndex === 'number' && bench[chosenHelica.benchIndex]) {
      const curId = typeof bench[chosenHelica.benchIndex] === 'object' ? bench[chosenHelica.benchIndex].id : bench[chosenHelica.benchIndex];
      if (curId === chosenHelica.id) {
        actualIdx = chosenHelica.benchIndex;
      }
    }
    if (actualIdx === -1) {
      actualIdx = bench.findIndex(b => (typeof b === 'object' && b !== null ? b.id : b) === chosenHelica.id);
    }

    if (actualIdx === -1) {
      if (typeof onDone === 'function') onDone(false);
      return;
    }

    const removedItem = bench.splice(actualIdx, 1)[0];
    const removedCharId = typeof removedItem === 'object' && removedItem !== null ? removedItem.id : removedItem;
    const myDeck = isPlayer ? playtestState.deck : playtestState.opponentDeck;
    myDeck.push(removedCharId);

    if (typeof shuffleArray === 'function') {
      shuffleArray(myDeck);
    }

    addLog(`${tag} ${isPlayer ? 'Barajaste' : 'El rival barajó'} a <strong>${chosenHelica.charName}</strong> de su banca en su deck.`, isPlayer ? 'var(--accent-purple)' : 'var(--accent-danger)');

    if (typeof updatePlaytestView === 'function') updatePlaytestView();

    // 3. Proceder al efecto secundario
    resolveSkillRecovery();
  };

  // Verificación de testOptions de coste
  if (testOptions && testOptions.cancelCost) {
    addLog(`${tag} Activación cancelada por el jugador.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  if (testOptions && (testOptions.benchIndex !== undefined || testOptions.benchCardId !== undefined)) {
    let chosen = null;
    if (testOptions.benchIndex !== undefined) {
      chosen = helicaCandidates.find(c => c.benchIndex === testOptions.benchIndex);
    } else if (testOptions.benchCardId !== undefined) {
      chosen = helicaCandidates.find(c => c.id === testOptions.benchCardId);
    }
    payCostAndProceed(chosen || helicaCandidates[0]);
    return;
  }

  // Si sólo hay 1 candidata o es la IA, proceder directamente
  if (helicaCandidates.length === 1 || !isPlayer) {
    payCostAndProceed(helicaCandidates[0]);
    return;
  }

  // Si hay varias en banca y es el jugador humano: abrir modal
  if (typeof openCardChooserModal === 'function') {
    openCardChooserModal(
      helicaCandidates,
      "Ascensión: Selecciona 1 Personaje Helica de tu banca para barajar en tu deck",
      (chosenIdx) => {
        const chosen = helicaCandidates[chosenIdx] || helicaCandidates[0];
        payCostAndProceed(chosen);
      },
      () => {
        addLog(`${tag} Activación cancelada por el jugador.`, 'var(--text-muted)');
        if (typeof onDone === 'function') onDone(false);
      }
    );
  } else {
    payCostAndProceed(helicaCandidates[0]);
  }
}
window.executeAscensionSP415 = executeAscensionSP415;

// Nobuko BBX-SP416: "Una vez por turno, si juegas 1 Personaje Nara o Ryu-chan a tu campo, puedes agregar a tu mano desde tu deck 1 Personaje Nara o Ryu-chan mientras sea de nombre diferente al Personaje jugado."
function checkAndTriggerNobukoSP416Play(playedCardId, playedSlotIndex, owner = 'player', testOptions = {}, onDone = null) {
  const isPlayer = owner === 'player';
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;
  const tag = isPlayer ? '[Efecto Nobuko BBX-SP416]' : '[Rival - Efecto Nobuko BBX-SP416]';

  if (!slots || !Array.isArray(slots)) {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const playedCard = cardsDatabase[playedCardId];
  if (!playedCard || playedCard.tipo !== 'Personaje') {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // Buscar slots con Nobuko (BBX-SP416) controlados por este jugador que no hayan usado su efecto este turno y no estén bloqueados
  const eligibleNobukoSlots = [];
  slots.forEach((s, idx) => {
    if (s && s.character === 'BBX-SP416' && !s.usedNobuko416ThisTurn) {
      if (typeof isCharacterEffectBlocked !== 'function' || !isCharacterEffectBlocked(owner, s)) {
        eligibleNobukoSlots.push({ slot: s, index: idx });
      }
    }
  });

  if (eligibleNobukoSlots.length === 0) {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // Deck del jugador que controla a Nobuko
  const deck = isPlayer ? playtestState.deck : playtestState.opponentDeck;
  if (!deck || !Array.isArray(deck) || deck.length === 0) {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // Buscar en el deck: 1 Personaje Nara o Ryu-chan mientras sea de nombre diferente al Personaje jugado
  const eligibleDeckTargets = [];
  deck.forEach((cId, dIdx) => {
    const c = cardsDatabase[cId];
    if (c && c.tipo === 'Personaje' && (c.nombre.includes('Nara') || c.nombre.includes('Ryu-chan')) && c.nombre !== playedCard.nombre) {
      eligibleDeckTargets.push({
        id: cId,
        index: dIdx,
        name: c.nombre,
        text: `"${c.nombre}" (${cId})`
      });
    }
  });

  // Strict Visibility: Si no hay objetivos válidos en el deck, no mostrar prompt
  if (eligibleDeckTargets.length === 0) {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // Usamos el primer slot elegible de Nobuko
  const activeNobukoSlot = eligibleNobukoSlots[0].slot;

  const applySearch = (chosenCardId) => {
    const actualDeckIdx = deck.indexOf(chosenCardId);
    if (actualDeckIdx !== -1) {
      deck.splice(actualDeckIdx, 1);
      if (typeof shuffleArray === 'function') {
        shuffleArray(deck);
      }
    }

    const hand = isPlayer ? playtestState.hand : playtestState.opponentHand;
    hand.push(chosenCardId);
    activeNobukoSlot.usedNobuko416ThisTurn = true;

    const chosenCardName = cardsDatabase[chosenCardId]?.nombre || chosenCardId;
    if (isPlayer) {
      addLog(`${tag} Agregaste a <strong>${chosenCardName}</strong> (${chosenCardId}) de tu deck a tu mano y barajaste el deck.`, 'var(--accent-purple)');
    } else {
      addLog(`${tag} El rival agregó a <strong>${chosenCardName}</strong> (${chosenCardId}) de su deck a su mano y barajó su deck.`, 'var(--accent-purple)');
    }

    if (typeof updatePlaytestView === 'function') updatePlaytestView();
    if (typeof onDone === 'function') onDone(true, { cardId: chosenCardId });
  };

  // Manejo de testOptions / skip / auto
  if (testOptions && (testOptions.activate === false || testOptions.skipActivation === true)) {
    addLog(`${tag} ${isPlayer ? 'Decidiste' : 'El rival decidió'} no activar el efecto de Nobuko.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  if (testOptions && (testOptions.chosenCardId !== undefined || testOptions.chosenTargetIndex !== undefined || testOptions.activate === true)) {
    let chosenId = null;
    if (testOptions.chosenCardId !== undefined) {
      const match = eligibleDeckTargets.find(item => item.id === testOptions.chosenCardId);
      chosenId = match ? match.id : eligibleDeckTargets[0].id;
    } else if (testOptions.chosenTargetIndex !== undefined) {
      const match = eligibleDeckTargets[testOptions.chosenTargetIndex];
      chosenId = match ? match.id : eligibleDeckTargets[0].id;
    } else {
      chosenId = eligibleDeckTargets[0].id;
    }
    applySearch(chosenId);
    return;
  }

  // Si es el rival (IA), toma automáticamente el primer objetivo elegible
  if (!isPlayer) {
    applySearch(eligibleDeckTargets[0].id);
    return;
  }

  // Jugador interactivo
  const proceedActivation = () => {
    const chooserTargets = eligibleDeckTargets.map(item => ({
      id: item.id,
      owner: 'player',
      text: item.text
    }));

    if (typeof openCardChooserModal === 'function') {
      openCardChooserModal(
        chooserTargets,
        `Nobuko (SP416): Selecciona 1 Personaje para agregar a tu mano`,
        (chosenIdx) => {
          const picked = eligibleDeckTargets[chosenIdx] || eligibleDeckTargets[0];
          applySearch(picked.id);
        },
        () => {
          addLog(`${tag} Decidiste no activar el efecto de Nobuko.`, 'var(--text-muted)');
          if (typeof updatePlaytestView === 'function') updatePlaytestView();
          if (typeof onDone === 'function') onDone(false);
        }
      );
    } else {
      applySearch(eligibleDeckTargets[0].id);
    }
  };

  const items = [
    {
      text: "🔍 Activar Nobuko: Agregar 1 Personaje Nara o Ryu-chan a tu mano",
      action: () => {
        proceedActivation();
      }
    },
    {
      text: "❌ No activar efecto de Nobuko",
      action: () => {
        addLog(`${tag} Decidiste no activar el efecto de Nobuko.`, 'var(--text-muted)');
        if (typeof updatePlaytestView === 'function') updatePlaytestView();
        if (typeof onDone === 'function') onDone(false);
      }
    }
  ];

  const dummyEvent = {
    clientX: typeof window !== 'undefined' ? window.innerWidth / 2 - 120 : 0,
    clientY: typeof window !== 'undefined' ? window.innerHeight / 2 - 80 : 0
  };
  if (typeof showContextMenu === 'function') {
    showContextMenu(dummyEvent, items);
  } else {
    proceedActivation();
  }
}
if (typeof window !== 'undefined') {
  window.checkAndTriggerNobukoSP416Play = checkAndTriggerNobukoSP416Play;
}

// Dominio del juego (BBX-SP418): "Solo puede ser portada por \"Void-oh\"\n\nRevela las 8 primeras cartas del tope del deck de tu adversario, si revelaste al menos 3 Skills que puedan ser portadas a 1 Personaje que tu adversario controle, portaselas (tú eliges), entonces baraja al deck el Personaje que porte esta Skill. Solo puedes usar este efecto de \"Dominio del juego\" una vez por turno."
function executeDominioDelJuegoSP418(activatorOwner = 'player', slotIndex, skIndex, testOptions = {}, onDone = null) {
  const isPlayer = activatorOwner === 'player';
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;
  const oppSlots = isPlayer ? playtestState.opponentSlots : playtestState.slots;
  const myDeck = isPlayer ? playtestState.deck : playtestState.opponentDeck;
  const oppDeck = isPlayer ? playtestState.opponentDeck : playtestState.deck;
  const myGrave = isPlayer ? playtestState.grave : playtestState.opponentGrave;
  const slot = slots ? slots[slotIndex] : null;

  if (!slot || !slot.character) {
    if (typeof onDone === 'function') onDone(false, { reason: 'no_slot_character' });
    return;
  }

  const effectiveSkIndex = typeof skIndex === 'number'
    ? skIndex
    : (slot.skills ? slot.skills.indexOf('BBX-SP418') : -1);

  if (effectiveSkIndex === -1 || !slot.skills || slot.skills[effectiveSkIndex] !== 'BBX-SP418') {
    if (typeof onDone === 'function') onDone(false, { reason: 'not_equipped' });
    return;
  }

  const tag = isPlayer ? '[Efecto Dominio del juego BBX-SP418]' : '[Rival - Efecto Dominio del juego BBX-SP418]';

  // 1. Requisito previo: El adversario debe controlar al menos 1 Personaje en su campo
  const oppHasCharacter = (oppSlots || []).some(s => s && s.character);
  if (!oppHasCharacter) {
    if (typeof onDone === 'function') onDone(false, { reason: 'no_opponent_characters' });
    return;
  }

  // 2. Requisito previo: El deck del adversario debe contener al menos 8 cartas
  if (!oppDeck || oppDeck.length < 8) {
    if (typeof onDone === 'function') onDone(false, { reason: 'deck_too_small' });
    return;
  }

  // 3. Comprobar Hard Once Per Turn (HOPT)
  const yaUsadoHOPT = isPlayer
    ? !!playtestState.usedDominioDelJuego418ThisTurn
    : !!playtestState.opponentUsedDominioDelJuego418ThisTurn;
  const usedGlobal = isPlayer
    ? (playtestState.usedGlobalEffects || [])
    : (playtestState.opponentUsedGlobalEffects || []);

  if (yaUsadoHOPT || usedGlobal.includes('Dominio del juego') || usedGlobal.includes('BBX-SP418')) {
    if (typeof onDone === 'function') onDone(false, { reason: 'already_used_this_turn' });
    return;
  }

  // 4. Comprobar bloqueo de Skill
  if (typeof isSkillEffectBlocked === 'function' && isSkillEffectBlocked('BBX-SP418', activatorOwner, slot)) {
    if (typeof onDone === 'function') onDone(false, { reason: 'blocked' });
    return;
  }

  // 5. Marcar HOPT
  if (isPlayer) {
    playtestState.usedDominioDelJuego418ThisTurn = true;
    playtestState.usedGlobalEffects = playtestState.usedGlobalEffects || [];
    playtestState.usedGlobalEffects.push('Dominio del juego');
    playtestState.usedGlobalEffects.push('BBX-SP418');
  } else {
    playtestState.opponentUsedDominioDelJuego418ThisTurn = true;
    playtestState.opponentUsedGlobalEffects = playtestState.opponentUsedGlobalEffects || [];
    playtestState.opponentUsedGlobalEffects.push('Dominio del juego');
    playtestState.opponentUsedGlobalEffects.push('BBX-SP418');
  }

  if (slot) {
    slot.usedSkills = slot.usedSkills || [];
    slot.usedSkillIndexes = slot.usedSkillIndexes || [];
    if (!slot.usedSkills.includes('BBX-SP418')) slot.usedSkills.push('BBX-SP418');
    if (!slot.usedSkillIndexes.includes(effectiveSkIndex)) slot.usedSkillIndexes.push(effectiveSkIndex);
  }
  if (typeof registerSkillActivation === 'function') {
    registerSkillActivation('BBX-SP418', activatorOwner);
  }

  // 6. Revelar las 8 primeras cartas del tope del deck del adversario
  const revealedCards = oppDeck.slice(0, 8);
  const revealedNames = revealedCards.map(id => cardsDatabase[id]?.nombre || id).join(', ');
  addLog(`${tag} Reveló las 8 primeras cartas del tope del deck del adversario: <strong>${revealedNames}</strong>.`, 'var(--accent-purple)');

  // 7. Evaluar compatibilidad con cada Personaje rival en campo
  const canEquipDeck = typeof canEquipFromZone === 'function' ? canEquipFromZone('deck', 'BBX-SP418') : true;

  const candidateMap = {}; // oppSlotIdx -> array of skill card IDs from revealedCards
  const eligibleOppSlotIndexes = [];

  if (canEquipDeck) {
    oppSlots.forEach((s, sIdx) => {
      if (!s || !s.character) return;
      const charCard = cardsDatabase[s.character];
      if (!charCard) return;

      const compatible = [];
      revealedCards.forEach((cid) => {
        const cData = cardsDatabase[cid];
        if (!cData || cData.tipo !== 'Skill') return;

        // Comprobar si equipar desde deck está bloqueado para esta skill específica
        if (typeof canEquipFromZone === 'function' && !canEquipFromZone('deck', cid)) return;

        const isNeutral = !cData.portador || cData.portador === 'Cualquiera' || cData.portador === 'Cualquier Personaje' || cData.portador.trim() === '';
        const isMatch = isNeutral || (typeof isCarrierMatch === 'function' && isCarrierMatch(cData.portador, charCard));

        if (isMatch) {
          compatible.push(cid);
        }
      });

      candidateMap[sIdx] = compatible;
      if (compatible.length >= 3) {
        eligibleOppSlotIndexes.push(sIdx);
      }
    });
  }

  // Barajado del resto del deck rival ("el resto se baraja al deck")
  const finishShuffleOppDeck = () => {
    if (typeof shuffleArray === 'function') shuffleArray(oppDeck);
    if (typeof checkAndTriggerInestabilidad === 'function') {
      checkAndTriggerInestabilidad(isPlayer ? 'opponent' : 'player');
    }
  };

  // CASO: Condición NO cumplida (menos de 3 Skills compatibles con ningún Personaje rival)
  if (eligibleOppSlotIndexes.length === 0) {
    addLog(`${tag} No se encontraron al menos 3 Skills compatibles con ningún Personaje del adversario. Las cartas se barajan al deck.`, 'var(--text-muted)');
    finishShuffleOppDeck();
    if (typeof updatePlaytestView === 'function') updatePlaytestView();
    if (typeof onDone === 'function') onDone(true, { success: false, reason: 'condition_not_met', revealedCards });
    return;
  }

  // CASO: Condición SÍ cumplida
  const applyDominioResolution = (targetSlotIdx, chosen3Skills) => {
    const targetSlot = oppSlots[targetSlotIdx];
    if (!targetSlot || !targetSlot.character) {
      finishShuffleOppDeck();
      if (typeof updatePlaytestView === 'function') updatePlaytestView();
      if (typeof onDone === 'function') onDone(false, { reason: 'target_slot_invalid' });
      return;
    }

    const targetCharCard = cardsDatabase[targetSlot.character];
    const targetCharName = targetCharCard ? targetCharCard.nombre : `Slot ${targetSlotIdx + 1}`;

    // 1. Portar las 3 Skills seleccionadas al Personaje rival
    targetSlot.skills = targetSlot.skills || [];
    chosen3Skills.forEach(skId => {
      const idxInDeck = oppDeck.indexOf(skId);
      if (idxInDeck !== -1) {
        oppDeck.splice(idxInDeck, 1);
      }
      targetSlot.skills.push(skId);
    });

    const equippedNames = chosen3Skills.map(id => cardsDatabase[id]?.nombre || id).join(', ');
    addLog(`${tag} Se portaron 3 Skills a <strong>${targetCharName}</strong> del adversario: <strong>${equippedNames}</strong>.`, 'var(--accent-purple)');

    // 2. "el resto se baraja al deck"
    finishShuffleOppDeck();
    addLog(`${tag} Las cartas restantes del adversario se barajaron a su deck.`, 'var(--text-muted)');

    // 3. "entonces baraja al deck el Personaje que porte esta Skill"
    const activatingSlot = slots[slotIndex];
    if (activatingSlot && activatingSlot.character) {
      const charId = activatingSlot.character;
      const charName = cardsDatabase[charId]?.nombre || 'Personaje';
      const removedSkills = [...(activatingSlot.skills || [])];

      // Sus Skills van al cementerio propio
      removedSkills.forEach(sk => {
        myGrave.push(sk);
        if (typeof checkAndTriggerReflejo === 'function') checkAndTriggerReflejo(sk);
        if (typeof checkAndTriggerTageroSP176 === 'function') checkAndTriggerTageroSP176(sk, isPlayer);
        if (typeof checkAndTriggerFulgorOfensivo === 'function') checkAndTriggerFulgorOfensivo(sk);
      });
      if (typeof notifySkillsRemovedByEffect === 'function') {
        notifySkillsRemovedByEffect(removedSkills, activatorOwner);
      }

      // Limpiar slot propio
      activatingSlot.character = null;
      activatingSlot.skills = [];
      activatingSlot.usedSkills = [];
      activatingSlot.usedSkillIndexes = [];
      activatingSlot.isRotated = false;
      activatingSlot.effectUsed = false;

      // Barajar el Personaje al deck propio
      myDeck.push(charId);
      if (typeof shuffleArray === 'function') shuffleArray(myDeck);
      if (typeof checkAndTriggerInestabilidad === 'function') {
        checkAndTriggerInestabilidad(activatorOwner);
      }

      addLog(`${tag} <strong>${charName}</strong> fue barajado a tu deck y sus Skills portadas fueron enviadas al cementerio.`, 'var(--accent-purple)');
    }

    if (typeof updatePlaytestView === 'function') updatePlaytestView();
    if (typeof onDone === 'function') onDone(true, {
      success: true,
      targetSlotIndex: targetSlotIdx,
      equippedSkills: chosen3Skills
    });
  };

  // Modo testOptions o IA automática
  if (testOptions && (testOptions.targetSlotIndex !== undefined || testOptions.chosenSkills !== undefined)) {
    const targetIdx = testOptions.targetSlotIndex !== undefined ? testOptions.targetSlotIndex : eligibleOppSlotIndexes[0];
    const available = candidateMap[targetIdx] || [];
    const skillsToEquip = (Array.isArray(testOptions.chosenSkills) && testOptions.chosenSkills.length === 3)
      ? testOptions.chosenSkills
      : available.slice(0, 3);
    applyDominioResolution(targetIdx, skillsToEquip);
    return;
  }

  if (!isPlayer) {
    // IA del rival
    const targetIdx = eligibleOppSlotIndexes[0];
    const skillsToEquip = (candidateMap[targetIdx] || []).slice(0, 3);
    applyDominioResolution(targetIdx, skillsToEquip);
    return;
  }

  // Jugador Humano
  const proceedToPickSkillsForSlot = (targetSlotIdx) => {
    const available = candidateMap[targetSlotIdx] || [];
    if (available.length === 3) {
      applyDominioResolution(targetSlotIdx, available);
      return;
    }

    if (typeof openMultiCardChooserModal === 'function') {
      openMultiCardChooserModal(available, "Dominio del juego: Elige 3 Skills para portar al Personaje rival", 3, (selectedSkills) => {
        applyDominioResolution(targetSlotIdx, selectedSkills);
      });
    } else {
      applyDominioResolution(targetSlotIdx, available.slice(0, 3));
    }
  };

  if (eligibleOppSlotIndexes.length === 1) {
    proceedToPickSkillsForSlot(eligibleOppSlotIndexes[0]);
  } else {
    // Más de 1 Personaje elegible: menú para elegir cuál
    const targetOptions = eligibleOppSlotIndexes.map(sIdx => {
      const charName = cardsDatabase[oppSlots[sIdx].character]?.nombre || `Slot ${sIdx + 1}`;
      return {
        text: `👤 Portar a [Slot ${sIdx + 1}] ${charName}`,
        action: () => proceedToPickSkillsForSlot(sIdx)
      };
    });
    const dummyEvent = {
      clientX: typeof window !== 'undefined' ? window.innerWidth / 2 - 120 : 0,
      clientY: typeof window !== 'undefined' ? window.innerHeight / 2 - 60 : 0
    };
    if (typeof showContextMenu === 'function') {
      showContextMenu(dummyEvent, targetOptions);
    } else {
      proceedToPickSkillsForSlot(eligibleOppSlotIndexes[0]);
    }
  }
}
if (typeof window !== 'undefined') {
  window.executeDominioDelJuegoSP418 = executeDominioDelJuegoSP418;
}

// ==========================================
// Contrato (BBX-SP419)
// "Solo puede ser portada por «Void-oh»
// Revela 1 Skill que no sea propia de Void-oh en tu mano, mientras «Contrato» permanezca portada, ningún jugador puede portar o usar los efectos de la Skill revelada en tu mano hasta el final del turno de tu adversario. Solo puedes usar este efecto de «Contrato» una vez por turno."
// ==========================================

function isSkillNotOfVoidOh(cardId) {
  if (!cardId) return false;
  const card = (typeof cardsDatabase !== 'undefined' && cardsDatabase) ? cardsDatabase[cardId] : null;
  if (!card || card.tipo !== 'Skill') return false;
  const portador = (card.portador || '').trim().toLowerCase();
  const nombre = (card.nombre || '').trim().toLowerCase();
  if (portador.includes('void-oh') || nombre.includes('void-oh')) {
    return false;
  }
  return true;
}

function isSkillBlockedByContratoSP419(skillId, checkType = 'all') {
  if (!skillId) return false;
  if (typeof playtestState === 'undefined' || !playtestState || !Array.isArray(playtestState.activeContratosSP419) || playtestState.activeContratosSP419.length === 0) {
    return false;
  }

  const targetCard = (typeof cardsDatabase !== 'undefined' && cardsDatabase) ? cardsDatabase[skillId] : null;
  const targetName = targetCard ? targetCard.nombre : skillId;

  // Filtrar contratos que sigan siendo válidos ("mientras «Contrato» permanezca portada")
  playtestState.activeContratosSP419 = playtestState.activeContratosSP419.filter(c => {
    const slots = (c.slotOwner === 'player') ? playtestState.slots : playtestState.opponentSlots;
    if (!slots) return false;
    const slot = slots[c.slotIndex];
    if (!slot || !slot.character || !Array.isArray(slot.skills)) return false;
    const stillEquipped = slot.skills.some(sk => sk === 'BBX-SP419' || (cardsDatabase && cardsDatabase[sk] && cardsDatabase[sk].nombre === 'Contrato'));
    return stillEquipped;
  });

  for (const c of playtestState.activeContratosSP419) {
    if (skillId === c.revealedCardId || (targetName && targetName === c.blockedSkillName)) {
      return true;
    }
  }
  return false;
}

function updateContratosSP419Expiration(endedTurnOwner) {
  if (typeof playtestState === 'undefined' || !playtestState || !Array.isArray(playtestState.activeContratosSP419) || playtestState.activeContratosSP419.length === 0) {
    if (playtestState) playtestState.activeContratosSP419 = [];
    return;
  }

  const remaining = [];
  for (const c of playtestState.activeContratosSP419) {
    // Si el turno que finalizó es el del adversario del activador, el efecto expira
    if (c.adversary === endedTurnOwner) {
      if (typeof addLog === 'function') {
        addLog(`[Efecto Contrato BBX-SP419] El bloqueo sobre «<strong>${c.blockedSkillName}</strong>» ha finalizado (terminó el turno del adversario).`, 'var(--text-muted)');
      }
    } else {
      remaining.push(c);
    }
  }
  playtestState.activeContratosSP419 = remaining;
}

function executeContratoSP419(activatorOwner = 'player', slotIndex, skIndex, testOptions = {}, onDone = null) {
  const isPlayer = activatorOwner === 'player';
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;
  const oppSlots = isPlayer ? playtestState.opponentSlots : playtestState.slots;
  const hand = isPlayer ? (playtestState.hand || []) : (playtestState.opponentHand || []);
  const slot = slots ? slots[slotIndex] : null;

  if (!slot || !slot.character) {
    if (typeof onDone === 'function') onDone(false, { reason: 'no_slot_character' });
    return;
  }

  const effectiveSkIndex = typeof skIndex === 'number'
    ? skIndex
    : (slot.skills ? slot.skills.indexOf('BBX-SP419') : -1);

  if (effectiveSkIndex === -1 || !slot.skills || (slot.skills[effectiveSkIndex] !== 'BBX-SP419' && (cardsDatabase && cardsDatabase[slot.skills[effectiveSkIndex]]?.nombre !== 'Contrato'))) {
    if (typeof onDone === 'function') onDone(false, { reason: 'not_equipped' });
    return;
  }

  const tag = isPlayer ? '[Efecto Contrato BBX-SP419]' : '[Rival - Efecto Contrato BBX-SP419]';

  // 1. Requisito HOPT
  const yaUsadoHOPT = isPlayer
    ? !!playtestState.usedContrato419ThisTurn
    : !!playtestState.opponentUsedContrato419ThisTurn;
  const usedGlobal = isPlayer
    ? (playtestState.usedGlobalEffects || [])
    : (playtestState.opponentUsedGlobalEffects || []);

  if (yaUsadoHOPT || usedGlobal.includes('Contrato') || usedGlobal.includes('BBX-SP419')) {
    if (isPlayer && typeof alert === 'function') {
      alert("Solo puedes usar este efecto de «Contrato» una vez por turno.");
    }
    if (typeof onDone === 'function') onDone(false, { reason: 'already_used_this_turn' });
    return;
  }

  // 2. Comprobar si el efecto de la Skill está bloqueado
  if (typeof isSkillEffectBlocked === 'function' && isSkillEffectBlocked('BBX-SP419', activatorOwner, slot)) {
    if (isPlayer && typeof alert === 'function') {
      alert("El efecto de «Contrato» está bloqueado.");
    }
    if (typeof onDone === 'function') onDone(false, { reason: 'blocked' });
    return;
  }

  // 3. Requisito: Revelar 1 Skill en mano que no sea propia de Void-oh
  const eligibleCards = hand.filter(cid => isSkillNotOfVoidOh(cid));
  if (eligibleCards.length === 0) {
    if (isPlayer && typeof alert === 'function') {
      alert("No tienes ninguna Skill en tu mano que no sea propia de Void-oh para revelar.");
    }
    if (typeof onDone === 'function') onDone(false, { reason: 'no_eligible_skills_in_hand' });
    return;
  }

  // Resolución del efecto al seleccionar la carta a revelar
  const applyContratoResolution = (revealedCardId) => {
    const revealedCard = cardsDatabase ? cardsDatabase[revealedCardId] : null;
    const revealedName = revealedCard ? revealedCard.nombre : revealedCardId;

    // Marcar HOPT
    if (isPlayer) {
      playtestState.usedContrato419ThisTurn = true;
      playtestState.usedGlobalEffects = playtestState.usedGlobalEffects || [];
      if (!playtestState.usedGlobalEffects.includes('Contrato')) playtestState.usedGlobalEffects.push('Contrato');
      if (!playtestState.usedGlobalEffects.includes('BBX-SP419')) playtestState.usedGlobalEffects.push('BBX-SP419');
    } else {
      playtestState.opponentUsedContrato419ThisTurn = true;
      playtestState.opponentUsedGlobalEffects = playtestState.opponentUsedGlobalEffects || [];
      if (!playtestState.opponentUsedGlobalEffects.includes('Contrato')) playtestState.opponentUsedGlobalEffects.push('Contrato');
      if (!playtestState.opponentUsedGlobalEffects.includes('BBX-SP419')) playtestState.opponentUsedGlobalEffects.push('BBX-SP419');
    }

    if (slot) {
      slot.usedSkills = slot.usedSkills || [];
      slot.usedSkillIndexes = slot.usedSkillIndexes || [];
      if (!slot.usedSkills.includes('BBX-SP419')) slot.usedSkills.push('BBX-SP419');
      if (effectiveSkIndex !== -1 && !slot.usedSkillIndexes.includes(effectiveSkIndex)) {
        slot.usedSkillIndexes.push(effectiveSkIndex);
      }
    }
    if (typeof registerSkillActivation === 'function') {
      registerSkillActivation('BBX-SP419', activatorOwner);
    }

    // Registrar en activeContratosSP419
    playtestState.activeContratosSP419 = playtestState.activeContratosSP419 || [];
    playtestState.activeContratosSP419.push({
      activator: activatorOwner,
      slotOwner: activatorOwner,
      slotIndex: slotIndex,
      revealedCardId: revealedCardId,
      blockedSkillName: revealedName,
      adversary: isPlayer ? 'opponent' : 'player'
    });

    if (typeof addLog === 'function') {
      addLog(`${tag} Reveló de su mano <strong>${revealedName}</strong>. Mientras «Contrato» permanezca portada, ningún jugador puede portar o usar los efectos de «${revealedName}» hasta el final del turno de su adversario.`, 'var(--accent-purple)');
    }

    if (typeof updatePlaytestView === 'function') updatePlaytestView();
    if (typeof onDone === 'function') onDone(true, { success: true, revealedCardId, blockedSkillName: revealedName });
  };

  // Modo testOptions
  if (testOptions && testOptions.revealedCardId) {
    applyContratoResolution(testOptions.revealedCardId);
    return;
  }

  // Turno/IA del Rival
  if (!isPlayer) {
    applyContratoResolution(eligibleCards[0]);
    return;
  }

  // Jugador Humano
  if (eligibleCards.length === 1) {
    applyContratoResolution(eligibleCards[0]);
  } else {
    if (typeof openCardChooserModal === 'function') {
      openCardChooserModal(
        eligibleCards,
        "Contrato: Revela 1 Skill que no sea propia de Void-oh",
        (chosenIdx) => {
          applyContratoResolution(eligibleCards[chosenIdx]);
        },
        () => {
          if (typeof onDone === 'function') onDone(false, { cancelled: true });
        }
      );
    } else {
      applyContratoResolution(eligibleCards[0]);
    }
  }
}

if (typeof window !== 'undefined') {
  window.isSkillNotOfVoidOh = isSkillNotOfVoidOh;
  window.isSkillBlockedByContratoSP419 = isSkillBlockedByContratoSP419;
  window.updateContratosSP419Expiration = updateContratosSP419Expiration;
  window.executeContratoSP419 = executeContratoSP419;
}

// Marina BBX-SP391: Si tu adversario agrega 1 Skill "Mapa" a su mano desde su deck por el efecto de una carta (no incluye robar), puedes enviar al cementerio todas las cartas en su mano.
function checkAndTriggerMarinaSP391(cardAdder = 'player', addedCardId, sourceZone = 'deck', isDraw = false, testOptions = {}, onDone = null) {
  if (!addedCardId) {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 1. Debe provenir del deck
  if (sourceZone !== 'deck') {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 2. No debe ser un robo regular ("no incluye robar")
  if (isDraw === true) {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 3. Debe ser una Skill "Mapa"
  const card = cardsDatabase[addedCardId];
  const isSkillMapa = card && card.tipo === 'Skill' && (card.nombre === 'Mapa' || card.nombre.includes('Mapa') || card.id === 'BBX-SP264');
  if (!isSkillMapa) {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 4. El controlador de Marina es el adversario de quien agregó la carta
  const marinaController = cardAdder === 'player' ? 'opponent' : 'player';
  const isPlayer = marinaController === 'player';
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;

  const activeMarinaSlot = slots.find(s => {
    if (!s || s.character !== 'BBX-SP391') return false;
    if (typeof isCharacterEffectBlocked === 'function' && isCharacterEffectBlocked(marinaController, s)) {
      return false;
    }
    return true;
  });

  if (!activeMarinaSlot) {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 5. La víctima (cardAdder) debe tener cartas en su mano
  const victimHand = cardAdder === 'player' ? playtestState.hand : playtestState.opponentHand;
  if (!victimHand || victimHand.length === 0) {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // Manejo de testOptions para pruebas automatizadas
  if (testOptions && testOptions.activateMarina !== undefined) {
    if (testOptions.activateMarina === false) {
      addLog(`[Marina BBX-SP391 ${isPlayer ? '' : 'Rival'}] Decidió no activar el efecto de Marina.`, 'var(--text-muted)');
      if (typeof onDone === 'function') onDone(false);
      return;
    }
    executeMarinaSP391Activation(marinaController, testOptions, onDone);
    return;
  }

  if (isPlayer) {
    const items = [
      {
        text: `🌊 Activar Marina (SP391): Enviar al cementerio todas las cartas de la mano del rival (${victimHand.length} cartas)`,
        action: () => {
          executeMarinaSP391Activation('player', testOptions, onDone);
        }
      },
      {
        text: `❌ No activar Marina`,
        action: () => {
          addLog(`[Marina BBX-SP391] Decidiste no activar el efecto de Marina.`, 'var(--text-muted)');
          if (typeof onDone === 'function') onDone(false);
        }
      }
    ];
    addLog(`[Trigger Marina BBX-SP391] Tu adversario agregó la Skill <strong>${card.nombre}</strong> a su mano desde su deck por efecto. ¿Deseas activar el efecto de <strong>Marina</strong> para enviar al cementerio todas las cartas en su mano?`, 'var(--accent-cyan)');
    const dummyEvent = { clientX: window.innerWidth / 2 - 150, clientY: window.innerHeight / 2 - 80 };
    showContextMenu(dummyEvent, items);
  } else {
    addLog(`[Trigger Marina BBX-SP391 Rival] Agregaste la Skill <strong>${card.nombre}</strong> a tu mano desde tu deck por efecto. El rival activa a <strong>Marina</strong> para enviar al cementerio todas las cartas en tu mano.`, 'var(--accent-cyan)');
    executeMarinaSP391Activation('opponent', testOptions, onDone);
  }
}

function executeMarinaSP391Activation(marinaController = 'player', testOptions = {}, onDone = null) {
  const isPlayer = marinaController === 'player';
  const victimOwner = isPlayer ? 'opponent' : 'player';
  const victimHand = isPlayer ? playtestState.opponentHand : playtestState.hand;
  const victimGrave = isPlayer ? playtestState.opponentGrave : playtestState.grave;
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;

  const activeMarinaSlot = slots.find(s => {
    if (!s || s.character !== 'BBX-SP391') return false;
    if (typeof isCharacterEffectBlocked === 'function' && isCharacterEffectBlocked(marinaController, s)) {
      return false;
    }
    return true;
  });

  if (!activeMarinaSlot) {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  if (!victimHand || victimHand.length === 0) {
    addLog(`[Efecto Marina BBX-SP391 ${isPlayer ? '' : 'Rival'}] No hay cartas en la mano para enviar al cementerio.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const tag = isPlayer ? '[Efecto Marina BBX-SP391]' : '[Rival - Efecto Marina BBX-SP391]';
  const discardedCards = victimHand.splice(0, victimHand.length);

  discardedCards.forEach(cardId => {
    victimGrave.push(cardId);
    if (typeof dispatchGraveTriggers === 'function') {
      dispatchGraveTriggers(cardId, victimOwner, { fromZone: 'hand', byEffect: true });
    }
    if (typeof checkAndTriggerRemembranza === 'function') {
      checkAndTriggerRemembranza(cardId, victimOwner);
    }
    if (typeof checkAndTriggerHoraDelTe === 'function') {
      checkAndTriggerHoraDelTe(cardId, victimOwner);
    }
    if (typeof checkAndTriggerMarinaSP410 === 'function') {
      checkAndTriggerMarinaSP410(cardId, marinaController, victimOwner);
    }
  });

  const cardNames = discardedCards.map(id => cardsDatabase[id]?.nombre || id).join(', ');
  addLog(`${tag} Se enviaron al cementerio todas las cartas en la mano de ${isPlayer ? 'tu adversario' : 'el jugador'} (${discardedCards.length} cartas): ${cardNames}.`, 'var(--accent-purple)');

  if (typeof updatePlaytestView === 'function') updatePlaytestView();
  if (typeof onDone === 'function') onDone(true);
}

// Nara BBX-SP392: Al final del turno de cualquier jugador, puedes enviar esta carta en tu mano al cementerio, tu adversario roba 1 carta de su deck and entonces agrega a tu mano desde tu deck 1 Personaje Ryu-chan, Nobuko o Fredlard.
function checkNaraSP392OrProceed(nextCallback) {
  const proceed = () => {
    if (typeof nextCallback === 'function') nextCallback();
  };

  const isPlayerHandBlocked = typeof isCharacterHandEffectBlocked === 'function' && isCharacterHandEffectBlocked('player');
  const isOppDrawBlocked = playtestState.opponentCannotDrawByEffectsThisTurn || (typeof isDrawByCharacterBlocked === 'function' && isDrawByCharacterBlocked('opponent', 1));
  const oppCanDraw = playtestState.opponentDeck && playtestState.opponentDeck.length >= 1 && !isOppDrawBlocked;
  const isTargetChar = (id) => {
    const c = cardsDatabase[id];
    return c && c.tipo === 'Personaje' && (c.nombre.includes('Ryu-chan') || c.nombre.includes('Nobuko') || c.nombre.includes('Fredlard'));
  };
  const playerTargets = (playtestState.deck || []).filter(isTargetChar);
  const canPlayerActivate = (playtestState.hand || []).includes('BBX-SP392') && !isPlayerHandBlocked && oppCanDraw && playerTargets.length > 0;

  const checkOpponentNara = () => {
    if (playtestState.isOnlineMatch) {
      proceed();
      return;
    }
    const isOppHandBlocked = typeof isCharacterHandEffectBlocked === 'function' && isCharacterHandEffectBlocked('opponent');
    const isPlayerDrawBlocked = playtestState.cannotDrawByEffectsThisTurn || (typeof isDrawByCharacterBlocked === 'function' && isDrawByCharacterBlocked('player', 1));
    const playerCanDraw = playtestState.deck && playtestState.deck.length >= 1 && !isPlayerDrawBlocked;
    const oppTargets = (playtestState.opponentDeck || []).filter(isTargetChar);
    const canOppActivate = (playtestState.opponentHand || []).includes('BBX-SP392') && !isOppHandBlocked && playerCanDraw && oppTargets.length > 0;

    if (canOppActivate) {
      executeNaraSP392Activation('opponent', -1, {}, () => {
        proceed();
      });
      return;
    }
    proceed();
  };

  if (canPlayerActivate) {
    const items = [
      {
        text: "⚡ Activar Nara (SP392) desde la Mano (Rival roba 1, buscas 1 Ryu-chan/Nobuko/Fredlard)",
        action: () => {
          executeNaraSP392Activation('player', -1, {}, () => {
            checkOpponentNara();
          });
        }
      },
      {
        text: "💥 No activar Nara (SP392)",
        action: () => {
          checkOpponentNara();
        }
      }
    ];
    addLog(`[Trigger] Puedes activar el efecto de mano de <strong>Nara (SP392)</strong> al final del turno.`, 'var(--accent-cyan)');
    const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
    showContextMenu(dummyEvent, items, () => {
      checkOpponentNara();
    });
    return;
  }

  checkOpponentNara();
}
window.checkNaraSP392OrProceed = checkNaraSP392OrProceed;

function executeNaraSP392Activation(activatorOwner = 'player', handIndex = -1, testOptions = {}, onDone = null) {
  const isPlayer = activatorOwner === 'player';
  const adversaryOwner = isPlayer ? 'opponent' : 'player';
  const myHand = isPlayer ? playtestState.hand : playtestState.opponentHand;
  const myGrave = isPlayer ? playtestState.grave : playtestState.opponentGrave;
  const myDeck = isPlayer ? playtestState.deck : playtestState.opponentDeck;
  const advHand = isPlayer ? playtestState.opponentHand : playtestState.hand;
  const advDeck = isPlayer ? playtestState.opponentDeck : playtestState.deck;

  const tag = isPlayer ? '[Efecto Nara BBX-SP392]' : '[Rival - Efecto Nara BBX-SP392]';

  // 1. Verificar presencia de BBX-SP392 en mano
  const cIdx = (handIndex >= 0 && myHand[handIndex] === 'BBX-SP392')
    ? handIndex
    : myHand.indexOf('BBX-SP392');

  if (cIdx === -1) {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 2. Verificar bloqueo de efectos en mano
  if (typeof isCharacterHandEffectBlocked === 'function' && isCharacterHandEffectBlocked(activatorOwner)) {
    addLog(`${tag} No se puede activar: Los efectos de Personajes en mano están bloqueados.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 3. Verificar que el adversario PUEDA robar 1 carta (mazo >= 1 y sin restricción de robo)
  const advCannotDraw = isPlayer
    ? !!playtestState.opponentCannotDrawByEffectsThisTurn
    : !!playtestState.cannotDrawByEffectsThisTurn;
  const advCharDrawBlocked = typeof isDrawByCharacterBlocked === 'function' && isDrawByCharacterBlocked(adversaryOwner, 1);

  if (!advDeck || advDeck.length === 0 || advCannotDraw || advCharDrawBlocked) {
    addLog(`${tag} No se puede activar: El adversario no puede robar cartas de su deck (mazo vacío o restricción de robo activa).`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 4. Verificar objetivos válidos en el mazo propio (Ryu-chan, Nobuko o Fredlard)
  const isTargetChar = (id) => {
    const c = cardsDatabase[id];
    return c && c.tipo === 'Personaje' && (c.nombre.includes('Ryu-chan') || c.nombre.includes('Nobuko') || c.nombre.includes('Fredlard'));
  };

  const eligibleInDeck = (myDeck || []).filter(isTargetChar);
  if (eligibleInDeck.length === 0) {
    addLog(`${tag} No se puede activar: No hay ningún Personaje Ryu-chan, Nobuko ni Fredlard en tu deck.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // Costo: enviar Nara de la mano al cementerio
  const discardedId = myHand.splice(cIdx, 1)[0];
  myGrave.push(discardedId);
  addLog(`${tag} ${isPlayer ? 'Enviaste' : 'El rival envió'} a <strong>Nara</strong> de su mano al cementerio como costo.`, 'var(--accent-purple)');

  if (typeof dispatchGraveTriggers === 'function') {
    dispatchGraveTriggers(discardedId, activatorOwner, { fromZone: 'hand', byEffect: true });
  }
  if (typeof checkAndTriggerRemembranza === 'function') {
    checkAndTriggerRemembranza(discardedId, activatorOwner);
  }

  // Paso 1: Adversario roba 1 carta de su deck
  const drawnId = advDeck.shift();
  advHand.push(drawnId);
  const drawnName = cardsDatabase[drawnId]?.nombre || drawnId;
  addLog(`${tag} ${isPlayer ? 'Tu adversario robó' : 'Robaste'} 1 carta de su deck${isPlayer ? '' : ` (<strong>${drawnName}</strong>)`}.`, 'var(--accent-purple)');

  // Paso 2: Agregar a la mano 1 Personaje Ryu-chan, Nobuko o Fredlard desde tu deck
  const resolveAddCharacter = (chosenId) => {
    const dIdx = myDeck.indexOf(chosenId);
    if (dIdx !== -1) {
      myDeck.splice(dIdx, 1);
    }
    myHand.push(chosenId);
    if (typeof shuffleArray === 'function') {
      shuffleArray(myDeck);
    }
    const charName = cardsDatabase[chosenId]?.nombre || chosenId;
    addLog(`${tag} ${isPlayer ? 'Agregaste' : 'El rival agregó'} a <strong>${charName}</strong> a su mano desde su deck y barajó su mazo.`, 'var(--accent-purple)');

    if (typeof checkAndTriggerInestabilidad === 'function') {
      checkAndTriggerInestabilidad(activatorOwner);
    }
    if (typeof updatePlaytestView === 'function') updatePlaytestView();
    if (typeof onDone === 'function') onDone(true);
  };

  // Re-evaluar disponibles
  const freshEligible = (myDeck || []).filter(isTargetChar);
  if (freshEligible.length === 0) {
    if (typeof shuffleArray === 'function') shuffleArray(myDeck);
    addLog(`${tag} Ya no hay objetivos válidos en el deck. Se barajó el mazo.`, 'var(--text-muted)');
    if (typeof updatePlaytestView === 'function') updatePlaytestView();
    if (typeof onDone === 'function') onDone(true);
    return;
  }

  if (testOptions && testOptions.chosenCardId !== undefined) {
    const chosen = freshEligible.includes(testOptions.chosenCardId) ? testOptions.chosenCardId : freshEligible[0];
    resolveAddCharacter(chosen);
    return;
  }
  if (testOptions && testOptions.chosenCardIndex !== undefined) {
    const chosen = freshEligible[testOptions.chosenCardIndex] || freshEligible[0];
    resolveAddCharacter(chosen);
    return;
  }

  if (!isPlayer) {
    resolveAddCharacter(freshEligible[0]);
  } else if (typeof openCardChooserModal === 'function') {
    const chooserTargets = freshEligible.map(id => ({ id, owner: 'player', from: 'deck' }));
    openCardChooserModal(chooserTargets, "Nara (SP392): Selecciona 1 Personaje Ryu-chan, Nobuko o Fredlard para agregar a tu mano", (chosenIdx) => {
      const chosen = freshEligible[chosenIdx] || freshEligible[0];
      resolveAddCharacter(chosen);
    });
  } else {
    resolveAddCharacter(freshEligible[0]);
  }
}

let lastInermeSP355TriggerTime = 0;
function checkAndTriggerInermeSP355(cardId, owner = 'player', ctx = {}) {
  if (cardId !== 'BBX-SP355') return;
  const isPlayer = owner === 'player';

  const now = Date.now();
  if (now - lastInermeSP355TriggerTime < 250) return;
  lastInermeSP355TriggerTime = now;

  // Comprobar HOPG (Hard Once Per Game)
  const yaUsadoPartida = isPlayer
    ? (playtestState.usedInerme355ThisGame || (playtestState.usedPerGameEffects || []).includes('BBX-SP355') || (playtestState.usedPerGameEffects || []).includes('¡Inerme!'))
    : (playtestState.opponentUsedInerme355ThisGame || (playtestState.opponentUsedPerGameEffects || []).includes('BBX-SP355') || (playtestState.opponentUsedPerGameEffects || []).includes('¡Inerme!'));

  if (yaUsadoPartida) {
    addLog(`[Efecto ¡Inerme! BBX-SP355${isPlayer ? '' : ' Rival'}] Ya se utilizó el efecto de "¡Inerme!" una vez en esta partida.`, 'var(--text-muted)');
    return;
  }

  // Comprobar bloqueo de efectos en cementerio
  if (typeof isCardGraveEffectBlocked === 'function' && isCardGraveEffectBlocked(owner, cardId)) {
    addLog(`[Efecto ¡Inerme! BBX-SP355${isPlayer ? '' : ' Rival'}] Los efectos de cartas en el cementerio están bloqueados.`, 'var(--text-muted)');
    return;
  }

  // Buscar Personajes Lyna que controle
  const targetSlots = isPlayer ? playtestState.slots : playtestState.opponentSlots;
  const lynaSlots = [];
  targetSlots.forEach((s, idx) => {
    if (s.character && cardsDatabase[s.character] && cardsDatabase[s.character].nombre.includes("Lyna")) {
      lynaSlots.push({ slot: s, index: idx, name: cardsDatabase[s.character].nombre });
    }
  });

  if (lynaSlots.length === 0) {
    addLog(`[Efecto ¡Inerme! BBX-SP355${isPlayer ? '' : ' Rival'}] Enviada al cementerio por efecto de una carta, pero no controlas ningún Personaje Lyna en tu campo.`, 'var(--text-muted)');
    return;
  }

  const applyProtection = (slotIdx) => {
    if (isPlayer) {
      playtestState.usedInerme355ThisGame = true;
      playtestState.usedPerGameEffects = playtestState.usedPerGameEffects || [];
      playtestState.usedPerGameEffects.push('BBX-SP355');
    } else {
      playtestState.opponentUsedInerme355ThisGame = true;
      playtestState.opponentUsedPerGameEffects = playtestState.opponentUsedPerGameEffects || [];
      playtestState.opponentUsedPerGameEffects.push('BBX-SP355');
    }

    const targetSlot = targetSlots[slotIdx];
    targetSlot.cannotBeDestroyedByBattleUntilTurnEnd = true;

    const lynaName = cardsDatabase[targetSlot.character].nombre;
    addLog(`[Efecto ¡Inerme! BBX-SP355${isPlayer ? '' : ' Rival'}] <strong>${lynaName}</strong> (${isPlayer ? 'Slot ' : 'Rival Slot '}${slotIdx + 1}) no puede ser destruido por una batalla por el resto de este turno.`, isPlayer ? 'var(--accent-cyan)' : 'var(--accent-purple)');

    if (typeof notifySkillInGraveEffectUsed === 'function') {
      notifySkillInGraveEffectUsed(owner);
    }
    updatePlaytestView();
  };

  if (isPlayer) {
    const items = [];
    if (lynaSlots.length === 1) {
      items.push({
        text: `🛡️ Activar ¡Inerme! (Proteger a ${lynaSlots[0].name} contra destrucción por batalla)`,
        action: () => applyProtection(lynaSlots[0].index)
      });
    } else {
      lynaSlots.forEach(l => {
        items.push({
          text: `🛡️ Proteger a ${l.name} (Slot ${l.index + 1}) contra destrucción por batalla`,
          action: () => applyProtection(l.index)
        });
      });
    }
    items.push({
      text: `❌ No activar ¡Inerme!`,
      action: () => {
        addLog(`[Efecto ¡Inerme! BBX-SP355] Decidiste no activar su efecto.`, 'var(--text-muted)');
        updatePlaytestView();
      }
    });

    addLog(`[Trigger ¡Inerme!] Se envió <strong>¡Inerme! (BBX-SP355)</strong> al cementerio por efecto de una carta: puedes activar su efecto para proteger a 1 Lyna.`, 'var(--accent-cyan)');
    const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
    showContextMenu(dummyEvent, items);
  } else {
    const items = [];
    if (lynaSlots.length === 1) {
      items.push({
        text: `🛡️ [RIVAL] Activar ¡Inerme! (Proteger a ${lynaSlots[0].name} rival)`,
        action: () => applyProtection(lynaSlots[0].index)
      });
    } else {
      lynaSlots.forEach(l => {
        items.push({
          text: `🛡️ [RIVAL] Proteger a ${l.name} rival (Slot ${l.index + 1})`,
          action: () => applyProtection(l.index)
        });
      });
    }
    items.push({
      text: `❌ [RIVAL] No activar ¡Inerme!`,
      action: () => {
        addLog(`[Efecto ¡Inerme! BBX-SP355 Rival] Se decidió no activar el efecto de ¡Inerme! rival.`, 'var(--text-muted)');
        updatePlaytestView();
      }
    });

    addLog(`[Trigger Rival ¡Inerme!] Se envió <strong>¡Inerme! (BBX-SP355)</strong> al cementerio rival por efecto de una carta: puedes activar su efecto.`, 'var(--accent-purple)');
    const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
    showContextMenu(dummyEvent, items);
  }
}

// Descifrar ruta (BBX-SP375): "Si esta Skill portada es enviada al cementerio por el efecto de una carta, puedes agregar a tu mano desde tu deck 1 Personaje Haruka. Solo puedes usar este efecto de \"Descifrar ruta\" una vez por turno."
let lastDescifrarRutaTriggerTime = 0;
let lastDescifrarRutaOpponentTriggerTime = 0;

function checkAndTriggerDescifrarRutaSP375(cardId, owner = 'player', ctx = {}, testOptions = {}, onDone = null) {
  if (cardId !== 'BBX-SP375') return;

  // Debe haber estado portada en el campo y haber sido enviada por el efecto de una carta (destrucción por batalla NO cuenta)
  if (!ctx || ctx.isEquipped !== true || ctx.byEffect === false) return;

  const isPlayer = owner === 'player';
  const now = Date.now();
  const skipDebounce = testOptions && (testOptions.autoAccept !== undefined || testOptions.skipDebounce);
  if (!skipDebounce) {
    if (isPlayer) {
      if (now - lastDescifrarRutaTriggerTime < 250) return;
      lastDescifrarRutaTriggerTime = now;
    } else {
      if (now - lastDescifrarRutaOpponentTriggerTime < 250) return;
      lastDescifrarRutaOpponentTriggerTime = now;
    }
  }

  // Comprobar Hard Once Per Turn (HOPT)
  const usedGlobal = isPlayer
    ? (playtestState.usedGlobalEffects || [])
    : (playtestState.opponentUsedGlobalEffects || []);

  if (usedGlobal.includes('Descifrar ruta') || usedGlobal.includes('BBX-SP375')) {
    addLog(`[Efecto Descifrar ruta BBX-SP375${isPlayer ? '' : ' Rival'}] Ya se utilizó el efecto de "Descifrar ruta" este turno (Límite 1 vez por turno).`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone();
    return;
  }

  // Comprobar bloqueo de efectos en cementerio (Anhelo, Secretos de Fafnirland, etc.)
  if (typeof isCardGraveEffectBlocked === 'function' && isCardGraveEffectBlocked(owner, cardId)) {
    addLog(`[Efecto Descifrar ruta BBX-SP375${isPlayer ? '' : ' Rival'}] Los efectos de cartas en el cementerio están bloqueados.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone();
    return;
  }

  // Buscar Personajes Haruka en el deck correspondiente
  const currentDeck = isPlayer ? playtestState.deck : playtestState.opponentDeck;
  const candidates = currentDeck.filter(id => cardsDatabase[id]?.tipo === 'Personaje' && cardsDatabase[id]?.nombre?.includes("Haruka"));

  if (candidates.length === 0) {
    addLog(`[Efecto Descifrar ruta BBX-SP375${isPlayer ? '' : ' Rival'}] Enviada portada al cementerio por efecto de una carta, pero no hay ningún Personaje Haruka en ${isPlayer ? 'tu deck' : 'el deck rival'}.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone();
    return;
  }

  const resolveAddHaruka = (chosenCardId) => {
    const deckRef = isPlayer ? playtestState.deck : playtestState.opponentDeck;
    const idx = deckRef.indexOf(chosenCardId);
    if (idx !== -1) {
      deckRef.splice(idx, 1);
      if (isPlayer) {
        playtestState.hand.push(chosenCardId);
      } else {
        playtestState.opponentHand.push(chosenCardId);
      }
    }

    if (isPlayer) {
      playtestState.usedGlobalEffects = playtestState.usedGlobalEffects || [];
      playtestState.usedGlobalEffects.push('Descifrar ruta');
    } else {
      playtestState.opponentUsedGlobalEffects = playtestState.opponentUsedGlobalEffects || [];
      playtestState.opponentUsedGlobalEffects.push('Descifrar ruta');
    }

    // Se baraja el deck tras extraer la carta (regla oficial)
    if (typeof shuffleArray === 'function') {
      shuffleArray(deckRef);
    }

    const cardName = cardsDatabase[chosenCardId]?.nombre || chosenCardId;
    addLog(`[Efecto Descifrar ruta BBX-SP375${isPlayer ? '' : ' Rival'}] Agregaste a <strong>${cardName}</strong> a ${isPlayer ? 'tu mano' : 'su mano'} desde el deck y barajaste el mazo.`, isPlayer ? 'var(--accent-purple)' : 'var(--accent-danger)');

    if (typeof checkAndTriggerInestabilidad === 'function') {
      checkAndTriggerInestabilidad(owner);
    }
    if (typeof notifySkillInGraveEffectUsed === 'function') {
      notifySkillInGraveEffectUsed(owner);
    }
    if (typeof updatePlaytestView === 'function') {
      updatePlaytestView();
    }
    if (typeof onDone === 'function') {
      onDone();
    }
  };

  // Soporte para pruebas automatizadas
  if (testOptions && testOptions.autoAccept !== undefined) {
    if (testOptions.autoAccept === false) {
      addLog(`[Efecto Descifrar ruta BBX-SP375${isPlayer ? '' : ' Rival'}] Decidiste no activar el efecto de Descifrar ruta.`, 'var(--text-muted)');
      if (typeof onDone === 'function') onDone();
      return;
    }
    const chosenIdx = testOptions.chosenCandidateIndex !== undefined ? testOptions.chosenCandidateIndex : 0;
    resolveAddHaruka(candidates[chosenIdx] || candidates[0]);
    return;
  }

  if (isPlayer) {
    const items = [
      {
        text: `⚡ Activar Descifrar ruta (Agregar 1 Haruka desde el deck a la mano)`,
        action: () => {
          if (typeof openCardChooserModal === 'function') {
            const chooserTargets = candidates.map(id => ({
              id: id,
              owner: 'player',
              from: 'deck',
              text: cardsDatabase[id]?.nombre || id
            }));
            openCardChooserModal(chooserTargets, "Descifrar ruta: Selecciona 1 Personaje Haruka para agregar a tu mano", (chosenIdx) => {
              const chosenId = chooserTargets[chosenIdx] ? chooserTargets[chosenIdx].id : candidates[chosenIdx];
              resolveAddHaruka(chosenId);
            });
          } else {
            resolveAddHaruka(candidates[0]);
          }
        }
      },
      {
        text: `❌ No activar Descifrar ruta`,
        action: () => {
          addLog(`[Efecto Descifrar ruta BBX-SP375] Decidiste no activar el efecto de Descifrar ruta.`, 'var(--text-muted)');
          if (typeof updatePlaytestView === 'function') updatePlaytestView();
          if (typeof onDone === 'function') onDone();
        }
      }
    ];

    addLog(`[Trigger Descifrar ruta] Se envió <strong>Descifrar ruta (BBX-SP375)</strong> portada al cementerio por efecto de una carta: puedes agregar 1 Personaje Haruka de tu deck a tu mano.`, 'var(--accent-cyan)');
    const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
    showContextMenu(dummyEvent, items);
  } else {
    const items = [
      {
        text: `⚡ [Rival] Activar Descifrar ruta (Agregar 1 Haruka del deck rival a su mano)`,
        action: () => {
          if (typeof openCardChooserModal === 'function') {
            const chooserTargets = candidates.map(id => ({
              id: id,
              owner: 'opponent',
              from: 'deck',
              text: cardsDatabase[id]?.nombre || id
            }));
            openCardChooserModal(chooserTargets, "[Rival] Descifrar ruta: Selecciona 1 Personaje Haruka para la mano rival", (chosenIdx) => {
              const chosenId = chooserTargets[chosenIdx] ? chooserTargets[chosenIdx].id : candidates[chosenIdx];
              resolveAddHaruka(chosenId);
            });
          } else {
            resolveAddHaruka(candidates[0]);
          }
        }
      },
      {
        text: `❌ [Rival] No activar Descifrar ruta`,
        action: () => {
          addLog(`[Efecto Descifrar ruta BBX-SP375 Rival] Se decidió no activar el efecto de Descifrar ruta rival.`, 'var(--text-muted)');
          if (typeof updatePlaytestView === 'function') updatePlaytestView();
          if (typeof onDone === 'function') onDone();
        }
      }
    ];

    addLog(`[Trigger Rival Descifrar ruta] Se envió <strong>Descifrar ruta (BBX-SP375)</strong> portada al cementerio rival por efecto de una carta: puede agregar 1 Personaje Haruka de su deck a su mano.`, 'var(--accent-purple)');
    const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
    showContextMenu(dummyEvent, items);
  }
}

// Caída oportuna (BBX-SP385): "Si esta carta es enviada al cementerio, puedes barajar a tu deck 1 Personaje Roy que controles. Solo puedes usar este efecto de \"Caída oportuna\" una vez por turno."
let lastCaidaOportunaTriggerTime = 0;
let lastCaidaOportunaOpponentTriggerTime = 0;

function checkAndTriggerCaidaOportunaSP385(cardId, owner = 'player', ctx = {}, testOptions = {}, onDone = null) {
  if (cardId !== 'BBX-SP385') {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const isPlayer = owner === 'player';
  const now = Date.now();
  const skipDebounce = testOptions && (testOptions.autoAccept !== undefined || testOptions.skipDebounce);
  if (!skipDebounce) {
    if (isPlayer) {
      if (now - lastCaidaOportunaTriggerTime < 250) {
        if (typeof onDone === 'function') onDone(false);
        return;
      }
      lastCaidaOportunaTriggerTime = now;
    } else {
      if (now - lastCaidaOportunaOpponentTriggerTime < 250) {
        if (typeof onDone === 'function') onDone(false);
        return;
      }
      lastCaidaOportunaOpponentTriggerTime = now;
    }
  }

  // Comprobar Hard Once Per Turn (HOPT)
  const usedGlobal = isPlayer
    ? (playtestState.usedGlobalEffects || [])
    : (playtestState.opponentUsedGlobalEffects || []);

  if (usedGlobal.includes('Caída oportuna') || usedGlobal.includes('BBX-SP385')) {
    addLog(`[Efecto Caída oportuna BBX-SP385${isPlayer ? '' : ' Rival'}] Ya se utilizó el efecto de "Caída oportuna" este turno (Límite 1 vez por turno).`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // Comprobar bloqueo de efectos en cementerio (Secretos de Fafnirland BBX-SP332, Anhelo BBX-SP352, etc.)
  if (typeof isSkillGraveEffectBlocked === 'function' && isSkillGraveEffectBlocked()) {
    addLog(`[Efecto Caída oportuna BBX-SP385${isPlayer ? '' : ' Rival'}] Efectos de Skills en el cementerio bloqueados por Secretos de Fafnirland.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }
  if (typeof isCardGraveEffectBlocked === 'function' && isCardGraveEffectBlocked(owner, cardId)) {
    addLog(`[Efecto Caída oportuna BBX-SP385${isPlayer ? '' : ' Rival'}] Los efectos de cartas en el cementerio están bloqueados.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }
  if (typeof window !== 'undefined' && window.RulesEngine && typeof window.RulesEngine.isAnheloGraveBlocked === 'function' && window.RulesEngine.isAnheloGraveBlocked(owner)) {
    addLog(`[Efecto Caída oportuna BBX-SP385${isPlayer ? '' : ' Rival'}] Los efectos en cementerio están bloqueados por Anhelo.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // Buscar Personajes Roy que controle (en slots de combate o en la banca)
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;
  const bench = isPlayer ? playtestState.bench : playtestState.opponentBench;

  const eligibleTargets = [];
  (slots || []).forEach((s, idx) => {
    if (s.character && cardsDatabase[s.character]) {
      const c = cardsDatabase[s.character];
      if (c.tipo === 'Personaje' && c.nombre.includes("Roy")) {
        eligibleTargets.push({
          type: 'slot',
          slotIndex: idx,
          cardId: s.character,
          name: c.nombre,
          slot: s,
          label: `Slot ${idx + 1}: ${c.nombre}`
        });
      }
    }
  });

  const aperturaActive = typeof isAperturaEnElCieloActive === 'function' && isAperturaEnElCieloActive();
  if (!aperturaActive) {
    (bench || []).forEach((bItem, bIdx) => {
      const bId = typeof bItem === 'object' && bItem !== null ? bItem.id : bItem;
      if (bId && cardsDatabase[bId]) {
        const c = cardsDatabase[bId];
        if (c.tipo === 'Personaje' && c.nombre.includes("Roy")) {
          eligibleTargets.push({
            type: 'bench',
            benchIndex: bIdx,
            cardId: bId,
            name: c.nombre,
            label: `Banca: ${c.nombre}`
          });
        }
      }
    });
  }

  if (eligibleTargets.length === 0) {
    addLog(`[Efecto Caída oportuna BBX-SP385${isPlayer ? '' : ' Rival'}] Enviada al cementerio, pero no controlas ningún Personaje Roy para barajar al deck.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const markUsed = () => {
    if (isPlayer) {
      playtestState.usedGlobalEffects = playtestState.usedGlobalEffects || [];
      playtestState.usedGlobalEffects.push('Caída oportuna');
      playtestState.usedGlobalEffects.push('BBX-SP385');
    } else {
      playtestState.opponentUsedGlobalEffects = playtestState.opponentUsedGlobalEffects || [];
      playtestState.opponentUsedGlobalEffects.push('Caída oportuna');
      playtestState.opponentUsedGlobalEffects.push('BBX-SP385');
    }
  };

  const resolveShuffleRoy = (target) => {
    markUsed();
    const deck = isPlayer ? playtestState.deck : playtestState.opponentDeck;
    const grave = isPlayer ? playtestState.grave : playtestState.opponentGrave;

    if (target.type === 'slot') {
      const s = target.slot;
      const charId = s.character;
      const attachedSkills = [...(s.skills || [])];

      s.character = null;
      s.skills = [];
      s.isRotated = false;
      s.effectUsed = false;
      s.usedSkills = [];
      s.usedSkillIndexes = [];
      s.maxAttacks = 1;
      s.attacksDeclared = 0;

      // Skills portadas van al cementerio
      if (attachedSkills.length > 0) {
        attachedSkills.forEach(sk => {
          grave.push(sk);
          if (typeof onEquippedSkillSentToGraveByEffect === 'function') {
            onEquippedSkillSentToGraveByEffect(sk, owner, owner);
          }
          if (typeof checkAndTriggerRemembranza === 'function') {
            checkAndTriggerRemembranza(sk, owner);
          }
          if (typeof checkAndTriggerFulgorOfensivo === 'function') {
            checkAndTriggerFulgorOfensivo(sk);
          }
          if (typeof dispatchGraveTriggers === 'function') {
            dispatchGraveTriggers(sk, owner, { fromZone: 'field', isEquipped: true, byEffect: true });
          }
        });
      }

      deck.push(charId);
    } else if (target.type === 'bench') {
      const benchRef = isPlayer ? playtestState.bench : playtestState.opponentBench;
      benchRef.splice(target.benchIndex, 1);
      deck.push(target.cardId);
    }

    // Barajar mazo obligatoriamente
    if (typeof shuffleArray === 'function') {
      shuffleArray(deck);
    }
    if (typeof checkAndTriggerInestabilidad === 'function') {
      checkAndTriggerInestabilidad(owner);
    }

    const charName = cardsDatabase[target.cardId]?.nombre || target.cardId;
    addLog(`[Efecto Caída oportuna BBX-SP385${isPlayer ? '' : ' Rival'}] ${isPlayer ? 'Barajaste' : 'El rival barajó'} a <strong>${charName}</strong> de ${target.type === 'slot' ? `su Slot ${target.slotIndex + 1}` : 'su Banca'} a su deck y barajó el mazo.`, isPlayer ? 'var(--accent-purple)' : 'var(--accent-danger)');

    if (typeof notifySkillInGraveEffectUsed === 'function') {
      notifySkillInGraveEffectUsed(owner);
    }
    if (typeof updatePlaytestView === 'function') updatePlaytestView();
    if (typeof onDone === 'function') onDone(true);
  };

  // Soporte para pruebas automatizadas (testOptions)
  if (testOptions && testOptions.autoAccept !== undefined) {
    if (testOptions.autoAccept === false) {
      addLog(`[Efecto Caída oportuna BBX-SP385${isPlayer ? '' : ' Rival'}] Decidiste no activar el efecto de Caída oportuna.`, 'var(--text-muted)');
      if (typeof onDone === 'function') onDone(false);
      return;
    }
    const chosenIdx = testOptions.chosenTargetIndex !== undefined ? testOptions.chosenTargetIndex : 0;
    const target = eligibleTargets[chosenIdx] || eligibleTargets[0];
    resolveShuffleRoy(target);
    return;
  }

  // Para el rival / IA automático
  if (!isPlayer) {
    resolveShuffleRoy(eligibleTargets[0]);
    return;
  }

  // Para el jugador humano (interactivo)
  const dummyEvent = {
    clientX: typeof window !== 'undefined' ? window.innerWidth / 2 - 120 : 0,
    clientY: typeof window !== 'undefined' ? window.innerHeight / 2 - 80 : 0
  };

  const promptOptions = [
    {
      text: `🔄 Activar Caída oportuna: Barajar 1 Roy que controles al deck`,
      action: () => {
        if (eligibleTargets.length === 1) {
          resolveShuffleRoy(eligibleTargets[0]);
        } else {
          // Si hay más de un Roy, ofrecer modal o menú para elegir cuál barajar
          const chooserTargets = eligibleTargets.map(t => t.cardId);
          if (typeof openCardChooserModal === 'function') {
            openCardChooserModal(chooserTargets, `Selecciona cuál Personaje Roy barajar a tu deck:`, (chosenIndex) => {
              resolveShuffleRoy(eligibleTargets[chosenIndex] || eligibleTargets[0]);
            });
          } else {
            resolveShuffleRoy(eligibleTargets[0]);
          }
        }
      }
    },
    {
      text: `❌ No activar efecto de Caída oportuna`,
      action: () => {
        addLog(`[Efecto Caída oportuna BBX-SP385] Decidiste no activar el efecto de Caída oportuna.`, 'var(--text-muted)');
        if (typeof updatePlaytestView === 'function') updatePlaytestView();
        if (typeof onDone === 'function') onDone(false);
      }
    }
  ];

  if (typeof showContextMenu === 'function') {
    showContextMenu(dummyEvent, promptOptions);
  } else {
    resolveShuffleRoy(eligibleTargets[0]);
  }
}

// Mareo (BBX-SP389): "Si esta Skill portada es enviada al cementerio por el efecto de una carta, puedes barajar al deck 1 Skill portada en el campo de tu adversario."
let lastMareoTriggerTime = 0;
let lastMareoOpponentTriggerTime = 0;

function checkAndTriggerMareoSP389(cardId, owner = 'player', ctx = {}, testOptions = {}, onDone = null) {
  if (cardId !== 'BBX-SP389') {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // Debe haber estado portada y haber sido enviada por el efecto de una carta
  if (!ctx || ctx.isEquipped !== true || ctx.byEffect === false) {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const isPlayer = owner === 'player';
  const now = Date.now();
  const skipDebounce = testOptions && (testOptions.autoAccept !== undefined || testOptions.skipDebounce);
  if (!skipDebounce) {
    if (isPlayer) {
      if (now - lastMareoTriggerTime < 250) {
        if (typeof onDone === 'function') onDone(false);
        return;
      }
      lastMareoTriggerTime = now;
    } else {
      if (now - lastMareoOpponentTriggerTime < 250) {
        if (typeof onDone === 'function') onDone(false);
        return;
      }
      lastMareoOpponentTriggerTime = now;
    }
  }

  // Comprobar bloqueo de efectos en cementerio
  if (typeof isSkillGraveEffectBlocked === 'function' && isSkillGraveEffectBlocked()) {
    addLog(`[Efecto Mareo BBX-SP389${isPlayer ? '' : ' Rival'}] Efectos de Skills en el cementerio bloqueados por Secretos de Fafnirland.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }
  if (typeof isCardGraveEffectBlocked === 'function' && isCardGraveEffectBlocked(owner, cardId)) {
    addLog(`[Efecto Mareo BBX-SP389${isPlayer ? '' : ' Rival'}] Los efectos de cartas en el cementerio están bloqueados.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }
  if (typeof window !== 'undefined' && window.RulesEngine && typeof window.RulesEngine.isAnheloGraveBlocked === 'function' && window.RulesEngine.isAnheloGraveBlocked(owner)) {
    addLog(`[Efecto Mareo BBX-SP389${isPlayer ? '' : ' Rival'}] Los efectos en cementerio están bloqueados por Anhelo.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const oppSlots = isPlayer ? playtestState.opponentSlots : playtestState.slots;
  const oppOwner = isPlayer ? 'opponent' : 'player';

  const eligibleTargets = [];
  (oppSlots || []).forEach((s, sIdx) => {
    if (s.character && Array.isArray(s.skills)) {
      s.skills.forEach((skId, skIdx) => {
        if (typeof canRemoveSkillByEffect === 'function') {
          if (canRemoveSkillByEffect(skId, true, owner, s, 'deck')) {
            eligibleTargets.push({
              slotIndex: sIdx,
              skillIndex: skIdx,
              skillId: skId,
              slot: s,
              charName: cardsDatabase[s.character]?.nombre || 'Personaje',
              skillName: cardsDatabase[skId]?.nombre || skId
            });
          }
        } else {
          eligibleTargets.push({
            slotIndex: sIdx,
            skillIndex: skIdx,
            skillId: skId,
            slot: s,
            charName: cardsDatabase[s.character]?.nombre || 'Personaje',
            skillName: cardsDatabase[skId]?.nombre || skId
          });
        }
      });
    }
  });

  if (eligibleTargets.length === 0) {
    addLog(`[Efecto Mareo BBX-SP389${isPlayer ? '' : ' Rival'}] Enviada portada al cementerio por efecto de una carta, pero no hay ninguna Skill portada en el campo de tu adversario que pueda ser barajada al deck.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const resolveShuffle = (target) => {
    const onCancel = () => {
      addLog(`[Efecto Mareo BBX-SP389] El barajado de la Skill <strong>${target.skillName}</strong> fue protegido.`, 'var(--accent-purple)');
      if (typeof updatePlaytestView === 'function') updatePlaytestView();
      if (typeof onDone === 'function') onDone(false);
    };

    const onProceed = () => {
      const skIdx = target.slot.skills.indexOf(target.skillId);
      if (skIdx === -1) {
        if (typeof onDone === 'function') onDone(false);
        return;
      }
      const removedId = target.slot.skills.splice(skIdx, 1)[0];
      const targetDeck = isPlayer ? playtestState.opponentDeck : playtestState.deck;
      targetDeck.push(removedId);
      if (typeof shuffleArray === 'function') {
        shuffleArray(targetDeck);
      }

      if (isPlayer) {
        addLog(`[Efecto Mareo BBX-SP389] Barajaste al deck la Skill portada del adversario <strong>${target.skillName}</strong> (de ${target.charName}).`, 'var(--accent-purple)');
      } else {
        addLog(`[Efecto Mareo BBX-SP389 Rival] El rival barajó a tu deck tu Skill portada <strong>${target.skillName}</strong> (de ${target.charName}).`, 'var(--accent-purple)');
      }

      if (typeof notifySkillsRemovedByEffect === 'function') {
        notifySkillsRemovedByEffect(1, 'deck', owner);
      }

      if (typeof updatePlaytestView === 'function') updatePlaytestView();
      if (typeof onDone === 'function') onDone(true);
    };

    if (typeof checkAndProtectShuffleSkillByRyuChan === 'function') {
      checkAndProtectShuffleSkillByRyuChan(oppOwner, onCancel, onProceed, 1);
    } else {
      onProceed();
    }
  };

  // Manejo de opción no activar
  if (testOptions && testOptions.activate === false) {
    addLog(`[Efecto Mareo BBX-SP389${isPlayer ? '' : ' Rival'}] Decidiste no activar el efecto de Mareo.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  if (testOptions && (testOptions.activate === true || testOptions.targetIndex !== undefined || testOptions.chosenTarget !== undefined)) {
    let chosenTarget = eligibleTargets[0];
    if (testOptions.targetIndex !== undefined && eligibleTargets[testOptions.targetIndex]) {
      chosenTarget = eligibleTargets[testOptions.targetIndex];
    } else if (testOptions.chosenTarget) {
      chosenTarget = testOptions.chosenTarget;
    }
    resolveShuffle(chosenTarget);
    return;
  }

  // Oponente automático (IA)
  if (!isPlayer) {
    resolveShuffle(eligibleTargets[0]);
    return;
  }

  // Jugador interactivo
  const dummyEvent = {
    clientX: typeof window !== 'undefined' ? window.innerWidth / 2 - 120 : 0,
    clientY: typeof window !== 'undefined' ? window.innerHeight / 2 - 80 : 0
  };

  const promptOptions = [
    {
      text: `🌀 Activar Mareo: Barajar al deck 1 Skill portada del adversario`,
      action: () => {
        if (eligibleTargets.length === 1) {
          resolveShuffle(eligibleTargets[0]);
        } else {
          if (typeof openCardChooserModal === 'function') {
            const chooserTargets = eligibleTargets.map(t => ({
              id: t.skillId,
              owner: 'opponent',
              text: `"${t.skillName}" (de ${t.charName} - Slot ${t.slotIndex + 1})`
            }));
            openCardChooserModal(chooserTargets, "Mareo: Selecciona 1 Skill portada del adversario para barajar al deck", (chosenIdx) => {
              const target = eligibleTargets[chosenIdx] || eligibleTargets[0];
              resolveShuffle(target);
            });
          } else {
            resolveShuffle(eligibleTargets[0]);
          }
        }
      }
    },
    {
      text: `❌ No activar efecto de Mareo`,
      action: () => {
        addLog(`[Efecto Mareo BBX-SP389] Decidiste no activar el efecto de Mareo.`, 'var(--text-muted)');
        if (typeof updatePlaytestView === 'function') updatePlaytestView();
        if (typeof onDone === 'function') onDone(false);
      }
    }
  ];

  if (typeof showContextMenu === 'function') {
    showContextMenu(dummyEvent, promptOptions);
  } else {
    resolveShuffle(eligibleTargets[0]);
  }
}

// Corriente esmeralda BBX-SP394: Si 1 Skill propia de Marina es enviada al cementerio por una batalla, puedes barajar al deck 1 Skill portada en el campo de tu adversario. Solo puedes usar este efecto de "Corriente esmeralda" una vez por turno.
// Regla: Debe permanecer equipada en el campo para resolver su efecto (por lo que solo se activa si otras skill de Marina son enviadas al cementerio o una segunda copia de SP394).
function checkAndTriggerCorrienteEsmeraldaSP394(lostSkillId, owner = 'player', testOptions = {}, onDone = null) {
  const isPlayer = owner === 'player';

  // 1. Validar que la Skill enviada al cementerio sea propia de Marina
  const lostCard = cardsDatabase[lostSkillId];
  if (!lostCard || lostCard.tipo !== 'Skill' || !lostCard.portador || !lostCard.portador.includes('Marina')) {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 2. Comprobar Hard Once Per Turn (HOPT)
  const usedGlobal = isPlayer
    ? (playtestState.usedGlobalEffects || [])
    : (playtestState.opponentUsedGlobalEffects || []);

  if (usedGlobal.includes('Corriente esmeralda') || usedGlobal.includes('BBX-SP394')) {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 3. Comprobar que el jugador tenga al menos una copia de Corriente esmeralda (BBX-SP394) actualmente equipada en el campo y no bloqueada
  const slots = isPlayer ? playtestState.slots : playtestState.opponentSlots;
  const eligibleCorrienteSlots = [];
  slots.forEach((s, sIdx) => {
    if (s.character && s.skills && s.skills.includes('BBX-SP394')) {
      const charBlocked = typeof isCharacterEffectBlocked === 'function' && isCharacterEffectBlocked(owner, s);
      const skillBlocked = typeof isSkillEffectBlocked === 'function' && isSkillEffectBlocked('BBX-SP394', owner, s);
      if (!charBlocked && !skillBlocked) {
        eligibleCorrienteSlots.push({ slot: s, slotIndex: sIdx });
      }
    }
  });

  if (eligibleCorrienteSlots.length === 0) {
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  // 4. Buscar Skills portadas en el campo del adversario
  const oppOwner = isPlayer ? 'opponent' : 'player';
  const oppSlots = isPlayer ? playtestState.opponentSlots : playtestState.slots;
  const eligibleTargets = [];

  oppSlots.forEach((s, sIdx) => {
    if (s.character && s.skills && s.skills.length > 0) {
      s.skills.forEach((skId, skIdx) => {
        const canRemove = typeof canRemoveSkillByEffect === 'function'
          ? canRemoveSkillByEffect(skId, true, owner, s, 'deck', 'BBX-SP394', 'Skill')
          : true;
        if (canRemove) {
          eligibleTargets.push({
            slotIndex: sIdx,
            skillIndex: skIdx,
            skillId: skId,
            slot: s,
            charName: cardsDatabase[s.character]?.nombre || 'Personaje',
            skillName: cardsDatabase[skId]?.nombre || skId
          });
        }
      });
    }
  });

  if (eligibleTargets.length === 0) {
    addLog(`[Efecto Corriente esmeralda BBX-SP394${isPlayer ? '' : ' Rival'}] Una Skill propia de Marina fue enviada al cementerio por una batalla, pero no hay ninguna Skill portada en el campo de tu adversario que pueda ser barajada al deck.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  const resolveShuffle = (target) => {
    const onCancel = () => {
      addLog(`[Efecto Corriente esmeralda BBX-SP394${isPlayer ? '' : ' Rival'}] El barajado de la Skill <strong>${target.skillName}</strong> fue protegido.`, 'var(--accent-purple)');
      if (typeof updatePlaytestView === 'function') updatePlaytestView();
      if (typeof onDone === 'function') onDone(false);
    };

    const onProceed = () => {
      const skIdx = target.slot.skills.indexOf(target.skillId);
      if (skIdx === -1) {
        if (typeof onDone === 'function') onDone(false);
        return;
      }
      const removedId = target.slot.skills.splice(skIdx, 1)[0];
      const targetDeck = isPlayer ? playtestState.opponentDeck : playtestState.deck;
      targetDeck.push(removedId);
      if (typeof shuffleArray === 'function') {
        shuffleArray(targetDeck);
      }

      if (isPlayer) {
        if (!playtestState.usedGlobalEffects) playtestState.usedGlobalEffects = [];
        playtestState.usedGlobalEffects.push('Corriente esmeralda');
        addLog(`[Efecto Corriente esmeralda BBX-SP394] Barajaste al deck la Skill portada del adversario <strong>${target.skillName}</strong> (de ${target.charName}).`, 'var(--accent-purple)');
      } else {
        if (!playtestState.opponentUsedGlobalEffects) playtestState.opponentUsedGlobalEffects = [];
        playtestState.opponentUsedGlobalEffects.push('Corriente esmeralda');
        addLog(`[Efecto Corriente esmeralda BBX-SP394 Rival] El rival barajó a tu deck tu Skill portada <strong>${target.skillName}</strong> (de ${target.charName}).`, 'var(--accent-purple)');
      }

      if (typeof notifySkillsRemovedByEffect === 'function') {
        notifySkillsRemovedByEffect(1, 'deck', owner);
      }

      if (typeof updatePlaytestView === 'function') updatePlaytestView();
      if (typeof onDone === 'function') onDone(true);
    };

    const onProceedWithBarreraCheck = () => {
      if (typeof checkAndProtectBarreraSP387 === 'function') {
        checkAndProtectBarreraSP387(oppOwner, 1, 'deck', onCancel, onProceed);
      } else {
        onProceed();
      }
    };

    if (typeof checkAndProtectShuffleSkillByRyuChan === 'function') {
      checkAndProtectShuffleSkillByRyuChan(oppOwner, onCancel, onProceedWithBarreraCheck, 1);
    } else {
      onProceedWithBarreraCheck();
    }
  };

  // Manejo de opción no activar
  if (testOptions && testOptions.activate === false) {
    addLog(`[Efecto Corriente esmeralda BBX-SP394${isPlayer ? '' : ' Rival'}] Decidiste no activar el efecto de Corriente esmeralda.`, 'var(--text-muted)');
    if (typeof onDone === 'function') onDone(false);
    return;
  }

  if (testOptions && (testOptions.activate === true || testOptions.targetIndex !== undefined || testOptions.chosenTarget !== undefined)) {
    let chosenTarget = eligibleTargets[0];
    if (testOptions.targetIndex !== undefined && eligibleTargets[testOptions.targetIndex]) {
      chosenTarget = eligibleTargets[testOptions.targetIndex];
    } else if (testOptions.chosenTarget) {
      chosenTarget = testOptions.chosenTarget;
    }
    resolveShuffle(chosenTarget);
    return;
  }

  // Oponente automático (IA)
  if (!isPlayer) {
    resolveShuffle(eligibleTargets[0]);
    return;
  }

  // Jugador interactivo
  const promptOptions = [
    {
      text: `🌊 Activar Corriente esmeralda: Barajar 1 Skill portada rival al deck`,
      action: () => {
        if (eligibleTargets.length === 1) {
          resolveShuffle(eligibleTargets[0]);
        } else {
          const chooserTargets = eligibleTargets.map(t => ({
            id: t.skillId,
            owner: 'opponent',
            text: `"${t.skillName}" (${t.charName})`
          }));
          if (typeof openCardChooserModal === 'function') {
            openCardChooserModal(chooserTargets, "Corriente esmeralda: Selecciona 1 Skill portada del adversario para barajar al deck", (chosenIdx) => {
              resolveShuffle(eligibleTargets[chosenIdx] || eligibleTargets[0]);
            });
          } else {
            resolveShuffle(eligibleTargets[0]);
          }
        }
      }
    },
    {
      text: `❌ No activar efecto de Corriente esmeralda`,
      action: () => {
        addLog(`[Efecto Corriente esmeralda BBX-SP394] Decidiste no activar el efecto de Corriente esmeralda.`, 'var(--text-muted)');
        if (typeof updatePlaytestView === 'function') updatePlaytestView();
        if (typeof onDone === 'function') onDone(false);
      }
    }
  ];

  const dummyEvent = {
    clientX: typeof window !== 'undefined' ? window.innerWidth / 2 - 120 : 0,
    clientY: typeof window !== 'undefined' ? window.innerHeight / 2 - 80 : 0
  };

  if (typeof showContextMenu === 'function') {
    showContextMenu(dummyEvent, promptOptions);
  } else {
    resolveShuffle(eligibleTargets[0]);
  }
}

function onEquippedSkillSentToGraveByEffect(skillId, slotOwner = 'player', sourceOwner = 'player') {
  if (typeof dispatchGraveTriggers === 'function') {
    dispatchGraveTriggers(skillId, slotOwner, { isEquipped: true, sourceOwner, byEffect: true });
    if (sourceOwner !== slotOwner && typeof checkAndTriggerMarinaSP410 === 'function') {
      checkAndTriggerMarinaSP410(skillId, sourceOwner, slotOwner);
    }
    return;
  }
  if (slotOwner === 'player') {
    checkAndTriggerVendavalTajante(skillId, true, 'player');
    checkAndTriggerDesenfundar(skillId, true, 'player');
    checkAndTriggerTripleEstocada(skillId, true, 'player');
    checkAndTriggerDescuido(skillId, true, 'player');
    checkAndTriggerTorbellino(skillId, true);
    checkAndTriggerDesvelo(skillId, 'player');
    checkAndTriggerDragoFulgor(skillId, 'player');
    checkAndTriggerHoloescudo(skillId, 'player');
    checkAndTriggerInermeSP355(skillId, 'player', { isEquipped: true, sourceOwner, byEffect: true });
    checkAndTriggerDescifrarRutaSP375(skillId, 'player', { isEquipped: true, sourceOwner, byEffect: true });
    checkAndTriggerCaidaOportunaSP385(skillId, 'player', { isEquipped: true, sourceOwner, byEffect: true });
    checkAndTriggerMareoSP389(skillId, 'player', { isEquipped: true, sourceOwner, byEffect: true });
    if (typeof checkAndTriggerVoluntadDelAguaSP421 === 'function') {
      checkAndTriggerVoluntadDelAguaSP421(skillId, 'player', { isEquipped: true, sourceOwner, byEffect: true });
    }
    if (sourceOwner === 'opponent') {
      checkAndTriggerHoraDelTe(skillId, 'player');
      if (typeof checkAndTriggerMarinaSP410 === 'function') {
        checkAndTriggerMarinaSP410(skillId, 'opponent', 'player');
      }
    }
  } else {
    checkAndTriggerVendavalTajanteOpponent(skillId, true, 'opponent');
    checkAndTriggerDesenfundarOpponent(skillId, true, 'opponent');
    checkAndTriggerTripleEstocadaOpponent(skillId, true, 'opponent');
    checkAndTriggerDescuidoOpponent(skillId, true, 'opponent');
    checkAndTriggerTorbellinoOpponent(skillId, true);
    checkAndTriggerDesvelo(skillId, 'opponent');
    checkAndTriggerDragoFulgor(skillId, 'opponent');
    checkAndTriggerHoloescudo(skillId, 'opponent');
    checkAndTriggerInermeSP355(skillId, 'opponent', { isEquipped: true, sourceOwner, byEffect: true });
    checkAndTriggerDescifrarRutaSP375(skillId, 'opponent', { isEquipped: true, sourceOwner, byEffect: true });
    checkAndTriggerCaidaOportunaSP385(skillId, 'opponent', { isEquipped: true, sourceOwner, byEffect: true });
    checkAndTriggerMareoSP389(skillId, 'opponent', { isEquipped: true, sourceOwner, byEffect: true });
    if (typeof checkAndTriggerVoluntadDelAguaSP421 === 'function') {
      checkAndTriggerVoluntadDelAguaSP421(skillId, 'opponent', { isEquipped: true, sourceOwner, byEffect: true });
    }
    if (sourceOwner === 'player') {
      checkAndTriggerHoraDelTe(skillId, 'opponent');
      if (typeof checkAndTriggerMarinaSP410 === 'function') {
        checkAndTriggerMarinaSP410(skillId, 'player', 'opponent');
      }
    }
  }
}

// ¡Descuido! (BBX-SP274): Si esta Skill portada es enviada al cementerio por el efecto de una carta, puedes enviar al cementerio 1 carta al azar en la mano de tu adversario. Solo puedes usar el efecto de "¡Descuido!" una vez por turno.
let lastDescuidoTriggerTime = 0;
function checkAndTriggerDescuido(skillId, isEquipped = true, owner = 'player') {
  if (skillId !== 'BBX-SP274' || !isEquipped) return;
  if (playtestState.descuidoUsedThisTurn) {
    addLog(`[¡Descuido! BBX-SP274] Ya usaste el efecto de "¡Descuido!" este turno.`, 'var(--text-muted)');
    return;
  }

  const now = Date.now();
  if (now - lastDescuidoTriggerTime < 300) return;
  lastDescuidoTriggerTime = now;

  if (playtestState.opponentHand.length === 0) {
    addLog(`[¡Descuido! BBX-SP274] Enviada al cementerio por efecto, pero tu adversario no tiene cartas en su mano.`, 'var(--text-muted)');
    return;
  }

  const items = [
    {
      text: "💥 Activar ¡Descuido! (Enviar al cementerio 1 carta al azar de la mano del rival)",
      action: () => {
        playtestState.descuidoUsedThisTurn = true;
        if (playtestState.opponentHand.length === 0) {
          updatePlaytestView();
          return;
        }
        const randomIdx = Math.floor(Math.random() * playtestState.opponentHand.length);
        const discardedId = playtestState.opponentHand.splice(randomIdx, 1)[0];
        playtestState.opponentGrave.push(discardedId);
        addLog(`[Efecto ¡Descuido! BBX-SP274] Se envió al azar <strong>${cardsDatabase[discardedId].nombre}</strong> de la mano de tu adversario a su cementerio.`, 'var(--accent-purple)');
        checkAndTriggerRemembranza(discardedId, 'opponent');
        checkAndTriggerDesvelo(discardedId, 'opponent');
        checkAndTriggerHoraDelTe(discardedId, 'opponent');
        if (typeof checkAndTriggerMarinaSP410 === 'function') {
          checkAndTriggerMarinaSP410(discardedId, 'player', 'opponent');
        }
        checkAndTriggerDragoFulgor(discardedId, 'opponent');
        updatePlaytestView();
      }
    },
    {
      text: "❌ No activar ¡Descuido!",
      action: () => {
        addLog(`[Efecto ¡Descuido! BBX-SP274] Decidiste no activar su efecto.`, 'var(--text-muted)');
        updatePlaytestView();
      }
    }
  ];

  addLog(`[Trigger] Se envió a <strong>¡Descuido! (SP274)</strong> portada al cementerio por efecto: puedes activar su efecto para enviar al cementerio 1 carta al azar de la mano del rival.`, 'var(--accent-cyan)');
  const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
  showContextMenu(dummyEvent, items);
}

let lastDescuidoOpponentTriggerTime = 0;
function checkAndTriggerDescuidoOpponent(skillId, isEquipped = true, owner = 'opponent') {
  if (skillId !== 'BBX-SP274' || !isEquipped) return;
  if (playtestState.opponentDescuidoUsedThisTurn) {
    addLog(`[¡Descuido! BBX-SP274 Rival] El rival ya usó el efecto de "¡Descuido!" este turno.`, 'var(--text-muted)');
    return;
  }

  const now = Date.now();
  if (now - lastDescuidoOpponentTriggerTime < 300) return;
  lastDescuidoOpponentTriggerTime = now;

  if (playtestState.hand.length === 0) {
    addLog(`[¡Descuido! BBX-SP274 Rival] Enviada al cementerio por efecto, pero no tienes cartas en tu mano.`, 'var(--text-muted)');
    return;
  }

  const items = [
    {
      text: "💥 [Rival] Activar ¡Descuido! (Enviar al cementerio 1 carta al azar de tu mano)",
      action: () => {
        playtestState.opponentDescuidoUsedThisTurn = true;
        if (playtestState.hand.length === 0) {
          updatePlaytestView();
          return;
        }
        const randomIdx = Math.floor(Math.random() * playtestState.hand.length);
        const discardedId = playtestState.hand.splice(randomIdx, 1)[0];
        playtestState.grave.push(discardedId);
        addLog(`[Efecto ¡Descuido! BBX-SP274 Rival] Se envió al azar <strong>${cardsDatabase[discardedId].nombre}</strong> de tu mano a tu cementerio.`, 'var(--accent-purple)');
        checkAndTriggerRemembranza(discardedId, 'player');
        checkAndTriggerDesvelo(discardedId, 'player');
        checkAndTriggerHoraDelTe(discardedId, 'player');
        if (typeof checkAndTriggerMarinaSP410 === 'function') {
          checkAndTriggerMarinaSP410(discardedId, 'opponent', 'player');
        }
        checkAndTriggerDragoFulgor(discardedId, 'player');
        updatePlaytestView();
      }
    },
    {
      text: "❌ [Rival] No activar ¡Descuido!",
      action: () => {
        addLog(`[Efecto ¡Descuido! BBX-SP274 Rival] Decidiste no activar el efecto de ¡Descuido! rival.`, 'var(--text-muted)');
        updatePlaytestView();
      }
    }
  ];

  addLog(`[Trigger Rival] Se envió a <strong>¡Descuido! (SP274)</strong> portada al cementerio rival por efecto: puedes activar su efecto.`, 'var(--accent-cyan)');
  const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
  showContextMenu(dummyEvent, items);
}

function openUpToMultiCardChooserModal(cardIds, title, maxQty, onConfirm) {
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay';
  overlay.style.zIndex = '6000';
  
  overlay.innerHTML = `
    <div class="modal-content glass-panel" style="max-width: 600px; text-align: center;">
      <div class="modal-header" style="justify-content: center;">
        <h3>${title}</h3>
      </div>
      <div class="modal-body" style="display: flex; flex-direction: column; align-items: center; gap: 20px;">
        <div id="chooser-grid" class="modal-cards-grid" style="grid-template-columns: repeat(auto-fill, minmax(90px, 1fr)); width: 100%;"></div>
        <div style="font-size: 0.8rem; color: var(--text-muted);">
          Haz clic para seleccionar de 1 a ${maxQty} cartas. Haz clic de nuevo para desmarcar.
        </div>
        <div style="display: flex; gap: 12px; margin-top: 10px;">
          <button class="btn btn-primary" id="btn-confirm-selection" disabled>Confirmar Selección</button>
        </div>
      </div>
    </div>
  `;

  const grid = overlay.querySelector('#chooser-grid');
  const confirmBtn = overlay.querySelector('#btn-confirm-selection');
  let selectedIndices = [];

  const updateSelectionView = () => {
    grid.innerHTML = '';
    cardIds.forEach((item, index) => {
      let id = item;
      let from = null;
      let owner = null;
      if (typeof item === 'object' && item !== null) {
        id = item.id;
        from = item.from;
        owner = item.owner;
      }

      const card = cardsDatabase[id];
      const div = document.createElement('div');
      div.className = 'deck-grid-item';
      div.style.position = 'relative';
      div.style.cursor = 'pointer';
      div.style.transition = 'var(--transition-smooth)';
      
      div.innerHTML = `<img src="/imagenes/${card.imagen}" alt="${card.nombre}" style="width:100%; height:100%; object-fit:cover; border-radius:8px;">`;

      if (owner === 'player') {
        div.style.border = '1px solid var(--accent-cyan)';
      } else if (owner === 'opponent') {
        div.style.border = '1px solid var(--accent-danger)';
      } else {
        div.style.border = '1px solid var(--border-glass)';
      }

      const selIdx = selectedIndices.indexOf(index);
      if (selIdx !== -1) {
        div.style.border = '3px solid var(--accent-warning)';
        div.style.boxShadow = '0 0 15px rgba(255, 170, 0, 0.6)';
        div.style.transform = 'translateY(-4px)';

        const badge = document.createElement('div');
        badge.style.position = 'absolute';
        badge.style.top = '4px';
        badge.style.right = '4px';
        badge.style.width = '24px';
        badge.style.height = '24px';
        badge.style.borderRadius = '50%';
        badge.style.background = 'var(--accent-warning)';
        badge.style.color = 'var(--bg-dark)';
        badge.style.fontWeight = 'bold';
        badge.style.display = 'flex';
        badge.style.alignItems = 'center';
        badge.style.justifyContent = 'center';
        badge.style.border = '2px solid white';
        badge.style.zIndex = '30';
        badge.textContent = "✓";
        div.appendChild(badge);
      }

      if (owner === 'player' && selIdx === -1) {
        const pBadge = document.createElement('div');
        pBadge.style.position = 'absolute';
        pBadge.style.top = '4px';
        pBadge.style.left = '4px';
        pBadge.style.padding = '2px 6px';
        pBadge.style.borderRadius = '4px';
        pBadge.style.fontSize = '0.55rem';
        pBadge.style.fontWeight = 'bold';
        pBadge.style.background = 'var(--accent-cyan)';
        pBadge.style.color = 'var(--bg-dark)';
        pBadge.textContent = "👤 Tú";
        pBadge.style.zIndex = '10';
        div.appendChild(pBadge);
      } else if (owner === 'opponent' && selIdx === -1) {
        const oBadge = document.createElement('div');
        oBadge.style.position = 'absolute';
        oBadge.style.top = '4px';
        oBadge.style.left = '4px';
        oBadge.style.padding = '2px 6px';
        oBadge.style.borderRadius = '4px';
        oBadge.style.fontSize = '0.55rem';
        oBadge.style.fontWeight = 'bold';
        oBadge.style.background = 'var(--accent-danger)';
        oBadge.style.color = '#fff';
        oBadge.textContent = "🤖 Rival";
        oBadge.style.zIndex = '10';
        div.appendChild(oBadge);
      }

      if (item && item.charName) {
        const charBadge = document.createElement('div');
        charBadge.style.position = 'absolute';
        charBadge.style.bottom = '4px';
        charBadge.style.left = '50%';
        charBadge.style.transform = 'translateX(-50%)';
        charBadge.style.padding = '2px 6px';
        charBadge.style.borderRadius = '4px';
        charBadge.style.fontSize = '0.55rem';
        charBadge.style.fontWeight = 'bold';
        charBadge.style.background = 'rgba(46, 204, 113, 0.85)';
        charBadge.style.color = '#fff';
        charBadge.style.whiteSpace = 'nowrap';
        charBadge.style.boxShadow = '0 2px 5px rgba(0,0,0,0.5)';
        charBadge.style.zIndex = '10';
        charBadge.textContent = `⚔ ${item.charName}`;
        div.appendChild(charBadge);
      }

      div.addEventListener('click', () => {
        if (selectedIndices.includes(index)) {
          selectedIndices = selectedIndices.filter(i => i !== index);
        } else if (selectedIndices.length < maxQty) {
          selectedIndices.push(index);
        }
        updateSelectionView();
      });

      grid.appendChild(div);
    });

    confirmBtn.disabled = selectedIndices.length === 0 || selectedIndices.length > maxQty;
  };

  confirmBtn.addEventListener('click', () => {
    if (selectedIndices.length >= 1 && selectedIndices.length <= maxQty) {
      onConfirm(selectedIndices);
      overlay.remove();
    }
  });

  updateSelectionView();
  document.body.appendChild(overlay);
}

