  addLog(`[Trigger] Al inicio del turno de tu adversario: el rival puede activar <strong>Nobuko (BBX-SP420)</strong> de su mano porque tienes ${playtestState.hand.length} cartas en tu mano.`, 'var(--accent-danger)');
  const dummyEvent = { clientX: window.innerWidth / 2 - 120, clientY: window.innerHeight / 2 - 80 };
