function executeRoySP130Activation(activatorOwner = 'player', handIndex = -1, testOptions = {}, onDone = null) {
  const isPlayer = activatorOwner === 'player';
  const hand = (isPlayer ? playtestState.hand : playtestState.opponentHand) || [];
  const grave = (isPlayer ? playtestState.grave : playtestState.opponentGrave) || [];
  const oppSlots = isPlayer ? playtestState.opponentSlots : playtestState.slots;
  const oppGrave = isPlayer ? playtestState.opponentGrave : playtestState.grave;
  const oppOwner = isPlayer ? 'opponent' : 'player';
  const tag = isPlayer ? '[Efecto Roy BBX-SP130]' : '[Rival - Efecto Roy BBX-SP130]';

  if (typeof isCharacterHandEffectBlocked === 'function' && isCharacterHandEffectBlocked(activatorOwner)) {
    if (typeof addLog === 'function') addLog(tag + ' Bloqueado por efecto continuo.', 'var(--text-muted)');
    if (onDone) onDone(false);
    return false;
  }

  const hIdx = (handIndex >= 0 && hand[handIndex] === 'BBX-SP130') ? handIndex : hand.indexOf('BBX-SP130');
  if (hIdx === -1) {
    if (onDone) onDone(false);
    return false;
  }

  const discardedId = hand.splice(hIdx, 1)[0];
  grave.push(discardedId);
  if (typeof addLog === 'function') addLog(tag + ' Envió a Roy al cementerio como costo.', 'var(--accent-purple)');

  if (typeof dispatchGraveTriggers === 'function') {
    dispatchGraveTriggers(discardedId, activatorOwner, { fromZone: 'hand' });
  }

  const cantInvestigacion = grave.filter(id => cardsDatabase[id]?.nombre?.includes("Investigación")).length;
  if (cantInvestigacion <= 0) {
    if (typeof addLog === 'function') addLog(tag + ' No hay copias de Investigación en el cementerio.', 'var(--text-muted)');
    if (typeof updatePlaytestView === 'function') updatePlaytestView();
    if (onDone) onDone(true);
    return true;
  }

  const targetableSkills = [];
  oppSlots.forEach((s, sIdx) => {
    if (s && s.character) {
      (s.skills || []).forEach((skId, skIdx) => {
        if (typeof canRemoveSkillByEffect !== 'function' || canRemoveSkillByEffect(skId, true, activatorOwner, s, 'grave')) {
          targetableSkills.push({ id: skId, slotIdx: sIdx, charName: cardsDatabase[s.character]?.nombre });
        }
      });
    }
  });

  const maxQty = Math.min(cantInvestigacion, targetableSkills.length);
  const removedLogs = [];
  targetableSkills.slice(0, maxQty).forEach(item => {
    const s = oppSlots[item.slotIdx];
    const skIndex = s.skills.indexOf(item.id);
    if (skIndex !== -1) {
      const rem = s.skills.splice(skIndex, 1)[0];
      oppGrave.push(rem);
      removedLogs.push(cardsDatabase[rem]?.nombre || rem);
      if (typeof onEquippedSkillSentToGraveByEffect === 'function') {
        onEquippedSkillSentToGraveByEffect(rem, oppOwner, activatorOwner);
      }
      if (typeof dispatchGraveTriggers === 'function') {
        dispatchGraveTriggers(rem, oppOwner, { isEquipped: true, fromZone: 'field' });
      }
    }
  });

  if (typeof notifySkillsRemovedByEffect === 'function') {
    notifySkillsRemovedByEffect(removedLogs.length, 'grave', activatorOwner);
  }
  if (typeof addLog === 'function') addLog(tag + ' Destruyó Skills: ' + removedLogs.join(', '), 'var(--accent-purple)');
  if (typeof updatePlaytestView === 'function') updatePlaytestView();
  if (onDone) onDone(true);
  return true;
}

